window.kbParts["entries-cdfe49c47a7d4c64"] = {"nodes":{"k-caedc47bc4c7745b":{"review":{"title":"耕地数量、质量、生态“三位一体”保护","type":"制度与规则","definition":"《加快建设农业强国规划（2024—2035年）》要求健全耕地数量、质量、生态“三位一体”保护制度体系，同时维护耕地面积、农业生产能力和耕地生态条件。","explanation":"在完善耕地占补平衡制度时，规划要求将各类耕地占用纳入统一管理，并完善补充耕地质量验收机制。","basis":"据关联原题及所列出处编释。","references":[{"source":"farm","location":"耕地数量、质量、生态保护"}],"related":["k-7f4a4aba9435a8e5","k-7710ae6ce7fdca2f"],"domain":"生态环境","examFocus":{"政治理论必刷100题#11":"依据农业强国建设部署，区分耕地保护的制度要求、产业振兴的地位和现代农业建设的首要任务。","政治理论必刷100题#37":"按农业强国建设规划的任务归属，辨别耕地保护、粮食生产和农产品加工流通等举措。"}},"aspects":[{"title":"耕地保护与粮食安全","uses":[{"unit":"Q1","role":"直接考查","use":"《政治理论必刷100题》第11题要求选出关于农业强国的错误表述。A项符合农业强国规划。按乡村全面振兴规划，现代农业建设的首要任务是确保国家粮食安全，因此将首要任务表述为巩固拓展脱贫攻坚成果的D项当选。","evidence":"健全耕地数量、质量、生态“三位一体”保护制度体系","qids":["政治理论必刷100题#11"]},{"unit":"Q2","role":"直接考查","use":"《政治理论必刷100题》第37题考查举措在农业强国规划中的归属。第①项的三位一体保护和第③项的两条保护红线同属“全面加强耕地保护和建设”，与第⑤项的粮食生产扶持举措均归入夯实粮食安全根基部分，共三项，选B。","evidence":"①健全耕地数量、质量、生态“三位一体”保护制度体系","qids":["政治理论必刷100题#37"]}]}]},"k-fbc703040a1d4d3a":{"review":{"title":"乡村产业振兴","type":"制度与规则","definition":"乡村产业振兴是依托农业农村特色资源发展乡村产业、促进农民增收的政策部署。2022年12月中央农村工作会议讲话将产业振兴置于乡村振兴的重中之重。","explanation":"做好“土特产”文章，要开发农业多种功能、挖掘乡村多元价值，通过一二三产业融合延伸农业产业链，培育农村新产业新业态，拓宽农民增收渠道。","basis":"据关联原题及所列出处编释。","references":[{"source":"agri","location":"产业振兴"}],"related":["k-6129abc029f16867","k-10875ff0d8a54918","k-82a4f4b98ff57ecb"],"examFocus":{"政治理论必刷100题#11":"区分产业振兴在乡村振兴中的地位与现代农业建设的首要任务，并核对各自的要求。","政治理论必刷100题#15":"核对乡村振兴部署中产业振兴的定位、基层党组织的职责、农田建设进度和县域经济布局。"}},"aspects":[{"title":"产业振兴的优先地位","uses":[{"unit":"Q1","role":"直接考查","use":"《政治理论必刷100题》第11题要求选出关于农业强国的错误表述。C项把产业振兴的优先地位与做好“土特产”文章结合起来，符合2022年12月中央农村工作会议讲话。将巩固拓展脱贫攻坚成果列为现代农业建设首要任务的D项当选。","evidence":"产业振兴是乡村振兴的重中之重，要做好“土特产”文章","qids":["政治理论必刷100题#11"]},{"unit":"Q2","role":"直接考查","use":"《政治理论必刷100题》第15题要求选出正确的乡村振兴举措。第①项符合习近平总书记2023年3月参加十四届全国人大一次会议江苏代表团审议时的要求，讲话还提出延伸农业产业链、拓宽农民增收渠道。第①项与加强农村基层党组织建设的第②项均正确，选D。","evidence":"①要把产业振兴作为乡村振兴的重中之重","qids":["政治理论必刷100题#15"]}]}]},"k-88abcb53c6b6b413":{"review":{"definition":"中共中央、国务院印发的《乡村全面振兴规划（2024—2027年）》明确，现代农业建设的首要任务是确保国家粮食安全，要求全面落实粮食安全党政同责。","explanation":"规划把稳定播种面积、提高粮食单产列为保障粮食供给的措施。巩固拓展脱贫攻坚成果属于乡村全面振兴的总体部署。D项把它填入“现代农业建设的首要任务”，因此是本题要选的错误项。","references":[{"source":"web-9adecb527c8b901d","location":"第三部分第（五）项“提高粮食和重要农产品供给保障水平”","quote":"把确保国家粮食安全作为现代农业建设的首要任务"}],"evidence":"把确保国家粮食安全作为现代农业建设的首要任务","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-f3e0db413c649131":{"review":{"definition":"习近平在《促进民营经济健康发展、高质量发展》中提出，扎扎实实落实促进民营经济发展的政策措施，是文章所说的当前工作重点。已经明确的党中央决策部署应当坚决执行。","explanation":"①复述了该文对工作重点的部署，强调把已经确定的政策措施落到实处。题中的“当前”指文章提出这一部署时的政策语境。","references":[],"evidence":"扎扎实实落实促进民营经济发展的政策措施是当前促进民营经济发展的工作重点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-450f6c8e0d8e6d14":{"review":{"definition":"《促进民营经济健康发展、高质量发展》提出，应破除妨碍依法平等使用生产要素和公平参与市场竞争的障碍，给予民营企业公平的发展机会，并持续推进基础设施竞争性领域向各类经营主体公平开放。","explanation":"④指出这类障碍主要涉及市场准入。文章把落实市场准入负面清单制度作为具体抓手，推动“非禁即入”。②对应文章提出的另一项具体要求，开放范围是基础设施的竞争性领域，开放对象是各类经营主体。","references":[],"evidence":"持续推进基础设施竞争性领域向各类经营主体公平开放","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-512468f9d40a3d90":{"review":{"definition":"《促进民营经济健康发展、高质量发展》提出，解决拖欠民营企业账款问题，要从政府、从国有企业特别是中央企业带头做起，落实清欠责任，加快清欠进度。","explanation":"⑤把带头主体改成了地方支柱企业，与文章明确列出的政府和国有企业不符。文章在国有企业中尤其强调中央企业。","references":[],"evidence":"从政府、从国有企业特别是中央企业带头做起","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ee8d3b24189131b4":{"review":{"definition":"中国推进高水平对外开放，要扩大市场准入、缩减外资准入负面清单，并提升现代服务业开放水平。","explanation":"缩减外资准入负面清单可以减少外资在准入环节受到禁止或限制的情形，提升现代服务业开放水平则明确了扩大开放的领域。第13题①同时列出这两项要求，符合2023年金砖国家工商论坛闭幕式上的相关表述，因此应选。","references":[],"evidence":"中国将坚定推进高水平开放，扩大市场准入","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-016883d61217faea":{"review":{"definition":"党的十九大报告提出，以“一带一路”建设为对外开放的重点，坚持引进来和走出去并重，遵循共商共建共享原则，加强创新能力开放合作。","explanation":"引进来和走出去并重强调双向开放，共商共建共享说明合作各方共同商议、共同建设、共享成果。第13题②把开放方向、合作原则和创新能力开放合作列在同一项，符合报告表述，因此应选。","references":[],"evidence":"要以“一带一路”建设为重点，坚持引进来和走出去并重","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"10bee87fb2da039b","label":"“一带一路”","topic":"产业、科技与对外开放","category":"非时政","text":"1.“一带一路”\n“一带一路”是“丝绸之路经济带”和“21 世纪海上丝绸之路”的简称。中国支持高\n质量共建“一带一路”的八项行动：\n①构建“一带一路”立体互联互通网络。②支持建设开放型世界经济。③开展务实合作。\n④促进绿色发展。⑤推动科技创新。⑥支持民间交往。⑦建设廉洁之路。⑧完善“一带一路”\n国际合作机制。","source":{"doc":"6cbfb01fe723bba64b75","first":32,"last":32,"page":32,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-489d2240ea12e4b2":{"review":{"title":"以世贸组织为核心的多边贸易体制","type":"制度与规则","definition":"以世贸组织为核心的多边贸易体制，是由世界贸易组织成员共同接受并遵循多边贸易规则所形成的制度安排。","explanation":"世贸组织为成员协商和实施共同贸易规则提供制度框架。习近平总书记在2025年3月28日会见国际工商界代表时指出，这一体制是国际贸易的基石，应共同维护。","basis":"据关联原题和解析编释。","references":[],"domain":"经济","examFocus":{"政治理论必刷100题#13":"同时核对国际贸易体制的组织依托和体制性质，分清两个层面的表述。","政治理论必刷100题#90":"核对国际贸易体制的作用、组织依托和体制性质是否与开放论述相符。"}},"aspects":[{"title":"核心组织与多边性质","uses":[{"unit":"Q1","role":"直接考查","use":"《政治理论必刷100题》第13题要求选出关于高水平对外开放的正确组合。第③项同时写错核心组织和体制性质，原论述指世界贸易组织和多边贸易体制。正确组合为①②④，选A。","evidence":"③我们要共同维护多边贸易体制，以联合国为核心的单边贸易体制是国际贸易的基石","qids":["政治理论必刷100题#13"]},{"unit":"Q2","role":"直接考查","use":"《政治理论必刷100题》第90题要求选出表述有误的一项。C项保留了“多边贸易体制是国际贸易的基石”，却把核心组织写成“联合国经济发展委员会”。原论述所指的核心组织是世界贸易组织，因此选C。","evidence":"以联合国经济发展委员会为核心的多边贸易体制是国际贸易的基石","qids":["政治理论必刷100题#90"]}]}]},"k-9a00bd0185c0ac82":{"review":{"title":"自由贸易试验区提升战略","type":"制度与规则","definition":"自由贸易试验区提升战略是党的二十大报告提出的开放部署，要求在现有自由贸易试验区基础上扩大开放、深化制度创新，建设更高水平的自由贸易试验区。","explanation":"2023年关于深入推进自由贸易试验区建设的重要指示提出，坚持党的全面领导，以高水平开放为引领、以制度创新为核心，统筹发展和安全，高标准对接国际经贸规则，深入推进制度型开放，发挥自贸试验区的示范作用。","basis":"据关联原题及所列出处编释。","references":[{"source":"open","location":"自贸试验区建设十周年指示"}],"related":["k-250dc0a204f29da1","k-0b56b67d9fed06b6","k-f65c4b65787428bd"],"domain":"经济","examFocus":{"政治理论必刷100题#13":"核对自由贸易试验区建设中引领方向、创新重点和经贸规则对接的要求，分清各项表述的作用。","国考 2024 行政执法 行测#7":"核对党的二十大报告的贸易投资开放部署，区分外资准入、区域开放布局和自贸区建设各项措施所针对的对象。"}},"aspects":[{"title":"自贸试验区建设的引领与核心","uses":[{"unit":"Q1","role":"解题依据","use":"本题的⑤对应2023年关于深入推进自由贸易试验区建设的重要指示。⑤保留了高水平开放引领和高标准对接国际经贸规则的要求，但将核心写成“技术创新”，因此该项错误。","evidence":"坚持以高水平开放为引领、以制度创新为核心","qids":["政治理论必刷100题#13"]}]},{"title":"党的二十大报告的开放部署","uses":[{"unit":"Q2","role":"直接考查","use":"本题的④对应党的二十大报告并列提出的两项部署，即实施自由贸易试验区提升战略、扩大面向全球的高标准自由贸易区网络。④与货物贸易、服务贸易和数字贸易措施所在的①均正确，选C。","evidence":"实施自由贸易试验区提升战略，扩大面向全球的高标准自由贸易区网络","qids":["国考 2024 行政执法 行测#7"]}]}],"sources":[{"id":"8e5b8d0370bf2daa","label":"自由贸易试验区提升战略","topic":"年度政府工作","category":"时政","text":"4.自由贸易试验区提升战略\n实施自由贸易试验区提升战略是推进高水平对外开放、推动高质量发展的重要举措。要\n坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三\n中全会精神，完整准确全面贯彻新发展理念，构建新发展格局，坚持党的全面领导，坚持以\n高水平开放为引领、以制度创新为核心，坚持统筹发展和安全，主动对接国际高标准经贸\n规则，稳步扩大规则、规制、管理、标准等制度型开放，加强改革整体谋划和系统集成，推\n动全产业链创新发展，将自由贸易试验区建设成为畅通国内国际双循环的重要枢纽、推动\n高质量发展的强劲引擎，在进一步全面深化改革、推进中国式现代化进程中更好发挥示范作\n用。\n经过 5 年左右的首创性、集成式探索，实现自由贸易试验区制度型开放水平、系统性改\n革成效、开放型经济质量全面提升，以贸易、投资、资金流动、交通运输、人员往来自由便\n利和数据安全有序流动为重点的政策体系更加完善，科技创新和产业创新深度融合，现代产\n业集群能级跃升，新质生产力加快发展，打造开放层次更高、营商环境更优、辐射作用更\n强的改革开放新高地。\n——《关于实施自由贸易试验区提升战略的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":8,"last":8,"page":8,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-1d1a7fe7dc6b2aa7":{"review":{"definition":"企业主导的产学研用协同创新体系，由企业发挥主导作用，联动产业、教育、科研和应用环节，推动科技成果落地。","explanation":"在第14题所引的人工智能部署中，企业主导的协同创新把技术研发与产业需求和应用场景连起来，从而助力传统产业改造升级。A项的主体和目标都符合该部署，因此在选非题中排除。","references":[],"evidence":"构建企业主导的产学研用协同创新体系，助力传统产业改造升级","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-82e38cce5dffdb53":{"review":{"definition":"我国推进人工智能发展，要全面推进科技创新、产业发展和赋能应用，同时完善人工智能监管体制机制。","explanation":"第14题所引讲话指出，人工智能在基础理论和关键核心技术等方面仍有短板，部署同时涵盖技术攻关、产业发展、应用和监管。C项完整保留了发展任务与治理要求，因此在选非题中排除。","references":[],"evidence":"全面推进人工智能科技创新、产业发展和赋能应用，完善人工智能监管体制机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0cb47e4f2df8e2ec":{"review":{"definition":"推进乡村全面振兴，要强化农村基层党组织建设，充分发挥基层党组织的战斗堡垒作用，为乡村振兴提供组织保障。","explanation":"习近平总书记在海南考察时围绕乡村全面振兴，既提出建设过硬的干部队伍、吸引各类人才，也要求强化农村基层党组织建设。第15题②保留了组织建设及其战斗堡垒作用两项相连的要求，因此应选。","references":[],"evidence":"要强化农村基层党组织建设，充分发挥基层党组织战斗堡垒作用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-334f362cbe22e29b":{"review":{"definition":"党的二十大报告提出，逐步把永久基本农田全部建成高标准农田。这是夯实粮食安全根基的一项要求。","explanation":"“全部”规定建设目标的覆盖范围，“逐步”规定推进节奏。第15题③保留了全部建成的目标，却把“逐步”改成“一步到位”，改变了报告规定的实施节奏，因此排除。","references":[],"evidence":"逐步把永久基本农田全部建成高标准农田","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8b44047717058f13":{"review":{"definition":"《乡村全面振兴规划（2024—2027年）》在推进城乡融合发展的部署中，提出构建以县城为枢纽、以小城镇为节点的县域经济体系。","explanation":"规划把县城定位为县域经济体系的枢纽，把小城镇定位为体系中的节点，并提出发挥产业园区带动作用，引导县域产业集聚发展。第15题④把县城与小城镇的角色对调，因此排除。","references":[],"evidence":"构建以县城为枢纽、以小城镇为节点的县域经济体系。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-89c1d03096d04b0b":{"review":{"title":"全国统一大市场建设中的竞争治理","type":"制度与规则","definition":"全国统一大市场建设中的竞争治理，旨在维护公平有序的市场竞争。2025年《政府工作报告》提出综合整治“内卷式”竞争，2025年7月1日中央财经委员会第六次会议提出依法依规治理企业低价无序竞争。","explanation":"《政府工作报告》把综合整治“内卷式”竞争与破除地方保护和市场分割、打通市场准入退出和要素配置堵点一并部署。中央财经委员会第六次会议把治理企业低价无序竞争与引导企业提升产品品质、推动落后产能有序退出一并部署，其中“无序”限定了低价竞争治理的对象。","basis":"据关联原题及所列出处编释。","references":[{"source":"market2","location":"治理企业低价无序竞争"}],"related":["k-0a6da28c772630a4"],"domain":"经济","examFocus":{"政治理论必刷100题#16":"对照全国统一大市场建设部署，核对企业竞争与落后产能治理、政府采购以及地方招商的要求。","政治理论必刷100题#36":"按2025年《政府工作报告》逐项核对重点领域改革举措，分清统一大市场建设要疏通的环节和要治理的竞争行为。"}},"aspects":[{"title":"低价无序竞争与落后产能退出","uses":[{"unit":"Q1","role":"直接考查","use":"题目要求选出不正确的表述。A项将会议要求的提升产品品质和推动落后产能有序退出，改为技术改造落后产能、避免淘汰，因此选A。","evidence":"引导企业提升产品品质，推动落后产能有序退出","qids":["政治理论必刷100题#16"]}]},{"title":"市场准入退出与“内卷式”竞争整治","uses":[{"unit":"Q2","role":"直接考查","use":"题目判断2025年重点领域改革举措。③同时列出打通市场准入退出堵点和综合整治“内卷式”竞争，符合当年《政府工作报告》的部署，列入正确组合D。","evidence":"打通市场准入退出等方面制约经济循环的卡点堵点，综合整治“内卷式”竞争","qids":["政治理论必刷100题#36"]}]}],"sources":[{"id":"a8fb7fb9427e00cc","label":"推进全国统一大市场建设","topic":"发展与治理","category":"非时政","text":"2.推进全国统一大市场建设\n《中共中央 国务院关于加快建设全国统一大市场的意见》于 2022 年 4 月 10 日发布。\n《意见》指出，建设全国统一大市场是构建新发展格局的基础支撑和内在要求。《意见》指\n出，加快建设全国统一大市场的工作原则是：立足内需，畅通循环；立破并举，完善制度；\n有效市场，有为政府；系统协同，稳妥推进；主要目标是：持续推动国内市场高效畅通和\n规模拓展，加快营造稳定公平透明可预期的营商环境，进一步降低市场交易成本，促进科\n技创新和产业升级，培育参与国际竞争合作新优势。","source":{"doc":"6cbfb01fe723bba64b75","first":28,"last":28,"page":28,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-0b56b67d9fed06b6":{"review":{"title":"自贸试验区建设中的制度创新","type":"制度与规则","definition":"习近平总书记2023年关于深入推进自由贸易试验区建设的重要指示明确，自贸试验区建设要坚持党的全面领导，坚持以高水平开放为引领、以制度创新为核心。","explanation":"高水平开放指明建设方向，制度创新是自贸试验区开展改革试验的着力点。相关部署要求高标准对接国际经贸规则、深入推进制度型开放，使自贸试验区更好发挥示范作用。","basis":"据关联原题及所列出处编释。","references":[{"source":"open","location":"高水平开放与制度创新"}],"related":["k-9a00bd0185c0ac82","k-f65c4b65787428bd"],"domain":"经济","examFocus":{"政治理论必刷100题#17":"对照自贸试验区建设部署，辨清开放层次与创新类型分别对应什么政策定位。","政治理论必刷100题#21":"辨清自贸试验区建设的引领方向和核心要求，核对相关表述有没有混用不同政策定位。"}},"aspects":[{"title":"高水平开放为引领、制度创新为核心","uses":[{"unit":"Q1","role":"解题依据","use":"改革开放表述辨析题中，A项保留了高水平开放的引领地位，却将核心写成理论创新，因而排除A项。","evidence":"坚持以高水平开放为引领、以制度创新为核心","qids":["政治理论必刷100题#17"]},{"unit":"Q2","role":"直接考查","use":"高水平对外开放组合判断题中，①准确表述了自贸试验区建设的引领方向和核心要求，与关于改革开放相互促进的②组成正确选项B。","evidence":"建设自由贸易试验区，要坚持以高水平开放为引领、以制度创新为核心","qids":["政治理论必刷100题#21"]}]}]},"k-ce4897cd351e7073":{"review":{"title":"新型举国体制","type":"制度与规则","definition":"新型举国体制是在国家统筹下，发挥市场机制作用，组织各方力量完成国家重大任务的制度安排。科技领域的重要应用是组织关键核心技术攻关。","explanation":"科技攻关涉及企业、高校、科研机构等主体。2024年《中共中央关于进一步全面深化改革、推进中国式现代化的决定》在深化科技体制改革部署中提出，优化重大科技创新组织机制，统筹强化关键核心技术攻关，强化企业科技创新主体地位。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"深化科技体制改革"}],"examFocus":{"政治理论必刷100题#19":"对照科技强国建设部署，核对科技的战略作用、举国体制、国际科技合作与青年人才培养的表述。","政治理论必刷100题#26":"把技术攻关放在做强国内大循环的部署中，同企业帮扶、就业和供需调整等要求一并核对。"}},"aspects":[{"title":"科技强国建设与科技自立自强","uses":[{"unit":"Q1","role":"直接考查","use":"题目要求选出建成科技强国相关表述中的错误项。2025年《求是》刊载的《朝着建成科技强国的宏伟目标奋勇前进》提出发挥新型举国体制优势，C项写成发挥传统举国体制优势，因此选C。","evidence":"充分发挥新型举国体制优势","qids":["政治理论必刷100题#19"]}]},{"title":"关键核心技术与前沿技术攻关","uses":[{"unit":"Q2","role":"直接考查","use":"在做强国内大循环的语境中，D项把健全新型举国体制与强化技术攻关、完善战略性产业发展政策和治理体系相联系，符合题据所引的2025年文章，因而排除D项。题目要求选错，答案为A。","evidence":"健全新型举国体制，强化关键核心技术和前沿技术攻关","qids":["政治理论必刷100题#26"]}]}],"sources":[{"id":"af1bf95a1262a21a","label":"新型举国体制","topic":"产业、科技与对外开放","category":"非时政","text":"2.新型举国体制\n新型举国体制是以国家发展和国家安全为目标，通过统筹资源配置与跨领域协同攻关，\n集中力量突破关键核心技术的国家战略组织模式。","source":{"doc":"6cbfb01fe723bba64b75","first":27,"last":27,"page":27,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-29516fdd1fe89293":{"review":{"definition":"2025年国务院办公厅关于做好金融“五篇大文章”的指导意见提出，要发挥多层次资本市场支持科技创新的关键枢纽作用，着力投早、投小、投长期、投硬科技。","explanation":"投早、投小分别指向企业所处的早期发展阶段和企业规模。第20题C项把这两项改为“投广、投大”，保留了“投长期、投硬科技”，因此是题目要求选出的不恰当举措。","references":[],"evidence":"着力投早、投小、投长期、投硬科技","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b415207c512d47c6":{"review":{"definition":"2025年国务院办公厅关于做好金融“五篇大文章”的指导意见要求，统筹运用股权、债权、保险等手段，为科技型企业提供全链条、全生命周期金融服务。","explanation":"全链条强调覆盖科技创新的各个环节，全生命周期强调覆盖企业发展的不同阶段。第20题B项同时列明了股权、债权、保险三类手段和这两方面的服务范围，符合科技金融部署。","references":[],"evidence":"统筹运用股权、债权、保险等手段","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-63a8452feac25c79":{"review":{"definition":"2025年国务院办公厅关于做好金融“五篇大文章”的指导意见要求，坚持“先立后破”，完善绿色金融体系，统筹支持绿色发展和低碳转型。","explanation":"“先立后破”强调先建立能够承接转型需求的支持体系，再逐步调整原有安排。第20题A项同时保留了这一转型次序和“绿色发展”“低碳转型”两方面的支持要求，符合指导意见。","references":[],"evidence":"坚持“先立后破”，完善绿色金融体系，统筹对绿色发展和低碳转型的支持","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-06e2f20717ba1846":{"review":{"definition":"2025年国务院办公厅关于做好金融“五篇大文章”的指导意见要求，加大对残疾人、退役军人、新市民、高校家庭经济困难学生等群体就业就学的金融支持力度。","explanation":"这项部署着眼于相关群体在就业和就学中的金融需求，列举的对象既包括新市民、退役军人等，也包括高校家庭经济困难学生。第20题D项所列群体和支持事项均符合普惠金融部署。","references":[],"evidence":"高校家庭经济困难学生等群体就业就学的金融支持力度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b498e5e8efb08688":{"review":{"definition":"2024年中央经济工作会议将推动义务教育优质均衡发展、扎实推进优质本科扩容，列为2025年保障和改善民生的教育举措。","explanation":"义务教育阶段强调提高教育质量并促进均衡发展，本科阶段强调增加优质教育供给。第22题②准确对应了这两个教育阶段及各自的政策着力点，应计入正确项。","references":[],"evidence":"推动义务教育优质均衡发展，扎实推进优质本科扩容","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a8a2fb78a556548e":{"review":{"title":"医疗卫生强基工程","type":"制度与规则","definition":"医疗卫生强基工程是通过推动优质医疗资源下沉、加强基层薄弱专业建设，提升县级医院和城乡基层医疗卫生机构服务能力的工程。","explanation":"2024年12月中央经济工作会议将实施该工程纳入2025年保障和改善民生任务。2025年6月，中共中央办公厅、国务院办公厅印发的《关于进一步保障和改善民生 着力解决群众急难愁盼的意见》明确了三项下沉要求。城市医疗资源向县级医院和城乡基层下沉，逐步实现紧密型县域医共体建设全覆盖。高水平医院的人员、服务、技术、管理等向基层医疗卫生机构下沉，并推进城市医联体建设。高水平医学人才向县级医院下沉，重点强化基层医疗卫生机构的薄弱专业。","basis":"据关联原题和解析编释。","references":[],"related":["k-abbc38c6242df627"],"domain":"公共管理","examFocus":{"政治理论必刷100题#22":"对照2024年中央经济工作会议的任务划分，判断题中就业、教育、医疗生育、绿色产业和外贸举措各归哪项任务。","政治理论必刷100题#67":"对照题引《意见》，逐项核对医疗卫生强基工程中下沉的对象、承接机构和配套措施。"}},"aspects":[{"title":"列入2025年民生重点任务","uses":[{"unit":"Q1","role":"直接考查","use":"《政治理论必刷100题》第22题的第③项并列列出实施该工程和制定促进生育政策，两项举措均属会议部署的保障和改善民生任务。全题正确的是①②③，共3项，选B。","evidence":"实施医疗卫生强基工程，制定促进生育政策","qids":["政治理论必刷100题#22"]}]},{"title":"三项下沉的对象与去向","uses":[{"unit":"Q2","role":"直接考查","use":"《政治理论必刷100题》第67题要求选出不属于2025年6月《意见》所列三项下沉的内容。A、C、D分别对应城市医疗资源、高水平医学人才、高水平医院的人员及服务等下沉。B所述远程医疗服务网络及诊断模式未列入这三项，故选B。","evidence":"推动远程医疗服务网络下沉，推广“分布式检查、集中式诊断”医疗服务模式","qids":["政治理论必刷100题#67"]}]}],"sources":[{"id":"6a7f675fdb5d48b7","label":"医疗卫生强基工程","topic":"年度政府工作","category":"时政","text":"1.医疗卫生强基工程\n以习近平新时代中国特色社会主义思想为指导，全面贯彻党的二十大和二十届二中、三\n中全会精神，深入学习贯彻习近平总书记关于健康中国建设的重要论述精神，落实新时代党\n的卫生与健康工作方针，坚持以基层为重点，着力强基层、固基础、保基本，织牢基层网底，\n改善基础服务条件，优化保障基本服务，加快推动从以治病为中心向以人民健康为中心转\n变，不断增强人民群众健康获得感、幸福感、安全感。\n到 2027 年，基层医疗卫生机构布局更加合理，设施条件进一步改善，基本公共卫生服\n务能力和基本医疗服务能力持续提升，力争居民 15 分钟可达最近的医疗服务点。到 2030\n年，基层医疗卫生服务体系进一步健全，人才队伍持续发展壮大，设施设备条件和数智化水\n平显著改善，基本公共卫生服务均等化和基本医疗服务均质化水平明显提升，县级及以下医\n疗卫生机构服务量占比持续提高，中西医协调发展迈向更高水平，分级诊疗体系建设取得显\n著成效，群众就近就便享有优质高效的健康服务。\n——《医疗卫生强基工程实施方案》","source":{"doc":"6cbfb01fe723bba64b75","first":10,"last":10,"page":10,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-5a20fdd9355d7fe3":{"review":{"definition":"2024年中央经济工作会议将营造绿色低碳产业健康发展生态、培育绿色建筑等新增长点，列入2025年经济社会发展全面绿色转型任务。","explanation":"会议把这项举措放在“协同推进降碳减污扩绿增长，加紧经济社会发展全面绿色转型”任务下。第22题问的是会议所列保障和改善民生任务的具体举措，因此④不计入正确项。","references":[],"evidence":"协同推进降碳减污扩绿增长，加紧经济社会发展全面绿色转型","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9d12deeca9714e70":{"review":{"definition":"2024年中央经济工作会议将积极发展服务贸易、绿色贸易、数字贸易，列入2025年扩大高水平对外开放、稳外贸稳外资任务。","explanation":"会议把发展这三类贸易与扩大自主开放和单边开放、扩大制度型开放等举措列在同一项任务下。第22题限定的是保障和改善民生任务，因此⑤不计入正确项。","references":[],"evidence":"扩大高水平对外开放，稳外贸、稳外资","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-44a98cfad08a2caf":{"review":{"definition":"2025年中央城市工作会议将分类推进以县城为重要载体的城镇化建设、继续推进农业转移人口市民化列为优化现代化城市体系的举措。","explanation":"这两项举措共同服务于提高城市对人口和经济社会发展的综合承载能力，促进大中小城市和小城镇协调发展。D项同时保留了县城建设的“分类推进”和农业转移人口市民化的“继续推进”，符合会议部署。","references":[],"evidence":"分类推进以县城为重要载体的城镇化建设，继续推进农业转移人口市民化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-636882250cd85d31":{"review":{"definition":"2025年中央城市工作会议要求转变城市发展理念，更加注重以人为本。","explanation":"会议把以人为本与发展理念相对应，把集约高效与发展方式相对应。A项将发展理念的要求改成“更加注重以经济发展为本”，因此错误。","references":[],"evidence":"更加注重以人为本","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4858add14304446a":{"review":{"definition":"2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会提出，坚持全面推进传统产业转型升级、积极发展新兴产业、超前布局未来产业并举，加快建设现代化产业体系。","explanation":"三项部署以科技创新为引领、以实体经济为根基，涵盖现有产业升级和新产业培育。A项保留了后两项，却把传统产业的“全面推进转型升级”改为“逐步淘汰”。题目要求选出不恰当的举措，因此选A。","references":[],"evidence":"坚持全面推进传统产业转型升级","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c10e89a5ead1add5":{"review":{"definition":"2025年4月30日，习近平在部分省区市“十五五”时期经济社会发展座谈会上指出，谋划“十五五”时期经济社会发展，要把造福人民作为根本价值取向，在发展中保障和改善民生，稳步推动共同富裕。","explanation":"讲话以中国式现代化是全体人民共同富裕的社会主义现代化为依据，把保障和改善民生、稳步推动共同富裕作为这一价值取向的具体要求。B项表述恰当，本题要求选出不恰当的举措。","references":[],"evidence":"把造福人民作为根本价值取向","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-916614127a8e1826":{"review":{"definition":"2025年4月30日，习近平在部分省区市“十五五”时期经济社会发展座谈会上提出，要多措并举稳就业、稳企业、稳市场、稳预期，有效稳住经济基本盘。","explanation":"讲话将这四项工作放在应对国际形势变化的语境中，与办好自己的事、扩大高水平对外开放一并部署。C项准确列出四项工作，符合座谈会要求，本题要求选出不恰当的举措。","references":[],"evidence":"多措并举稳就业、稳企业、稳市场、稳预期","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-535061fccc514e91":{"review":{"definition":"2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会提出，各地区谋划“十五五”时期经济社会发展，要深入调查研究，坚持目标导向和问题导向相统一。","explanation":"各地要在全国大局中精准定位、加强规划衔接，同时通过调研摸清制约本地发展的现实问题，据此确定发展思路和举措，体现自身特色、发挥比较优势。D项符合座谈会要求，本题要求选出不恰当的举措。","references":[],"evidence":"要深入调查研究，坚持目标导向和问题导向相统一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1abeb450374ef8bd":{"review":{"definition":"习近平总书记在二十届中央政治局第十四次集体学习时提出，要坚定不移贯彻新发展理念，更加自觉地把高质量充分就业作为经济社会发展的优先目标。","explanation":"这项部署要求提高发展的就业带动力，使高质量发展的过程成为就业提质扩容的过程。第25题②把这一讲话中的优先目标换成了“经济高速增长”，因此错误。","references":[],"evidence":"使高质量发展的过程成为就业提质扩容的过程","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-94be4678f0fc6ea8":{"review":{"definition":"习近平总书记在参加十四届全国人大三次会议江苏代表团审议时提出，要完整准确全面贯彻新发展理念，统筹国内国际，抓好城乡融合、区域联动，优化生产力布局。","explanation":"讲话从国内国际统筹、城乡融合和区域联动三个方面部署相关工作，并把优化生产力布局纳入推动高质量发展的要求。第25题③保留了这组要求，表述正确。","references":[],"evidence":"统筹国内国际，抓好城乡融合、区域联动，优化生产力布局","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-94bd0deb6b482627":{"review":{"definition":"习近平总书记在纪念陈云同志诞辰120周年座谈会上提出，要加强党对经济工作的领导，深化对社会主义经济建设规律的认识，完整准确全面贯彻新发展理念。","explanation":"这段讲话把党的领导、对经济建设规律的认识和贯彻新发展理念一并列为经济工作要求，并进一步提出坚持有效市场和有为政府相结合。第25题④准确列出了前三项要求。","references":[],"evidence":"要加强党对经济工作的领导，深化对社会主义经济建设规律的认识，完整准确全","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4795b507e2dd0725":{"review":{"definition":"《深入实施以人为本的新型城镇化战略五年行动计划》将推进农业转移人口市民化确定为新型城镇化的首要任务。","explanation":"行动计划把进城农民工及其随迁家属作为市民化的重点，提出拓宽城镇落户渠道等举措。第27题①将“首要任务”对应为“提高城镇资源环境承载能力”，与行动计划的表述不符。","references":[],"evidence":"把推进农业转移人口市民化作为新型城镇化首要任务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e5d2d791e4c48ef1":{"review":{"definition":"2025年政府工作报告在部署新型城镇化和区域协调发展时，提出加快补齐县城基础设施和公共服务短板，大力发展县域经济。","explanation":"补短板的对象是县城的基础设施和公共服务，经济发展的范围是县域。第27题②准确保留了“县城”与“县域”各自对应的任务，表述正确。","references":[],"evidence":"加快补齐县城基础设施和公共服务短板，大力发展县域经济","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c20354fbf1f418c6":{"review":{"definition":"《深入实施以人为本的新型城镇化战略五年行动计划》要求进一步拓宽城镇落户渠道，推行由常住地登记户口提供基本公共服务制度。","explanation":"这项市民化部署以进城农民工及其随迁家属为重点，兼顾城市间流动人口，并提出缩小户籍人口城镇化率与常住人口城镇化率的差距。第27题③同时写明拓宽落户渠道和由常住地登记户口提供基本公共服务，符合行动计划。","references":[],"evidence":"拓宽城镇落户渠道，推行由常住地登记户口提供基本公共服务制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-62d38cae7836cb1c":{"review":{"definition":"2025年政府工作报告提出，发展现代化都市圈、优化空间格局，提升超大特大城市现代化治理水平，促进大中小城市和小城镇协调发展。","explanation":"报告把都市圈建设和空间格局优化与不同规模城市、小城镇的协调发展纳入同一部署。第27题④列举了其中的发展现代化都市圈、优化空间格局和促进各类城镇协调发展的要求，表述正确。","references":[],"evidence":"发展现代化都市圈、优化空间格局，促进大中小城市和小城镇协调发展","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"cbe2b045c4cc446b","label":"现代化都市圈","topic":"农业与城乡治理","category":"非时政","text":"1.现代化都市圈\n城市群是新型城镇化主体形态，是支撑全国经济增长、促进区域协调发展、参与国际竞\n争合作的重要平台。都市圈是城市群内部以超大特大城市或辐射带动功能强的大城市为中\n心、以 1 小时通勤圈为基本范围的城镇化空间形态。\n坚持以供给侧结构性改革为主线，坚持市场化改革、扩大高水平开放，以促进中心城市\n与周边城市（镇）同城化发展为方向，以创新体制机制为抓手，以推动统一市场建设、基\n础设施一体高效、公共服务共建共享、产业专业化分工协作、生态环境共保共治、城乡融合\n发展为重点，培育发展一批现代化都市圈，形成区域竞争新优势，为城市群高质量发展、经\n济转型升级提供重要支撑。\n到 2022 年，都市圈同城化取得明显进展，基础设施一体化程度大幅提高，阻碍生产要\n素自由流动的行政壁垒和体制机制障碍基本消除，成本分担和利益共享机制更加完善，梯次\n形成若干空间结构清晰、城市功能互补、要素流动有序、产业分工协调、交通往来顺畅、\n公共服务均衡、环境和谐宜居的现代化都市圈。到 2035 年，现代化都市圈格局更加成熟，\n形成若干具有全球影响力的都市圈。\n——《国家发展改革委关于培育发展现代化都市圈的指导意见》","source":{"doc":"6cbfb01fe723bba64b75","first":9,"last":9,"page":9,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-01f5c5547e1ff037":{"review":{"definition":"制造业发展要立足现有产业基础，扎实推进先进制造业高质量发展，加快推动传统制造业升级。","explanation":"习近平总书记2023年在黑龙江考察时提出，要发挥科技创新的增量器作用，推进产业升级和结构优化。第28题①把产业发展的立足点改成了“未来产业”，又把先进制造业的发展要求改成了“高速发展”。题干中的超前布局未来产业是一项发展部署，制造业发展的立足点仍是现有产业基础。","references":[],"evidence":"立足现有产业基础，扎实推进先进制造业高质量发展，加快推动传统制造业升级","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c3d30d65fc9dc5e6":{"review":{"definition":"推动长江经济带高质量发展，要大力推动产业链供应链现代化，接续实施增强制造业核心竞争力行动。","explanation":"习近平总书记2023年在进一步推动长江经济带高质量发展座谈会上的讲话，将产业链供应链现代化与接续实施增强制造业核心竞争力行动一并部署，并提出培育壮大先进制造业。第28题②准确对应前两项要求，其中“接续实施”强调延续推进既有行动。","references":[],"evidence":"大力推动产业链供应链现代化，接续实施增强制造业核心竞争力行动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-26b61ed5615576c8":{"review":{"definition":"2025年中央一号文件提出，在统筹县域城乡规划布局中，顺应人口变化趋势，推动乡村全面振兴与新型城镇化有机结合，促进城乡产业发展、基础设施、公共服务一体化。","explanation":"文件要求发挥县乡国土空间规划的空间统筹和要素保障作用，为城乡产业发展、基础设施、公共服务一体化提供支撑。第30题①写全了这三方面的一体化要求，符合文件表述。","references":[],"evidence":"推动乡村全面振兴与新型城镇化有机结合","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-13c1a3a7e75457c3":{"review":{"definition":"2025年中央一号文件提出，在耕地总量不减少、永久基本农田布局基本稳定的前提下，开展以县域为统筹单元、以乡镇为基本实施单元的全域土地综合整治。","explanation":"文件将统筹和基本实施分别放在县域、乡镇两个层级。第30题②把统筹单元下移到了乡镇，又把基本实施单元下移到了村，两处都与文件表述不符。","references":[],"evidence":"以县域为统筹单元、以乡镇为基本实施单元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5b54d9e218ae52a6":{"review":{"definition":"2025年中央一号文件提出，分类推进城乡供水一体化、集中供水规模化、小型供水规范化建设。","explanation":"第30题③准确保留了三组对应关系，城乡供水对应一体化，集中供水对应规模化，小型供水对应规范化。文件同时规定，有条件的地方可推行农村供水县域统管和专业化管护。","references":[],"evidence":"分类推进城乡供水一体化、集中供水规模化、小型供水规范化建设","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8301efeb35a1694f":{"review":{"definition":"2025年中央一号文件提出，以人员下沉为重点推进紧密型县域医共体建设，提升中心乡镇卫生院服务能力。","explanation":"在提高农村基本公共服务水平的部署中，人员下沉是推进医共体建设的重点，中心乡镇卫生院是文件明确要求提升服务能力的机构。第30题④准确对应了这两项要求。","references":[],"evidence":"以人员下沉为重点推进紧密型县域医共体建设，提升中心乡镇卫生院服务能力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e8774128dc211731":{"review":{"definition":"稳量提质是指保持外贸规模基本稳定，同时提高外贸发展质量。题给人民日报文章将其与深化外贸体制改革相联系。","explanation":"按题给文章的表述，“稳”对应外贸规模，“提”对应外贸质量。②写成“稳质提量”，调换了两个政策着力点，因此应排除。","references":[],"evidence":"深化外贸体制改革，促进外贸稳量提质","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d11d9398a41ef59c":{"review":{"definition":"持续扩大面向全球的高标准自由贸易区网络，是2025年政府工作报告提出的深化多双边和区域经济合作的举措。","explanation":"报告把推动签署中国－东盟自贸区3.0版升级协定，以及推进加入《数字经济伙伴关系协定》和《全面与进步跨太平洋伙伴关系协定》，列为同一段落的具体安排。③保留了“面向全球”和“高标准”两个限定，符合报告表述。","references":[],"evidence":"持续扩大面向全球的高标准自由贸易区网络","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-413643aca282b6b9":{"review":{"definition":"2025年政府工作报告将拓展境外经贸合作区功能和发展中间品贸易列为稳定对外贸易发展的举措。中间品是用于后续生产环节的投入品。","explanation":"报告把拓展境外经贸合作区功能、发展中间品贸易和开拓多元化市场并列部署。④准确摘录了其中前两项，属于题目所问的对外开放举措。","references":[],"evidence":"拓展境外经贸合作区功能，发展中间品贸易，开拓多元化市场","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6905c95fceae446b":{"review":{"definition":"2024年中央经济工作会议在部署2025年现代化产业体系建设时，要求加强基础研究和关键核心技术攻关，超前布局重大科技项目。","explanation":"这一部署同时强调积累基础知识、突破关键技术和提前谋划重大科技项目。A项保留了“加强”和“超前布局”的原文搭配，属于本题选非时应排除的正确表述。","references":[],"evidence":"加强基础研究和关键核心技术攻关，超前布局重大科技项目","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-146b3490c92b8726":{"review":{"definition":"2024年中央经济工作会议将健全多层次金融服务体系、壮大耐心资本纳入2025年现代化产业体系建设任务。耐心资本着眼长期回报，能够承受较长的投资周期。","explanation":"会议在这两项安排之后提出吸引更多社会资本参与创业投资、梯度培育创新型企业，具体说明了金融支持的方向。B项准确摘录了前两项安排，在选非题中应排除。","references":[],"evidence":"健全多层次金融服务体系，壮大耐心资本","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9fe805a639ce6c15":{"review":{"definition":"2024年中央经济工作会议在部署现代化产业体系建设时，提出综合整治“内卷式”竞争，并要求规范地方政府和企业行为。","explanation":"会议点明了地方政府和企业两类行为主体。C项用“市场主体”概括规范对象，遗漏了会议明确列出的地方政府，因此是本题要求选出的不正确表述。","references":[],"evidence":"规范地方政府和企业行为","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"9a577840592b8b76","label":"“内卷式”竞争","topic":"发展与治理","category":"非时政","text":"3.“内卷式”竞争\n“内卷式”竞争本质是市场失灵下的资源错配，当所有经营主体的收益改进空间消失，\n经营主体便陷入了低水平均衡困境，只能在有限市场中进行同质化竞争，最终使得社会资源\n配置的整体效率降低。\n——求是网","source":{"doc":"6cbfb01fe723bba64b75","first":8,"last":8,"page":8,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-c7e82c81295ae032":{"review":{"definition":"2024年中央经济工作会议提出，积极运用数字技术、绿色技术改造提升传统产业。这是会议部署的2025年现代化产业体系建设举措之一。","explanation":"这项任务的改造对象是现有传统产业，采用的手段是数字技术和绿色技术。D项保留了这组手段与对象的对应关系，符合会议表述，在选非题中应排除。","references":[],"evidence":"积极运用数字技术、绿色技术改造提升传统产业","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"1c1d38d153317062","label":"传统产业","topic":"产业、科技与对外开放","category":"非时政","text":"1.传统产业\n传统产业是基本盘、老家底，是现代化产业体系的基底。从各地实践来看，不少传统制\n造业经过技术改造，就转变成了新兴产业，如新材料、新能源汽车正展现出前所未有的发展\n前景。","source":{"doc":"6cbfb01fe723bba64b75","first":26,"last":26,"page":26,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-68ab013ecdd81487":{"review":{"definition":"《提振消费专项行动方案》将依法保障劳动者休息休假权益纳入消费环境改善提升行动。用人单位不得违法延长劳动者工作时间。","explanation":"方案在该行动中同时提出鼓励带薪年休假与小长假连休，休息休假安排关系到劳动者能否获得可用于消费的闲暇时间，因此A项符合题意。冰雪旅游、消费品以旧换新和发展庭院经济等措施分别归入服务消费提质惠民行动、大宗消费更新升级行动和城乡居民增收促进行动。","references":[],"evidence":"依法保障劳动者休息休假权益，不得违法延长劳动者工作时间","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-01c56f94ffc9caf9":{"review":{"definition":"《乡村全面振兴规划（2024—2027年）》提出，到2027年，乡村全面振兴取得实质性进展，农业农村现代化迈上新台阶。到2035年，乡村全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件。","explanation":"B项把“实质性进展”对应到2027年，把“决定性进展”和“农业现代化基本实现”对应到2035年，与解析所引的规划目标一致，因此选非时排除B项。","references":[],"evidence":"全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-46b4352a61bc814b":{"review":{"definition":"2024年中央一号文件在促进县域城乡融合发展的部署中，鼓励有条件的县（市、区）将城镇常住人口全部纳入住房保障政策范围。","explanation":"“有条件的”限定受鼓励的县（市、区），“全部”限定当地纳入保障的城镇常住人口。C项删掉前一限定，扩大了适用范围，因此是本题要求选出的不正确表述。","references":[],"evidence":"鼓励有条件的县（市、区）将城镇常住人口全部纳入住房保障","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a0bc27ccf9dfd2b3":{"review":{"definition":"《乡村全面振兴规划（2024—2027年）》要求统筹不同区域，合理确定阶段性重点任务和推进时序，尊重客观规律，不超越发展阶段，不提脱离实际的目标。","explanation":"任务的轻重缓急和实施顺序要与各地实际发展阶段相匹配。D项同时保留了统筹不同区域、安排阶段性任务和时序、遵循实际发展阶段三层要求，符合规划表述，选非时应排除。","references":[],"evidence":"合理确定阶段性重点任务和推进时序，尊重客观规律，不超越发展阶段","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1dd18f359c18aba2":{"review":{"definition":"2025年政府工作报告部署实施国有经济布局优化和结构调整指引，并加快建立国有企业履行战略使命评价制度。","explanation":"前一项要求实施布局优化和结构调整指引，后一项要求加快建立评价国有企业履行战略使命情况的制度。①准确保留了两个政策动作，属于正确组合D。","references":[],"evidence":"实施国有经济布局优化和结构调整指引，加快建立国有企业履行战略使命评价制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e83c65f4421ead1f":{"review":{"definition":"2025年政府工作报告要求政府寓管理于服务之中，在为企业提供服务的过程中履行管理职责，以服务增强企业信心。","explanation":"“寓管理于服务之中”把服务作为落实管理的方式。②写成“寓服务于管理之中”，将两者的位置互换，因此不能选入正确组合。","references":[],"evidence":"政府要寓管理于服务之中，用服务的暖心增强企业的信心。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7f5afdaca5cfe92a":{"review":{"definition":"2025年政府工作报告将深化资本市场投融资综合改革、大力推动中长期资金入市列为深化财税金融体制改革的举措。","explanation":"④同时保留了改革覆盖投资和融资两端、推动入市的资金为中长期资金这两个要点，符合报告表述，与①③组成正确选项D。","references":[],"evidence":"深化资本市场投融资综合改革，大力推动中长期资金入市","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7710ae6ce7fdca2f":{"review":{"title":"耕地保护红线","type":"制度与规则","definition":"耕地保护红线是国家为保障粮食安全而设定的耕地保有面积底线。《加快建设农业强国规划（2024—2035年）》要求守牢18.65亿亩耕地和15.46亿亩永久基本农田保护红线。","explanation":"永久基本农田属于耕地，两项面积是各自适用范围内的保护底线。党的二十大报告提出“牢牢守住十八亿亩耕地红线”，农业强国规划在全面加强耕地保护和建设的部署中列出了两项具体面积要求。","basis":"据关联原题及所列出处编释。","references":[{"source":"farm","location":"严守耕地红线"}],"related":["k-7f4a4aba9435a8e5","k-caedc47bc4c7745b"],"domain":"生态环境","examFocus":{"政治理论必刷100题#37":"对照农业强国建设规划的任务划分，核对耕地和永久基本农田保护、农产品外贸及加工举措分别归在哪一项任务下。","江苏 2024 C类 申论#3":"从给定资料6找出耕地保护和防止耕地“非粮化”的政策依据，结合F村基本农田种藕的情况，向村民说明为何要退藕还稻。"}},"aspects":[{"title":"农业强国规划的两项面积要求","uses":[{"unit":"Q1","role":"直接考查","use":"本题的③列出耕地和永久基本农田的保护面积要求。该举措列在规划的“全方位夯实粮食安全根基，把中国人的饭碗端得更牢更稳”部分，与①⑤同属题问范围，共3项，选B。","evidence":"守牢 18.65 亿亩耕地和 15.46 亿亩永久基本农田保护红线","qids":["政治理论必刷100题#37"]}]},{"title":"退藕还稻的政策依据","uses":[{"unit":"Q2","role":"解题依据","use":"本题要求以F村村“两委”名义写公开信。材料中孙副镇长援引党的二十大报告的十八亿亩耕地红线要求，并提到县里的防止耕地“非粮化”工作方案，可结合F村基本农田种藕蔓延的情况说明退藕还稻的必要性。","evidence":"牢牢守住十八亿亩耕地红线","qids":["江苏 2024 C类 申论#3"]}]}],"sources":[{"id":"ac62f51740fec606","label":"耕地红线","topic":"农业与城乡治理","category":"非时政","text":"4.耕地红线\n耕地红线是指经常进行耕种的土地面积的最低值，守住耕地红线旨在确保国家粮食安全。\n国务院印发《全国土地利用总体规划纲要（2006—2020 年）》提出，确保 18 亿亩的耕地红\n线。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":34,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-6d2f594a351d9390":{"review":{"definition":"《加快建设农业强国规划（2024—2035年）》要求健全保障耕地用于种植基本农作物的管理体系，并健全粮食主产区利益补偿机制。两项举措均列在“健全粮食生产扶持政策”下。","explanation":"前一项保障耕地用于基本农作物生产，后一项通过利益补偿和产粮大县奖补支持承担粮食生产任务的地区。⑤的两项措施都属于规划中“全方位夯实粮食安全根基”这一部分，与①③合计三项，对应B。","references":[],"evidence":"健全保障耕地用于种植基本农作物管理体系，健全粮食主产区利益补偿机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-160f067f85c0f2b5":{"review":{"definition":"《关于加快推进科技服务业高质量发展的实施意见》提出，培育壮大科技服务业的服务主体，引导科技服务机构向专业化、市场化、平台化方向发展。","explanation":"题中政策把培育壮大服务主体列为优化科技服务业发展生态的措施，并明确提出三个发展方向。A项完整保留了这三个方向，在选非题中应排除。","references":[],"evidence":"引导科技服务机构专业化、市场化、平台化发展。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c02a6cbca919afb1":{"review":{"definition":"《关于加快推进科技服务业高质量发展的实施意见》提出，引导科技服务机构树立质量第一的意识，加强服务质量管理，推动服务质量持续提升。","explanation":"B项对应政策中推动质量持续提升的措施。树立质量第一的意识是对科技服务机构的引导，推广应用先进质量管理方法和加强服务质量管理是落实这一要求的做法。","references":[],"evidence":"引导科技服务机构牢固树立质量第一的意识","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dd3f3dd7424a753c":{"review":{"definition":"《关于加快推进科技服务业高质量发展的实施意见》提出，加强科技服务业标准体系建设，加快研制重点领域标准，并强化标准实施。","explanation":"标准研制补充重点领域的技术和服务依据，标准实施推动这些依据用于服务实践。D项同时写出了体系建设和标准实施，符合题中政策所述的标准支撑措施。","references":[],"evidence":"加强标准体系建设，加快研制一批重点领域标准，强化标准实施","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-04b16df7eec1756e":{"review":{"definition":"原题引文：发挥政府主导作用，引领科技服务机构健康秩序有效的高速发展","explanation":"第38题为选非题，标准答案是C。工信部公开发布稿把发展目标概括为规模增长和质效提升，把部门、地方的工作概括为统筹协调、政策支持、统计监测等。C项的“政府主导”和“高速发展”偏离这两处表述。题解的“市场主导”应以发布稿中的“市场导向”为准。","references":[{"source":"web-19296ba6c3b83ae6","location":"首段，发展原则和目标","quote":"以创新驱动、市场导向、融合发展、系统推进、质量为先为原则"},{"source":"web-19296ba6c3b83ae6","location":"末段，组织实施","quote":"加大政策支持，加强统计监测"}],"evidence":"发挥政府主导作用，引领科技服务机构健康秩序有效的高速发展","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-27aabb6f443eaee2":{"review":{"definition":"《关于完善价格治理机制的意见》规定，公办养老、托育、医疗机构的基本服务收费实行政府指导价管理。","explanation":"这项政策服务于公共服务均衡可及，适用范围由“公办机构”和“基本服务”共同限定。B项把这类收费写成全面放开由市场调节，与《意见》规定的管理方式冲突，因此应在本题选出。","references":[],"evidence":"公办养老、托育、医疗机构基本服务收费，\n\n实行政府指导价管理","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-818ebfad08e1e3b3":{"review":{"definition":"《关于完善价格治理机制的意见》要求规范市场价格行为，防止经营者以低于成本的价格开展恶性竞争。","explanation":"这项监管要求同时涉及价格低于成本和经营者借此开展恶性竞争，单凭售价较低无法判断是否属于这项要求针对的行为。A项保留了这两层限定，符合《意见》，选非时应排除。","references":[],"evidence":"规范市场价格行为，防止经营者以低于成本的价格开展恶性竞争","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5d69918771d1b71e":{"review":{"definition":"在公共数据授权运营中，用于公共治理、公益事业的公共数据产品和服务有条件无偿使用，用于产业发展、行业发展的有条件有偿使用。","explanation":"《关于完善价格治理机制的意见》按使用目的区分收费方式。有偿使用的收费标准按补偿成本、合理盈利的原则确定，并动态调整。D项对应公共治理和公益事业用途，且保留“有条件”这一限定，符合规定，选非时应排除。","references":[],"evidence":"用于公共治理、公益事业的公共数据产品和服务有条件无偿使用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d77fd5ea4356cf82":{"review":{"definition":"深化经济体制改革仍是进一步全面深化改革的重点，主要任务是完善有利于推动高质量发展的体制机制。","explanation":"坚持和落实“两个毫不动摇”、构建全国统一大市场等，都是这一重点下的部署。A项写对了主要任务，却将“经济体制改革”换成了“政治体制改革”。题干要求选不正确的一项，因此选A。","references":[],"evidence":"深化经济体制改革仍是进一步全面深化\n\n改革的重点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3ba756a60062ad2d":{"review":{"definition":"2024年《关于〈中共中央关于进一步全面深化改革、推进中国式现代化的决定〉的说明》将提出制定民营经济促进法列为推动非公有制经济发展的举措。","explanation":"B项的“提出制定”对应当时的立法部署。说明把这项部署与加强产权执法司法保护、加强公平竞争审查刚性约束等举措一并论述，指出这些举措将更好激发全社会内生动力和创新活力，因此B项表述正确。","references":[],"evidence":"着眼推动非公有制经济发展，提出制定民营经济促进法","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-afebf20e30b5ec05":{"review":{"title":"两个毫不动摇","type":"制度与规则","definition":"“两个毫不动摇”是坚持和完善社会主义基本经济制度的要求，指毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展。","explanation":"党的二十大报告将坚持和完善社会主义基本经济制度纳入构建高水平社会主义市场经济体制的部署。2024年党的二十届三中全会《决定》进一步明确，保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受到法律保护，促进各种所有制经济优势互补、共同发展。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"构建高水平社会主义市场经济体制"}],"domain":"经济","examFocus":{"政治理论必刷100题#43":"对照进一步全面深化改革的部署，核对改革重点、民营经济立法和不同所有制经济的平等保障。","江苏 2025 A类 行测#6":"按改革举措所针对的对象，核对其在党的二十届三中全会《决定》中的归属。"}},"aspects":[{"title":"经济体制改革重点与民营经济政策","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题，选A。2024年党的二十届三中全会《决定》的说明将深化经济体制改革列为进一步全面深化改革的重点，A写成了政治体制改革。B所述制定民营经济促进法是当时提出的举措，C、D分别对应2025年2月17日民营企业座谈会讲话中的平等保障和政策延续要求。","evidence":"深化政治体制改革是进一步全面深化改革的重点","qids":["政治理论必刷100题#43"]}]},{"title":"高水平社会主义市场经济体制的举措","uses":[{"unit":"Q2","role":"直接考查","use":"本题同选D。按2024年党的二十届三中全会《决定》的篇章归属，③落实“两个毫不动摇”，与②构建全国统一大市场、④完善产权制度同属构建高水平社会主义市场经济体制的举措。①培育壮大先进制造业集群归入健全推动经济高质量发展体制机制。","evidence":"坚持和落实“两个毫不动摇”，促进各种所有制经济优势互补、共同发展","qids":["江苏 2025 A类 行测#6","江苏 2025 B类 行测#6","江苏 2025 C类 行测#6"]}]}],"sources":[{"id":"39174200a2f5f745","label":"“两个毫不动摇”","topic":"发展与治理","category":"非时政","text":"1.“两个毫不动摇”\n即“毫不动摇巩固和发展公有制经济”“毫不动摇鼓励、支持、引导非公有制经济发\n展”。\n党的十六大提出：“必须毫不动摇地巩固和发展公有制经济”“必须毫不动摇地鼓励、\n支持和引导非公有制经济发展”。党的十八大进一步提出：“毫不动摇鼓励、支持、引导非\n公有制经济发展，保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受\n到法律保护。”\n党的十九大把“两个毫不动摇”写入新时代坚持和发展中国特色社会主义的基本方略，\n作为党和国家一项大政方针进一步确定下来。党的二十大提出：“坚持和完善社会主义基本\n经济制度，毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发\n展”。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-8ad204b416d318ef":{"review":{"definition":"党和国家对民营经济发展的基本方针政策，已经纳入中国特色社会主义制度体系，将一以贯之坚持和落实。","explanation":"2025年2月17日民营企业座谈会上的讲话明确了这些基本方针政策的制度定位和持续性。D项的“不能变，也不会变”指的正是这些基本方针政策，符合讲话表述。","references":[],"evidence":"党和国家对民营经济发展的基本方针政策，已经纳入中国特色社会主义制度体系","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"213cbd4fab59c3ce","label":"民营经济","topic":"产业、科技与对外开放","category":"非时政","text":"2.民营经济\n民营经济是我国经济制度的内在要素。民营经济是社会主义市场经济发展的重要成果，\n是推动社会主义市场经济发展的重要力量，是推进供给侧结构性改革、推动高质量发展、建\n设现代化经济体系的重要主体，也是我们党长期执政、团结带领全国人民实现“两个一百年”\n奋斗目标和中华民族伟大复兴中国梦的重要力量。\n习近平总书记在民营企业座谈会上的讲话中指出，我国民营经济已经成为推动我国发展\n不可或缺的力量，成为创业就业的主要领域、技术创新的重要主体、国家税收的重要来源，\n为我国社会主义市场经济发展、政府职能转变、农村富余劳动力转移、国际市场开拓等发挥\n了重要作用。\n——2018 年 11 月习近平在民营企业座谈会上的讲话","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":30,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-23b9b52adc801c03":{"review":{"definition":"新时代推动中部地区崛起的交通建设部署要求加强现代化交通基础设施体系建设，强化中部地区的大通道格局。","explanation":"2024年新时代推动中部地区崛起座谈会把这项交通部署与加强同其他重大发展战略的衔接、更好融入和支撑新发展格局联系起来。①准确对应了建设手段和所要强化的交通格局，因此计入正确表述。","references":[],"evidence":"要加强现代化交通基础设施体系建设，强化中部地区的大通道格局","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-785becfc5369c929":{"review":{"definition":"《中共中央 国务院关于新时代推动中部地区高质量发展的意见》要求围绕对话交流、重大事项协商、规划衔接，建立健全中部地区省际合作机制。","explanation":"这项要求列在推动省际协作和交界地区协同发展的部署中。②完整列出了合作机制所围绕的三项事项，因此计入正确表述。","references":[],"evidence":"围绕对话交流、重大事项协商、规划衔接，建立健全中部地区省际合作机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-80ed55f1de5c9bb3":{"review":{"definition":"新时代推动中部地区崛起要求统筹推进深层次改革和高水平开放，持续打造更具竞争力的内陆开放高地。","explanation":"2024年新时代推动中部地区崛起座谈会把统筹推进深层次改革和高水平开放作为打造内陆开放高地的要求。③同时保留了两项部署及其目标，因此计入正确表述。","references":[],"evidence":"要统筹推进深层次改革和高水平开放，持续打造更具竞争力的内陆开放高地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f727931b29028092":{"review":{"definition":"2021年《中共中央 国务院关于新时代推动中部地区高质量发展的意见》提出，到2035年，中部地区现代化经济体系基本建成，产业整体迈向中高端。","explanation":"④的地区、建设对象和目标年份均与《意见》相符，但将目标程度由“基本建成”提高到了“全面建成”，因此④错误。只有①②③正确，共3项，对应C。","references":[],"evidence":"到 2035 年，中部地区现\n\n代化经济体系基本建成","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-77afdc0ca18e348a":{"review":{"definition":"消费能力保障支持行动是2025年《提振消费专项行动方案》中的一项行动，包括加大生育养育保障力度、提高医疗养老保障能力等措施。","explanation":"健全基本养老保险待遇合理调整机制属于提高医疗养老保障能力，研究建立育儿补贴制度属于加大生育养育保障力度。两项都列在该行动下，因此本题选③⑤，共2项。","references":[],"evidence":"健全基本养老保险待遇合理调整机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-80e78a1d0d350c3b":{"review":{"definition":"育儿补贴制度是通过向符合条件的家庭提供补贴来加强养育保障的制度安排。2025年《提振消费专项行动方案》提出研究建立这一制度。","explanation":"《方案》将这项任务列在消费能力保障支持行动的“加大生育养育保障力度”之下，因此⑤的政策归属正确。“研究建立”是该方案在此处使用的政策措辞。","references":[],"evidence":"研究建立育儿补贴制度","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"dacac9bacd101e70","label":"育儿补贴制度","topic":"年度政府工作","category":"时政","text":"4.育儿补贴制度\n（一）补贴对象。从 2025 年 1 月 1 日起，对符合法律法规规定生育的 3 周岁以下婴幼\n儿发放补贴，至其年满 3 周岁。\n（二）补贴标准。育儿补贴按年发放，现阶段国家基础标准为每孩每年 3600 元。其中，\n对 2025 年 1 月 1 日之前出生、不满 3 周岁的婴幼儿，按应补贴月数折算计发补贴。对按照\n育儿补贴制度规定发放的育儿补贴免征个人所得税。在最低生活保障对象、特困人员等救助\n对象认定时，育儿补贴不计入家庭或个人收入。\n——《育儿补贴制度实施方案》","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":3,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-466671fd53beeb11":{"review":{"definition":"城乡居民增收促进行动是2025年《提振消费专项行动方案》中的一项行动，包括促进工资性收入合理增长和拓宽财产性收入渠道等措施。","explanation":"①直接对应拓宽财产性收入渠道，②通过健全最低工资标准调整机制、科学合理提高最低工资标准来促进工资性收入合理增长。本题要求识别消费能力保障支持行动，因此①②均排除。","references":[],"evidence":"①拓宽财产性收入渠道","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f0b4ead371af1ddf":{"review":{"definition":"2025年《提振消费专项行动方案》将加大消费品以旧换新支持力度列入大宗消费更新升级行动，并提出用好超长期特别国债资金。","explanation":"④所述措施着眼于促进消费品更新。《方案》在大宗消费更新升级行动下部署该措施，因此本题统计消费能力保障支持行动的措施时排除④。","references":[],"evidence":"④加大消费品以旧换新支持力度","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"249b6ddd9b684c24","label":"实施消费品以旧换新","topic":"年度政府工作","category":"时政","text":"2.实施消费品以旧换新\n“两新”，是指推动新一轮大规模设备更新和消费品以旧换新。2024 年 3 月，国务院\n印发《推动大规模设备更新和消费品以旧换新行动方案》，对实施设备更新、消费品以旧换\n新、回收循环利用、标准提升四大行动等作出具体安排。\n——求是网","source":{"doc":"6cbfb01fe723bba64b75","first":6,"last":6,"page":6,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-4522b855176bbb2d":{"review":{"definition":"2025年《关于完善中国特色现代企业制度的意见》提出，经过5年左右，推动具备条件的企业普遍建立适合国情、符合实际、满足发展需要的中国特色现代企业制度。","explanation":"这里的企业范围以“具备条件”为限定。B项将适用范围写成“所有国有企业”，同时把制度要求简化为“符合国情”。本题要求选出表述有误的一项，因此选B。","references":[],"evidence":"推动具备条件的\n\n企业普遍建立适合国情、符合实际、满足发展需要的中国特色现代企业制度","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"ac232bb3da2166c7","label":"中国特色现代企业制度","topic":"产业、科技与对外开放","category":"非时政","text":"3.中国特色现代企业制度\n党的十九届四中全会提出“深化国有企业改革，完善中国特色现代企业制度”，这是中\n央文件首次提出了“中国特色现代企业制度”的概念。习近平总书记指出“坚持党对国有企\n业的领导是重大政治原则，必须一以贯之；建立现代企业制度是国有企业的方向，也必须一\n以贯之。”现代企业制度定义为以市场经济为基础，以企业法人制度为主体，以公司制度\n为核心，以产权清晰、权责明确、政企分开、管理科学为条件的新型企业制度。“中国特\n色现代国有企业制度，‘特’就特在把党的领导融入公司治理各环节，把企业党组织内嵌到\n公司治理结构之中，明确和落实党组织在公司法人治理结构中的法定地位，做到组织落实、\n干部到位、职责明确、监督严格。”","source":{"doc":"6cbfb01fe723bba64b75","first":30,"last":30,"page":30,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-fe35a3967360cf44":{"review":{"definition":"2025年《关于完善中国特色现代企业制度的意见》提出，以产权清晰、权责明确、政企分开、管理科学为基础，以完善公司治理为重点。","explanation":"A项准确对应《意见》对制度基础和建设重点的表述。D项所说的以制度建设促发展、推动公司治理结构和组织形态创新，也符合《意见》的总体要求。本题为选非题，A、D均排除。","references":[],"evidence":"以产权清晰、权责明确、政企分开、管理科学为基础，以完善公司治理为重点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9fac6a162326dd37":{"review":{"definition":"2025年《关于完善中国特色现代企业制度的意见》提出，健全以职工代表大会为基本形式的企业民主管理制度，坚持和完善职工董事制度。","explanation":"职工代表大会是企业民主管理的基本形式，职工董事制度是职工参与董事会治理的制度安排。C项准确列出《意见》在提升企业科学管理水平方面提出的两项要求，因此在选非题中排除。","references":[],"evidence":"健全以职工代表大会为基本形式的企业民主管理制度，坚持和完善职工董事制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-89eb4fb079f70fa6":{"review":{"title":"基本实现社会主义现代化","type":"制度与规则","definition":"基本实现社会主义现代化是党的二十大报告所述全面建成社会主义现代化强国两步走战略的第一步目标，时间节点为2035年。","explanation":"到2035年的目标涵盖经济、科技、社会、生态等领域。在基本实现社会主义现代化的基础上，第二步是到本世纪中叶把我国建设成为综合国力和国际影响力领先的社会主义现代化强国。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"全面建成社会主义现代化强国的战略安排"}],"examFocus":{"政治理论必刷100题#47":"对照“十五五”经济社会发展座谈会讲话，核对这一时期的阶段目标，区分现代化建设各阶段的目标表述。","国考 2023 地市级 行测#1":"对照党的二十大报告的两步走安排，逐项核对经济、科技、产业和生态目标对应的阶段及实现程度。"}},"aspects":[{"title":"“十五五”规划谋划围绕的阶段目标","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题，选A。2025年4月30日部分省区市“十五五”时期经济社会发展座谈会讲话要求，谋划这一时期的发展要围绕基本实现社会主义现代化，分领域确定目标任务。A将阶段目标写成了“全面实现社会主义现代化”。","evidence":"紧紧围绕基本实现社会主义现代化目标","qids":["政治理论必刷100题#47"]}]},{"title":"二十大报告的2035年发展目标","uses":[{"unit":"Q2","role":"直接考查","use":"本题选A，①人均国内生产总值达到中等发达国家水平、③建成现代化经济体系并基本实现新型工业化等两项正确。②的原文目标是进入创新型国家前列。④涉及的原文目标是碳排放达峰后稳中有降、美丽中国目标基本实现。⑤所述建成社会主义现代化强国对应本世纪中叶。","evidence":"碳排放达峰后稳中有降，生态环境\n根本好转，美丽中国目标基本实现","qids":["国考 2023 地市级 行测#1"]}]}],"sources":[{"id":"053a24013e87f6af","label":"基本实现社会主义现代化","topic":"党政制度与理论","category":"非时政","text":"1.基本实现社会主义现代化\n“基本实现社会主义现代化”是中国到 2035 年要实现的社会主义现代化目标，是全\n面建成社会主义现代化强国的第一阶段战略安排。第一阶段从 2020 年到 2035 年，基本\n实现社会主义现代化；第二阶段从 2035 年到本世纪中叶，建成富强民主文明和谐美丽的\n社会主义现代化强国。","source":{"doc":"41195a191a57c1c36332","first":23,"last":23,"page":23,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-f21d7fa71f536ad2":{"review":{"title":"稳中求进工作总基调","type":"制度与规则","definition":"稳中求进是指在保持总体稳定的基础上积极推进发展和改革的工作总基调。","explanation":"2024年中共中央办公厅、国务院办公厅《关于数字贸易改革创新发展的意见》在总体要求中明确坚持稳中求进，并提出促进实体经济和数字经济深度融合。2024年12月2日第四次“一带一路”建设工作座谈会讲话也明确坚持稳中求进工作总基调，并提出以互联互通为主线。","basis":"据关联原题及所列出处编释。","references":[{"source":"trade","location":"一、总体要求"}],"examFocus":{"政治理论必刷100题#48":"对照数字贸易改革创新发展的政策文件，区分工作总基调、基本原则和实施举措。","政治理论必刷100题#89":"核对第四次“一带一路”建设工作座谈会讲话中工作总基调的完整表述，并区分原则、主线和协调机制。"}},"aspects":[{"title":"数字贸易改革创新的总体要求","uses":[{"unit":"Q1","role":"直接考查","use":"本题选C。①把稳中求进和促进实体经济与数字经济深度融合列入数字贸易改革创新发展的总体要求，③培育经营主体、④发挥引导基金作用也符合《意见》。②颠倒了政策原则的用词，文件表述是“创新为要、安全为基”。","evidence":"坚持稳中求进工作总基调","qids":["政治理论必刷100题#48"]}]},{"title":"共建“一带一路”的工作总基调","uses":[{"unit":"Q2","role":"直接考查","use":"本题为选非题，选D。按2024年12月2日第四次“一带一路”建设工作座谈会讲话，工作总基调表述为“稳中求进”。D将“以进促稳、先立后破”一并写入，超出了这次讲话的表述。其余三项分别对应共商共建共享原则、互联互通主线和三类联通协调推进机制。","evidence":"要坚持稳中求进、以进促稳、先立后破工作总基调","qids":["政治理论必刷100题#89"]}]}],"sources":[{"id":"81ecb322a280cd46","label":"稳中求进工作总基调","topic":"经济指标与宏观调控","category":"非时政","text":"1.稳中求进工作总基调\n稳中求进工作总基调是我们党治国理政的重要原则，也是做好经济工作的方法论。\n党的十八大以来，习近平总书记围绕坚持稳中求进工作总基调发表一系列重要论述，指出\n“发展是硬道理，稳定也是硬道理，抓发展、抓稳定两手都要硬”，强调“要坚持稳中求\n进、以进促稳、先立后破”。\n习近平总书记强调，“‘稳’的重点要放在稳住经济运行上，确保增长、就业、物价\n不出现大的波动，确保金融不出现区域性系统性风险。‘进’的重点要放在调整经济结构\n和深化改革开放上，确保转变经济发展方式和创新驱动发展取得新成效”。\n“稳”和“进”是辩证统一的关系，“稳”为“进”创造更好的环境和时机，“进”\n为“稳”的动态平衡提供动力支撑。","source":{"doc":"41195a191a57c1c36332","first":21,"last":22,"page":21,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-c942f879f87b0c86":{"review":{"definition":"2024年《中共中央办公厅 国务院办公厅关于数字贸易改革创新发展的意见》提出，按照创新为要、安全为基，扩大开放、合作共赢，深化改革、系统治理，试点先行、重点突破的原则推进数字贸易改革创新发展。","explanation":"“为要”对应创新，“为基”对应安全，分别体现创新的引领作用和安全的基础作用。第②项将两者的定位对调，即使其余三组原则表述一致，该项仍不成立。","references":[],"evidence":"按照创新为要、安全为基","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-48c47b7ed5ee0f0d":{"review":{"definition":"2024年《关于数字贸易改革创新发展的意见》提出，培育具有较强创新能力和影响力的数字贸易领军企业，并积极培育外向度高、具有独特竞争优势的中小型数字贸易企业。","explanation":"政策分别明确了领军企业和中小型企业的培育方向。第③项所述的“外向度高”和“具有独特竞争优势”都对应中小型数字贸易企业，符合该项政策要求。","references":[],"evidence":"外向度高、具有独特竞争优势的中小型数字贸易企业","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dfd7a07483ebdd85":{"review":{"definition":"服务贸易创新发展引导基金是2024年《关于数字贸易改革创新发展的意见》明确提出发挥作用的支持工具，用于带动社会资本投资数字贸易领域。","explanation":"《意见》将发挥该基金作用列入多渠道支持保障措施。第④项准确对应了政策工具、所带动的资本和投资方向，即由该基金带动社会资本投向数字贸易领域。","references":[],"evidence":"新发展引导基金作用，带动社会资本投资数字贸易领域。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7f602a4ba445680b":{"review":{"definition":"《关于健全资源环境要素市场化配置体系的意见》提出，完善全国温室气体自愿减排交易市场，逐步扩大其支持领域。","explanation":"同一段政策还要求稳步扩大全国碳排放权交易市场的行业覆盖范围。第①项所说的“逐步扩大支持领域”对应全国温室气体自愿减排交易市场，把“自愿减排”改成“强制减排”改变了政策所指的市场。","references":[],"evidence":"室气体自愿减排交易市场，逐步扩大支持领域。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ddbebe8c29187bbd":{"review":{"definition":"《关于健全资源环境要素市场化配置体系的意见》要求坚持节约优先方针，完善贯穿能源生产和消费全链条的节能管理制度。","explanation":"节约优先是健全节能市场化机制的方针，“全链条”明确了节能管理从能源生产延伸至消费的覆盖范围。第②项同时写对了方针和制度覆盖范围。","references":[],"evidence":"坚持节约优先方针，完善贯穿能源生产和消费全链条的节能管理制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e5d5200e491540b1":{"review":{"definition":"《关于健全资源环境要素市场化配置体系的意见》要求，以省级行政区域为单位，因地制宜建立健全排污权有偿使用和交易制度。","explanation":"“以省级行政区域为单位”规定制度建设的区域尺度，“因地制宜”要求制度安排结合当地实际。第③项完整保留了这两个条件，符合深化排污权交易的政策要求。","references":[],"evidence":"以省级行政区域为单位因地制宜建立健全排污权有偿使用和交易制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d30f371870af4e9c":{"review":{"definition":"《关于健全资源环境要素市场化配置体系的意见》要求坚持市场化原则，分类健全资源环境要素价格形成机制，使价格充分反映市场供求关系、资源稀缺程度、环境损害成本和生态产品价值。","explanation":"分类健全价格形成机制旨在发挥价格杠杆作用，促进资源环境要素高效合理配置。第④项保留了“分类健全”的要求，却将价格形成的原则由“市场化”改为“政府主导”，因此错误。","references":[],"evidence":"坚持市场化原则，分类健全资源环境要素价格形成机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-706604ca8d59a95b":{"review":{"definition":"推进改革应当运用法治思维和法治方式，维护法治权威。重大改革应当有法律依据。","explanation":"“重大改革于法有据”明确了重大改革的依据要求。文章同时强调法律面前人人平等，平等保护公民、法人和其他组织的合法权益。C项准确表述了推进改革的法治方式及重大改革的依据要求。","references":[],"evidence":"维护法治权威，做到重大改革于法有据","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-40ff1c577156271c":{"review":{"definition":"2024年12月9日，习近平在中共中央政治局第十八次集体学习时强调，要坚持把推进中华民族共同体建设作为边疆民族地区工作的主线。","explanation":"讲话把这条主线落实到增进边疆地区各族群众的认同、构筑中华民族共有精神家园等工作。①把该次讲话针对边疆民族地区工作的表述换成了“铸牢中华民族共同体意识”，因此按本题所据讲话判错。","references":[],"evidence":"作为边疆民族地区工作的主线","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-03c58c94ebbcdde9":{"review":{"definition":"2024年12月9日，习近平在中共中央政治局第十八次集体学习时提出，要打造一支政治立场坚定、理论修养和综合素质过硬的边疆治理研究队伍。","explanation":"这项队伍建设要求与加强边疆史和边疆治理相关的多学科研究、建构中国自主的边疆学知识体系一并提出。②的对象是边疆治理研究队伍，并完整列出了政治立场、理论修养和综合素质三方面要求，因此正确。","references":[],"evidence":"打造一支政治立场坚定、理论修养和综合素质过硬的边疆治理研究队伍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3c91ffae4f24261e":{"review":{"definition":"2024年12月9日，习近平在中共中央政治局第十八次集体学习时强调，要坚持把维护国家安全和社会稳定作为边疆治理的底线要求。","explanation":"讲话在提出这一底线后，要求完善共建共治共享的社会治理制度，夯实基层基础，提升边疆地区社会治理效能。③把全面建成小康社会中的“少数民族一个都不能少”放到了边疆治理底线要求的位置，与该次讲话的表述不符。","references":[],"evidence":"维护国家安全和社会稳定作为边疆治理","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a2a4f239feec1a30":{"review":{"definition":"2024年12月9日，习近平在中共中央政治局第十八次集体学习时提出，要把边疆地区发展纳入中国式现代化战略全局，同时纳入区域协调发展战略、区域重大战略。","explanation":"讲话指出，推进中国式现代化，边疆地区一个都不能少。上述战略安排旨在支持边疆地区依托自身条件禀赋，在融入新发展格局和全国统一大市场的过程中实现高质量发展。④同时保留了战略全局和两项区域战略，因此正确。","references":[],"evidence":"纳入区域协调发展战略、区域重大战略","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cd103ea7d100d309":{"review":{"definition":"党的二十大报告提出统筹推进政党协商、人大协商、政府协商、政协协商、人民团体协商、基层协商以及社会组织协商，并健全各种制度化协商平台。","explanation":"政协协商与政党、人大、政府等方面的协商并列，七类渠道共同构成报告所述协商民主体系。第54题A完整列出这七类渠道，表述正确，因此在选非题中排除。","references":[],"evidence":"人民团体协商、基层协商以及社会组织协商","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6ad5ecbfc9ce3c8d":{"review":{"definition":"中国人民政治协商会议的主要职能是政治协商、民主监督、参政议政。这三项职能是各党派团体、各族各界人士通过人民政协参与国事、发挥作用的基本形式。","explanation":"第54题B保留了政治协商和民主监督，却把第三项“参政议政”换成“依法行政”。依法行政是对行政机关行使行政职权的要求，而人民政协通过参政议政反映意见、提出建议。题目要求选出错误表述，因此选B。","references":[],"evidence":"中国人民政治协商会议的主要职能是政治协商、民主监督、参政议政","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0fe7109701cd68dc":{"review":{"definition":"党的二十届三中全会《中共中央关于进一步全面深化改革 推进中国式现代化的决定》要求健全协商于决策之前和决策实施之中的落实机制，完善协商成果采纳、落实、反馈机制。","explanation":"决策之前和决策实施之中是开展协商的两个时段，采纳、落实、反馈则是处理协商成果的环节。第54题C同时写明了时段和成果处理要求，符合《决定》表述，因此在选非题中排除。","references":[],"evidence":"实施之中的落实机制，完善协商成果采纳、落实、反馈机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-275eec537c1fb9bc":{"review":{"definition":"协商民主是实践全过程人民民主的重要形式，是党领导人民有效治理国家、保证人民当家作主的重要制度设计。","explanation":"习近平总书记在2019年中央政协工作会议暨庆祝中国人民政治协商会议成立70周年大会上的讲话中指出，协商民主与选举民主相互补充，人民政协在协商中促进广泛团结、推进多党合作、实践人民民主。第54题D复述了讲话对协商民主的制度定位，表述正确，因此在选非题中排除。","references":[],"evidence":"协商民主是党领导人民有效治理国家、保证人民当家作主的重要制度设计","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9a9a9867c701a684":{"review":{"title":"党的政治建设","type":"制度与规则","definition":"党的政治建设是中国共产党围绕政治方向、政治立场、政治纪律和政治规矩等开展的建设，在新时代党的建设总体布局中发挥统领作用。","explanation":"新时代党的建设总要求明确，以党的政治建设为统领，以坚定理想信念宗旨为根基。党的政治建设要求把政治标准和政治要求贯穿党的各项建设，严肃党内政治生活，净化党内政治生态，促进全党团结统一和行动一致。","basis":"据关联原题及所列出处编释。","references":[{"source":"party","location":"新时代党的建设总要求"},{"source":"web-d2f182ac2286236f","location":"正文首段，文末注标明讲话日期","quote":"我们把制度建设贯穿党的各项建设"}],"related":["k-066270830d9bbfc2","k-7094c74d45ee3380"],"examFocus":{"政治理论必刷100题#56":"按党的政治建设有关论述，核对各项表述的适用范围和定位。","江苏 2025 A类 行测#2":"对照全面从严治党有关论述，核对各项建设的作用及范围。"}},"aspects":[{"title":"党的政治建设的统领作用","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。A项关于以党的政治建设为统领、推动全面从严治党向纵深发展的表述正确。答案D将巩固和发展最广泛的爱国统一战线称为“新时代最大的政治”。根据题解引述的2023年12月29日全国政协新年茶话会讲话，“新时代最大的政治”指以中国式现代化全面推进强国建设、民族复兴伟业。","evidence":"新征程上，要坚持以党的政治建设为统领，推动全面从严治党向纵深发展","qids":["政治理论必刷100题#56"]},{"unit":"Q2","role":"直接考查","use":"本题共用题面。第⑤项将以党的政治建设统领党的建设各项工作、增强党组织政治功能列为新时代全面从严治党的成就。三份所附答案均为C，均将第④项判为正确。所给题面第④项写“把制度建设贯穿党的政治各方面”，2023年1月9日讲话原文为“我们把制度建设贯穿党的各项建设”。检索未找到官方原卷或答案，原卷第④项的措辞及答案C仍待核实。","evidence":"以党的政治建设统领党的建设的各项工作，不断增强党组织政治功能","qids":["江苏 2025 A类 行测#2","江苏 2025 B类 行测#2","江苏 2025 C类 行测#2"]}]}],"sources":[{"id":"43a0142f83147a14","label":"党的政治建设","topic":"党政制度与理论","category":"非时政","text":"1.党的政治建设\n学习领会习近平党的政治建设思想，要把握三个“要义”。第一，旗帜鲜明讲政治。\n这是马克思主义政党的根本要求。第二，政治建设放首位。政治建设是党的根本性建设，\n决定了党的建设的方向和效果。第三，全党服从中央是首要任务。全党各个组织和全体党\n员服从党的全国代表大会和中央委员会。\n——求是网","source":{"doc":"41195a191a57c1c36332","first":10,"last":11,"page":10,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-473c43235efd31f0":{"review":{"definition":"总体国家安全观是建设更高水平平安中国的重要遵循，各级党委和政府必须坚定不移贯彻，把发展和安全统一起来。","explanation":"2025年2月28日，习近平在中共中央政治局第十九次集体学习时要求各级党委和政府共同谋划、一体部署发展和安全。第②项把原表述中的“重要遵循”改成“唯一遵循”，因此错误。","references":[],"evidence":"总体国家安全观是建设更高水平平安中国的重要遵循","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"499077802f3e9111","label":"总体国家安全观","topic":"新时代中国特色社会主义思想","category":"非时政","text":"党的十八届三中全会《决定》提出：“设立国家安全委员会，完善国家安全体制和国家\n安全战略，确保国家安全。”\n2014 年 4 月 15 日，中央国家安全委员会召开第一次会议，习近平总书记创造性地提\n出总体国家安全观。\n党的十九大将“坚持总体国家安全观”纳入新时代坚持和发展中国特色社会主义的基本\n方略并写入党章。\n2020 年 12 月 11 日，十九届中央政治局举行第二十六次集体学习，习近平总书记就\n贯彻总体国家安全观提出“十个坚持”的重要要求，标志着总体国家安全观理论体系的正式\n确立。\n“十个坚持”是指：\n（1）坚持党对国家安全工作的绝对领导，\n（2）坚持中国特色国家\n安全道路，（3）坚持以人民安全为宗旨，（4）坚持统筹发展和安全，（5）坚持把政治安全\n放在首要位置，（6）坚持统筹推进各领域安全，（7）坚持把防范化解国家安全风险摆在突\n出位置，\n（8）坚持推进国际共同安全，\n（9）坚持推进国家安全体系和能力现代化，\n（10）坚\n持加强国家安全干部队伍建设。\n党的二十大对国家安全工作进行专章部署，提出：“坚持以人民安全为宗旨、以政治安\n全为根本、以经济安全为基础、以军事科技文化社会安全为保障、以促进国际安全为依托，\n统筹外部安全和内部安全、国土安全和国民安全、传统安全和非传统安全、自身安全和共同\n安全，统筹维护和塑造国家安全，夯实国家安全和社会稳定基层基础，完善参与全球安全治\n理机制，建设更高水平的平安中国，以新安全格局保障新发展格局。”\n（粉笔敲黑板：注意总\n体国家安全关 5 个安全的地位，尤其是政治安全为根本）\n总体国家安全观的关键是“总体”。强调大安全理念，涵盖政治、军事、国土、经济、\n金融、文化、社会、科技、网络、粮食、生态、资源、核、海外利益、太空、深海、极地、\n生物、人工智能、数据等诸多领域，而且将随着社会发展不断动态调整。总体国家安全观的\n核心要义，集中体现为“十个坚持”。\n“一个总体”、\n“十个坚持”有机融合、有机统一，凝结\n着我们党坚持和发展中国特色国家安全的宝贵经验，反映了以习近平同志为核心的党中央对\n国家安全工作规律性认识的深化、拓展、升华。","source":{"doc":"3ccc56f4000d1642c2d1","first":28,"last":29,"page":28,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-419f54bd4d79bd94":{"review":{"definition":"建设更高水平平安中国，要把捍卫国家政治安全摆在首位，坚定维护国家政权安全、制度安全和意识形态安全。完善公共安全体系，要推动公共安全治理模式向事前预防转型。","explanation":"第①项的“摆在首位”明确了国家政治安全的优先地位，“向事前预防转型”明确了公共安全治理的方向，涉及安全生产、防灾减灾救灾等工作。两项要求均符合2025年2月28日的讲话。","references":[],"evidence":"把捍卫国家政治安全摆在首位，推动公共安全治理模式向事前预防转型","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-394eb3d9e53ec1db":{"review":{"definition":"建设更高水平平安中国，要强化社会治安整体防控，把专项治理与系统治理、依法治理、综合治理、源头治理结合起来，发展壮大群防群治力量。","explanation":"第③项同时列出了治理方式和参与力量两方面的要求。针对突出治安问题开展专项治理时，要与着眼全局、依法开展、综合施策和从源头预防的治理结合起来，同时发挥群众参与防范和治理的作用，符合2025年2月28日的讲话。","references":[],"evidence":"要把专项治理和系统治理、依法治理、综合治理、源头治理结合起来，发展壮大群防群治力量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3f1c376e61227ee3":{"review":{"definition":"建设社会治理共同体，要完善社会治理体系、健全社会工作体制机制，实现人人有责、人人尽责、人人享有。","explanation":"第④项把完善体系、健全机制与共同体建设的目标连在一起。“有责”指共同承担治理责任，“尽责”指实际履行责任，“享有”指共享治理成果。这与讲话中增进民生福祉、维护群众合法权益和社会公平正义的要求相衔接，因此该项正确。","references":[],"evidence":"人人尽责、人人享有的社会治理共同体","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e70be2bb8023926d":{"review":{"definition":"党的领导是平安中国建设的根本保证。要坚持党中央对国家安全工作、对政法工作的绝对领导，发挥各级党委在平安建设中总揽全局、协调各方的领导作用。","explanation":"第⑤项同时写明了两个层级的领导要求。党中央对国家安全工作和政法工作实行绝对领导，各级党委在平安建设中负责总揽全局、协调各方。两层表述均符合2025年2月28日的讲话。","references":[],"evidence":"党的领导是平安中国建设的根本保证","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-037f61aed9e69a4c":{"review":{"definition":"2025年中央城市工作会议提出，城市工作要坚持因地制宜、分类指导，以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市为目标。","explanation":"第①项将因地制宜、分类指导列为工作要求，将创新等六个方面列为建设目标，符合会议表述。在同一组总体要求中，推动城市高质量发展是主题，坚持城市内涵式发展是主线，推进城市更新是重要抓手。","references":[],"evidence":"以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市为目标","disposition":"独立词条","basis":"据原题和解析编释。","title":"现代化人民城市建设目标","related":[],"examFocus":{"政治理论必刷100题#23":"核对中央城市工作会议对城市发展理念、发展阶段、建设目标和重点任务的表述。","政治理论必刷100题#65":"逐条核对城市建设目标、文化遗产保护原则、老旧小区改造要求、城镇化阶段和宜居城市规划部署。"}},"readings":[{"origin":"k-037f61aed9e69a4c","title":"现代化人民城市建设目标","qs":["政治理论必刷100题#65"],"definition":"2025年中央城市工作会议提出，城市工作要坚持因地制宜、分类指导，以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市为目标。","explanation":"第①项将因地制宜、分类指导列为工作要求，将创新等六个方面列为建设目标，符合会议表述。在同一组总体要求中，推动城市高质量发展是主题，坚持城市内涵式发展是主线，推进城市更新是重要抓手。","evidence":"以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市为目标","doubt":"","references":[]},{"origin":"k-81f451061ba6cbd8","title":"现代化人民城市建设目标","qs":["政治理论必刷100题#23"],"definition":"2025年中央城市工作会议提出，当前和今后一个时期城市工作的目标是建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市。","explanation":"会议同时将推动城市高质量发展定为主题，将坚持城市内涵式发展定为主线。C项虽然保留了“美丽”，却用“低碳、便捷、包容”改写了建设目标的完整表述，因此错误。","evidence":"文明、智慧的现代化人民城市为目标","doubt":"","references":[]}]},"k-6548716f32fc5d7f":{"review":{"definition":"2025年《关于持续推进城市更新行动的意见》要求坚持保护第一、应保尽保、以用促保，在城市更新全过程、各环节加强城市文化遗产保护。","explanation":"“保护第一”规定了保护与利用的优先次序，“以用促保”要求利用服务于保护。第②项虽保留了“应保尽保、以用促保”和全过程保护的要求，却把“保护第一”改成“利用第一”，因此错误。","references":[],"evidence":"应保尽保、以用促保，在城市更新全过程、各环节加强城市文化遗产保护","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7b8bac1c6a492016":{"review":{"definition":"习近平在2024年4月考察重庆时指出，老旧小区改造是城市更新的一个重点，也是一项民生工程，既要保留历史记忆和特色风貌，又要解决居民关切的实际问题。","explanation":"第③项保留了改造的双重定位及相应要求。作为城市更新的重点，改造要延续历史记忆和特色风貌。作为民生工程，改造要回应居民关切的实际问题。因此第③项正确。","references":[],"evidence":"既要保留历史记忆和特色风貌，又要解决居民","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1ab87841fd160ef2":{"review":{"definition":"2025年中央城市工作会议提出，建设舒适便利的宜居城市，要坚持人口、产业、城镇、交通一体规划，优化城市空间结构。","explanation":"一体规划要求统筹人口分布、产业布局、城镇空间和交通安排，使居民居住、就业和出行的需求在空间布局中相互衔接。第⑤项准确列出了四个规划要素及其目标，属于会议部署的宜居城市建设任务。","references":[],"evidence":"坚持人口、产业、城镇、交通一体规划，优化城市空间结构","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-822ba0160341550b":{"review":{"definition":"党建引领基层治理要求加强基层党组织建设，由基层党组织团结带领群众贯彻党的理论和路线方针政策、落实党的任务。","explanation":"第66题①具体说明了基层党组织发挥战斗堡垒作用的方式，即把贯彻党的理论和路线方针政策、落实党的任务同组织群众结合起来，因此①应纳入正确组合。","references":[],"evidence":"政策、落实党的任务的战斗堡垒","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6fed0dadc033dc9b":{"review":{"definition":"要夯实社会治理基层基础，推动社会治理重心下移，在党组织领导下构建共建共治共享的城乡基层治理格局。","explanation":"第66题③同时交代了治理重心的方向、领导主体和治理格局。治理重心向基层下移，城乡基层治理由党组织领导，各方共同建设、共同治理、共享成果，因此③应纳入正确组合。","references":[],"evidence":"推动社会治理重心下移，构建党组织领导的共建共治共享","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f1dc468c55a7e7c8":{"review":{"definition":"基层治理要深入推进社区治理创新，通过改进社区治理方式，构建富有活力和效率的新型基层社会治理体系。","explanation":"第66题④将社区治理创新作为改进基层治理方式的举措，将增强活力和效率作为治理体系建设的目标。该表述与解析所引要求一致，因此④应纳入正确组合。","references":[],"evidence":"构建富有活力和效率的新型基层社会治理体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-18c308cec72bd4a4":{"review":{"definition":"党的二十届三中全会《决定》将“在发展中保障和改善民生”定位为中国式现代化的重大任务，要求坚持尽力而为、量力而行，完善基本公共服务制度体系。","explanation":"第68题要求选出不正确的说法。C项把“重大任务”改成“唯一任务”，将政策强调的任务重要性改成了排他性，因此本题选C。","references":[],"evidence":"改善民生是中国式现代化的重大任务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-84847d642fbd8d82":{"review":{"definition":"党的十八届五中全会提出，保障基本民生要坚守底线、突出重点、完善制度、引导预期，并注重机会公平。","explanation":"第68题A项保留了四项工作要求，也保留了“注重机会公平”这一原则，表述与解析所引全会要求一致。由于题目要求选出不正确的说法，A项应排除。","references":[],"evidence":"坚守底线、突出重点、完善制度、引导预期，注重机会公平，保障基本民生","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-909311a1a80d1dc0":{"review":{"definition":"《习近平新时代中国特色社会主义思想学习纲要（2023年版）》提出，做好民生工作必须坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果。","explanation":"“人人尽责”强调参与推动发展，“人人享有”强调分享发展成果。第68题D项同时写明这两层要求，并明确发展成果由所有劳动者分享，符合《纲要》表述，在选非题中应排除。","references":[],"evidence":"必须坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b04cf0c4881c60de":{"review":{"definition":"新时代立德树人工程是落实立德树人根本任务的教育部署。《加快建设教育强国》提出，坚持不懈用新时代中国特色社会主义思想铸魂育人，推动思政课建设与党的创新理论武装同步推进。","explanation":"第69题要求选出错误表述。A项写对了“立德树人根本任务”，但把文章中铸魂育人所用的“新时代中国特色社会主义思想”换成了“马克思主义思想”，因此应选A。","references":[],"evidence":"实施新时代立德树人工程，坚持思政课建设与党的创新理论","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"f38d8f67c27bf86e","label":"新时代立德树人工程","topic":"年度政府工作","category":"时政","text":"1.新时代立德树人工程\n实施新时代立德树人工程，促进思政课堂和社会课堂有效融合，加强体育、美育、劳动\n教育，完善教育评价体系。\n——《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》\n要坚定不移落实好立德树人根本任务。坚持不懈用新时代中国特色社会主义思想铸魂育\n人，实施新时代立德树人工程，坚持思政课建设与党的创新理论武装同步推进。加强党的创\n新理论体系化学理化研究阐释，构建以各学科标识性概念、原创性理论为主干的中国哲学社\n会科学自主知识体系。不断拓展实践育人和网络育人的空间和阵地。\n——《求是》杂志文章《加快建设教育强国》","source":{"doc":"6cbfb01fe723bba64b75","first":41,"last":41,"page":41,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-e7676eca049c3ac1":{"review":{"definition":"教育强国建设要强化教育对科技和人才的支撑作用，统筹实施科教兴国战略、人才强国战略、创新驱动发展战略，一体推进教育发展、科技创新和人才培养。","explanation":"第69题B项把“强化教育对科技和人才的支撑作用”与“推动教育科技人才良性循环”放在一起，分别对应文章提出的支撑方向和协同推进要求，符合原文部署。","references":[],"evidence":"强化教育对科技和人才的支撑作用，坚持推动教育科技人才良性循环","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-65185c0762be6570":{"review":{"definition":"培养造就新时代高水平教师队伍，要实施教育家精神铸魂强师行动，加强师德师风建设，提高教师培养培训质量，统筹优化教师管理与资源配置。","explanation":"第69题C项列出的铸魂强师行动和师德师风建设，都是《加快建设教育强国》在教师队伍建设方面明确提出的措施，C项表述正确。","references":[],"evidence":"实施教育家精神铸魂强师行动，加强师德师风建设","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"6b35b860c9e28c54","label":"建设高素质专业化教师队伍","topic":"就业、社保与公共服务","category":"非时政","text":"2.建设高素质专业化教师队伍\n建设高素质专业化教师队伍，筑牢教育强国根基。实施教育家精神铸魂强师行动，提升\n教师专业素质能力，优化教师管理和资源配置，提高教师政治地位、社会地位、职业地位。\n——《教育强国建设规划纲要（2024—2035 年）》","source":{"doc":"6cbfb01fe723bba64b75","first":41,"last":41,"page":41,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-d79e4f69d14e2138":{"review":{"definition":"建设具有全球影响力的重要教育中心，要深入推动教育对外开放，统筹教育领域的“引进来”和“走出去”，提升教育国际影响力、竞争力和话语权。","explanation":"第69题D项前半句写建设目标，后半句写实现路径。《加快建设教育强国》把深化教育对外开放列在这一建设目标之下，D项对应准确。","references":[],"evidence":"建设具有全球影响力的重要教育中心，深入推动教育对外开放","disposition":"独立词条","basis":"据原题和解析编释。","title":"建设具有全球影响力的重要教育中心","related":[],"examFocus":{"政治理论必刷100题#69":"对照教育强国建设的原文，辨析铸魂育人、教育科技人才协同、教师队伍建设和对外开放的目标与举措。","政治理论必刷100题#74":"核对教育强国建设原文中关于根本任务、支撑作用、开放目标和教育质量的表述。"}},"readings":[{"origin":"k-d79e4f69d14e2138","title":"建设具有全球影响力的重要教育中心","qs":["政治理论必刷100题#69"],"definition":"建设具有全球影响力的重要教育中心，要深入推动教育对外开放，统筹教育领域的“引进来”和“走出去”，提升教育国际影响力、竞争力和话语权。","explanation":"第69题D项前半句写建设目标，后半句写实现路径。《加快建设教育强国》把深化教育对外开放列在这一建设目标之下，D项对应准确。","evidence":"建设具有全球影响力的重要教育中心，深入推动教育对外开放","doubt":"","references":[]},{"origin":"k-ffb1a94cba76fe4c","title":"建设具有全球影响力的重要教育中心","qs":["政治理论必刷100题#74"],"definition":"建设具有全球影响力的重要教育中心是建设教育强国的一项要求，旨在通过教育对外开放提升我国教育的国际影响力、竞争力和话语权。","explanation":"习近平在《加快建设教育强国》中提出，要统筹教育领域的“引进来”和“走出去”，以扩大教育对外开放。第74题C项准确复述了这一建设目标，属于正确项。","evidence":"建设具有全球影响力的重要教育中心。","doubt":"","references":[]}]},"k-fa4c9b1efd99976e":{"review":{"definition":"2024年《关于实施就业优先战略促进高质量充分就业的意见》提出，职业技能培训供给以市场化培训为主导、行业企业自主培训为主体，并鼓励企业建设职业技能培训基地。","explanation":"第70题A项同时写对了基地建设的政策措施与培训供给结构。“主导”对应市场化培训，“主体”对应行业企业自主培训，二者分别说明供给方向和主要承担者。","references":[],"evidence":"形成以市场化培训为主导、行业企业自主培训为主体","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9eeed367c9360dfe":{"review":{"definition":"2024年《关于实施就业优先战略促进高质量充分就业的意见》提出，扩大理工农医类专业招生规模，并根据社会需要、产业需求、职业开发优化调整学科专业设置，以提高教育供给与人才需求的匹配度。","explanation":"第70题B项列出了两项相配合的措施，理工农医类扩招调整招生规模，按社会需要、产业需求和职业开发调整专业设置优化培养结构，均属于缓解结构性就业矛盾的政策安排。","references":[],"evidence":"根据社会需要、产业需求、职业开发优化调整学科专业设置","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-41bd0663b65c9692":{"review":{"definition":"2024年《关于实施就业优先战略促进高质量充分就业的意见》提出，发挥国有企业就业引领作用，综合运用财政支持、税收优惠、金融支持和社会保障等政策，引导各类主体履行稳岗扩岗社会责任。","explanation":"第70题要求选出不恰当的举措。C项的财政支持、税收优惠等政策工具和引导各类主体稳岗扩岗的方向符合《意见》，错误在于把发挥就业引领作用的主体由国有企业换成了民营企业。","references":[],"evidence":"发挥国有企业就业引领作用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6732eea197b8c87e":{"review":{"definition":"2024年《关于实施就业优先战略促进高质量充分就业的意见》提出，健全创业培训、创业服务、创业孵化、创业活动支持体系，以优化创业促进就业的政策环境，提升创业质量。","explanation":"第70题D项列出的四类支持及其目标，均对应《意见》中“优化自主创业灵活就业保障制度”的部署，因此属于恰当举措。","references":[],"evidence":"健全创业培训、创业服务、创业孵化、创业活动支持体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9000bb8382ecfe18":{"review":{"definition":"《关于建立健全养老服务综合监管制度促进养老服务高质量发展的意见》要求建立健全养老服务标准和评价体系，实施养老机构服务质量、安全基本规范等标准。","explanation":"服务标准为机构提供质量和安全方面的规范，评价体系为衡量服务是否达到要求提供依据。题中②所说的以标准和评价体系引领养老服务高质量发展，符合该意见的监管要求。","references":[],"evidence":"建立健全养老服务标准和评价体系，引领养老服务高质量发展","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f3787eb1bfac677e":{"review":{"definition":"《关于加强新时代老龄工作的意见》提出扩大养老保险覆盖面，逐步实现基本养老保险法定人员全覆盖。覆盖对象按法律制度规定的人员范围确定。","explanation":"政策以是否属于法定覆盖对象界定扩面范围。题中③将「法定人员」改为「城市人员」，把法定范围换成了城乡地域口径，因此③错误。","references":[],"evidence":"养老保险法定人员全覆盖","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3d692f1b00429d93":{"review":{"definition":"《关于推进基本养老服务体系建设的意见》要求落实发展养老服务的优惠扶持政策，鼓励社会力量参与提供基本养老服务。","explanation":"优惠扶持旨在调动社会力量参与服务供给。该意见举出的具体做法是支持物业服务企业因地制宜提供居家社区养老服务。题中④准确表述了政策工具和鼓励参与的主体，因此正确。","references":[],"evidence":"落实发展养老服务优惠扶持政策，鼓励社会力量参与提供基本养老服务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dfa03c2991ab7cf7":{"review":{"definition":"《关于深化养老服务改革发展的意见》提出，到2035年，全体老年人享有基本养老服务，适合我国国情的养老服务体系成熟定型。","explanation":"该意见还提出，到2035年，养老服务网络更加健全，服务供给与需求更加协调适配。题中⑤同时写对了目标年份、基本养老服务的覆盖对象和养老服务体系的建设目标，因此正确。","references":[],"evidence":"到 2035 年，全体老年人享有基本养老服务，适合我国国情的养老服务体系成熟定型","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-181746d46e6fdc2e":{"review":{"definition":"后陈经验发端于浙江省武义县后陈村，以设立村务监督委员会、公开村务和接受群众监督来约束村级权力。","explanation":"村务公开让村民能够了解村级事务，村务监督委员会为发现问题、推动纠正提供了制度渠道。第73题第②项所列的权力约束、村务公开、群众监督和自我纠偏，正对应这套村级监督机制。","references":[],"evidence":"权力受到约束、村务全面公开、群众有效监督、自我能够纠偏","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f2b489cac21d826a":{"review":{"definition":"立德树人是教育的根本任务，要求落实党的教育方针，培养德智体美劳全面发展的社会主义建设者和接班人。","explanation":"党的二十大报告将“落实立德树人根本任务”与培养目标连在一起，明确了教育要培养什么样的人。第74题B项准确表述了这一根本任务，属于正确项。","references":[],"evidence":"落实立德树人根本任务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4546e942c098e952":{"review":{"definition":"各级各类教育要坚持把高质量发展作为生命线，并加快建设高质量教育体系。","explanation":"习近平在2023年5月29日二十届中央政治局第五次集体学习时提出这一要求。第74题D项把“高质量发展”替换成“人民满意度”，改变了这句话所强调的内容。题干要求选出不正确的表述，因此答案是D。","references":[],"evidence":"要坚持把高质量发展作为各级各类教育的生命线","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-460b58dc5ec080c8":{"review":{"definition":"2025年《中共中央 国务院关于推动城市高质量发展的意见》提出，稳妥有序推动城市群一体化和都市圈同城化，发展组团式、网络化的现代化城市群和都市圈。","explanation":"组团式、网络化是构建布局合理的现代化城市体系的布局要求。第75题A项把这两个政策关键词改成了“分散式、独立化”，因此是题目要求选出的不正确项。","references":[],"evidence":"发展组团式、网络化的现代化城市群和都市圈","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c91819e2d39ed423":{"review":{"definition":"2025年《中共中央 国务院关于推动城市高质量发展的意见》提出，支持超大特大城市布局科技创新平台基地，提升原创性、颠覆性科技创新能力。","explanation":"这项支持措施属于增强超大特大城市综合竞争力的部署。第75题B项准确写出了支持对象、布局举措和能力目标，符合《意见》表述。","references":[],"evidence":"支持超大特大城市布局科技创新平台基地，提升原创性、颠覆性科技创新能力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b41208974cfdf04d":{"review":{"definition":"2025年《中共中央 国务院关于推动城市高质量发展的意见》提出，对经济规模大、人口增长快的县级市和特大镇，适时调整扩大其经济社会管理权限。","explanation":"这项安排列在提高中小城市和县城承载能力的部署中，并与因地制宜发展小城镇相衔接。第75题C项保留了“适时”这一时间要求，以及“经济规模大、人口增长快”两个对象条件，符合《意见》表述。","references":[],"evidence":"适时调整扩大经济规模大、人口增长快的县级市和特大镇经济社会管理权限","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6310d6fba43245e1":{"review":{"definition":"2025年《中共中央 国务院关于推动城市高质量发展的意见》提出，结合高质量共建“一带一路”，建设一批国际门户枢纽城市和区域性开放节点城市。","explanation":"两类城市的建设都属于提升城市对外开放合作水平的部署。第75题D项保留了高质量共建“一带一路”这一政策背景和两类建设对象，符合《意见》表述。","references":[],"evidence":"结合高质量共建“一带一路”，建设一批国际门户枢纽城市和区域性开放节点城市","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-491df3789a7323ad":{"review":{"definition":"绿化祖国要坚持扩绿、兴绿、护绿“三绿”并举，推动森林水库、钱库、粮库、碳库“四库”联动。","explanation":"这是习近平2025年4月3日参加首都义务植树活动时提出的要求。第77题①列对了“三绿”，但把“四库”中的“钱库、粮库”换成了“油库、财库”，因此整项错误。","references":[],"evidence":"推动森林水库、钱库、粮库、碳库“四库”联动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-803336781894757c":{"review":{"definition":"中央生态环境保护督察是党中央推进生态文明建设的一项重大举措，以压实各级领导干部的生态环境保护政治责任为切入点。","explanation":"2025年3月31日召开的中共中央政治局会议指出，督察通过压实政治责任，推动查处破坏生态环境的重大典型案件，解决群众反映强烈的突出环境问题。第77题②准确写出了督察的定位和切入点。","references":[],"evidence":"从压实各级领导干部生态环境保护政治责任入手","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-304b862858092a3f":{"review":{"definition":"《中共中央关于全面深化改革若干重大问题的决定》要求建立系统完整的生态文明制度体系，用制度保护生态环境。该体系涉及源头保护、损害赔偿、责任追究、环境治理和生态修复。","explanation":"决定要求实行最严格的源头保护制度、损害赔偿制度和责任追究制度，并完善环境治理和生态修复制度。第78题A概括了这项制度建设要求，表述正确，在选非题中应排除。","references":[],"evidence":"必须建立系统完整的生态文明制度体系，用制度保护生态环境","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e24885300c2dde70":{"review":{"definition":"党的十九大报告提出，构建政府为主导、企业为主体、社会组织和公众共同参与的环境治理体系。","explanation":"第78题B保留了企业的主体地位及社会组织、公众的参与角色，却把主导者由政府换成市场。题目要求选出错误表述，因此选B。C项所说的“市场化”修饰的是生态补偿机制。","references":[],"evidence":"构建政府为主导、企业为主体、社会组织和公众共同参","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0e51f6a1e7929fc9":{"review":{"definition":"党的十九大报告提出，健全耕地、草原、森林、河流、湖泊休养生息制度，建立市场化、多元化生态补偿机制。","explanation":"报告把这两项要求列在“加大生态系统保护力度”部分，同段还提出扩大轮作休耕试点。第78题C列出的五类对象对应休养生息制度，“市场化、多元化”对应生态补偿机制，符合报告表述，在选非题中应排除。","references":[],"evidence":"健全耕地草原森林河流湖泊休养生息制度，建立市场化、多元化生态补偿机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-49ccabb4215ba52f":{"review":{"definition":"《中共中央关于进一步全面深化改革、推进中国式现代化的决定》要求完善生态文明制度体系，加快完善落实绿水青山就是金山银山理念的体制机制。","explanation":"决定在“深化生态文明体制改革”部分提出这项要求，同段部署还包括协同推进降碳、减污、扩绿、增长和积极应对气候变化。第78题D准确概括了其中的制度要求，在选非题中应排除。","references":[],"evidence":"加快完善落实绿水青山就是金山银山理念的体制机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-992083d8d5e2b4cf":{"review":{"definition":"我国加快构建以国家公园为主体的自然保护地体系，国家公园在整个自然保护地体系中居于主体地位。","explanation":"第80题②与习近平在全国生态环境保护大会上的讲话一致。这里的“主体”指国家公园在整个自然保护地体系中的地位，讲话所述的建设任务覆盖整个自然保护地体系。","references":[],"evidence":"加快构建以国家公园为主体的自然保护地体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1f8d4b3e86cc722a":{"review":{"definition":"习近平在全国生态环境保护大会上的讲话提出，蓝天保卫战要以京津冀及周边、长三角、汾渭平原等重点区域为主战场，净土保卫战重在强化污染风险管控。","explanation":"第80题③所列三个区域符合讲话对大气污染治理主战场的部署。⑤所说的风险管控涵盖防止土壤新增污染，以及逐步解决长期积累的土壤和地下水严重污染问题，因此③、⑤均正确。","references":[],"evidence":"净土保卫战重在强化污染风险管控。","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"285d545a34d41ff8","label":"蓝天、碧水、净土保卫战","topic":"生态环境与能源","category":"非时政","text":"3.蓝天、碧水、净土保卫战\n持续深入打好蓝天保卫战。以京津冀及周边、长三角、汾渭平原等重点区域为主战场，\n以细颗粒物控制为主线，大力推进多污染物协同减排。\n持续深入打好碧水保卫战。统筹水资源、水环境、水生态治理，深入推进长江、黄河等\n大江大河和重要湖泊保护治理，优化调整水功能区划及管理制度。\n持续深入打好净土保卫战。开展土壤污染源头防控行动，严防新增污染，逐步解决长期\n积累的土壤和地下水严重污染问题。\n——《中共中央 国务院关于全面推进美丽中国建设的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":46,"last":46,"page":46,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-c7730ecb4f004583":{"review":{"definition":"水土流失、荒漠化、石漠化等生态退化突出问题，应以自然恢复为主，辅以必要的人工修复。生态系统受损严重且难以自行恢复的区域，应主动采取科学的人工修复措施。","explanation":"第80题④用“全部”把第一类情形的要求扩大到了所有生态问题。讲话还提出，超大特大城市和城市群要积极探索自然恢复与人工修复深度融合，具体方式随生态系统和区域条件而定。","references":[],"evidence":"靠自身难以恢复的区域，则要主动采取科学的人工修复措施","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5edc4405e43bc8f1":{"review":{"definition":"深入推进党的自我革命，必须以坚持党中央集中统一领导为根本保证。","explanation":"《深入推进党的自我革命》要求在党中央领导下统一谋划、统一部署、统一推进，确保自我革命始终沿着正确方向前进。C项将根本保证写成“完善党内法规体系”，因此是本题应选的错误项。","references":[],"evidence":"以坚持党中央集中统一领导为根本保证。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a45163b1b685436c":{"review":{"definition":"在纵深推进全面从严治党过程中，要以彻底的自我革命精神把反腐败斗争进行到底，坚持一体推进不敢腐、不能腐、不想腐。","explanation":"2024年10月28日中央政治局会议把这一要求与深化标本兼治、持续保持惩治腐败高压态势、完善权力运行制约机制相联系。B项准确复述了会议对纵深推进全面从严治党和反腐败斗争的要求，因此在本题选非时排除。","references":[],"evidence":"纵深推进全面从严治党，以彻底的自我革命精神把反腐败斗争进行到底","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e165bb4de22a4508":{"review":{"definition":"正风肃纪反腐是深入推进党的自我革命的重要抓手，必须把端正作风、严明纪律、反对腐败结合起来一起抓。","explanation":"《深入推进党的自我革命》要求以优良作风作引领、以严明纪律强保障、以反腐惩恶清障碍。D项的“结合起来一起抓”准确体现了三方面协同推进的要求，因此在本题选非时排除。","references":[],"evidence":"以正风肃纪反腐为重要抓手。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-279f14414eaebdae":{"review":{"definition":"共青团要把加强对广大团员和青年的政治引领摆在首位，努力培养社会主义建设者和接班人。","explanation":"《激励新时代青年在中国式现代化建设中挺膺担当》在阐明共青团的政治属性后，明确了摆在首位的是政治引领。B项保留了培养社会主义建设者和接班人的目标，却把首位要求写成“思想引领”，因此是本题应选的错误项。","references":[],"evidence":"和青年的政治引领摆在首位，努力培养社会主义建设者和接班人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-371dfaa7660604a8":{"review":{"definition":"共青团要坚持围绕中心、服务大局，主动对接国家重大战略和重大任务，组织动员广大青年立足本职岗位投身中国式现代化建设。","explanation":"文章把共青团对接国家任务和青年立足本职岗位联系起来，列举了科技创新、乡村振兴、绿色发展等实践领域。A项准确写出了共青团主动对接任务、组织动员青年的要求，因此在本题选非时排除。","references":[],"evidence":"共青团要坚持围绕中心、服务大局，主动对接国家重大战略和重大任务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-daf4d949dbcd11ef":{"review":{"definition":"加强对广大青年的理想信念教育，要引导青年树立共产主义远大理想，坚定中国特色社会主义共同理想。","explanation":"文章把理想信念教育放在加强青年政治引领的要求中，并将两种理想与坚定听党话、跟党走的政治信念相联系。C项准确对应“树立”共产主义远大理想和“坚定”中国特色社会主义共同理想，因此在本题选非时排除。","references":[],"evidence":"引导广大青年树立共产主义远大理想，坚定中国特色社会主义共同理想","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-06664d6b16cb709f":{"review":{"definition":"中央八项规定是党中央抓作风建设的规定。习近平将其概括为党中央徙木立信之举、新时代管党治党的标志性措施。","explanation":"党中央从中央政治局带头执行，以明确规矩和严格约束推动作风建设，并聚焦纠治“四风”开展整治。“徙木立信”在这里指通过带头执行和严格落实立信。C项对中央八项规定地位的表述正确，因此在本题选非时排除。","references":[],"evidence":"中央八项规定是党中央徙木立信之举，是新时代管党治党的标志性措施。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a40a903e235e6670":{"review":{"definition":"全面从严治党在对象上覆盖党的各级组织和全体党员，重点抓好党员领导干部这一「关键少数」，特别是高级干部和「一把手」。","explanation":"二十届中央纪委二次全会讲话同时明确了管党治党的覆盖范围和重点对象。第②项表述的是其中的重点，所列高级干部和「一把手」与讲话一致，因此正确。","references":[],"evidence":"重点是抓好“关键少数”，管好党员领导干部特别是高级干部、“一把手”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2363b62b516cec73":{"review":{"definition":"领导干部要努力成为全社会的道德楷模，带头践行社会主义核心价值观，以实际行动带动全社会崇德向善、尊法守法。","explanation":"2016年12月9日的中央政治局集体学习讲话把领导干部自身的道德实践与对全社会的示范带动联系起来。第③项同时列出「崇德向善」和「尊法守法」，符合讲话对示范作用的表述。","references":[],"evidence":"以实际行动带动全社会崇德向善、尊法守法","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0279b622bbfc1cdd":{"review":{"definition":"领导干部特别是高级干部担负推进改革的重要职责，要增强政治责任感和历史使命感，在风险挑战面前继续推进改革发展。","explanation":"2024年10月29日的专题研讨班开班式讲话既点明了推进改革的责任主体，也提出了面对风险挑战的行动要求。第⑤项的「应对风险挑战不退缩」对应这项要求，因此正确。","references":[],"evidence":"领导干部特别是高级干部担负着推进改革的重要职责","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-259e0b87a97a8b62":{"review":{"definition":"推进党风廉政建设要把党性教育、作风建设和纪律建设一同抓好，推动正风、肃纪、反腐相贯通。","explanation":"2025年3月习近平在贵州考察时，把这项要求同持续铲除腐败滋生的土壤和条件联系起来。B项保留了「正风肃纪反腐相贯通」，却把「党性党风党纪」改成「党规党纪党务」，因此是本题要求选出的不准确表述。","references":[],"evidence":"党性党风党纪一起抓、正风肃纪反腐相贯通","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"73010ca4730714f9","label":"党性党风党纪一起抓","topic":"党政制度与理论","category":"非时政","text":"1.党性党风党纪一起抓\n党性：是政党固有的本质特征，是党员干部立身、立业、立言、立德的基石，\n是净化党风、严明党纪的内在依据。\n党风：是党在思想、政治、组织、工作、生活等各方面表现出来的态度和行为，\n是党性、党纪的外在体现，关系人心向背，关系党的生死存亡。\n党纪：是管党治党的戒尺，也是党员、干部约束自身行为的标准和遵循。\n党性、党风、党纪是有机整体，党性是根本，党风是表现，党纪是保障。党性、\n党风、党纪的内在一致性，决定了三者必须“一起抓”才能达到治病强身、固本培\n元的整体效果。","source":{"doc":"41195a191a57c1c36332","first":17,"last":17,"page":17,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-22b35f1b6c6a78e3":{"review":{"definition":"各级领导干部要切实履行管党治党责任，作风正派、公道处事，以自身模范行动推动政治生态持续净化。","explanation":"2025年3月习近平在云南考察时，把政治生态好不好作为观察一个地方党的领导和党的建设水平的重要方面，并对各级领导干部提出履责和示范要求。A项同时保留了「作风正派、公道处事」和「推动政治生态持续净化」，表述准确。","references":[],"evidence":"各级领导干部要切实履行管党治党责任，作风正派、公道处事","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-df86a6532824ef9d":{"review":{"title":"风腐同查同治","type":"制度与规则","definition":"风腐同查同治是纪检监察机关在正风肃纪反腐工作中，联动查处相互交织的不正之风和腐败问题，并针对两者的共性根源开展治理的工作要求。","explanation":"2025年1月6日，二十届中央纪委四次全会上的讲话提出，以“同查”严惩风腐交织问题，以“同治”铲除风腐共性根源。治理措施包括通过查办案件推动整改，完善权力配置和运行的制约与监督机制。","basis":"据关联原题及所列出处编释。","references":[{"source":"graft","location":"正风肃纪反腐相贯通"}],"examFocus":{"政治理论必刷100题#85":"核对中央八项规定背景下的作风建设要求，区分风腐同查与同治的治理对象及各项要求的用语。","政治理论必刷100题#86":"对照从严监督执纪的要求，区分风腐同查同治的治理对象与各类监督的作用。"}},"aspects":[{"title":"同查与同治的治理对象","uses":[{"unit":"Q1","role":"直接考查","use":"本题以中央八项规定为背景。C项准确对应同查针对风腐交织问题、同治针对风腐共性根源。题目选不准确项，答案B把2025年3月贵州考察讲话中的“党性党风党纪一起抓”改成了“党规党纪党务一起抓”。","evidence":"以“同查”严惩风腐交织问题，以“同治”铲除风腐共性根源","qids":["政治理论必刷100题#85"]},{"unit":"Q2","role":"直接考查","use":"本题在从严监督执纪的语境中考查正风肃纪反腐相贯通，D项所述同查、同治的分工成立。题目选不正确项，答案B误将“前哨”作用归于司法监督。按2025年6月30日中央政治局第二十一次集体学习讲话，这里强调发挥群众监督、舆论监督的“前哨”作用。","evidence":"要坚持正风肃纪反腐相贯通，以“同查”严惩风腐交织问题","qids":["政治理论必刷100题#86"]}]}]},"k-1f5a2ec1f3c9f176":{"review":{"definition":"以案促改促治要求从查办的案件中发现问题，推动整改和治理，完善权力配置运行的制约和监督机制，丰富防治新型腐败和隐性腐败的有效办法。","explanation":"二十届中央纪委四次全会讲话将增强以案促改促治实效与完善权力监督、丰富腐败防治办法相联系。D项复述这组要求，表述准确。C项的「同查」「同治」对应同一讲话中关于风腐交织问题及其共性根源的要求，也表述准确。","references":[],"evidence":"增强以案促改促治实效，推动完善权力配置运行的制约和监督机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a460727ca8a3699e":{"review":{"definition":"从严监督执纪要求把党内监督和人民监督结合起来，重视发挥群众监督、舆论监督的“前哨”作用，推动各类监督贯通协调。","explanation":"“前哨”强调及时发现和反映问题。2025年6月30日中共中央政治局第二十一次集体学习讲话中的这一表述，明确点名群众监督和舆论监督。B项将两者替换成司法监督，因此是本题要求选出的不正确项。","references":[],"evidence":"要把党内监督和人民监督结合起来，重视发挥群众监督、舆论监督‘前哨’","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cbc9e0669b3200e8":{"review":{"definition":"从严监督执纪要求坚持完善党和国家监督制度，形成全面覆盖、常态长效的监督合力。","explanation":"“全面覆盖”强调监督的覆盖范围，“常态长效”强调监督能够经常开展、长期发挥作用，“监督合力”强调各类监督协同发力。A项符合十九届中央纪委六次全会讲话提出的要求，在本题中属于正确表述。","references":[],"evidence":"坚持完善党和国家监督制度，形成全面覆盖、常态长效的监督合力。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-16f3b707864928dd":{"review":{"definition":"党的二十大报告要求坚持严管和厚爱相结合，加强对干部全方位管理和经常性监督，落实“三个区分开来”，激励干部敢于担当、积极作为。","explanation":"全方位管理和经常性监督体现严管。处理干部工作中的问题时，需要区分改革探索中的失误与明知故犯的违纪违法行为，使严格监督与担当激励相衔接。C项将严管厚爱、“三个区分开来”和激励担当相联系，符合报告表述。","references":[],"evidence":"坚持严管和厚爱相结合，落实“三个区分开来”，激励干部敢于担当、积极作为","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b2e8968d79ac7287":{"review":{"definition":"军队党的建设必须紧紧围绕能打仗、打胜仗来展开，以战斗力为根本标准。","explanation":"新华社2023年7月的述评把军队党的建设与增强部队战斗力相联系，并列举军队现代化水平和实战能力的提升。A项准确表述了军队党的建设的着力方向，在本题中属于正确表述。","references":[],"evidence":"军队党的建设必须紧紧围绕能打仗、打胜仗来展开","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f0fe2b99668b4de3":{"review":{"definition":"军队人才队伍建设要坚持改革创新，通过调整人员结构和布局等措施激发人才队伍的动力活力。","explanation":"新华社2023年7月的述评以压减全军团级以上机关现役员额、精简服务保障等机构和人员为例，说明改革如何落实到人员结构调整。D项概括了述评提出的工作要求，在本题中属于正确表述。","references":[],"evidence":"坚持改革创新，深层激发人才队伍动力活力。人员结构布局深度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c6ba5d81a0865505":{"review":{"definition":"2025年中央周边工作会议提出，以建设和平、安宁、繁荣、美丽、友好“五大家园”为共同愿景。","explanation":"①把愿景中的“安宁”换成了“富裕”，因此错误。“富邻”出现在周边工作的理念方针中。","references":[],"evidence":"以建设和平、安宁、繁荣、美丽、友好“五大家园”为共同愿景","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-070e83cdfab10849":{"review":{"definition":"2025年中央周边工作会议提出，以睦邻、安邻、富邻、亲诚惠容、命运与共为理念方针，以安危与共、求同存异、对话协商的亚洲安全模式为战略支撑。","explanation":"②把“睦邻、安邻、富邻、亲诚惠容、命运与共”归入作为战略支撑的亚洲安全模式，混淆了会议对理念方针和战略支撑的表述，因此错误。","references":[],"evidence":"安危与共、求同存异、对话协商的亚洲安全模式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7fb9af815df9bccb":{"review":{"definition":"2025年中央周边工作会议提出，构建周边命运共同体要与周边国家深化发展融合，构建高水平互联互通网络，加强产业链供应链合作。","explanation":"构建高水平互联互通网络和加强产业链供应链合作，都是会议部署的发展合作举措。③准确列出了深化发展融合和构建高水平互联互通网络两项要求。","references":[],"evidence":"深化发展融合，构建高水平互联互通网络","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-25feb76dd68b4557":{"review":{"definition":"共建“一带一路”始终坚持共商共建共享原则，由参与各方共同商议合作事项、共同推进建设、共享合作成果。","explanation":"习近平在2024年第四次“一带一路”建设工作座谈会上，回顾了自2013年倡议提出以来坚持这一原则的实践，并将共商共建共享列入高质量发展阶段的指导原则。A项表述正确，题目要求选出错误项。","references":[],"evidence":"始终坚持共商共建共享的原则","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0433e42edfc26311":{"review":{"definition":"2024年第四次“一带一路”建设工作座谈会提出，高质量共建“一带一路”以互联互通为主线，以高质量共建“一带一路”八项行动为指引。","explanation":"B项准确指出了“主线”对应互联互通。讲话同时将八项行动定位为“指引”，将稳中求进表述为“工作总基调”。题目要求选出错误项。","references":[],"evidence":"以互联互通为主线","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2138844f54632c77":{"review":{"definition":"2024年第四次“一带一路”建设工作座谈会提出，要完善“硬联通”“软联通”“心联通”协调推进机制，统筹推进基础设施互联互通、规则标准衔接和共建国家人民之间的交往与理解。","explanation":"C项对应座谈会部署的机制建设举措，要求协调推进三方面的联通。C项表述正确，题目要求选出错误项。","references":[],"evidence":"完善“硬联通”、“软联通”、“心联通”协调推进机制","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"5bfcba55f93da9ec","label":"“硬联通”、“软联通”、“心联通”","topic":"发展与治理","category":"非时政","text":"2.“硬联通”、“软联通”、“心联通”\n“硬联通”指基础设施建设，包括铁路、港口、公路等硬件的联通。它为合作提供了物\n质基础，能够降低贸易成本；“软联通”是指规则标准、制度机制的对接，涵盖海关、税收、\n技术标准等方面的协调。软联通为深化合作提供了制度保障，有助于促进区域市场一体化。\n通过统一规则和标准，减少了贸易壁垒和合作中的不确定性，使得不同地区之间的经济交流\n更加顺畅；“心联通”强调民众间的情感、文化、价值认同。它通过人文交流来增进信任，\n为“软硬联通”奠定民意基础。\n2021 年 11 月 19 日，习近平总书记在出席第三次“一带一路”建设座谈会并发表重要\n讲话时强调，把基础设施“硬联通”作为重要方向，把规则标准“软联通”作为重要支撑，\n把同共建国家人民“心联通”作为重要基础。","source":{"doc":"6cbfb01fe723bba64b75","first":32,"last":32,"page":32,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-bcbf6952157cb0ea":{"review":{"definition":"习近平在2023年二十届中共中央政治局第十次集体学习时提出，要在法治基础上推进高水平对外开放，并在扩大开放中推进涉外法治建设。","explanation":"D项的“跟进一步”强调，随着开放扩大，涉外法治建设也要推进，以夯实进一步开放的法治基础。该项符合讲话原意，题目要求选出有误的表述。","references":[],"evidence":"对外开放向前推进一步，涉外法治建设就要跟进一步","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0807661aee57e16d":{"review":{"definition":"在已经开放的领域，相关部门既要让外资企业依法进入市场，也要解决妨碍符合条件的企业实际开展经营的具体问题。","explanation":"2025年3月28日会见国际工商界代表时，习近平用“大门开、小门不开”指领域已经开放、实际经营仍有具体障碍的情形。①提出破解这些障碍，对应讲话中让外资企业在已开放领域“既准入又准营”的要求。","references":[],"evidence":"‘既准入又准营’","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1a52a78a369b0586":{"review":{"definition":"在华外资企业依法享有公平获得生产要素的机会，这是保障外资企业国民待遇、维护市场公平竞争的一项要求。","explanation":"习近平在2025年3月28日会见国际工商界代表时，将依法公平获得生产要素与加快构建全国统一大市场一并列为维护市场公平竞争的举措。②同时保留了“依法公平”和“加快构建”这两处表述，符合讲话内容。","references":[],"evidence":"保证外资企业依法公平获得生产要素，加快构建全国统一大市场","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-43f645ff244d3f3f":{"review":{"definition":"习近平在2025年3月28日会见国际工商界代表时提出，中国将在当年扩大一些方面的开放试点，并加快文化、教育等领域的开放。","explanation":"④复述了讲话关于进一步扩大开放的两项安排。“扩大”对应一些方面的开放试点，“加快”对应文化、教育等领域的开放进度。","references":[],"evidence":"我们将扩大一些方面开放试点，还将加快文化、教育等领域的开放","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-785051fea527ef0c":{"review":{"definition":"党的二十大报告指出，坚持依法执政首先要坚持依宪执政，坚持宪法确定的中国共产党领导地位不动摇。","explanation":"A项省去了“依宪执政”这一首要要求，并将确定中国共产党领导地位的依据由“宪法”改成“党章”。题干要求选出错误说法，因此选A。","references":[],"evidence":"坚持依法执政首先要坚持依宪执政，坚持宪法确定的中国共产党领导地位","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0e316f9318843f53":{"review":{"definition":"党的二十大报告在部署完善以宪法为核心的中国特色社会主义法律体系时，要求加强重点领域、新兴领域、涉外领域立法，统筹推进国内法治和涉外法治。","explanation":"报告同时明确了三个立法着力领域和国内法治、涉外法治的统筹要求，目的是以良法促进发展、保障善治。B项完整保留了这两层要求，在选非题中应排除。","references":[],"evidence":"加强重点领域、新兴领域、涉外领域立法，统筹推进国内法治和涉外法治","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c2383a4ccfc99a5b":{"review":{"title":"法治政府建设","type":"制度与规则","definition":"法治政府建设是推动各级政府依法履行职能，将行政权力的配置、行使和监督纳入法治轨道的建设任务。党的二十大报告将其定位为全面依法治国的重点任务和主体工程。","explanation":"推进政府机构、职能、权限、程序和责任法定化，可以明确行政机关的职责和权限。重大行政决策应履行法定程序，行政执法应当有法定依据，行政权力行使应当接受监督。","basis":"据关联原题及所列出处编释。","references":[{"source":"govlaw","location":"纲要开篇·建设定位"}],"related":["k-469f06bedb2b5a5f","k-e69dd9ac0a8d9123"],"domain":"法律","examFocus":{"政治理论必刷100题#93":"对照党的二十大报告，区分依法执政、立法、法治政府建设和公正司法的定位与要求。","政治理论必刷100题#94":"在习近平法治思想相关表述中，区分法治队伍建设、法治监督体系和法治政府建设各自的要求。","政治理论必刷100题#95":"依据党的二十大报告区分法治政府与法治社会的定位，并核对司法和公共法律服务的要求。","政治理论必刷100题#96":"把领导干部的带头要求、党的领导、法治政府建设和指导思想的表述放回全面依法治国的部署中核对。","江苏 2024 B类 申论#4":"结合给定资料7和执法案例，辨析“加分”与“乘效”分别涉及哪些执法手段、运行条件和成效。"}},"aspects":[{"title":"在全面依法治国中的定位","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。C项关于扎实推进依法行政和法治政府建设定位的表述正确。答案为A，错在把党的二十大报告所说的“宪法确定”写成“党章确定”。","evidence":"扎实推进依法行政，法治政府建设是全面依法治国的重点任务和主体工程","qids":["政治理论必刷100题#93"]},{"unit":"Q2","role":"直接考查","use":"本题要求选出关于习近平法治思想的不正确表述。D项符合《法治政府建设实施纲要（2021—2025年）》对法治政府建设的定位。答案为A，高素质法治队伍应强调德才兼备。","evidence":"法治政府建设是全面依法治国的重点任务和主体工程","qids":["政治理论必刷100题#94"]},{"unit":"Q3","role":"直接考查","use":"本题要求选出正确表述。②把法治政府建设的定位套用于法治社会建设。党的二十大报告将法治社会定位为构筑法治国家的基础，因此排除②，选B（①③④）。","evidence":"②法治社会建设是全面依法治国的重点任务和主体工程","qids":["政治理论必刷100题#95"]},{"unit":"Q4","role":"直接考查","use":"本题的③对应2020年中央全面依法治国工作会议关于系统谋划、推动法治政府建设率先突破的部署。③成立，四项表述均正确，选D。","evidence":"③全面依法治国是一个系统工程，法治政府建设是重点任务和主体工程","qids":["政治理论必刷100题#96"]}]},{"title":"行政执法规范化与效能提升","uses":[{"unit":"Q5","role":"解题依据","use":"本题要求阐释智慧执法与执法创新。给定资料7以《提升行政执法质量三年行动计划（2023—2025年）》为背景，将执法质量和效能与群众切身利益相联系，并把健全执法机构运行规范、提升人员素质作为科技赋能的基础。其他材料中的行政行为码和裁量基准分别提供了执法过程可追溯和统一处罚尺度的实例。","evidence":"行政执法是法治政府建设的“最后一公里”。","qids":["江苏 2024 B类 申论#4"]}]}],"sources":[{"id":"dc297c735547bdb5","label":"法治政府建设","topic":"发展与治理","category":"非时政","text":"1.法治政府建设\n我们要坚持走中国特色社会主义法治道路，建设中国特色社会主义法治体系、建设社会\n主义法治国家，围绕保障和促进社会公平正义，坚持依法治国、依法执政、依法行政共同推\n进，坚持法治国家、法治政府、法治社会一体建设，全面推进科学立法、严格执法、公正司\n法、全民守法，全面推进国家各方面工作法治化。\n扎实推进依法行政。法治政府建设是全面依法治国的重点任务和主体工程。\n——《党的二十大报告》","source":{"doc":"6cbfb01fe723bba64b75","first":51,"last":52,"page":51,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-fc9736bec72386b6":{"review":{"definition":"党的二十大报告将公正司法定位为维护社会公平正义的最后一道防线，并要求深化司法体制综合配套改革，全面准确落实司法责任制。","explanation":"D项前半句说明公正司法的功能，后半句列出推进严格公正司法的改革要求。两处均符合党的二十大报告“严格公正司法”部分的表述，因此在选非题中应排除。","references":[],"evidence":"公正司法是维护社会公平正义的最后一道防线，深化司法体制综合配套改革","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bc278a5767c63b77":{"review":{"definition":"全面推进依法治国要建设一支德才兼备的高素质法治队伍，对队伍的品德和业务能力都有要求。","explanation":"2014年党的十八届四中全会第二次全体会议讲话使用的是“德才兼备”。第94题A项将这一要求改为“以才为先”，把德与才的并重要求改成了对才的优先排序，因此是本题应选的错误项。","references":[],"evidence":"建设一支德才兼备的高素质法治队伍至关重要","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-58d5cf44b69b7f4f":{"review":{"definition":"严密的法治监督体系以规范和约束公权力为重点，要求有权必有责、用权受监督、违法必追究。","explanation":"通过监督公权力的行使并追究违法责任，可以纠正有法不依、执法不严、违法不究等行为，保障宪法和法律有效实施。第94题C项准确指出了该体系的监督重点，在选非题中应排除。","references":[],"evidence":"严密的法治监督体系以规范和约束公权力为重点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bfc18066bbb72edd":{"review":{"definition":"宪法居于中国特色社会主义法律体系的核心地位。完善这一体系要加强宪法实施和监督，健全保证宪法全面实施的制度体系。","explanation":"党的二十大报告把宪法的核心地位落实到依法治国和依法执政的要求中，分别强调首先坚持依宪治国和依宪执政。第95题①准确表述了完善法律体系的要求，应纳入正确组合。","references":[],"evidence":"完善以宪法为核心的中国特色社会主义法律体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b24ada92ba0cb009":{"review":{"definition":"严格公正司法要求全面准确落实司法责任制，加快建设公正高效权威的社会主义司法制度。","explanation":"党的二十大报告把公正司法定位为维护社会公平正义的最后一道防线，并将落实司法责任制和完善司法制度列为推进严格公正司法的举措。第95题③同时写出了这两项要求，应纳入正确组合。","references":[],"evidence":"全面准确落实司法责任制，加快建设公正高效权威的社会主义司法制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-62f51a6bb3034262":{"review":{"definition":"法治社会是构筑法治国家的基础。建设法治社会要建设覆盖城乡的现代公共法律服务体系，深入开展法治宣传教育，增强全民法治观念。","explanation":"第95题④的公共法律服务对应城乡服务覆盖，法治宣传教育对应增强全民法治观念，两者都是党的二十大报告提出的法治社会建设举措。②将法治政府建设的定位“重点任务和主体工程”赋予了法治社会建设，因此正确组合保留④、排除②。","references":[],"evidence":"建设覆盖城乡的现代公共法律服务体系，深入开展法治宣传教育，增强全民法治观念","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9938f2750c608d1a":{"review":{"definition":"全面依法治国要抓住领导干部这个“关键少数”。各级领导干部应带头尊崇法治、敬畏法律，做尊法学法守法用法的模范。","explanation":"2020年中央全面依法治国工作会议强调，领导干部既要发挥示范作用，也要提高运用法治思维和法治方式深化改革、化解矛盾等工作的能力。第96题①把“关键少数”明确为领导干部，并准确列出其带头要求。","references":[],"evidence":"各级领导干部要带头尊崇法治、敬畏法律","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a2c146db107f2a3d":{"review":{"definition":"党的二十大报告提出，到2035年，我国经济实力、科技实力、综合国力大幅跃升，人均国内生产总值迈上新的大台阶，达到中等发达国家水平。","explanation":"第①项准确对应两组目标。经济实力、科技实力和综合国力对应“大幅跃升”，“达到中等发达国家水平”具体修饰人均国内生产总值。","references":[],"evidence":"经济实力、科技实力、综合国力大幅跃升，人均国内生产总值迈上新的大台阶，达到中等发达国家水平","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4422e18d55c882e4":{"review":{"definition":"党的二十大报告提出，到2035年，我国要实现高水平科技自立自强，进入创新型国家前列。","explanation":"第②项保留了“实现高水平科技自立自强”，却将“进入创新型国家前列”改成“力争进入创新型国家行列”，同时改变了目标措辞和所要求的位次，因此错误。","references":[],"evidence":"实现高水平科技自立自强，进入创新型国家前列","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-547ee6bea4bc57b4":{"review":{"definition":"党的二十大报告提出，到2035年，我国要建成现代化经济体系，形成新发展格局，基本实现新型工业化、信息化、城镇化、农业现代化。","explanation":"第③项准确对应三组目标及其达成程度。现代化经济体系对应“建成”，新发展格局对应“形成”，“基本实现”统领随后列出的四项现代化。","references":[],"evidence":"建成现代化经济体系，形成新发展格局，基本实现新型工业化、信息化、城镇化、农业现代化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-90b98b240ade170c":{"review":{"definition":"党的二十大报告提出，到2035年，我国要广泛形成绿色生产生活方式，碳排放达峰后稳中有降，生态环境根本好转，美丽中国目标基本实现。","explanation":"报告描述的是碳排放达到峰值后的下降趋势。第④项把这一趋势改成“基本实现‘碳中和’目标”，又把美丽中国目标的“基本实现”改成“全面实现”，因此错误。","references":[],"evidence":"广泛形成绿色生产生活方式，碳排放达峰后稳中有降","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-604a13a0d9eb34e7":{"review":{"definition":"党的二十大报告提出，到2035年基本实现社会主义现代化，在此基础上继续奋斗，到本世纪中叶把我国建设成为综合国力和国际影响力领先的社会主义现代化强国。","explanation":"第⑤项的强国目标对应本世纪中叶。题干限定的是2035年总体目标，因此第⑤项所述目标的时间节点不符合题意。","references":[],"evidence":"到本世纪中叶，把我国建设成为综合国力和国际影响力领先的社会主义现代化强国","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-538b5dcf352e7b28":{"review":{"definition":"《中国共产党党徽党旗条例》第十条第一款第五项将开展党的对外交往活动列为可以使用党旗的情形。","explanation":"该项规定的对象是党旗，“可以使用”表示允许使用。A项把开展党的对外交往活动表述为“必须使用党徽党旗”，将许可写成义务，因此是本题要求选出的错误项。","references":[],"evidence":"下列情形可以使用党旗：（五）开展党的\n对外交往活动。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4182ab8ce823d14c":{"review":{"definition":"根据《中国共产党党徽党旗条例》第十六条第一款，在网络、出版物等使用党徽党旗图案，应当将图案置于显著位置。","explanation":"使用图案是这项位置要求的适用前提。B项同时写明了使用场景和“应当置于显著位置”的要求，符合条文，本题选不正确项，故排除B项。","references":[],"evidence":"在网络、出版物等使用党徽党旗图案，应当置于显著位置","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ffafb2e498b53eb8":{"review":{"definition":"《中国共产党党徽党旗条例》第十四条第一款规定，不得在党徽党旗上添加任何文字、符号和图案等。","explanation":"禁令同时适用于党徽和党旗，“任何”涵盖在其上添加的各类文字、符号和图案。C项准确复述了这项禁令，本题选不正确项，故排除C项。","references":[],"evidence":"不得在党徽党旗上添加任何文字、符号和图案等","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a769b61f23e5092e":{"review":{"definition":"《中国共产党党徽党旗条例》第四条规定，党徽党旗制作、使用、管理必须坚持统一标准、统一规范，坚持分级负责、集中管理。","explanation":"统一标准、统一规范覆盖制作、使用和管理三个环节。D项准确表述了这两项要求，本题选不正确项，故排除D项。","references":[],"evidence":"党徽党旗制作、使用、管理必须坚持统一标准、统一规范","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-120f6e5b8b0a98b6":{"review":{"definition":"《黄河流域生态保护和高质量发展规划纲要》提出，到2035年，黄河流域生态保护和高质量发展取得重大战略成果。","explanation":"纲要将生态环境全面改善、水资源节约集约利用水平全国领先等列为同一时点的发展目标。A项准确对应了2035年和“取得重大战略成果”这一规划目标，本题选错误项，故排除A项。","references":[],"evidence":"到2035年黄河流域生态保护和高质量发展取得重大战略成果","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-67629cadc60f58af":{"review":{"title":"新型农业补贴政策体系","type":"制度与规则","definition":"《中华人民共和国乡村振兴促进法》第六十条规定，国家构建以高质量绿色发展为导向的新型农业补贴政策体系。","explanation":"该条规定了构建农业补贴政策体系应遵循的三项原则，即增加总量、优化存量、提高效能。","basis":"据关联原题及所列出处编释。","references":[{"source":"rural","location":"第六十条"}],"examFocus":{"国考 2023 副省级 行测#8":"按《乡村振兴促进法》核对农业补贴的构建主体和政策导向，并区分城乡发展、耕地保护和基层法律服务的规定。"}},"aspects":[{"title":"农业补贴的高质量绿色发展导向","uses":[{"unit":"Q1","role":"直接考查","use":"B项准确对应第六十条规定的构建主体和政策导向，应选B。","evidence":"国家构建以高质量绿色发展为导向的新型农业补贴政策体系","qids":["国考 2023 副省级 行测#8","国考 2023 行政执法 行测#7"]}]}]},"k-254d4e19b07dfa68":{"review":{"title":"农业农村优先发展原则","type":"制度与规则","definition":"《中华人民共和国乡村振兴促进法》第四条第一项规定，全面实施乡村振兴战略应当坚持农业农村优先发展。","explanation":"法条将优先要求落实为干部配备上优先考虑、要素配置上优先满足、资金投入上优先保障、公共服务上优先安排。","basis":"据关联原题及所列出处编释。","references":[{"source":"rural","location":"第四条"}],"related":["k-fb585b673e5cb691","k-7f4a4aba9435a8e5"],"examFocus":{"国考 2023 副省级 行测#8":"依据《中华人民共和国乡村振兴促进法》，区分城乡融合原则与优先发展原则各自回答的问题。"}},"aspects":[{"title":"乡村振兴的优先发展对象","uses":[{"unit":"Q1","role":"解题依据","use":"A项把优先发展的对象写成城镇，依据第四条第一项排除。正确项B对应第六十条规定的新型农业补贴政策体系。","evidence":"坚持农业农村优先发展，在干部配备上优先考虑","qids":["国考 2023 副省级 行测#8","国考 2023 行政执法 行测#7"]}]}]},"k-7f4a4aba9435a8e5":{"review":{"title":"省级政府的耕地保护责任","type":"制度与规则","definition":"《中华人民共和国乡村振兴促进法》第十四条第一款要求省、自治区、直辖市人民政府采取措施，确保耕地总量不减少、质量有提高。","explanation":"该款同时规定国家建立农用地分类管理制度，严格控制农用地转为建设用地，以及耕地转为林地、园地等其他类型农用地。","basis":"据关联原题及所列出处编释。","references":[{"source":"rural","location":"第十四条"}],"related":["k-254d4e19b07dfa68","k-fb585b673e5cb691","k-caedc47bc4c7745b","k-7710ae6ce7fdca2f"],"examFocus":{"国考 2023 副省级 行测#8":"核对《乡村振兴促进法》规定的耕地保护责任时，分清责任主体、耕地总量要求和耕地质量要求。"}},"aspects":[{"title":"耕地总量底线","uses":[{"unit":"Q1","role":"解题依据","use":"C项列出的责任主体符合条文，但把总量不减少的底线写成了稳步增加的目标，因此排除。正确答案为B。","evidence":"省、自治区、直辖市人\n民政府应当采取措施确保耕地总量不减少、质量有提高。","qids":["国考 2023 副省级 行测#8","国考 2023 行政执法 行测#7"]}]}]},"k-b1e0d35a468bafd8":{"review":{"definition":"《中华人民共和国乡村振兴促进法》第四十八条鼓励乡镇人民政府根据需要设立法律顾问和公职律师，并鼓励有条件的地方在村民委员会建立公共法律服务工作室。","explanation":"条文对两项措施均使用“鼓励”，分别对应乡镇实际需要和地方具备条件。D项把乡镇设立法律顾问和公职律师写成义务，又把“根据需要”移用于村级工作室，因此错误。本题选正确项，答案是关于新型农业补贴政策体系的B项。","references":[],"evidence":"鼓励乡镇人民政府根据需要设立法律顾问和公职律师，鼓励有条件的地方在村民委员会建立公共法律服务工作\n室","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-73763240b8736f2e":{"review":{"definition":"《“十四五”推进农业农村现代化规划》以南菜北运基地和黄淮海地区设施蔬菜生产为冬春蔬菜基地建设重点，以高山、高原、高海拔等冷凉地区蔬菜生产为夏秋蔬菜基地建设重点。","explanation":"规划按季节安排不同地区的生产重点，以实现品种互补、档期合理和区域协调。C项把冬春蔬菜基地的建设重点写成了夏秋蔬菜基地的建设重点，符合题干选错误项的要求。","references":[],"evidence":"以高山、高原、高海拔等冷凉地区蔬菜生产为重点加强夏秋蔬菜生产基地建设","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0c358834d81f8df3":{"review":{"definition":"《“十四五”推进农业农村现代化规划》提出扩大稻谷、小麦、玉米三大粮食作物完全成本保险和种植收入保险的实施范围。","explanation":"这是规划完善粮食生产扶持政策的一项措施。A项所列的三种作物、两类保险及扩大实施范围的要求均与规划一致，因此在本题的选非条件下应排除。","references":[],"evidence":"扩大稻谷、小麦、玉米三大粮食作物完全成本保险和种植收入保险实施范围","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d91598b1346db534":{"review":{"definition":"《“十四五”推进农业农村现代化规划》提出稳定发展优质粳稻，巩固提升南方双季稻生产能力。","explanation":"两项部署同属优化粮食品种结构的措施。“稳定发展”对应优质粳稻，“巩固提升生产能力”对应南方双季稻。B项保留了这两组对应关系，符合规划。","references":[],"evidence":"稳定发展优质粳稻，巩固提升南方双季稻生产能力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cfcfff1d769fbfca":{"review":{"definition":"《“十四五”推进农业农村现代化规划》提出推进耕地保护与质量提升行动，加强南方酸化耕地降酸改良和北方盐碱耕地压盐改良。","explanation":"两类改良措施分别针对耕地酸化和盐碱化问题。D项把南方酸化耕地与降酸、北方盐碱耕地与压盐正确对应，符合规划提升耕地质量的部署。","references":[],"evidence":"加强南方酸化耕地降酸改良治理和北方盐碱耕地压盐改良治理","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f56483cb71c38b3e":{"review":{"definition":"有价证券持有人可以依证券种类及适用规则行使相应权利。不同类别证券的持有人可以享有不同的权利，行使权利也可能有条件。","explanation":"解析以优先股为例。优先股持有人可以在利润和剩余财产分配上享有优先权，同时其参与公司决策的表决权一般受限。分配优先与表决受限可以并存，足以支持C项所说的“不一定能行使有价证券的全部权利”。","references":[],"evidence":"有价证券的持有人不一定能行使有价证券的全部权利","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-55a9ec5f5997c1d3":{"review":{"definition":"我国海关统计货物贸易金额时，出口货物采用离岸价格口径，进口货物采用到岸价格口径。","explanation":"离岸价以货物在出口地装运为计价界点，到岸价还计入货物运抵进口地所需的运费和保险费。D项把出口的离岸价口径也套用于进口，因此“一律按离岸价格统计”的说法错误。","references":[],"evidence":"出口货物按离岸价格统计，进口货物按到岸价格统计","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e7367a6531ecfefb":{"review":{"definition":"材料记载，2021年公布整县（市、区）屋顶分布式光伏开发试点名单时，国家有关部门要求试点地区落实“自愿不强制、试点不审批、到位不越位、竞争不垄断、工作不暂停”，相关部门应加强监管。","explanation":"B县先暂缓全县光伏项目，后把整县屋顶资源交给一家企业，分别与“工作不暂停”和“竞争不垄断”的要求相冲突。题中据此可归纳开发模式问题，并提出让符合条件的企业参与公平竞争、由政府做好监管和协调服务的建议。","references":[],"evidence":"“自愿不强制、试点不审批、到位不越位、竞争不垄断、工作不暂停”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-98bb2095a67b66dd":{"review":{"definition":"党的二十大报告提出，到2035年，我国经济实力、科技实力、综合国力大幅跃升，人均国内生产总值迈上新的大台阶，达到中等发达国家水平。","explanation":"①同时写出了三项实力跃升和人均国内生产总值达到的水平，与报告所列2035年目标一致。⑤所说建设成为综合国力和国际影响力领先的社会主义现代化强国，时间节点是本世纪中叶。本题①③正确，共2项。","references":[],"evidence":"人均国内生产总值迈上新的大台阶，达到中等发达国家水平","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-06edceaa98ac52f6":{"review":{"definition":"党的二十大报告提出，到2035年，我国实现高水平科技自立自强，进入创新型国家前列。","explanation":"②保留了“实现高水平科技自立自强”，却把“进入创新型国家前列”写成“力争进入创新型国家行列”，同时改变了目标措辞和所处位置，因此②错误。","references":[],"evidence":"实现高水平科技自立自强，进入创新型国家前列","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-598e8dde0675f422":{"review":{"definition":"党的二十大报告提出，到2035年，我国建成现代化经济体系，形成新发展格局，基本实现新型工业化、信息化、城镇化、农业现代化。","explanation":"③准确保留了三组目标的完成程度：现代化经济体系用“建成”，新发展格局用“形成”，新型工业化、信息化、城镇化、农业现代化用“基本实现”。因此③正确。","references":[],"evidence":"建成现代化经济体系，形成新发展格局，基本实现新型工业化、信息化、城镇化、农业现代化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-86638e7ed22a64c3":{"review":{"definition":"党的二十大报告提出，到2035年，我国广泛形成绿色生产生活方式，碳排放达峰后稳中有降，生态环境根本好转，美丽中国目标基本实现。","explanation":"④正确保留了绿色生产生活方式和生态环境好转的表述，却把达峰后的碳排放下降趋势改成“基本实现‘碳中和’目标”，又将美丽中国目标的“基本实现”改为“全面实现”，因此④错误。","references":[],"evidence":"碳排放达峰后稳中有降，生态环境\n根本好转，美丽中国目标基本实现","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1bb202a2f48a8ed3":{"review":{"definition":"2021年中央财经委员会第十次会议提出，在高质量发展中促进共同富裕，要正确处理效率和公平的关系，构建初次分配、再分配、三次分配协调配套的基础性制度安排。","explanation":"会议提出将三个分配环节统筹起来，作为处理效率与公平关系的制度安排。第③项同时写明效率与公平的关系以及三个分配环节的协调配套，符合会议表述，应计入正确项。","references":[],"evidence":"构建初次分配、再分配、三次分配协调配套的基础性制度安排","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7081e04dab610420":{"review":{"definition":"《“十四五”全国农业绿色发展规划》提出，到2035年，农村生态环境根本好转，绿色生产生活方式广泛形成。","explanation":"规划在“发展目标”中把这两项要求都列入2035年远期目标。A项的年份和两项表述均与规划一致，本题要求选出错误说法，A项应排除。","references":[],"evidence":"到2035年，农村生态环境根本好转，绿色生产生活方式广泛形成","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-11e85c28a9075b2c":{"review":{"definition":"《“十四五”全国农业绿色发展规划》把果菜茶优势区列为推动粪肥还田利用的重点区域，以有机肥替代部分化肥，减少化肥用量。","explanation":"B项把重点区域“果菜茶优势区”、措施“粪肥还田”和目标“减少化肥用量”对应起来，符合规划中化肥减量增效的安排，因此应在选非题中排除。","references":[],"evidence":"以果菜茶优势区为重点推动粪肥还田利用，减少化肥用量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-98f984f05f1aea9f":{"review":{"definition":"《“十四五”全国农业绿色发展规划》提出，在西北地区支持一批用膜大县以整县为单位推进农膜回收。","explanation":"规划在加强白色污染治理的安排中明确了支持地区、县域对象和推进范围。C项中的“西北地区”“一批用膜大县”和“整县推进”均与规划一致，因此应在选非题中排除。","references":[],"evidence":"在西北地区支持一批用膜大县整县推进农膜回收","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-036485e66ac9034c":{"review":{"definition":"《“十四五”全国农业绿色发展规划》提出，在长江中下游、西南和华南等南方粮食主产区推进酸化耕地降酸改良，在西北灌溉区、滨海灌溉区和松嫩平原西部等盐碱集中地区示范耕作压盐等技术，推进盐碱耕地改良。","explanation":"规划按耕地退化类型和地区配置治理措施。D项把适用于盐碱集中地区的耕作压盐示范放到了长江中下游、西南等南方粮食主产区，错配了地区与技术，因此是本题应选的错误项。","references":[],"evidence":"在长江中下游、西南地区等南方粮食主产区集中示范耕作压盐技术模式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4982f03b1299726b":{"review":{"definition":"票据债务人依法按票据记载承担付款义务。取得票据原则上应给付对价，依法因税收、继承、赠与无偿取得的情形除外。","explanation":"本题为选非题，A项把请求相应对价概括为有价证券债务人的一般权利，所给答案选A。以票据为例，债务人不能仅凭自己负有票据付款义务就向持票人请求对价。对与自己有直接债权债务关系且未履行约定义务的持票人，债务人可依法抗辩。解析中的“单方义务”应限于证券上的付款关系理解，对价还可能来自取得证券的基础交易。","references":[{"source":"web-0f691ce75929a2f1","location":"第十条至第十三条","quote":"票据的取得，必须给付对价"}],"evidence":"有价证券的债务人可以请求债权人支付相应对价","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-5d9a97755247e962":{"review":{"definition":"国家助学贷款是政府主导、由金融机构向符合条件的家庭经济困难高校学生提供的信用贷款，用于帮助解决就学费用。学生无须办理贷款担保或抵押，并应按约定还款。","explanation":"第7题D项判断的是办理贷款时是否需要担保或抵押。按解析所述的信用贷款规则，D项成立，学生仍应履行约定的还款义务。","references":[],"evidence":"国家助学贷款是信用贷款，学生不需要办理贷款担保或抵押","disposition":"独立词条","basis":"据原题和解析编释。","title":"国家助学贷款","related":[],"examFocus":{"国考 2023 地市级 行测#7":"辨析国家助学贷款的性质，以及办理时对担保和抵押的要求。"}},"readings":[{"origin":"k-5d9a97755247e962","title":"国家助学贷款","qs":["国考 2023 地市级 行测#7"],"definition":"国家助学贷款是政府主导、由金融机构向符合条件的家庭经济困难高校学生提供的信用贷款，用于帮助解决就学费用。学生无须办理贷款担保或抵押，并应按约定还款。","explanation":"第7题D项判断的是办理贷款时是否需要担保或抵押。按解析所述的信用贷款规则，D项成立，学生仍应履行约定的还款义务。","evidence":"国家助学贷款是信用贷款，学生不需要办理贷款担保或抵押","doubt":"","references":[]},{"origin":"k-9bb1cfa0c5f94c1f","title":"国家助学贷款","qs":["国考 2023 行政执法 行测#6"],"definition":"国家助学贷款是由政府主导、金融机构向符合条件的家庭经济困难高校学生发放的信用贷款。学生无须提供担保或抵押，应按约定履行还款义务。","explanation":"D项考的是办理国家助学贷款时的增信要求。学生凭信用申请，无须找人担保或以财产抵押，因此D项成立。借款人仍应按约定还款。","evidence":"国家助学贷款是信用贷款，学生不需要办理贷款担保或抵押","doubt":"","references":[]}]},"k-a6e4dd95d97c36c8":{"review":{"definition":"退役军人随迁子女需要转学、入学时，安置地人民政府教育行政部门应当及时办理。参战退役军人的随迁子女属于优先保障对象。","explanation":"第8题A项同时给出了“参战退役军人”和“随迁子女入学”两个条件，符合题引《中华人民共和国退役军人保障法》第二十九条第四款所列的优先保障情形。","references":[],"evidence":"对下列退役军人的随迁子女，优先保障：（一）参战退役军人。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ef6576c99f720e30":{"review":{"definition":"逐月领取退役金是《中华人民共和国退役军人保障法》为符合条件的退役军官和退役军士列明的安置方式之一。","explanation":"第8题B项把退役军士和退役义务兵并列为适用对象。题引第二十二条将逐月领取退役金列入军士安置方式，第二十三条为义务兵列出的是自主就业、安排工作和供养，因此B项整体错误。","references":[],"evidence":"对退役的军士，国家采取逐月领取退役金、","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5b7bf537c5ac2899":{"review":{"title":"退役军人创业扶持","type":"制度与规则","definition":"《中华人民共和国退役军人保障法》第四十六条规定，退役军人创办小微企业，可以按照国家有关规定申请创业担保贷款，并享受贷款贴息等融资优惠政策。退役军人从事个体经营，依法享受税收优惠政策。","explanation":"创业担保贷款须依有关规定申请。贷款贴息是按政策对贷款利息给予补贴，个体经营可享受的具体税收优惠按适用规定确定。","basis":"据关联原题及所列出处编释。","references":[{"source":"veteran","location":"第四十六条"}],"examFocus":{"国考 2023 地市级 行测#8":"根据《中华人民共和国退役军人保障法》，区分不同创业形式适用的融资与税收优惠，并核对政策的适用范围。"}},"aspects":[{"title":"融资和税收优惠的适用情形","uses":[{"unit":"Q1","role":"直接考查","use":"D项把扶持对象泛称为创办企业的退役军人，并把优惠写成免税和贷款免息。第四十六条明确了小微企业的融资优惠和个体经营的税收优惠，因此排除D项，答案为A。（国考 2023 地市级 行测第8题、国考 2023 行政执法 行测第8题）","evidence":"退役军人创办企业可以享受免税、贷款免息等优惠政策","qids":["国考 2023 地市级 行测#8","国考 2023 行政执法 行测#8"]}]}]},"k-154df3807c95078a":{"review":{"definition":"依题引《中华人民共和国生物安全法》第四十六条，高等级病原微生物实验室从事涉及高致病性或疑似高致病性病原微生物的实验活动，须依法获得批准，并向批准部门报告活动情况。","explanation":"第9题是选非题。C项用“一律不得”概括法定管理要求。题引条文明确规定符合条件的实验室须经审批并履行报告义务，因此C项错误。","references":[],"evidence":"动情况向批准部门报告。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a853499c2f59aca3":{"review":{"definition":"交通事故损失由非机动车驾驶人或行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。","explanation":"第10题C项明示行人故意碰撞机动车并因此造成交通事故。就题引《中华人民共和国道路交通安全法》第七十六条第二款规定的损失赔偿而言，该条件使机动车一方免于赔偿，C项所说的承担次要责任有误。","references":[],"evidence":"行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2cec074bf48cfbbc":{"review":{"definition":"实施电信网络诈骗时非法使用伪基站，干扰无线电通讯秩序且符合刑法第二百八十八条规定的，以扰乱无线电通讯管理秩序罪追究刑事责任。同时构成诈骗罪的，依照处罚较重的规定定罪处罚。","explanation":"第11题A项把题述行为直接归入非法侵入计算机信息系统罪。题引司法意见要求判断是否符合扰乱无线电通讯管理秩序罪的构成条件，并规定同时构成诈骗罪时从一重处罚，因此A项错误。","references":[],"evidence":"同时构成诈骗罪的，依照处罚较重的规定定罪处罚。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c1666a11d5805da7":{"review":{"definition":"根据本题所引《中华人民共和国职业教育法》第五十八条第二款，企业设立具备生产与教学功能的产教融合实习实训基地所发生的费用，可以参照职业学校享受相应的用地、公用事业费等优惠。","explanation":"条文以职业学校的相应优惠为参照。A项把“可以参照”改成了“享受高于职业学校的优惠政策”，改变了优惠标准，因此是本题要求选出的错误说法。","references":[],"evidence":"可以参照职业学校享受相应的用地、公用事业费等优惠","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8c7629388b4025c1":{"review":{"definition":"面向公众的招牌、广告一般应使用规范汉字。材料3中，D市执法人员依据国家通用语言文字法对部分不规范用字进行纠错，并劝导商家整改。","explanation":"材料列出普通商家招牌和广告中繁简混用以及把“啤酒”写成“啤九”、把“鸡蛋”写成“鸡旦”等情形。这些例子对应提纲中的户外设施用字摸排和整改。部分商家不了解相关规定，则是提纲提出加强宣传的依据。","references":[],"evidence":"招牌、广告用字应该使用规范汉字","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a00a8fcb9d224472":{"review":{"title":"收入分配制度","type":"制度与规则","definition":"收入分配制度规定收入如何形成、分配和调节。我国坚持按劳分配为主体、多种分配方式并存，构建初次分配、再分配、第三次分配协调配套的制度体系。","explanation":"初次分配形成劳动报酬等收入。政府通过税收、社会保障和转移支付等机制进行再分配。第三次分配主要通过社会力量自愿参与公益慈善等方式发挥作用。党的二十大报告将分配制度明确为促进共同富裕的基础性制度。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"完善分配制度"}],"related":["k-aa052a4589f73e60","k-abc7a40f1ee48790"],"domain":"经济","examFocus":{"国考 2023 行政执法 行测#3":"核对党的二十大报告中分配制度与民生目标的关系，并与就业、社会保障体系和人民健康的定位区分。","国考 2025 副省级 行测#10":"对照收入分配制度改革部署，按调节方式和作用区分初次分配、再分配和第三次分配。"}},"aspects":[{"title":"促进共同富裕的基础性作用","uses":[{"unit":"Q1","role":"直接考查","use":"本题 要求辨认党的二十大报告关于民生福祉的表述。D项准确对应完善分配制度部分。","evidence":"分配制度是促进共同富裕的基础性制度","qids":["国考 2023 行政执法 行测#3"]}]},{"title":"再分配调节机制","uses":[{"unit":"Q2","role":"直接考查","use":"本题 均为选非题。党的二十届三中全会2024年通过的《中共中央关于进一步全面深化改革 推进中国式现代化的决定》第42条将税收、社会保障、转移支付列为再分配调节机制。D项将其归为第三次分配，故三卷均选D。","evidence":"完善税收、社会保障、转移支付等第三次分配调节机制","qids":["国考 2025 副省级 行测#10","国考 2025 地市级 行测#10","国考 2025 行政执法 行测#10"]}]}],"sources":[{"id":"5cbd9b1179a2a2b6","label":"收入分配制度","topic":"就业、社保与公共服务","category":"非时政","text":"3.收入分配制度\n分配制度是促进共同富裕的基础性制度。党的二十届三中全会提出，“完善收入分配制\n度。构建初次分配、再分配、第三次分配协调配套的制度体系，提高居民收入在国民收入分\n配中的比重，提高劳动报酬在初次分配中的比重”。这为完善收入分配制度提供了基本遵循。\n要正确处理好初次分配、再分配、第三次分配的关系。\n初次分配是指在社会生产活动中，企业作为分配主体，将国民收入在国家、企业、个人\n之间进行分配，是最基本的分配关系，主要是在市场机制中形成的。再分配是指在初次分配\n结果的基础上，政府对收入分配进行再次调节的过程，目的在于调节城乡、区域、部门和劳\n动者之间的收入分配关系，保障社会公平。第三次分配是指企业、社会组织和个人在自愿基\n础上向他人进行捐赠或无偿提供帮助。初次分配是基础，再分配是保障，第三次分配是必要\n的补充。","source":{"doc":"6cbfb01fe723bba64b75","first":18,"last":19,"page":18,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-f640aa57d133633d":{"review":{"definition":"社会保障体系是为居民提供基本生活保障、分担养老等风险的制度体系。党的二十大报告将其概括为人民生活的安全网和社会运行的稳定器。","explanation":"报告提出健全覆盖全民、统筹城乡的多层次社会保障体系。A项把“安全网和稳定器”的定位移给了就业，而报告称就业是最基本的民生。D项保留了“分配制度是促进共同富裕的基础性制度”的正确对应。","references":[],"evidence":"人民生活的安全网和社会运行的稳定器。","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"39ebe4485fa4e480","label":"社会保障体系","topic":"就业、社保与公共服务","category":"非时政","text":"4.社会保障体系\n社会保障主要由社会保险、社会救助、社会福利、社会优抚组成，还包括其他社会保障\n形式，它们共同构成我国的社会保障体系。社会保障体系是人民生活的安全网和社会运行的\n稳定器。健全覆盖全民、统筹城乡、公平统一、安全规范、可持续的多层次社会保障体系。","source":{"doc":"6cbfb01fe723bba64b75","first":19,"last":19,"page":19,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-7e903b25643f6630":{"review":{"definition":"《黄河流域生态保护和高质量发展规划纲要》规定，荒漠化防治区以内蒙古高原南缘、宁夏中部等为主，水土保持区以青海东部、陇中陇东、陕北、晋西北、宁夏南部黄土高原为主。","explanation":"两区同属纲要生态保护空间布局中的“五区”。D项把荒漠化防治区的主要地域写成了水土保持区的主要地域，因此是本题应选的错误项。","references":[],"evidence":"南缘、宁夏中部等为主的荒漠化防治区","disposition":"独立词条","basis":"据原题和解析编释。","title":"黄河流域荒漠化防治区与水土保持区","related":[],"examFocus":{"国考 2023 副省级 行测#7":"对照《黄河流域生态保护和高质量发展规划纲要》，辨析荒漠化防治区与水土保持区各自覆盖的主要地域。"}},"readings":[{"origin":"k-7e903b25643f6630","title":"黄河流域荒漠化防治区与水土保持区","qs":["国考 2023 行政执法 行测#5"],"definition":"《黄河流域生态保护和高质量发展规划纲要》规定，荒漠化防治区以内蒙古高原南缘、宁夏中部等为主，水土保持区以青海东部、陇中陇东、陕北、晋西北、宁夏南部黄土高原为主。","explanation":"两区同属纲要生态保护空间布局中的“五区”。D项把荒漠化防治区的主要地域写成了水土保持区的主要地域，因此是本题应选的错误项。","evidence":"南缘、宁夏中部等为主的荒漠化防治区","doubt":"","references":[]},{"origin":"k-bf16165649c20d7e","title":"黄河流域荒漠化防治区与水土保持区","qs":["国考 2023 副省级 行测#7"],"definition":"在黄河流域生态保护“一带五区多点”布局中，荒漠化防治区以内蒙古高原南缘、宁夏中部等为主。水土保持区以青海东部、陇中陇东、陕北、晋西北、宁夏南部黄土高原为主。","explanation":"纲要分别把宁夏中部和宁夏南部黄土高原列为荒漠化防治区和水土保持区的主要地域。D项把内蒙古高原南缘、宁夏中部等写成水土保持区的主要地域，错配了两类分区，因此是本题要求选出的错误项。","evidence":"以内蒙古高原\n南缘、宁夏中部等为主的荒漠化防治区，以青海东部、陇中陇东、陕北、晋西北、宁夏南部黄土高原为主的水土保\n持区","doubt":"","references":[]}]},"k-e923b06705f1243e":{"review":{"definition":"《黄河流域生态保护和高质量发展规划纲要》提出，到2035年，黄河流域生态保护和高质量发展取得重大战略成果。","explanation":"这一规划目标包括流域生态环境全面改善、生态系统健康稳定、水资源节约集约利用水平全国领先和现代化经济体系基本建成。A项的目标年份和“取得重大战略成果”的表述均符合纲要，选非时应排除。","references":[],"evidence":"到2035年黄河流域生态保护和高质量发展取得重大战略成果","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6180e015318d8912":{"review":{"definition":"《黄河流域生态保护和高质量发展规划纲要》提出，支持青海、甘肃、四川等风能、太阳能丰富地区构建风光水多能互补系统。","explanation":"纲要提出发挥黄河上游水电站和电网系统的调节能力，使风电、光伏发电和水电协调运行。C项用“青海、甘肃等”举例，保留了风能、太阳能丰富这一条件和建设风光水多能互补系统这一要求，符合纲要。","references":[],"evidence":"支持青海、甘肃、四川等风能、太阳能丰富地区构建风光水多能互补系统。","disposition":"独立词条","basis":"据原题和解析编释。","title":"黄河流域风光水多能互补系统","related":[],"examFocus":{"国考 2023 副省级 行测#7":"对照规划纲要，核对风光水多能互补系统的布局地区和资源条件。"}},"readings":[{"origin":"k-6180e015318d8912","title":"黄河流域风光水多能互补系统","qs":["国考 2023 行政执法 行测#5"],"definition":"《黄河流域生态保护和高质量发展规划纲要》提出，支持青海、甘肃、四川等风能、太阳能丰富地区构建风光水多能互补系统。","explanation":"纲要提出发挥黄河上游水电站和电网系统的调节能力，使风电、光伏发电和水电协调运行。C项用“青海、甘肃等”举例，保留了风能、太阳能丰富这一条件和建设风光水多能互补系统这一要求，符合纲要。","evidence":"支持青海、甘肃、四川等风能、太阳能丰富地区构建风光水多能互补系统。","doubt":"","references":[]},{"origin":"k-dc8c1a49f1f655cb","title":"黄河流域风光水多能互补系统","qs":["国考 2023 副省级 行测#7"],"definition":"《黄河流域生态保护和高质量发展规划纲要》提出，发挥黄河上游水电站和电网系统的调节能力，支持青海、甘肃、四川等风能、太阳能丰富地区构建风光水多能互补系统。","explanation":"纲要将能源布局与当地风能、太阳能资源条件相联系，并提出利用水电站和电网系统的调节能力。C项用“青海、甘肃等”列举支持地区，四川也在“等”所涵盖的范围内，故C项符合纲要。","evidence":"支持青海、甘肃、四川等风能、太阳能丰富地区构建风光水多能互补系统。","doubt":"","references":[]}]},"k-90b991e43833763f":{"review":{"definition":"有价证券载明支付义务的，证券债务人应当依证券记载向权利人履行该义务，无权就该项履行要求权利人另付对价。","explanation":"本题A项所称的对价，指债务人履行证券所载支付义务时向债权人索取的额外给付。证券认购、转让等交易中的价款属于相应交易关系。A项将支付义务说成可以附带对价请求，符合本题选错项的要求。","references":[],"evidence":"债务人不得请求权利人支付相应对价。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c33bce762157beda":{"review":{"definition":"《中华人民共和国乡村振兴促进法》第四十八条鼓励乡镇人民政府根据需要设立法律顾问和公职律师，鼓励有条件的地方在村民委员会建立公共法律服务工作室。","explanation":"D项把乡镇按需设立法律顾问和公职律师的鼓励性规定写成了“应设立”，又把村级工作室的条件写成了“根据需要”。法条对两项均使用“鼓励”，并分别规定“根据需要”和“有条件”。","references":[],"evidence":"鼓励乡镇人民政府根据需要设立法律顾问和公职律师，鼓励有条件的地方","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-256694e7e02f4b30":{"review":{"definition":"依照《中华人民共和国退役军人保障法》第二十九条，随迁子女需要转学、入学的，安置地人民政府教育行政部门应当及时办理。参战退役军人的随迁子女享有优先保障。","explanation":"法条先规定安置地教育行政部门应及时办理随迁子女的转学、入学，再将参战退役军人的随迁子女列入优先保障范围。A项同时符合“参战退役军人”和“随迁子女入学”两个条件。","references":[],"evidence":"对下列退役军人的随迁子女，优先保障：（一）参战退役军人。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-381e462bce51c189":{"review":{"definition":"《中华人民共和国退役军人保障法》将逐月领取退役金列为退役军官和退役军士的安置方式之一，符合相应条件的人员可以适用。","explanation":"该法第二十一条、第二十二条分别在退役军官、退役军士的安置方式中列有逐月领取退役金。第二十三条列出的退役义务兵安置方式为自主就业、安排工作和供养。B项把义务兵一并纳入，扩大了适用对象。","references":[],"evidence":"退役的军官与军士可适用逐月领取退役金的安置方式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-29ea1742bf587271":{"review":{"definition":"依照《中华人民共和国退役军人保障法》第三十五条，入伍前已被普通高校录取或者正在普通高校就读的人员，服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学。","explanation":"入伍前已录取的人员保留入学资格，入伍前已在读的人员保留学籍，分别对应退役后入学和复学。两种情形的期限均从退役后计算，C项把法定的两年写成了四年。","references":[],"evidence":"服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学","disposition":"独立词条","basis":"据原题和解析编释。","title":"退役军人入学与复学期限","related":[],"examFocus":{"国考 2023 地市级 行测#8":"区分入伍前已获录取和尚在高校就读两种情形，核对退役后入学或复学的期限及起算点。"}},"readings":[{"origin":"k-29ea1742bf587271","title":"退役军人入学与复学期限","qs":["国考 2023 行政执法 行测#8"],"definition":"依照《中华人民共和国退役军人保障法》第三十五条，入伍前已被普通高校录取或者正在普通高校就读的人员，服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学。","explanation":"入伍前已录取的人员保留入学资格，入伍前已在读的人员保留学籍，分别对应退役后入学和复学。两种情形的期限均从退役后计算，C项把法定的两年写成了四年。","evidence":"服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学","doubt":"","references":[]},{"origin":"k-32156d1b910f06ee","title":"退役军人入学与复学期限","qs":["国考 2023 地市级 行测#8"],"definition":"入伍前已被普通高等学校录取或正在普通高等学校就学的军人，服现役期间保留入学资格或学籍，退役后两年内可以入学或复学。","explanation":"第8题C项对应入伍前已被普通高校录取的情形。依题引《中华人民共和国退役军人保障法》第三十五条，期限从退役后起算，为两年，C项所写的四年有误。","evidence":"服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学","doubt":"","references":[]}]},"k-efc8706014526f3e":{"review":{"definition":"依本题所引《生物安全法》第四十六条，高等级病原微生物实验室从事高致病性或疑似高致病性病原微生物实验活动，应当经省级以上人民政府卫生健康或者农业农村主管部门批准，并将实验活动情况向批准部门报告。","explanation":"该条对高等级实验室的相关活动设有批准和报告要求。C项称相关实验活动「一律不得从事」，与条文规定冲突，因此是本题要选的错误项。","references":[],"evidence":"应当经省级以上人民政府卫生健康或者农业农村主管部门批准","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-30aabb0239c93385":{"review":{"definition":"依本题所引《生物安全法》第三十八条，高风险、中风险生物技术研究、开发活动应当由在我国境内依法成立的法人组织进行，并依法取得批准或者进行备案。","explanation":"A项中的境外组织以其境外主体身份开展题述活动，欠缺在我国境内依法成立的法人资格。判断主体资格的依据是法人组织的依法成立地，A项符合本题所引条文。","references":[],"evidence":"应当由在我国境内依法成立的法人组织进行，并依法取得批准或者进行备案。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c0382109e778ac55":{"review":{"definition":"依本题所引《生物安全法》第六十条，任何单位和个人未经批准，不得擅自引进、释放或者丢弃外来物种。","explanation":"批准要求同时约束单位和个人，并覆盖引进、释放、丢弃三类行为。B项完整列出了适用主体和行为，表述正确。","references":[],"evidence":"任何单位和个人未经批准，不得擅自引进、释放或者丢弃外来物种","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-529e14e283b2ed0a":{"review":{"definition":"依本题所引《生物安全法》第五十三条，国家对我国人类遗传资源和生物资源享有主权。","explanation":"条文的主权主体是国家，适用对象包括我国人类遗传资源和生物资源。D项的主体、资源范围和「享有主权」的表述均与条文一致。","references":[],"evidence":"国家对我国人类遗传资源和生物资源享有主权","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e0eb2345b9f587a6":{"review":{"definition":"依本题所引《噪声污染防治法》第七十四条，违反规定在噪声敏感建筑物集中区域改建、扩建工业企业，未采取有效措施防止工业噪声污染的，由生态环境主管部门责令改正并处以罚款。","explanation":"解析将甲企业在该区域改建厂房造成工业噪声污染的情形按本款处理。条文指定生态环境主管部门，A项却对应住房和城乡建设部门，因此是本题要选的错误项。","references":[],"evidence":"未采取有效措施防止工业噪声污染的，由生态环境主管部门责令改正","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-679be4e27ad19abf":{"review":{"definition":"依本题所引《噪声污染防治法》第七十五条，违反规定，无排污许可证排放工业噪声或者超过噪声排放标准排放工业噪声的，由生态环境主管部门责令改正或者限制生产、停产整治，并处罚款。","explanation":"无证排放与超标排放是并列的适用情形。B项中的乙企业无排污许可证即排放工业噪声，已符合无证排放这一情形，对应生态环境主管部门正确。","references":[],"evidence":"由生态环境主管部门责令改正或者限制生产、停产整治","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dd7c0722d7d05b64":{"review":{"definition":"依本题所引《噪声污染防治法》第八十一条，在商业经营活动中使用高音广播喇叭或者采用其他持续反复发出高噪声的方法进行广告宣传的，由地方人民政府指定的部门责令改正并处以罚款。","explanation":"C项中的丙商场在促销时持续使用高音喇叭，符合在商业经营活动中使用高音喇叭进行广告宣传的情形，对应地方人民政府指定的部门正确。","references":[],"evidence":"丙商场在促销时持续使用高音喇叭发出噪声","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ce3b653db4f0fd16":{"review":{"definition":"依本题所引《噪声污染防治法》第七十九条，违反规定驾驶擅自改装的机动车轰鸣、疾驶的，由县级以上地方人民政府公安机关交通管理部门依照有关道路交通安全的法律法规处罚。","explanation":"D项同时交代了机动车已拆除消声器和丁驾驶该车轰鸣行驶，符合本条所列的行驶情形，对应公安机关交通管理部门正确。","references":[],"evidence":"丁驾驶拆除消声器的机动车轰鸣行驶","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-05e868a7fd828ea3":{"review":{"definition":"《个人信息保护法》第二十六条规定，在公共场所安装图像采集、个人身份识别设备，应当为维护公共安全所必需，遵守国家有关规定，并设置显著的提示标识。依此收集的个人图像和身份识别信息原则上只能用于维护公共安全，取得个人单独同意的，可以用于其他目的。","explanation":"该条约束的是公共场所安装相关设备及其所采集信息的用途。B项把限制泛化为经人脸识别技术收集的信息一律只能用于公共安全，并遗漏个人单独同意的例外，因此是本题要求选出的不符合法律规定的说法。","references":[],"evidence":"只能用于维护公共安全的目的，不得用于其他目的；取得个人单独同意的除外。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7308099024ce7130":{"review":{"definition":"《个人信息保护法》第二十四条第二款规定，个人信息处理者通过自动化决策向个人进行信息推送或商业营销，应当同时提供不针对个人特征的选项，或者提供便捷的拒绝方式。","explanation":"两种方式满足其一即可。“同时”要求在进行自动化推送或营销时提供相应选项或拒绝方式。A项保留了商业营销的适用情形和两种方式之间的“或”，符合该款规定。","references":[],"evidence":"应当同时提供不针对其个人特征的选项，或者向个人提供便捷的拒绝方式。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c8d014f59596bf4b":{"review":{"definition":"《民法典》第一千零三十四条第三款规定，个人信息中的私密信息适用有关隐私权的规定。隐私权规则没有相应规定时，适用有关个人信息保护的规定。","explanation":"适用顺序取决于信息是否属于个人信息中的私密信息。C项明确将隐私权规则的适用对象限定为其中的私密信息，符合该条规定。","references":[],"evidence":"个人信息当中的私密信息适用有关隐私权的规定","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c57c0a4e3c50e969":{"review":{"definition":"原题引文：用户量巨大的个人信息处理者需要定期发布个人信息保护社会责任报告","explanation":"公开题文的D项只写了“用户量巨大”，省略了提供重要互联网平台服务和业务类型复杂两项条件。所给答案和中公公开解析均选B，B项遗漏了公共场所采集的个人图像、身份识别信息在取得个人单独同意时可以用于其他目的的例外。严格按条文判断，D项也把义务主体写宽了。","references":[{"source":"web-cec54a9feaef5338","location":"第二十六条、第五十八条及其第四项","quote":"提供重要互联网平台服务、用户数量巨大、业务类型复杂的个人信息处理者"},{"source":"web-5e757a7ee4410394","location":"例1的D项及参考答案","quote":"用户量巨大的个人信息处理者"}],"evidence":"用户量巨大的个人信息处理者需要定期发布个人信息保护社会责任报告","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-6626bd10f06175c1":{"review":{"definition":"在电信网络诈骗活动中，非法使用伪基站干扰无线电通讯秩序，符合《刑法》第二百八十八条规定的，以扰乱无线电通讯管理秩序罪追究刑事责任。同时构成诈骗罪的，依照处罚较重的规定定罪处罚。","explanation":"本题A项仅凭非法使用伪基站实施电信诈骗，就按非法侵入计算机信息系统罪追责。题内所引司法意见要求根据干扰无线电通讯秩序的行为及相应犯罪构成定罪，因此A项的归罪错误，是本题所选项。","references":[],"evidence":"同时构成诈骗罪的，依照处罚较重的规定定罪处罚。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d76047124b0a23d8":{"review":{"definition":"依照《刑法》第二百六十六条，诈骗公私财物数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。","explanation":"电信网络诈骗依诈骗罪处罚时，达到数额特别巨大或有其他特别严重情节，即进入包括无期徒刑的法定刑幅度。B项说的是最高可判无期徒刑，符合这一规定。","references":[],"evidence":"数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c9297c70b0e19984":{"review":{"definition":"依照《反电信网络诈骗法》第四十六条第二款，电信业务经营者违反该法规定并造成他人损害的，依照《民法典》等法律承担民事责任。","explanation":"本题C项中的服务缺陷，须具体体现为经营者违反法定反诈义务，例如未履行风险防控义务，并且该违法行为造成了受害人的损害。满足这些条件时，受害人可以通过诉讼主张相应民事责任。","references":[],"evidence":"违反本法规定，造成他人损害的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2332adf2c52104d5":{"review":{"definition":"依照《关于办理电信网络诈骗等刑事案件适用法律若干问题的意见》，负责招募他人实施电信网络诈骗犯罪活动的，以诈骗共同犯罪论处。","explanation":"D项所述招募明确指向实施电信网络诈骗犯罪活动。该司法意见将这种分工纳入诈骗共同犯罪，招募者即使未亲自实施对被害人的欺骗，也可依该规则追究刑事责任。","references":[],"evidence":"实施电信网络诈骗犯罪活动的，以共同犯罪论处","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5f6705c4e19cc1ad":{"review":{"definition":"交通事故的损失由非机动车驾驶人或行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。","explanation":"适用这一规则须同时满足故意碰撞和该碰撞造成事故损失两个条件。C项写的是行人故意碰撞机动车，却称机动车一方承担次要责任，与法定赔偿规则冲突，因此本题选C。","references":[],"evidence":"机动车一方不承担赔偿责任。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0f8be829eb51f204":{"review":{"definition":"机动车载运爆炸物品、易燃易爆化学物品以及剧毒、放射性等危险物品，应当经公安机关批准，按指定的时间、路线、速度行驶，并悬挂警示标志、采取必要的安全措施。","explanation":"A项所列的放射性危险物品属于这一规定的适用范围。选项表述的批准机关和三项行驶要求均与法条一致，因此A项正确。","references":[],"evidence":"应当经公安机关批准后，按指定的时间、路线、速度行驶","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2a5a953ab5e288ff":{"review":{"definition":"在允许拖拉机通行的道路上，拖拉机可以从事货运，禁止用于载人。","explanation":"B项先限定道路允许拖拉机通行，再分别说明货运和载人的规则。允许通行的路段仍适用载人禁令，因此B项正确。","references":[],"evidence":"在允许拖拉机通行的道路上，拖拉机可以从事货运，但是不得用于载人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8044e2d611689642":{"review":{"definition":"机动车在同一车道行驶时，前车为执行紧急任务的警车、消防车、救护车或工程救险车的，后车不得超车。","explanation":"判断这一禁超情形要看前车的种类和任务状态。D项列举的救护车和工程救险车都在法定范围内，并明确前车正在执行紧急任务，因此D项正确。","references":[],"evidence":"前车为执行紧急任务的救护车、工程救险车的，后车不得超车","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-64d2864f2646a380":{"review":{"definition":"企业设立兼具生产与教学功能的产教融合实习实训基地，所发生的费用可以参照职业学校享受相应的用地、公用事业费等优惠。","explanation":"法条以职业学校的相应优惠为参照。A项把参照享受公用事业费优惠改成享受高于职业学校的优惠，因此本题选A。","references":[],"evidence":"可以参照职业学校享受相应的用地、公用事业费等优惠。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a0d6c45c01630444":{"review":{"definition":"企业应当根据国务院规定的标准，按照职工工资总额的一定比例提取和使用职工教育经费。其中，用于企业一线职工职业教育的经费应当达到国家规定的比例。","explanation":"B项说的是经费提取和使用的口径，计算基数为职工工资总额。C项说的是经费用途的比例要求，针对用于一线职工职业教育的经费。两项分别对应法条中的两项义务，均正确。","references":[],"evidence":"其中用于企业一线职工职业教育的经费应当达到国家规定的比例。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4e2e8ea325be2b03":{"review":{"definition":"用人单位安排职工到职业学校或职业培训机构接受职业教育的，应当在职工接受职业教育期间依法支付工资，并保障相关待遇。","explanation":"D项中的企业是作出安排的用人单位，职业学校也是法条列明的机构，因此企业应依法支付职工在接受职业教育期间的工资。D项正确。","references":[],"evidence":"应当在其接受职业教育期间依法支付工资","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e6fbd439ca279965":{"review":{"definition":"按材料4转述的上级文件，高标准农田原则上全部用于粮食生产。","explanation":"福树村规划图把标号325的地块划为高标准农田，实地却是种植多年的苹果园。调研组还发现至少30处标号地块与实际不符。粮食生产用途要求说明了为什么规划前应核实地块现状，并请基层确认规划意见。","references":[],"evidence":"高标准农田原则上全部用于\n粮食生产","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-fbe56f334fecd67b":{"review":{"definition":"按C市农业农村局对凤溪县2022年项目的批复，项目须按获批的初步设计实施，确需变更时须先提交申请，经上级批复同意后才可调整。材料据此要求验收核对获批设计及变更，未经批准的调整不予通过。","explanation":"凤溪县已完成县级验收，但县农业农村局负责人认为完成数与规划数一致即可。只核对总量无法确认实际施工地块是否符合获批设计，也无法确认调整是否事先报批。这是汇报中认定验收把关不严、建议按批复逐项核验的依据。","references":[],"evidence":"必须\n要先上报变更申请，待上级批复同意以后，才可以调整","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1d9d287163ec3883":{"review":{"definition":"按材料4所述C市农业农村局的要求，改造后的高标准农田均须增施有机肥，由施工单位统一施入相应地块，严禁用发放肥料代替实际施用。","explanation":"洪林县多个村庄按人口把肥料直接发给村民。贵康村有农户仍存放往年发放的肥料，也有农户把肥料挪给果树使用。即使改为按亩发给农户，也未落实由施工单位统一施肥入田的要求。","references":[],"evidence":"有机肥应通过施工单位统一实施入田，严禁“以发代施”","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e47d1ff68d6e390b":{"review":{"definition":"有能力、有条件的民营企业要加强自主创新，在推进科技自立自强和科技成果转化中发挥更大作用。","explanation":"2023年3月的讲话明确限定了这一要求的适用对象，并同时指出科技自立自强和科技成果转化两个着力点。本题②同时保留了主体限定和两个着力点，符合讲话表述。","references":[],"evidence":"有能力、有条件的民营企业要加强自主创新，在推进科技自立自强和科技成果转化中发挥更大作用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d5b4cb678fd08ef4":{"review":{"title":"民间资本参与重大项目","type":"制度与规则","definition":"民间资本参与重大项目，是指民间资本参与国家重大工程、重点产业链供应链项目等建设。2023年3月，习近平总书记在看望参加全国政协会议的民建、工商联界委员时提出，鼓励和吸引更多民间资本参与这两类项目建设。","explanation":"这项部署旨在激发民间投资活力，服务构建新发展格局和推动高质量发展。讲话同时提出依法规范和引导各类资本健康发展，为各类所有制企业创造公平竞争、竞相发展的环境。","basis":"据关联原题和解析编释。","references":[],"domain":"经济","examFocus":{"国考 2024 副省级 行测#2":"对照民营经济高质量发展相关部署，辨别民间资本的参与范围、自主创新要求和资本监管要求。"}},"aspects":[{"title":"鼓励参与的项目范围","uses":[{"unit":"Q1","role":"直接考查","use":"本题 中，③把讲话列举的国家重大工程和重点产业链供应链项目改成互联网投资和境外投资，表述有误。①②④符合讲话内容，两卷均选A。","evidence":"吸引更多民间资本参与国家重大工程、重点产业链供应链项目建设","qids":["国考 2024 副省级 行测#2","国考 2024 地市级 行测#5"]}]}]},"k-1734f37f8feba81f":{"review":{"definition":"按照习近平2023年7月在四川考察时对主题教育成效提出的要求，检验调查研究成效，要看是否摸清社情民意、是否解决实际问题。","explanation":"摸清社情民意检验调研对群众实际情况的掌握，解决实际问题检验调研取得的实际成效。本题③同时列出了这两项标准，对应主题教育“五个检验”中的调查研究成效。","references":[],"evidence":"检验调查研究成效，要看是否摸清社情民意、是否解决实际问题","disposition":"独立词条","basis":"据原题和解析编释。","title":"调查研究成效的检验标准","related":[],"examFocus":{"国考 2024 副省级 行测#3":"核对调查研究的作用、工作要求和成效标准，并分清不同材料的用途。"}},"readings":[{"origin":"k-1734f37f8feba81f","title":"调查研究成效的检验标准","qs":["国考 2024 副省级 行测#3"],"definition":"按照习近平2023年7月在四川考察时对主题教育成效提出的要求，检验调查研究成效，要看是否摸清社情民意、是否解决实际问题。","explanation":"摸清社情民意检验调研对群众实际情况的掌握，解决实际问题检验调研取得的实际成效。本题③同时列出了这两项标准，对应主题教育“五个检验”中的调查研究成效。","evidence":"检验调查研究成效，要看是否摸清社情民意、是否解决实际问题","doubt":"","references":[]},{"origin":"k-ed4d18ae50880b18","title":"调查研究成效的检验标准","qs":["国考 2024 地市级 行测#3"],"definition":"习近平于2023年7月在四川考察时提出，检验主题教育中的调查研究成效，要看是否摸清社情民意、是否解决实际问题。","explanation":"摸清社情民意检验调研是否掌握了实际情况，解决实际问题检验调研是否取得实际成效。第③项完整列出了这两项标准，对应主题教育“五个检验”中的调查研究成效检验。","evidence":"要看是否摸清社情民意、是否解决实际问题","doubt":"","references":[]}]},"k-434cb41aa2a9e3dc":{"review":{"definition":"推进新型城镇化，要以县城为重要载体，构建以县城为枢纽、以小城镇为节点的县域经济体系。","explanation":"习近平2023年5月在陕西考察时提出，提升县城综合承载能力，发挥县城对县域经济发展的辐射带动作用，同时因地制宜发展小城镇。本题①把载体和枢纽都改成建制镇，并把县域经济体系改成县镇经济体系，因此错误。","references":[],"evidence":"构建以县城为枢纽、以小城镇为节点的县域经济体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6e26c39c3c40caf2":{"review":{"definition":"巩固脱贫成果要持续实施动态监测，不断增强脱贫地区内生发展动力，坚决守住不发生规模性返贫的底线。","explanation":"动态监测用于及时掌握返贫风险，增强内生发展动力着眼于脱贫地区的持续发展。本题②同时写出了监测措施、发展要求和规模性返贫底线，符合习近平2023年5月在陕西考察时的讲话。","references":[],"evidence":"持续实施动态监测，不断增强脱贫地区内生发展动力，坚决守住不发生规模性返贫底线","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-82631811a412ac48":{"review":{"definition":"要因地制宜发展乡村特色产业，推动农业生产与加工、流通和服务等环节融合，拓宽农民增收致富渠道。","explanation":"习近平2023年5月在陕西考察时，把因地制宜发展特色产业、推进农村一二三产业融合与拓宽农民增收致富渠道联系起来。本题③写出了选择特色产业的原则和推进产业融合的要求，符合讲话表述。","references":[],"evidence":"因地制宜大力发展特色产业，推进农村一、二、三产业融合发展","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-77e85e605a6dc522":{"review":{"definition":"要持续深化农村人居环境整治，加强传统村落和乡村特色风貌保护，加强农村精神文明建设，培育文明乡风。","explanation":"习近平2023年5月在陕西考察时并列提出了环境整治、传统村落和特色风貌保护、农村精神文明建设。本题④保留了这三项要求，符合讲话表述。","references":[],"evidence":"持续深化农村人居环境整治，加强传统村落和乡村特色风貌保护，加强农村精神文明建设","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3c6beb95f2bc7326":{"review":{"definition":"深入推进新时代党的建设新的伟大工程，以坚持和加强党中央集中统一领导为最高原则，以忠诚为党护党、全力兴党强党为根本使命，以解决大党独有难题、健全全面从严治党体系为重大任务。","explanation":"本题①②③分别对应习近平2023年6月关于党的建设和组织工作重要指示中的最高原则、根本使命和重大任务。按解析所引党的十九大报告，新时代党的建设主线是加强党的长期执政能力建设、先进性和纯洁性建设，统领是党的政治建设，根基是坚定理想信念宗旨。④把组织体系建设列为主线，⑤把制度建设列为统领，均有误，所以正确的有3项。","references":[],"evidence":"以解决大党独有难题、健全全面从严治党体系为重大任务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7094c74d45ee3380":{"review":{"title":"新时代党的建设总要求","type":"制度与规则","definition":"党的十九大报告提出新时代党的建设总要求，明确坚持和加强党的全面领导，坚持党要管党、全面从严治党。党的建设以加强党的长期执政能力建设、先进性和纯洁性建设为主线，以党的政治建设为统领，以坚定理想信念宗旨为根基。","explanation":"总要求以调动全党积极性、主动性、创造性为着力点，部署全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，并深入推进反腐败斗争。","basis":"据关联原题及所列出处编释。","references":[{"source":"party","location":"新时代党的建设总要求"}],"related":["k-066270830d9bbfc2","k-9a9a9867c701a684"],"examFocus":{"国考 2024 副省级 行测#5":"按党的建设总要求区分主线、统领和根基，再核对题中最高原则、根本使命与重大任务的表述。"}},"aspects":[{"title":"党的建设主线、统领与根基","uses":[{"unit":"Q1","role":"解题依据","use":"④把组织体系建设列为主线，⑤把制度建设列为统领，两项均错。⑤关于根基的后半句正确。①②③对应2023年6月关于党的建设和组织工作的重要指示，全题选B。","evidence":"④以加强党的组织体系建设为主线⑤以党的制度建设为统领，以坚定理想信念宗旨为根基","qids":["国考 2024 副省级 行测#5","国考 2024 行政执法 行测#4"]}]}]},"k-e044e94381764929":{"review":{"definition":"2023年《国务院关于推进普惠金融高质量发展的实施意见》将坚持党的领导列为基本原则，要求加强党的全面领导和党中央集中统一领导。","explanation":"这一原则要求进一步发挥各级党组织的作用，为普惠金融高质量发展提供政治保证和组织保障。题中①直接对应这项原则，应计入正确项。","references":[],"evidence":"坚持加强党的全面领导和党中央集中统一领导","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b6ea9c9767aeae93":{"review":{"definition":"2023年《国务院关于推进普惠金融高质量发展的实施意见》要求坚持人民至上，牢固树立以人民为中心的发展思想，使普惠金融发展为了人民、依靠人民，发展成果由人民共享。","explanation":"题中②直接对应坚持人民至上。文件把人民对美好生活的向往作为普惠金融发展的方向，并以增强人民群众的金融服务获得感体现这一要求。","references":[],"evidence":"牢固树立以人民为中心的发展思想","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d2caea7cfdcf46c6":{"review":{"definition":"2023年《国务院关于推进普惠金融高质量发展的实施意见》要求坚持政策引领，进一步明确各级政府责任，加强规划引导，加大政策、资源倾斜力度。","explanation":"题中③列出的政府责任、规划引导和政策资源倾斜，都是坚持政策引领的具体要求。该原则还要求各级政府依法行政，优化营商环境，维护市场秩序。","references":[],"evidence":"进一步明确各级政府责任，加强规划引导，加大政策、资源倾斜力度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ef2d969a3b367e63":{"review":{"definition":"2023年《国务院关于推进普惠金融高质量发展的实施意见》要求坚持改革创新，遵循金融规律，按照市场化、法治化原则探索成本可负担、商业可持续的发展模式。","explanation":"题中④所列的深化改革、破除机制障碍和强化科技赋能，是文件对坚持改革创新的具体要求，因此④应计入基本原则。","references":[],"evidence":"持续深化改革，破除机制障碍，强化科技赋能","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6501a718b0f05363":{"review":{"definition":"2023年《国务院关于推进普惠金融高质量发展的实施意见》要求坚持安全发展，以底线思维统筹发展和安全，加强和完善现代金融监管。","explanation":"题中⑤直接对应坚持安全发展。文件将防范化解中小金融机构风险和守住不发生系统性金融风险的底线列为这项原则下的具体要求。","references":[],"evidence":"坚持底线思维，统筹发展和安全，加强和完善现代金融监管","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6ba971f5f12946ef":{"review":{"definition":"习近平在2023年全国生态环境保护大会上提出强化美丽中国建设的法治保障，要求全面实行排污许可制，完善自然资源资产管理制度体系，健全国土空间用途管制制度。","explanation":"三项制度分别涉及排污许可、自然资源资产管理和国土空间用途管制，均属于大会讲话列举的法治保障措施，因此①正确。","references":[],"evidence":"全面实行排污许可制，完善自然资源资产管理制度体系，健全国土空间用途管制制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0195620e687ca6c8":{"review":{"definition":"习近平在2023年全国生态环境保护大会上提出完善绿色低碳发展经济政策，要求强化财政支持、税收政策支持、金融支持和价格政策支持。","explanation":"题中②完整列举了大会讲话点明的四类经济政策支持，其中价格政策与财政、税收政策和金融并列，因此②正确。","references":[],"evidence":"强化财政支持、税收政策支持、金融支持、价格政策支持","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-efea7a0cc3e5f7d1":{"review":{"definition":"习近平在2023年全国生态环境保护大会上提出加快构建环保信用监管体系，规范环境治理市场，促进环保产业和环境服务业健康发展。","explanation":"题中③把构建环保信用监管体系、规范市场和促进行业健康发展列在一起，与大会讲话中的市场治理要求一致，因此③正确。","references":[],"evidence":"加快构建环保信用监管体系，规范环境治理市场，促进环保产业和环境服务业健康发展","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9acb99e05d6bbafc":{"review":{"definition":"习近平在2023年全国生态环境保护大会上提出，将碳排放权、用能权、用水权、排污权等资源环境要素一体纳入要素市场化配置改革，推动有效市场和有为政府更好结合。","explanation":"大会讲话提出支持出让、转让、抵押、入股等市场交易，体现市场在资源配置中的决定性作用，政府则通过规范环境治理市场等方式发挥作用。题中④将配置中的决定性作用归于政府，因此错误。","references":[],"evidence":"放权、用能权、用水权、排污权等资源环境要素一体纳入要素市场化配置改革总盘子","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-122f143f77b87bbf":{"review":{"definition":"《乡村振兴责任制实施办法》规定，坚持党对农村工作的全面领导，省、市、县、乡、村五级书记抓乡村振兴。","explanation":"五级书记抓乡村振兴是在党委统一领导、政府负责、党委农村工作部门统筹协调的领导体制下落实的。A项同时写对了领导原则和五级责任层次，在本题中属于准确表述。","references":[],"evidence":"坚持党对农村工作的全面领导，省市县乡村五级书记抓乡村振兴","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d2ac6f9105c3c59b":{"review":{"definition":"《乡村振兴责任制实施办法》将县级党委和政府定位为乡村振兴的“一线指挥部”。县级党委和政府主要负责人是本地区乡村振兴第一责任人。","explanation":"县级党委和政府承担结合本地实际谋划制定乡村振兴规划和年度实施方案等职责。D项所列层级和主体均与这一定位相符，在选非题中应排除。","references":[],"evidence":"县级党委和政府是乡村振兴“一线指挥部”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d22ed0cc96c00f49":{"review":{"definition":"原题引文：县级人大常委可以对基层治理方面的事项制定地方性法规","explanation":"所给题文B项把这项权限赋予县级人大常委会，主体层级错误。A项关于国家监察委员会可以向全国人大常委会提出法律案的说法，依据是第二十九条第二款。题给解析援引的第十七条第二款讲的是向全国人大提出法律案，适用的受案主体不同。按所给选项顺序，本题选B。","references":[],"evidence":"县级人大常委可以对基层治理方面的事项制定地方性法规","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6fd304ee09ecabdb":{"review":{"definition":"原题引文：资料能够满足需要的，不得要求被审计单位重复提供","explanation":"公开题本的A项只说审计机关通过政务信息系统取得数据后又要求提供同一数据。给定答案选A，其判法以已有数据足以满足审计需要为前提。仅凭选项所述的取得渠道和数据相同，无法判断资料是否已满足需要。","references":[{"source":"web-6d2d598e82b50ad2","location":"2021年修正文本第三十五条第二款","quote":"资料能够满足需要的，不得要求被审计单位重复提供"},{"source":"web-da350f6fab2d21ee","location":"常识判断《审计法》题A项","quote":"取得数据后，要求被审计单位提供同一数据"}],"evidence":"资料能够满足需要的，不得要求被审计单位重复提供","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-895da8f86516614f":{"review":{"definition":"国家安全机关应当及时将传唤原因通知被传唤人家属。无法通知或者通知可能妨碍调查时，可暂缓通知，相关情形消失后应当立即通知。","explanation":"甲仍有间谍行为嫌疑，并不当然妨碍家属通知。A项以嫌疑是否消除决定能否通知，改变了法定的暂缓通知条件，因此是本题的错误选项。","references":[],"evidence":"除无法通知或者可能妨碍调查的情形以外","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6a0653e1776b87b7":{"review":{"definition":"原题引文：可以按照国家有关规定享受融资优惠等政策。","explanation":"所给题本的B项把法条中的“融资优惠”写成了“出资优惠”，因此B项表述错误。另有考生回忆版将经营待遇写作“融资优惠”，把错误项设为退出预备役时收回军衔。第十五条规定，退出预备役时保留军衔，并在军衔前冠以“退役”。","references":[{"source":"web-cd326c29b0a058e1","location":"第十五条、第四十六条第二款","quote":"可以按照国家有关规定享受融资优惠等政策"},{"source":"web-a10fd46acf9bbca3","location":"常识判断，预备役人员法题B项","quote":"其预备役衔予以收回"},{"source":"web-5791bc9625a5e039","location":"预备役人员法题解析","quote":"故本题选C"}],"evidence":"可以按照国家有关规定享受融资优惠等政策。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-e1a1e3156633cd5b":{"review":{"definition":"科举是中国古代由朝廷设科考试、选拔人才的制度，考试表现是取士的重要依据。","explanation":"引言将考核治理国家所需的专门知识与选官格局的变化相联系，D项同时概括了科举创建和它对选官制度的影响。引言中“隋文帝废除了察举制”是金滢坤文章的论述。有研究根据隋文帝的选官诏书，认为当时仍可能沿用北周的察举方式。另有研究把隋炀帝设进士科视为科举创立的标志。解答标题题可依据引言的论述主线，科举形成的具体时点在研究中存在不同判断。","references":[{"source":"web-673437fb341b3e7c","location":"正文首段","quote":"废除了士族赖以维系的选举工具——察举制"},{"source":"web-1771516301fb53b8","location":"论开皇诏令及隋文帝选官方式的段落","quote":"极有可能仍然是北周政权所实施的察举制度"},{"source":"web-90e033a20ebc9504","location":"摘要，讨论科举创制的标志","quote":"隋炀帝创立进士科"}],"evidence":"“科举制度”即通过考试选拔官吏的制度","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-db9666c6e95971fd":{"review":{"definition":"在本题所设的网络就医流程中，患者先线上挂号，再接受远程问诊。需要用药时，医生根据问诊情况开具处方。","explanation":"A项的三个环节依次发生，符合题干的先后顺序关系。B项的铁路铺设和桥梁建造没有固定先后，D项中的救治伤员通常先于保险赔付，顺序与选项排列相反。","references":[],"evidence":"网络就医一般先线上挂号，再远程问诊，最后开具处方","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6fd3088bb13c87c9":{"review":{"definition":"党的二十大报告提出，发展壮大医疗卫生队伍，把工作重点放在农村和社区。","explanation":"这一部署是Y市实施意见的指导思想。材料中的乡镇中心卫生院通过配备医护团队、接受上级医院专家指导，让周边患者能在家门口做透析，体现了工作重点向基层落实。","references":[],"evidence":"要发展壮大医疗卫生队伍，把工作重点放在农村和社区","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-33ff5ec883ef1fe6":{"review":{"definition":"江平县在招聘季组织人事、卫生健康、财政等部门按规定对急缺人才开展现场考试，通过后及时录取，并按招聘对象、工作地点和帮扶期限给予相应待遇。","explanation":"基层招聘的本科及以上学历毕业生可获一次性购房补贴，驻偏远乡镇的全科医师每人每年增发2万元补助，主城区单位执业医师在偏远乡镇帮扶1年以上可优先评定职称。本题将现场考录和分类待遇写入“优化人才管聘工作”，分别回应基层补员和岗位吸引力问题。","references":[],"evidence":"按照规定对急缺人才现场考试，通过后及时录取","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-caa4e906a15f8f36":{"review":{"definition":"卫生事业编制周转池是统筹调剂卫生事业编制的机制。江平县将公立医院的富余编制纳入周转池，专项用于基层招聘紧缺型专业人才。","explanation":"材料记载，江平县已统筹调剂50个编制。这项做法回应了乡镇卫生院临床、麻醉、影像等专业人员短缺的问题，在实施意见中属于“优化人才管聘工作”。50个是江平县已有的调剂数量。","references":[],"evidence":"“卫生事业编制周转池”，专门用于基层招聘紧缺型专业人才","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8234b6d70b73fb13":{"review":{"definition":"在材料所述农村卫生人才安排中，“县管乡用”指由县级管理、乡镇使用，“乡管村用”指由乡镇管理、村级使用。","explanation":"两项安排分别明确了县与乡、乡与村之间的人才管理和使用层级。江平县根据上级文件推动实施，本题可将其写入“优化人才管聘工作”，与现场考录和编制调剂共同构成人才配置措施。","references":[],"evidence":"“县管乡用”和“乡管村用”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a96089f8349a97d9":{"review":{"definition":"江平县依托基层实训示范基地，每两年对基层护理人员、全科医生、乡村医生开展一轮全覆盖培训，每年组织不少于30名执业医师到大医院脱产培训，并保障进修期间的工资奖金、费用报销和补贴。","explanation":"全覆盖培训面向三类基层人员，脱产进修面向选派的执业医师。材料中，李医生进修期间工资奖金照发，交通费和伙食费得到报销，并领取了补贴。两项安排与待遇保障均可写入本题的“完善人才培养机制”。","references":[],"evidence":"每年组织不少于30名执业医师到各地大医院进行脱产培训","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-0be09be59a13ade0":{"review":{"definition":"2022年中央农村工作会议提出，推进农业科技创新要以农业关键核心技术攻关为引领，以产业急需为导向。","explanation":"会议列举了底盘技术、核心种源、关键农机装备等重点攻关领域。第①项准确表述了攻关引领要求，但把创新导向写成了“促进大规模经营”，因此整项错误。","references":[],"evidence":"关键核心技术攻关为引领，以产业急需为导向","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b076ac2019ffe1bd":{"review":{"title":"增加农民收入","type":"制度与规则","definition":"习近平在2022年中央农村工作会议上指出，建设农业强国、全面推进乡村振兴，要坚持把增加农民收入作为“三农”工作的中心任务。","explanation":"这一部署要求拓宽农民增收致富渠道，并将人力投入、物力配置、财力保障向乡村振兴转移。","basis":"据关联原题及所列出处编释。","references":[{"source":"agri","location":"增加农民收入"}],"examFocus":{"国考 2024 地市级 行测#2":"对照建设农业强国的部署，区分“三农”工作中心任务、农业科技创新方向与农业强国建设的首要任务。"}},"aspects":[{"title":"“三农”工作的中心任务","uses":[{"unit":"Q1","role":"直接考查","use":"判断建设农业强国的相关表述时，第②项准确表述了“三农”工作的中心任务，和第③项共同构成正确选项C。","evidence":"要坚持把增加农民收入作为“三农”工作的中心任务","qids":["国考 2024 地市级 行测#2","国考 2024 行政执法 行测#2"]}]}]},"k-82a4f4b98ff57ecb":{"review":{"title":"农业现代化与农村现代化","type":"制度与规则","definition":"习近平在2022年中央农村工作会议上提出，建设农业强国要一体推进农业现代化和农村现代化，实现乡村全面提升。","explanation":"农业现代化着眼于农业生产和产业发展，农村现代化涵盖乡村生活条件、公共服务和治理。会议将农村现代化视为建设农业强国的内在要求和必要条件，并把建设宜居宜业和美乡村纳入这一部署。","basis":"据关联原题及所列出处编释。","references":[{"source":"agri","location":"一体推进农业现代化和农村现代化"}],"related":["k-6129abc029f16867","k-fbc703040a1d4d3a","k-10875ff0d8a54918"],"examFocus":{"国考 2024 地市级 行测#2":"核对农业强国建设中农业现代化与农村现代化的关系，并区分农业科技、农民增收和粮食安全要求。"}},"aspects":[{"title":"一体推进两类现代化","uses":[{"unit":"Q1","role":"直接考查","use":"第③项将一体推进农业现代化和农村现代化与乡村的全面提升相联系，符合2022年中央农村工作会议上的相关部署，和第②项共同构成正确选项C。","evidence":"要一体推进农业现代化和农村现代化，实现乡村由表及里、形神兼备的全面提升","qids":["国考 2024 地市级 行测#2","国考 2024 行政执法 行测#2"]}]}]},"k-8ca0fff4761e01cb":{"review":{"definition":"我国宪法确认中国共产党的领导地位。习近平在纪念现行宪法公布施行40周年的文章中指出，这是我国宪法最显著的特征。","explanation":"该文把中国共产党领导地位的宪法确认与宪法的全面贯彻实施相联系，指出党的领导是宪法全面贯彻实施的根本保证。第①项准确表述了宪法确认的内容及其地位。","references":[],"evidence":"我国宪法确认了中国共产党的领导地位，这是我国宪法最显著的特征","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e69dd9ac0a8d9123":{"review":{"title":"宪法的根本法地位","type":"制度与规则","definition":"中华人民共和国宪法是国家的根本法，具有最高法律效力。习近平在2022年纪念现行宪法公布施行40周年的署名文章中指出，宪法是治国安邦的总章程，是中国共产党治国理政的根本法律依据。","explanation":"法律、行政法规和地方性法规都必须遵守宪法。在立法中，宪法的根本法地位要求立法机关在每一个立法环节把好宪法关，使各项立法符合宪法精神、保证宪法实施。","basis":"据关联原题及所列出处编释。","references":[{"source":"legal","location":"现行宪法的地位与实施"}],"related":["k-c2383a4ccfc99a5b","k-469f06bedb2b5a5f"],"examFocus":{"国考 2024 地市级 行测#4":"区分宪法的显著特征、治国理政地位、立法作用和实施监督要求，再按原表述逐项核对。"}},"aspects":[{"title":"宪法在治国理政和立法中的地位","uses":[{"unit":"Q1","role":"直接考查","use":"第②项关于宪法是治国理政根本法律依据的表述和第③项关于立法各环节把好宪法关的要求均符合署名文章，连同第①项共3项正确，故选C。","evidence":"宪法是治国安邦的总章程，是中国共产党治国理政的根本法律依据","qids":["国考 2024 地市级 行测#4","国考 2024 行政执法 行测#1"]}]}]},"k-71a7d3baf998d419":{"review":{"definition":"立法应当充分发挥宪法的核心地位功能，在每个立法环节把好宪法关，使各项立法符合宪法精神、体现宪法权威、保证宪法实施。","explanation":"习近平在纪念现行宪法公布施行40周年的文章中，把这一要求放在完善立法体制机制、统筹立改废释纂的背景下提出。第③项准确写出了宪法要求贯穿立法全过程。","references":[],"evidence":"要全面发挥宪法在立法中的核心地位功能，每一个立法环节都把好宪法关","disposition":"独立词条","basis":"据原题和解析编释。","title":"宪法在立法中的核心地位","related":[],"examFocus":{"国考 2024 地市级 行测#4":"逐项辨析我国宪法的显著特征、在治国理政和立法中的地位，以及宪法实施与监督的关系。"}},"readings":[{"origin":"k-71a7d3baf998d419","title":"宪法在立法中的核心地位","qs":["国考 2024 地市级 行测#4"],"definition":"立法应当充分发挥宪法的核心地位功能，在每个立法环节把好宪法关，使各项立法符合宪法精神、体现宪法权威、保证宪法实施。","explanation":"习近平在纪念现行宪法公布施行40周年的文章中，把这一要求放在完善立法体制机制、统筹立改废释纂的背景下提出。第③项准确写出了宪法要求贯穿立法全过程。","evidence":"要全面发挥宪法在立法中的核心地位功能，每一个立法环节都把好宪法关","doubt":"","references":[]},{"origin":"k-cbe610311870a0b8","title":"宪法在立法中的核心地位","qs":["国考 2024 行政执法 行测#1"],"definition":"立法应当发挥宪法的核心作用，在每一个立法环节把好宪法关。","explanation":"这一要求贯穿立法全过程，目的是使每一项立法都符合宪法精神、体现宪法权威、保证宪法实施。第③项中的“每一个立法环节”准确体现了这一要求的适用范围，因此表述正确。","evidence":"要全面发挥宪法在立法中的核心地位功能，每一个立法环节都把好宪法关","doubt":"","references":[]}]},"k-8f37b058f136b422":{"review":{"definition":"习近平在纪念现行宪法公布施行40周年的文章中指出，必须坚持宪法实施与监督制度化法规化，宪法的生命和权威都在于实施。","explanation":"原文的制度要求同时涵盖宪法实施与监督。第④项只写了监督制度化法规化，又把宪法生命和权威所系的“实施”换成“监督”，因此错误。","references":[],"evidence":"必须坚持宪法实施与监督制度化法规化。宪法的生命在于实施","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3186d723de9c8221":{"review":{"definition":"《中华人民共和国黑土地保护法》第五条规定，黑土层深厚、土壤性状良好的黑土地，应当按照规定的标准划入永久基本农田，重点用于粮食生产，并实行严格保护。","explanation":"A项对应第五条的划入对象和重点用途。法条还要求按规定标准划入，并保持数量和质量长期稳定。本题要求选择不符合法律规定的一项，A项符合规定。","references":[],"evidence":"黑土层深厚、土壤性状良好的黑土地应当按照规定的标准划入永久基本农田，重点用于粮食生产","disposition":"独立词条","basis":"据原题和解析编释。","title":"黑土地划入永久基本农田","related":[],"examFocus":{"国考 2024 地市级 行测#8":"核对《黑土地保护法》中划入永久基本农田的条件和用途，并辨析修复、规划与建设占用各自适用的规定。"}},"readings":[{"origin":"k-3186d723de9c8221","title":"黑土地划入永久基本农田","qs":["国考 2024 地市级 行测#8"],"definition":"《中华人民共和国黑土地保护法》第五条规定，黑土层深厚、土壤性状良好的黑土地，应当按照规定的标准划入永久基本农田，重点用于粮食生产，并实行严格保护。","explanation":"A项对应第五条的划入对象和重点用途。法条还要求按规定标准划入，并保持数量和质量长期稳定。本题要求选择不符合法律规定的一项，A项符合规定。","evidence":"黑土层深厚、土壤性状良好的黑土地应当按照规定的标准划入永久基本农田，重点用于粮食生产","doubt":"","references":[]},{"origin":"k-c27e96f57a368a41","title":"黑土地划入永久基本农田","qs":["国考 2024 行政执法 行测#10"],"definition":"《中华人民共和国黑土地保护法》规定，黑土层深厚、土壤性状良好的黑土地，应当按照规定的标准划入永久基本农田，重点用于粮食生产。","explanation":"划定时要看黑土层厚度和土壤性状，并执行规定的标准。划入后实行严格保护，确保数量和质量长期稳定。A项所列的土地条件、划入类别和重点用途均符合规定。","evidence":"黑土层深厚、土壤性状良好的黑土地划入永久基本农田，重点用于粮食生产","doubt":"","references":[]}]},"k-b3ab2a226c13dbb0":{"review":{"definition":"国务院农业农村主管部门会同自然资源、水行政等有关部门确定并适时调整黑土地保护范围。历史上属黑土地的，原则上应纳入保护范围进行修复，确无法修复的除外。","explanation":"全国人大常委会公报第四条第二款写作“进行修复”，农业农村部转载网页写作“进行修恢复”。B项的“不列入……进行修复”可按该款的修复例外理解，条文免除了对确无法修复地块原则上应纳入修复范围的要求。选非题选D，因为第二十一条允许确需占用黑土地的建设项目依法严格审批，并补充数量和质量相当的耕地。","references":[{"source":"web-d06742b1a06210f4","location":"第四条第二款、第二十一条第一款","quote":"原则上都应列入黑土地保护范围进行修复"},{"source":"web-cf4e0dba8e83ecfb","location":"第四条第二款末句","quote":"进行修恢复"}],"evidence":"无法修复的黑土地不列入黑土地保护范围进行修复","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-b0719895aa22b0ea":{"review":{"definition":"《中华人民共和国黑土地保护法》第十条第一款规定，县级以上人民政府应当将黑土地保护工作纳入国民经济和社会发展规划。","explanation":"C项同时写对了义务主体、纳入事项和规划名称。承担义务的是县级以上人民政府，纳入的是黑土地保护工作，规划是国民经济和社会发展规划，因此C项符合规定。","references":[],"evidence":"县级以上人民政府应当将黑土地保护工作纳入国民经济和社会发展规划","disposition":"独立词条","basis":"据原题和解析编释。","title":"黑土地保护纳入国民经济和社会发展规划","related":[],"examFocus":{"国考 2024 地市级 行测#8":"核对《黑土地保护法》中的规划条款，留意由哪一级政府负责、纳入什么工作以及纳入哪类规划。"}},"readings":[{"origin":"k-b0719895aa22b0ea","title":"黑土地保护纳入国民经济和社会发展规划","qs":["国考 2024 地市级 行测#8"],"definition":"《中华人民共和国黑土地保护法》第十条第一款规定，县级以上人民政府应当将黑土地保护工作纳入国民经济和社会发展规划。","explanation":"C项同时写对了义务主体、纳入事项和规划名称。承担义务的是县级以上人民政府，纳入的是黑土地保护工作，规划是国民经济和社会发展规划，因此C项符合规定。","evidence":"县级以上人民政府应当将黑土地保护工作纳入国民经济和社会发展规划","doubt":"","references":[]},{"origin":"k-fd105a825337b490","title":"黑土地保护纳入国民经济和社会发展规划","qs":["国考 2024 行政执法 行测#10"],"definition":"《中华人民共和国黑土地保护法》规定，县级以上人民政府应当将黑土地保护工作纳入国民经济和社会发展规划。","explanation":"“县级以上”包含县级人民政府，“应当”表明纳入规划是法定义务。C项写明的主体、规划名称和纳入事项均与规定一致。","evidence":"县级以上人民政府应当将黑土地保护工作纳入国民经济和社会发展规划","doubt":"","references":[]}]},"k-83b7f72a89d80b84":{"review":{"definition":"《中华人民共和国黑土地保护法》第二十一条第一款规定，建设项目不得占用黑土地。确需占用的，应当依法严格审批，并补充数量和质量相当的耕地。","explanation":"法条以“确需占用”为例外条件，并同时要求严格审批和补充数量、质量相当的耕地。D项把例外限定为选址无法避开黑土地的国防建设项目，并声称其他建设项目一律不得占用，缩小了该款规定的例外范围，因此本题选D。","references":[],"evidence":"应当依法严格审批，并补充数量和质量相当的耕地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a3db0569f0c9b8b1":{"review":{"definition":"设区的市人民代表大会及其常务委员会可以根据本市具体情况和实际需要，就基层治理事项制定地方性法规。法规不得同宪法、法律、行政法规及本省、自治区的地方性法规相抵触，并须报省、自治区人大常委会批准后施行。","explanation":"《立法法》将基层治理列入设区的市可以制定地方性法规的事项，法律另有规定的从其规定。B项把这项制定权限归给县级人大常委会，因此是本题应选的错误项。","references":[],"evidence":"城乡建设与管理、生态文明建设、历史文化保护、基层治理等方面的事项","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c77c03550b5349a7":{"review":{"definition":"省、自治区、直辖市和设区的市、自治州的人大常委会根据实际需要设立基层立法联系点，听取基层群众和有关方面对地方性法规、自治条例和单行条例草案的意见。","explanation":"C项所列的设区的市人大常委会属于《立法法》规定的设立主体，“根据实际需要”也是条文规定的设立条件，因此C项表述正确。","references":[],"evidence":"设区的市人大常委会可以根据实际需要设立基层立法联系点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-777de4b01f5168a9":{"review":{"definition":"提出法律案时，应当同时提交法律草案文本及其说明。说明应包括制定或者修改法律的必要性、可行性和主要内容，涉及合宪性问题的相关意见，以及起草过程中对重大分歧意见的协调处理情况。","explanation":"D项列出的是草案说明的一项法定内容，时间范围是起草过程，说明的内容是重大分歧意见如何协调处理，因此D项表述正确。","references":[],"evidence":"起草过程中对重大分歧意见的协调处理情况","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-96692c77e259dab1":{"review":{"definition":"国家安全机关应当及时将传唤原因通知被传唤人家属。无法通知或者通知可能妨碍调查的，可以暂缓，相关情形消失后应当立即通知。","explanation":"甲仍有间谍行为嫌疑这一事实本身不构成暂缓通知的条件。A项把通知时间一律推迟到嫌疑消除后，违反了及时通知及例外情形消失后立即通知的要求，因此是本题应选的错误项。","references":[],"evidence":"除无法通知或者可能妨碍调查的情形以外","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4a42c4881f96466a":{"review":{"definition":"对涉嫌间谍行为的人员，省级以上国家安全机关可以通知移民管理机构不准其出境。","explanation":"B项中的乙涉嫌间谍行为，发出通知的是省国家安全机关，接到通知并执行的是移民管理机构，符合《反间谍法》规定的适用对象和机关权限。","references":[],"evidence":"移民管理机构接到省国家安全机关通知后，不准其出境","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-34c85e96e1627859":{"review":{"definition":"在境外受胁迫或诱骗参加间谍组织、敌对组织并从事危害中华人民共和国国家安全活动的人，及时向我国驻外机构如实说明情况，或者入境后直接或通过所在单位及时向国家安全机关如实说明情况，并有悔改表现的，可以不予追究。","explanation":"C项中的丙在境外受胁迫参加间谍组织，及时向大使馆如实说明情况并有悔改表现。大使馆属于条文所称的驻外机构，选项中的“可以不予追究”保留了条文规定的裁量空间。","references":[],"evidence":"及时向大使馆如实说明情况，并有悔改表现，可以不予追究","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d4f892497b29b8ca":{"review":{"definition":"个人和组织因支持、协助反间谍工作导致财产损失的，根据国家有关规定给予补偿。","explanation":"D项明确丁的财产损失由协助反间谍工作导致，符合补偿所需的因果条件。丁可以依国家有关规定获得补偿。","references":[],"evidence":"因协助反间谍工作导致财产损失，根据国家有关规定，可获得补偿","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1d05d1cd542c534e":{"review":{"definition":"《乡村振兴责任制实施办法》规定，中央和国家机关有关部门要以处理好农民和土地的关系为主线深化农村改革。","explanation":"这一职责包括巩固和完善农村基本经营制度、发展新型农村集体经济和农业适度规模经营。B项把该项职责的主线写成“健全城乡融合发展体制”，与《实施办法》第五条的规定不符，因此是本题应选的表述不准确项。","references":[],"evidence":"民和土地的关系为主线深化农村改革，巩固和完善农村基本经营制度","disposition":"独立词条","basis":"据原题和解析编释。","title":"深化农村改革的主线","related":[],"examFocus":{"国考 2024 副省级 行测#8":"对照《乡村振兴责任制实施办法》，核对深化农村改革的责任主体和主线。"}},"readings":[{"origin":"k-1d05d1cd542c534e","title":"深化农村改革的主线","qs":["国考 2024 地市级 行测#11"],"definition":"《乡村振兴责任制实施办法》规定，中央和国家机关有关部门要以处理好农民和土地的关系为主线深化农村改革。","explanation":"这一职责包括巩固和完善农村基本经营制度、发展新型农村集体经济和农业适度规模经营。B项把该项职责的主线写成“健全城乡融合发展体制”，与《实施办法》第五条的规定不符，因此是本题应选的表述不准确项。","evidence":"民和土地的关系为主线深化农村改革，巩固和完善农村基本经营制度","doubt":"","references":[]},{"origin":"k-37c9075ae657f74d","title":"深化农村改革的主线","qs":["国考 2024 副省级 行测#8"],"definition":"《乡村振兴责任制实施办法》规定，中央和国家机关有关部门要以处理好农民和土地的关系为主线深化农村改革。","explanation":"该职责包括巩固和完善农村基本经营制度、发展农业适度规模经营等。B项把该条规定的主线写成“健全城乡融合发展体制”，因此是本题要求选出的不准确表述。","evidence":"以健全城乡融合发展体制为主线深化农村改革","doubt":"","references":[]},{"origin":"k-6b06443487e3d702","title":"深化农村改革的主线","qs":["国考 2024 行政执法 行测#9"],"definition":"《乡村振兴责任制实施办法》规定，中央和国家机关有关部门应当以处理好农民和土地的关系为主线深化农村改革。","explanation":"巩固和完善农村基本经营制度、发展农业适度规模经营等是这项责任所列的具体工作。B项把规定的改革主线换成了“健全城乡融合发展体制”，因此是本题所选的不准确表述。","evidence":"关系为主线深化农村改革，巩固和完善农村基本经营制度","doubt":"","references":[]}]},"k-1e34a76fe1be2d3b":{"review":{"definition":"《乡村振兴责任制实施办法》要求坚持党对农村工作的全面领导，健全党委统一领导、政府负责、党委农村工作部门统筹协调的领导体制，由省、市、县、乡、村五级书记抓乡村振兴。","explanation":"A项同时写出了党的全面领导和书记抓乡村振兴的具体层级，从省级到村级共五级，符合《实施办法》第三条的规定。","references":[],"evidence":"坚持党对农村工作的全面领导，省市县乡村五级书记抓乡村振兴","disposition":"独立词条","basis":"据原题和解析编释。","title":"五级书记抓乡村振兴","related":[],"examFocus":{"国考 2024 地市级 行测#11":"依据《乡村振兴责任制实施办法》，核对各层级书记在乡村振兴中的责任范围。"}},"readings":[{"origin":"k-1e34a76fe1be2d3b","title":"五级书记抓乡村振兴","qs":["国考 2024 地市级 行测#11"],"definition":"《乡村振兴责任制实施办法》要求坚持党对农村工作的全面领导，健全党委统一领导、政府负责、党委农村工作部门统筹协调的领导体制，由省、市、县、乡、村五级书记抓乡村振兴。","explanation":"A项同时写出了党的全面领导和书记抓乡村振兴的具体层级，从省级到村级共五级，符合《实施办法》第三条的规定。","evidence":"坚持党对农村工作的全面领导，省市县乡村五级书记抓乡村振兴","doubt":"","references":[]},{"origin":"k-f500c93c1c824916","title":"五级书记抓乡村振兴","qs":["国考 2024 行政执法 行测#9"],"definition":"《乡村振兴责任制实施办法》规定，坚持党对农村工作的全面领导，由省、市、县、乡、村五级书记抓乡村振兴。","explanation":"农村工作实行党委统一领导、政府负责、党委农村工作部门统筹协调的领导体制。A项准确列出了党的全面领导原则和五级书记的责任层级，在本题的选非条件下应排除。","evidence":"坚持党对农村工作的全面领导，省市县乡村五级书记抓乡村振兴","doubt":"","references":[]}]},"k-fb585b673e5cb691":{"review":{"title":"乡村振兴的县级责任","type":"制度与规则","definition":"2022年《乡村振兴责任制实施办法》第十一条规定，县级党委和政府是乡村振兴的“一线指挥部”，县级党委和政府主要负责人是本地区乡村振兴第一责任人。","explanation":"县级党委和政府应结合本地区实际谋划制定乡村振兴规划和年度实施方案。主要负责人应当把主要精力放在乡村振兴工作上。","basis":"据关联原题及所列出处编释。","references":[{"source":"ruralDuty","location":"县级党委和政府责任"}],"related":["k-254d4e19b07dfa68","k-7f4a4aba9435a8e5"],"domain":"公共管理","examFocus":{"国考 2024 地市级 行测#11":"按《乡村振兴责任制实施办法》区分县级党委和政府的定位、地方保供责任和中央部门的农村改革要求。"}},"aspects":[{"title":"县级党委和政府的职责定位","uses":[{"unit":"Q1","role":"直接考查","use":"题目要求选出不准确的说法。D项关于县级党委和政府的定位符合第十一条。应选B，中央和国家机关有关部门深化农村改革的主线是处理好农民和土地的关系。","evidence":"县级党委和政府是乡村振兴“一线指挥部”","qids":["国考 2024 地市级 行测#11","国考 2024 行政执法 行测#9"]}]}]},"k-5eae7bf860317823":{"review":{"title":"疾病诊断和治疗方法的专利排除","type":"制度与规则","definition":"《中华人民共和国专利法》（2020年修正）第二十五条第一款第三项规定，疾病的诊断和治疗方法不授予专利权。","explanation":"以治疗疾病为目的的手术方法属于这一排除范围。用于诊断或治疗的药品、医疗器械可作为产品申请专利，能否获授权取决于其技术方案是否符合法定条件。","basis":"据关联原题及所列出处编释。","references":[{"source":"patent","location":"第二十五条第一款第三项"}],"examFocus":{"国考 2024 地市级 行测#12":"按《专利法》的客体排除规则，判断技术方案属于方法还是器具，再核对该方案的用途。"}},"aspects":[{"title":"治疗性手术方法的专利排除","uses":[{"unit":"Q1","role":"直接考查","use":"题目问哪一项不能被授予专利权。B项所述手术用于治疗主动脉夹层，属于疾病治疗方法，即使是新型手术也适用法定排除。","evidence":"一种治疗主动脉夹层的新型手术方法","qids":["国考 2024 地市级 行测#12","国考 2024 行政执法 行测#15"]}]}]},"k-7865181983f54911":{"review":{"definition":"动物和植物品种不授予专利权。获得这些品种的生产方法符合专利法规定的，可以授予专利权。","explanation":"本题问哪一项不能被授予专利权。D项的保护对象是获得水稻品种的育种技术，属于可依法审查授权的生产方法。B项的手术方法用于治疗主动脉夹层，属于明确排除的疾病治疗方法，因此选B。","references":[],"evidence":"对前款第（四）项所列产品的生产方法，可以依照本法规定授予专利权。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-76ff272e4c9eebae":{"review":{"definition":"依本题所引《中华人民共和国消费税暂行条例》，纳税人出口应税消费品，免征消费税，国务院另有规定的除外。","explanation":"A项用“一般免征”概括出口应税消费品的免税规则，同时为国务院另有规定的情形保留例外，因此是正确选项。","references":[],"evidence":"对纳税人出口应税消费品，一般免征消费税","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2396deee96a157ea":{"review":{"definition":"纳税人应按《中华人民共和国印花税法》所附税目税率表确定适用税率，再以计税依据乘以适用税率计算应纳税额。","explanation":"2022年7月1日起施行的《印花税法》在考试时适用，旧条例的按件定额规定随条例废止。附表的法定税率有五个不同数值，即万分之零点五、二点五、三、五和千分之一。自2023年8月28日起，证券交易印花税减半征收，按成交金额折算为万分之五。租赁等合同仍有适用千分之一的情形，因此单计证券交易减半对税率表的影响，仍可数出五个不同数值。B项所说的统一税率错误。","references":[{"source":"web-c168415f6ae6951c","location":"第四条、第八条、第二十条及所附《印花税税目税率表》","quote":"依照本法所附《印花税税目税率表》执行"},{"source":"web-26fd775d626ac093","location":"2023年第39号公告正文","quote":"自2023年8月28日起，证券交易印花税实施减半征收"}],"evidence":"所有印花税税目均按照统一的税率征收","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-119d5b65f76ea264":{"review":{"definition":"企业计算应纳税所得额时，向投资者支付的股息、红利等权益性投资收益款项不得扣除。","explanation":"D项讨论的是企业向投资者支付的款项。对支付方而言，分配这类收益不能减少其应纳税所得额，因此D项所称“不包括”与题引企业所得税法的扣除规则不符。","references":[],"evidence":"向投资者支付的股息、红利等权益性投资收益款项","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-67435687a2ff3a21":{"review":{"definition":"按题干所指的2023年《公开地图内容表示规范》，表现地为我国境内的遥感影像，地面分辨率不得优于0.5米。","explanation":"用米表示的地面分辨率数值越小，影像能呈现的地面细节越细。D项将限制写成0.1米，例如0.2米影像符合D项所述的限制，却优于规范规定的0.5米。本题要求选出与规范不相符的一项，因此选D。","references":[],"evidence":"地面分辨率不得优于0.5\n米","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-26b78af2e3f98fda":{"review":{"definition":"按题干所指的2023年《公开地图内容表示规范》，香港特别行政区、澳门特别行政区在公开地图上应当按省级行政单位表示。","explanation":"A项同时列出香港和澳门两个特别行政区，并将两者的地图表示层级都写为省级行政单位，符合规范中的特别行政区地图表示规定。","references":[],"evidence":"香港特别行政区、澳门特别行政区在地图上应按省级行政单位表示","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e756f23f4a64f019":{"review":{"definition":"按题干所指的2023年《公开地图内容表示规范》，表现地为我国境内的公开地图不得表示未对社会公众开放的卫星导航定位基准站。对社会公众开放的基准站适用该项限制的例外。","explanation":"规范第二十项将卫星导航定位基准站列入限制表示的内容，并设有对社会公众开放的例外。B项同时保留了地图表现地为我国境内和基准站未对社会公众开放两个条件，符合规范。","references":[],"evidence":"表现地为我国境内的地图不得表示未对社会公众开放的卫星导航定位基准站","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5375770ada0b14bb":{"review":{"definition":"按题干所指的2023年《公开地图内容表示规范》，台湾省地图的图幅范围应当绘出钓鱼岛和赤尾屿。以“台湾岛”命名的地图适用例外。","explanation":"C项说的是台湾省地图，符合应当绘出两岛的一般规定。按解析所引条文，两岛可以绘入台湾省全图，也可以用附图反映两岛与台湾本岛的地理关系。","references":[],"evidence":"钓鱼岛和赤尾屿（以‘台湾岛’命名的地图除外）","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-895302ad49793c24":{"review":{"definition":"按本题所涉时点适用的司法解释，用人单位招用已依法享受养老保险待遇或者领取退休金的人员，发生用工争议并起诉的，人民法院应按劳务关系处理。符合地方政策条件的超龄从业人员，可由从业单位为其单项参加工伤保险。","explanation":"材料中的小丁父亲已领取退休金。电力公司认可他的技术和经验，却顾虑工作中发生意外后的赔偿责任，双方最终通过雇主险和意外伤害险安排保障。这是本题归纳“保障不到位”并提出完善保障建议的依据。广东已有针对特定人员的单项参保制度，覆盖符合条件的已享受基本养老保险待遇的超龄从业人员。材料未交代就业地，个案能否走这一渠道取决于当地规则和参保条件。","references":[{"source":"web-7fbc050aabe9a5ce","location":"第三十二条第一款，武汉市人力资源和社会保障局转载","quote":"人民法院应当按劳务关系处理"},{"source":"web-59add0947c3d5731","location":"第二条，适用单位、单项参保和从业人员范围","quote":"包括已享受和未享受机关事业单位或者城镇职工基本养老保险待遇人员"}],"evidence":"已经领取了退休金，无法与用人单位确立劳动关系，自然也不能缴纳工伤保险","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-0f30a7c3385a3f70":{"review":{"definition":"我国宪法确认中国共产党的领导地位，这是我国宪法最显著的特征。","explanation":"习近平在纪念现行宪法公布施行40周年的文章中指出，坚持中国共产党领导是我国宪法得到全面贯彻实施的根本保证。第①项准确表述了宪法确认的领导地位及其在我国宪法中的地位，应计入正确项。","references":[],"evidence":"我国宪法确认了中国共产党的领导地位，这是我国宪法最显著的特征","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2db437084e1442d3":{"review":{"definition":"必须坚持宪法实施与监督制度化法规化。宪法的生命和权威都在于实施。","explanation":"制度化法规化的要求同时涵盖宪法实施与监督。第④项只提监督制度化法规化，又把宪法生命和权威所系的“实施”改成了“监督”，因此表述错误。","references":[],"evidence":"必须坚持宪法实施与监督制度化法规化。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-10743d1ed12b9c47":{"review":{"definition":"按照2022年中央农村工作会议提出的要求，农业科技创新要以农业关键核心技术攻关为引领，以产业急需为导向。","explanation":"产业急需用于确定优先攻关的领域，讲话列举了底盘技术、核心种源和关键农机装备。第①项保留了关键核心技术攻关这一引领要求，却把导向换成了“促进大规模经营”，因此表述错误。","references":[],"evidence":"以产业急需为导向，聚焦底盘技术、核心种源、关键农机装备等领域","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0c2145ad55b6f200":{"review":{"definition":"保障国家粮食安全是全面推进乡村振兴、加快建设农业强国的首要任务。为此要不断提高粮食综合生产能力，完善粮食产能提高机制。","explanation":"《全面推进乡村振兴 加快建设农业强国》把首要任务表述为保障国家粮食安全，并提出持续提升粮食产能。第④项把其中的任务目标改成“扩大耕地面积”，因此表述错误。","references":[],"evidence":"任务就是保障国家粮食安全，不断提高粮食综合生产能力，全面完善粮食产能提高机制。","disposition":"独立词条","basis":"据原题和解析编释。","title":"建设农业强国的首要任务","related":[],"examFocus":{"国考 2024 地市级 行测#2":"核对建设农业强国的相关表述，区分政策文件所说的首要任务和落实任务的具体举措。"}},"readings":[{"origin":"k-0c2145ad55b6f200","title":"建设农业强国的首要任务","qs":["国考 2024 行政执法 行测#2"],"definition":"保障国家粮食安全是全面推进乡村振兴、加快建设农业强国的首要任务。为此要不断提高粮食综合生产能力，完善粮食产能提高机制。","explanation":"《全面推进乡村振兴 加快建设农业强国》把首要任务表述为保障国家粮食安全，并提出持续提升粮食产能。第④项把其中的任务目标改成“扩大耕地面积”，因此表述错误。","evidence":"任务就是保障国家粮食安全，不断提高粮食综合生产能力，全面完善粮食产能提高机制。","doubt":"","references":[]},{"origin":"k-ae0e7e67777e819f","title":"建设农业强国的首要任务","qs":["国考 2024 地市级 行测#2"],"definition":"《全面推进乡村振兴 加快建设农业强国》提出，全面推进乡村振兴、加快建设农业强国的首要任务是保障国家粮食安全。","explanation":"文章要求提高粮食综合生产能力、完善粮食产能提高机制，以夯实粮食安全根基。第④项把首要任务写成了“扩大耕地面积”，与文章确定的任务不符。","evidence":"保障国家粮食安全，不断提高粮食综合生产能力","doubt":"","references":[]}]},"k-5f3fb666ab2438d0":{"review":{"definition":"2023年6月，习近平在对党的建设和组织工作作出的重要指示中明确，深入推进新时代党的建设新的伟大工程，要以坚持和加强党中央集中统一领导为最高原则。","explanation":"第4题①准确对应「最高原则」及其内容。②的忠诚为党护党、全力兴党强党对应「根本使命」，③的解决大党独有难题、健全全面从严治党体系对应「重大任务」。","references":[],"evidence":"以坚持和加强党中央集中统一领导为最高原则","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d0fc0a88cf1ff5df":{"review":{"definition":"2023年6月，习近平在对党的建设和组织工作作出的重要指示中明确，深入推进新时代党的建设新的伟大工程，要以忠诚为党护党、全力兴党强党为根本使命。","explanation":"第4题②完整保留了「忠诚为党护党」和「全力兴党强党」两部分，并准确归入「根本使命」。题中⑤所说的「根基」则对应党的建设总要求中的坚定理想信念宗旨。","references":[],"evidence":"以忠诚为党护党、全力兴党强党为根本使命","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-47c7a086ba3b038f":{"review":{"definition":"2023年6月，习近平在对党的建设和组织工作作出的重要指示中明确，深入推进新时代党的建设新的伟大工程，要以解决大党独有难题、健全全面从严治党体系为重大任务。","explanation":"第4题③准确列出了重大任务的两项内容。同一指示还提出要严密上下贯通、执行有力的组织体系，而④把加强党的组织体系建设放在了「主线」位置。按解析所引党的十九大报告，主线是加强党的长期执政能力建设、先进性和纯洁性建设。","references":[],"evidence":"以解决大党独有难题、健全全面从严治党体系为重大任务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1c612e0e0e3f331c":{"review":{"definition":"党的二十大报告在推进高水平对外开放的部署中提出，推动货物贸易优化升级，创新服务贸易发展机制，发展数字贸易，加快建设贸易强国。","explanation":"第7题①分别写出货物贸易的「优化升级」、服务贸易的「发展机制创新」和数字贸易的「发展」，与报告表述相符。④所列自由贸易试验区提升战略和高标准自由贸易区网络也符合该报告，因此选①④。","references":[],"evidence":"推动货物贸易优化升级，创新服务贸易发展机制，发展数字贸易，加快建设贸易强国","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a703efe116689ce3":{"review":{"definition":"党的二十大报告提出，推进高水平对外开放要合理缩减外资准入负面清单，依法保护外商投资权益，营造市场化、法治化、国际化一流营商环境。","explanation":"外资准入负面清单列明外商投资准入的特别管理措施，「缩减」指缩小清单所列措施的范围。第7题②保留了营商环境的正确表述，却把清单的调整方向写成「扩大」，因此整项错误。","references":[],"evidence":"合理缩减外资准入负面清单","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5c0a8245363305d4":{"review":{"definition":"党的二十大报告提出，在推进高水平对外开放中优化区域开放布局，巩固东部沿海地区开放先导地位，提高中西部和东北地区开放水平。","explanation":"第7题③把「开放先导地位」赋给中西部和东北地区，又把「提高开放水平」配给东部地区，调换了报告中两项部署所对应的地区，因此应排除。","references":[],"evidence":"巩固东部沿海地区开放先导地位，提高中西部和东北地区开放水平","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-51fc278700651cf6":{"review":{"definition":"《乡村振兴责任制实施办法》规定，地方党委和政府应当把确保粮食和重要农产品供给作为乡村振兴的首要任务。","explanation":"这项任务要求全面落实耕地保护和粮食安全党政同责，并完成粮食和重要农产品生产目标任务。C项所说的地方政府是条文列明的责任主体之一，所述首要任务也与条文一致。","references":[],"evidence":"把确保粮食和重要农产品供给作为首要任务","disposition":"独立词条","basis":"据原题和解析编释。","title":"地方乡村振兴的首要任务","related":[],"examFocus":{"国考 2024 副省级 行测#8":"依据《乡村振兴责任制实施办法》，核对各级主体的职责分工、地方政府的任务排序和深化农村改革的主线。"}},"readings":[{"origin":"k-51fc278700651cf6","title":"地方乡村振兴的首要任务","qs":["国考 2024 行政执法 行测#9"],"definition":"《乡村振兴责任制实施办法》规定，地方党委和政府应当把确保粮食和重要农产品供给作为乡村振兴的首要任务。","explanation":"这项任务要求全面落实耕地保护和粮食安全党政同责，并完成粮食和重要农产品生产目标任务。C项所说的地方政府是条文列明的责任主体之一，所述首要任务也与条文一致。","evidence":"把确保粮食和重要农产品供给作为首要任务","doubt":"","references":[]},{"origin":"k-c41295c6bc396d11","title":"地方乡村振兴的首要任务","qs":["国考 2024 副省级 行测#8"],"definition":"《乡村振兴责任制实施办法》规定，地方党委和政府要把确保粮食和重要农产品供给作为乡村振兴的首要任务。","explanation":"为保障供给，地方党委和政府要落实耕地保护和粮食安全党政同责，完成粮食和重要农产品生产目标任务。C项只陈述地方政府承担这项任务，与规定相符。完整的责任主体还包括地方党委。","evidence":"地方政府乡村振兴要把确保粮食和重要农产品供给作为首要任务","doubt":"","references":[]},{"origin":"k-d92098387b9ac1c0","title":"地方乡村振兴的首要任务","qs":["国考 2024 地市级 行测#11"],"definition":"《乡村振兴责任制实施办法》规定，地方党委和政府应当把确保粮食和重要农产品供给作为乡村振兴的首要任务，并落实耕地保护和粮食安全党政同责。","explanation":"C项列举地方政府承担的首要任务，任务内容与《实施办法》第八条一致。该条规定的完整责任主体是地方党委和政府，具体要求还包括落实耕地和永久基本农田保护、高标准农田建设任务。","evidence":"把确保粮食和重要农产品供给作为首要任务","doubt":"","references":[]}]},"k-b35eccc07c6f0011":{"review":{"definition":"《中华人民共和国黑土地保护法》规定，历史上属黑土地的，原则上应当列入黑土地保护范围进行修复，确无法修复的除外。","explanation":"B项对应的是历史上属黑土地的情形，其中“无法修复”按条文理解为“确无法修复”。这项例外适用于是否列入黑土地保护范围进行修复，因此B项在该语境下符合规定。","references":[],"evidence":"历史上属黑土地的，除确无法修复的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a13f7bcce0ab0589":{"review":{"definition":"《中华人民共和国黑土地保护法》规定，建设项目不得占用黑土地。确需占用的，应当依法严格审批，并补充数量和质量相当的耕地。","explanation":"确需占用时，依法严格审批和补充耕地两项要求均须满足，补充的耕地在数量和质量上都须相当。D项把这一例外限于选址无法避开黑土地的国防建设项目，缩小了条文的适用范围，因此是本题所选的不合规表述。","references":[],"evidence":"应当依法严格审批，并补充数量和质量相当的耕地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3db5f1f0ed6cbff7":{"review":{"definition":"原题引文：甲综合行政执法局责令孙某限期拆除其违法建筑","explanation":"本题标准答案为A。第十八条提供相对集中处罚权的制度依据。按《城乡规划法》第六十四条，未按规划许可要求建设且无法采取改正措施消除规划影响的，适用限期拆除规定。2012年国务院法制办复函将该条的限期拆除理解为纠正违法行为的责令。甲局能否作出责令，还取决于当地具体职权分工和违建情形。A项写的是要求孙某限期自行拆除，实际强制拆除另有法定条件。","references":[{"source":"web-f8e2c75d89338c50","location":"第十八条第一、二款","quote":"由一个行政机关行使有关行政机关的行政处罚权"},{"source":"web-804c3171bbc45bdd","location":"第六十四条、第六十八条","quote":"无法采取改正措施消除影响的，限期拆除"},{"source":"web-4e7c333d8a599225","location":"鄂尔多斯市住房和城乡建设局汇总第十四项","quote":"不应当理解为行政处罚行为"}],"evidence":"甲综合行政执法局责令孙某限期拆除其违法建筑","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-e5c60b39955e2776":{"review":{"definition":"建设项目未依法办理所需环评审批即开工的，“未批先建”行政处罚追责期限从建设行为终了之日起算。行政处罚一般适用二年发现期限，涉及公民生命健康安全或金融安全且有危害后果的延长至五年，法律另有规定的从其规定。","explanation":"环保部2018年意见援引的是当时《行政处罚法》第二十九条。2021年修订后，第三十六条沿用了连续或继续状态从行为终了起算的规则，新增了特定情形的五年期限。B项中变电站建成六年后才被发现，题面也未给出适用特别期限的依据，故不能就该次“未批先建”罚款。若存在另外的未验收即投产等行为，应按其各自的违法事实判断。","references":[{"source":"web-fcc231cd27cb48ba","location":"第二部分第（一）、（二）项，追溯期限与起算时间","quote":"应当自建设行为终了之日起计算"},{"source":"web-f8e2c75d89338c50","location":"第三十六条第一、二款","quote":"从行为终了之日起计算"}],"evidence":"某变电站项目建成六年后，乙生态环境局发现其系“未批先建”，处以罚款","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-856a5094ee72c642":{"review":{"definition":"行政机关对当事人的同一个违法行为，不得给予两次以上罚款。同一个违法行为违反多个法律规范且应当给予罚款时，按照罚款数额高的规定处罚。","explanation":"C项明示某公司因某一次违规代开发票被罚款三次，三次罚款针对同一个违法行为，违反《行政处罚法》第二十九条。","references":[],"evidence":"对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-af57231f3ca90c19":{"review":{"definition":"限制人身自由的行政处罚权只能由公安机关和法律规定的其他机关行使，行政拘留属于此类处罚。","explanation":"D项由市场监督管理局对王某作出行政拘留七日并罚款一千元的处罚。依《行政处罚法》第十八条第三款，本题中的市场监督管理局无权作出该行政拘留，因而D项不符合规定。","references":[],"evidence":"限制人身自由的行政处罚权只能由公安机关和法律规定的其他机关行使","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7d452819897a6ed2":{"review":{"definition":"犯罪行为或犯罪结果有一项发生在中华人民共和国领域内，即视为在我国领域内犯罪。除法律有特别规定外，在我国领域内犯罪适用我国刑法。","explanation":"A项的行为发生在我国境内机场，受害人出境后死亡，境内行为已满足属地管辖的条件。C项的电话教唆行为发生在我国境内，境外实施的杀人行为也不影响我国对境内教唆行为适用刑法。题目问我国刑法不具有管辖权的情形，A、C均应排除。","references":[],"evidence":"犯罪的行为或者结果有一项发生在中华人民共和国领域内的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2ec71e3d81274aa8":{"review":{"definition":"在中华人民共和国船舶或者航空器内犯罪，适用我国刑法。这一规定也适用于处在我国领域外的我国船舶或航空器。","explanation":"B项的国际列车虽从我国出发，但抢劫发生时列车已进入甲国。刑法第六条第二款列举的是船舶和航空器，国际列车不适用该款。题中行为人、被害人均为外国公民，按本题给出的事实，B符合题干所问的无管辖权情形。","references":[],"evidence":"凡在中华人民共和国船舶或者航空器内犯罪的，也适用本法","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-324d99b93689120e":{"review":{"definition":"中华人民共和国公民在我国领域外犯我国刑法规定之罪，适用我国刑法。按我国刑法规定的最高刑为三年以下有期徒刑的，可以不予追究。","explanation":"D项实施绑架的是我国公民，即使行为发生在甲国、被害人是甲国公民，我国仍可依据行为人的中国国籍行使管辖权。题目问我国刑法不具有管辖权的情形，D应排除。","references":[],"evidence":"中华人民共和国公民在中华人民共和国领域外犯本法规定之罪的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-be3dd7a10e3b2753":{"review":{"definition":"《民法典》第一百九十六条规定，停止侵害、排除妨碍、消除危险的请求，不动产物权人或登记的动产物权人返还财产的请求，以及支付抚养费、赡养费或者扶养费的请求，均不适用诉讼时效。其他依法不适用诉讼时效的请求权也属例外。","explanation":"①拆除挡路围墙属于排除妨碍，②修复可能导致儿童坠落的下水道属于消除危险。解析将③表述为停止侵害，按题意，房屋权利人要求占用人搬离也可直接归入不动产物权人请求返还财产。④要求支付专利使用费是金钱给付请求，题中没有适用例外的条件，因此选①②③，即C。","references":[],"evidence":"不动产物权和登记的动产物权的权利人请求返还财产","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-288ffb6436d9291e":{"review":{"definition":"出卖人欠缺处分权这一事实本身不导致买卖合同无效。合同效力与标的物所有权能否转移，应分别判断。","explanation":"老张是房屋所有权人，小张出售房屋属于无权处分。按题解采用的小张与小王订立合同的前提，不能仅凭小张无权处分、伪造手续就采纳A项的无效结论。B、C两项都认可合同有效，二者的区别在于小王能否因善意取得而获得房屋所有权。","references":[],"evidence":"无权处分并不影响房屋买卖合同的效力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-741680e376fea3e3":{"review":{"definition":"原题引文：小王支付对价并办理了产权变更手续","explanation":"本题给出小王不知情、支付对价和办妥产权变更登记。标准答案C隐含交易价格合理这一前提，无权处分本身不影响买卖合同效力。在满足善意取得条件时，小王取得房屋所有权，老张可向无处分权的小张请求赔偿。合理价格须结合转让时当地市场价格、付款方式及交易习惯等认定，题文仅写“支付对价”，价格条件仍缺乏事实支持。","references":[{"source":"web-f4e85f00d16e5fcc","location":"第三百一十一条第一、二款","quote":"以合理的价格转让"},{"source":"web-b738d581015976df","location":"第十八条","quote":"参考转让时交易地市场价格以及交易习惯"}],"evidence":"小王支付对价并办理了产权变更手续","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-512804f0d78cc90c":{"review":{"definition":"受让人依法善意取得所有权后，原所有权人有权向无处分权人请求损害赔偿。","explanation":"以题解认定小王已善意取得房屋为前提，老张是原所有权人，小张是无处分权人，故这一规则下的赔偿请求应向小张提出。D项把请求对象写成了受让人小王。","references":[],"evidence":"原所有权人有权向无处分权人请求损害赔偿","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f089608e006a6a61":{"review":{"definition":"动物和植物品种本身不授予专利权。其生产方法符合专利法规定的，可以授予专利权。","explanation":"D项描述的是针对水稻的辐射诱变育种技术，判断时应区分育种方法与所得水稻品种。题目问哪一项不能被授予专利权，B项治疗主动脉夹层的手术方法属于疾病治疗方法，落入法定排除范围。D项的具体技术能否获权仍取决于其是否满足相应条件。","references":[],"evidence":"对前款第（四）项所列产品的生产方法，可以依照本法规定授予专利权","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-268865f2f65777a4":{"review":{"definition":"2023年中央金融工作会议要求优化资金供给结构，把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业。","explanation":"A项保留了科技创新、绿色发展，却把先进制造改成传统制造，把中小微企业改成国有企业。题目要求选出表述不准确的一项，因此选A。D项所述支持国有大型金融机构做优做强，属于金融机构定位要求。","references":[],"evidence":"把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b7bf49ef35298ccf":{"review":{"definition":"2023年中央金融工作会议要求为经济社会发展提供高质量金融服务，着力营造良好的货币金融环境，切实加强对重大战略、重点领域和薄弱环节的优质金融服务。","explanation":"B项同时写出了货币金融环境和优质金融服务的三个着力点，与会议要求相符。本题是选非题，因此排除B项。","references":[],"evidence":"切实加强对重大战略、重点领域和薄弱环节的优质金融服务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-72228e652f9d5cd4":{"review":{"title":"国有大型金融机构的职能定位","type":"制度与规则","definition":"2023年10月中央金融工作会议提出，支持国有大型金融机构做优做强，当好服务实体经济的主力军和维护金融稳定的压舱石。","explanation":"这一定位适用于国有大型金融机构。同一会议对中小金融机构强调严格准入和监管要求、立足当地开展特色化经营，对政策性金融机构则提出强化职能定位。","basis":"据关联原题及所列出处编释。","references":[{"source":"finance","location":"完善机构定位"}],"related":["k-6ac8c8091aa99122"],"domain":"经济","examFocus":{"国考 2025 副省级 行测#5":"对照中央金融工作会议，核对金融机构的定位与职责，并区分机构职责和金融资源投向。"}},"aspects":[{"title":"服务实体经济与维护金融稳定","uses":[{"unit":"Q1","role":"解题依据","use":"D项将服务实体经济和维护金融稳定两项职能归于国有大型金融机构，符合会议部署。题干要求选出不准确的表述，应选错列金融资源重点投向的A项。","evidence":"完善机构定位，支持国有大型金融机构做优做强，当好服务实体经济的主力军和维护金融稳定的压舱石","qids":["国考 2025 副省级 行测#5","国考 2025 行政执法 行测#5"]}]}]},"k-10875ff0d8a54918":{"review":{"title":"农业现代化的科技和改革双轮驱动","type":"制度与规则","definition":"科技和改革双轮驱动是建设农业强国、推进农业农村现代化的一项部署，要求加强农业科技创新，同时通过改革完善农业农村发展所需的体制机制。","explanation":"2022年12月关于加快建设农业强国、推进农业农村现代化的讲话提出发挥科技和改革的双重作用。2023年12月中央农村工作会议进一步提出加大核心技术攻关力度、改革完善“三农”工作体制机制。","basis":"据关联原题及所列出处编释。","references":[{"source":"agri","location":"科技和改革双轮驱动"}],"related":["k-6129abc029f16867","k-fbc703040a1d4d3a","k-82a4f4b98ff57ecb"],"examFocus":{"国考 2025 副省级 行测#6":"逐项辨析粮食安全部署中党政责任、食物供给、耕地建设、对外开放以及科技和改革各自涉及的政策要求。"}},"readings":[{"origin":"k-10875ff0d8a54918","title":"农业现代化的科技和改革双轮驱动","qs":["国考 2025 副省级 行测#6","国考 2025 行政执法 行测#6"],"definition":"科技和改革双轮驱动是建设农业强国、推进农业农村现代化的一项部署，要求加强农业科技创新，同时通过改革完善农业农村发展所需的体制机制。","explanation":"2022年12月关于加快建设农业强国、推进农业农村现代化的讲话提出发挥科技和改革的双重作用。2023年12月中央农村工作会议进一步提出加大核心技术攻关力度、改革完善“三农”工作体制机制。","evidence":"","doubt":"","references":[{"source":"agri","location":"科技和改革双轮驱动"}]},{"origin":"k-865d37e48a1ad809","title":"农业现代化的科技和改革双轮驱动","qs":["国考 2025 地市级 行测#6"],"definition":"2023年中央农村工作会议提出，推进农业现代化要强化科技和改革双轮驱动，加大核心技术攻关力度，改革完善“三农”工作体制机制。","explanation":"核心技术攻关对应科技驱动，完善“三农”工作体制机制对应改革驱动。题中⑤同时保留了科技和改革两方面，并点明核心技术攻关，符合会议部署。","evidence":"强化科技和改革双轮驱动，加大核心技术攻关力度","doubt":"","references":[]}],"aspects":[{"title":"粮食安全领域的核心技术攻关","uses":[{"unit":"Q1","role":"直接考查","use":"第⑤项所列核心技术攻关是科技驱动在保障粮食安全中的具体举措，符合2023年12月中央农村工作会议部署，应计入4项正确举措，选C。","evidence":"强化科技和改革双轮驱动，加大核心技术攻关力度","qids":["国考 2025 副省级 行测#6","国考 2025 行政执法 行测#6"]}]}]},"k-a3a5a64141d4d254":{"review":{"definition":"保障粮食安全要立足国内生产，把粮食供给主动权掌握在自己手中，同时可以利用国内国际两个市场、两种资源。","explanation":"④把扩大粮食领域高水平对外开放具体化为逐步提高国外种业资源和海外粮食产品在国内的市场占有率。解析认可利用国际资源，判错点在于把提高国外资源和产品的国内市场份额设为保障粮食安全的目标。排除④后，正确的有4项，对应C。","references":[],"evidence":"中国人的饭碗任何时候都要牢牢端在自己手中","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1ee6f0c02f41907a":{"review":{"title":"就业工作方针","type":"制度与规则","definition":"习近平《促进高质量充分就业》（2024年《求是》第21期）提出全面贯彻劳动者自主就业、市场调节就业、政府促进就业和鼓励创业的方针。","explanation":"劳动者自主选择职业，市场调节劳动力供求，政府通过政策和公共就业服务促进就业。鼓励创业有助于创造新的就业岗位，文章将坚持创业带动就业列为新时代就业工作的经验。","basis":"据关联原题及所列出处编释。","references":[{"source":"jobs","location":"新时代就业工作的经验"}],"related":["k-c9e54faa00997e23","k-5dfa658086207b9d","k-95491b6a9bb3eff5"],"domain":"公共管理","examFocus":{"国考 2025 副省级 行测#7":"核对就业工作方针中劳动者、市场和政府各自的作用，并辨清创业与就业的带动方向。"}},"aspects":[{"title":"市场、政府和创业在就业中的作用","uses":[{"unit":"Q1","role":"直接考查","use":"第①项把“市场调节就业、政府促进就业”改为“政府主导就业、市场促进就业”，还漏列鼓励创业。第③项把“创业带动就业”写成“就业带动创业”。两项均错，正确组合为②④，选C。","evidence":"劳动者自主就业、市场调节就业、政府促进就业和\n鼓励创业的方针","qids":["国考 2025 副省级 行测#7","国考 2025 地市级 行测#7"]}]}]},"k-18c82678850d3bcc":{"review":{"definition":"习近平在《促进高质量充分就业》中提出，加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点，并及时总结经验、形成制度。","explanation":"试点扩围是加强这两类劳动者权益保障的一项具体部署。题中④同时保留了保障对象和扩大试点的要求，与强调扩大就业容量和提升就业质量相结合的②共同构成正确组合，选C。","references":[],"evidence":"加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点","disposition":"独立词条","basis":"据原题和解析编释。","title":"灵活就业和新就业形态劳动者权益保障","related":[],"examFocus":{"政治理论必刷100题#22":"按中央经济工作会议的任务分工，辨析就业权益、教育、卫生生育、绿色产业和外贸举措各自归属哪项重点任务。","国考 2025 副省级 行测#7":"核对就业方针中各主体的分工、创业与就业的带动方向，以及权益保障对象与试点安排的对应关系。"}},"readings":[{"origin":"k-18c82678850d3bcc","title":"灵活就业和新就业形态劳动者权益保障","qs":["国考 2025 副省级 行测#7"],"definition":"习近平在《促进高质量充分就业》中提出，加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点，并及时总结经验、形成制度。","explanation":"试点扩围是加强这两类劳动者权益保障的一项具体部署。题中④同时保留了保障对象和扩大试点的要求，与强调扩大就业容量和提升就业质量相结合的②共同构成正确组合，选C。","evidence":"加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点","doubt":"","references":[]},{"origin":"k-4e755d00a8aba2bf","title":"灵活就业和新就业形态劳动者权益保障","qs":["国考 2025 行政执法 行测#7"],"definition":"《促进高质量充分就业》提出，要加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点，并及时总结经验、形成制度。","explanation":"第7题④同时写对了权益保障面向的两类劳动者和扩大职业伤害保障试点的要求，因此与②组成正确选项C。文章在此处部署的是试点扩围和后续制度建设。","evidence":"加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点","doubt":"","references":[]},{"origin":"k-d1592e3853590e62","title":"灵活就业和新就业形态劳动者权益保障","qs":["国考 2025 地市级 行测#7"],"definition":"2024年《促进高质量充分就业》提出，加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点，及时总结经验、形成制度。","explanation":"④保留了灵活就业和新就业形态两类保障对象，也准确写出文章当时提出的“扩大职业伤害保障试点”，因此正确。","evidence":"加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点","doubt":"","references":[]},{"origin":"k-d6e6bf47f93ebf1c","title":"灵活就业和新就业形态劳动者权益保障","qs":["政治理论必刷100题#22"],"definition":"2024年中央经济工作会议在部署2025年重点任务时，要求加强灵活就业和新就业形态劳动者权益保障，并将其列入保障和改善民生任务。","explanation":"会议在部署支持重点领域、重点行业等促进就业的措施后，紧接着提出这项劳动者权益保障要求。第22题①对应的是民生任务中的就业权益保障举措，应计入正确项。","evidence":"加强灵活就业和新就业形态劳动者权益保障。","doubt":"","references":[]}]},"k-1632ca8680fadb9b":{"review":{"title":"党的自我革命“九个以”","type":"制度与规则","definition":"2024年，习近平在二十届中央纪委三次全会上提出新征程上深入推进党的自我革命的九项实践要求。坚持党中央集中统一领导是根本保证，引领伟大社会革命是根本目的，习近平新时代中国特色社会主义思想是根本遵循。","explanation":"以跳出历史周期率为战略目标，以解决大党独有难题为主攻方向，以健全全面从严治党体系为有效途径，以锻造坚强组织、建设过硬队伍为重要着力点，以正风肃纪反腐为重要抓手，以自我监督和人民监督相结合为强大动力。","basis":"据关联原题及所列出处编释。","references":[{"source":"self","location":"深入推进党的自我革命实践要求"}],"related":["k-843675050c632a63","k-ce1e1cc79bdb2c0f"],"examFocus":{"国考 2025 副省级 行测#8":"对照党的自我革命“九个以”，核对不同举措与根本目的、战略目标、主攻方向和强大动力的对应关系。"}},"aspects":[{"title":"实践要求与各项定位的对应关系","uses":[{"unit":"Q1","role":"直接考查","use":"本题均为选非题。A、B、C分别正确对应根本目的、战略目标和主攻方向。D把与自我监督相结合的人民监督换成法律监督，故选D。","evidence":"以自我监督和法律监督相结合为强大动力","qids":["国考 2025 副省级 行测#8","国考 2025 地市级 行测#8","国考 2025 行政执法 行测#8"]}]}]},"k-5e57a8b4ac0cd85f":{"review":{"definition":"2024年党的二十届三中全会《决定》提出，允许科研类事业单位实行比一般事业单位更灵活的管理制度，并探索实行企业化管理。","explanation":"B项准确写出了适用主体和政策赋予的管理灵活性。《决定》对基础研究的投入机制要求竞争性支持与稳定支持相结合，鼓励开展高风险、高价值基础研究，并允许科技人员在成果转化收益分配上有更大自主权。据此可排除A、C、D。","references":[],"evidence":"允许科研类事业单位实行比一般事业单位更灵活的管理制度","disposition":"独立词条","basis":"据原题和解析编释。","title":"科研类事业单位管理制度","related":[],"examFocus":{"国考 2025 副省级 行测#9":"辨析深化科技体制改革中基础研究投入、科研单位管理和成果转化收益分配各自对应的政策要求。"}},"readings":[{"origin":"k-5e57a8b4ac0cd85f","title":"科研类事业单位管理制度","qs":["国考 2025 副省级 行测#9"],"definition":"2024年党的二十届三中全会《决定》提出，允许科研类事业单位实行比一般事业单位更灵活的管理制度，并探索实行企业化管理。","explanation":"B项准确写出了适用主体和政策赋予的管理灵活性。《决定》对基础研究的投入机制要求竞争性支持与稳定支持相结合，鼓励开展高风险、高价值基础研究，并允许科技人员在成果转化收益分配上有更大自主权。据此可排除A、C、D。","evidence":"允许科研类事业单位实行比一般事业单位更灵活的管理制度","doubt":"","references":[]},{"origin":"k-b0182804aaf2a861","title":"科研类事业单位管理制度","qs":["国考 2025 行政执法 行测#9"],"definition":"2024年党的二十届三中全会《决定》允许科研类事业单位实行比一般事业单位更灵活的管理制度，并提出探索实行企业化管理。","explanation":"第9题B项准确保留了政策的适用主体“科研类事业单位”、授权用语“允许”和比较对象“一般事业单位”，因此当选。“探索实行企业化管理”是进一步的改革方向。","evidence":"允许科研类事业单位实行比一般事业单位更灵活的管理制度","doubt":"","references":[]}]},"k-8a3f973b9dbf1b25":{"review":{"definition":"2023年新时代推动东北全面振兴座谈会提出，东北地区要主动对接国家战略需求，整合和优化科教创新资源，加大研发投入，掌握更多关键核心技术。","explanation":"讲​​话将对接国家战略需求、统筹科教创新资源和攻克关键核心技术放在以科技创新推动产业创新的部署中。①准确列出前两项要求。⑤所写的弱化央地合作与讲话提出的创新央地合作模式、促进央地融合发展不符。","references":[],"evidence":"主动对接国家战略需求，整合和优化科教创新资源","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d42814e474bdf061":{"review":{"definition":"2023年新时代推动东北全面振兴座谈会提出，积极培育产业园区，加强对口合作，加快科研成果落地转化。","explanation":"培育产业园区和加强对口合作是讲话为推动科研成果落地提出的具体举措，服务于以科技创新推动产业创新。②完整列出这两项举措和转化目标，计入正确的四项。","references":[],"evidence":"积极培育产业园区，加强对口合作，加快科研成果落地转化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5463af2ea6914a4a":{"review":{"title":"宣传思想文化工作的首要政治任务","type":"制度与规则","definition":"2023年10月全国宣传思想文化工作会议传达的习近平总书记重要指示明确，宣传思想文化工作的首要政治任务是用党的创新理论武装全党、教育人民。","explanation":"这项任务以党的创新理论为内容，面向全党开展理论武装，面向人民开展宣传教育。同一指示还部署了培育和践行社会主义核心价值观、赓续中华文脉等工作。","basis":"据关联原题及所列出处编释。","references":[{"source":"prom","location":"2023年全国宣传思想文化工作会议"}],"related":[],"examFocus":{"国考 2025 副省级 行测#13":"对照习近平总书记关于宣传思想文化工作的指示，辨析各项工作要求的定位，留意“首要政治任务”这一限定。"}},"readings":[{"origin":"k-5463af2ea6914a4a","title":"宣传思想文化工作的首要政治任务","qs":["国考 2025 副省级 行测#13","国考 2025 行政执法 行测#13"],"definition":"2023年10月全国宣传思想文化工作会议传达的习近平总书记重要指示明确，宣传思想文化工作的首要政治任务是用党的创新理论武装全党、教育人民。","explanation":"这项任务以党的创新理论为内容，面向全党开展理论武装，面向人民开展宣传教育。同一指示还部署了培育和践行社会主义核心价值观、赓续中华文脉等工作。","evidence":"","doubt":"","references":[{"source":"prom","location":"2023年全国宣传思想文化工作会议"}]},{"origin":"k-b4ba07f3316e4b25","title":"宣传思想文化工作的首要政治任务","qs":["国考 2025 地市级 行测#13"],"definition":"习近平总书记在2023年关于宣传思想文化工作的重要指示中明确，宣传思想文化工作的首要政治任务是用党的创新理论武装全党、教育人民。","explanation":"B项对应指示中明确列为“首要政治任务”的表述。A项培育和践行社会主义核心价值观、C项提升国家文化软实力和中华文化影响力、D项赓续中华文脉和推动中华优秀传统文化创造性转化、创新性发展，也属于相关工作要求，题目问的是其中的首要政治任务。","evidence":"用党的创新理论武装全党、教育人民","doubt":"","references":[]}],"aspects":[{"title":"重要指示明确的首要政治任务","uses":[{"unit":"Q1","role":"直接考查","use":"题干要求从同一指示涉及的工作中识别首要政治任务，B项对应理论武装和教育。","evidence":"用党的创新理论武装全党、教育人民","qids":["国考 2025 副省级 行测#13","国考 2025 行政执法 行测#13"]}]}]},"k-b4942ae6eae340e8":{"review":{"title":"碳排放双控","type":"制度与规则","definition":"碳排放双控是同时管理碳排放总量和强度的制度。总量衡量一定范围内的排放规模，强度通常以单位国内生产总值的碳排放量衡量。","explanation":"2024年《中共中央关于进一步全面深化改革、推进中国式现代化的决定》第（49）项提出，建立能耗双控向碳排放双控全面转型新机制。随着转型推进，双控的对象由能源消费转向碳排放。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"健全绿色低碳发展机制"}],"domain":"生态环境","examFocus":{"国考 2025 副省级 行测#15":"对照党的二十届三中全会《决定》，核对绿色低碳措施的对象及双控制度的转型方向。"}},"aspects":[{"title":"能耗双控向碳排放双控转型","uses":[{"unit":"Q1","role":"直接考查","use":"题干要求选出健全绿色低碳发展机制中不恰当的举措。B项将《决定》规定的转型方向写反。","evidence":"建立碳排放双控向能耗双控全面转型新机制","qids":["国考 2025 副省级 行测#15","国考 2025 行政执法 行测#15"]}]}],"sources":[{"id":"af6fa182a8393e20","label":"碳排放总量和强度双控制度","topic":"生态环境与能源","category":"非时政","text":"7.碳排放总量和强度双控制度\n“十五五”时期，实施以强度控制为主、总量控制为辅的碳排放双控制度，建立碳达峰\n碳中和综合评价考核制度，加强重点领域和行业碳排放核算能力，健全重点用能和碳排放单\n位管理制度，开展固定资产投资项目碳排放评价，构建符合中国国情的产品碳足迹管理体系\n和产品碳标识认证制度，确保如期实现碳达峰目标。\n碳达峰后，实施以总量控制为主、强度控制为辅的碳排放双控制度，建立碳中和目标评\n价考核制度，进一步强化对各地区及重点领域、行业、企业的碳排放管控要求，健全产品碳\n足迹管理体系，推行产品碳标识认证制度，推动碳排放总量稳中有降。\n——《加快构建碳排放双控制度体系工作方案》","source":{"doc":"6cbfb01fe723bba64b75","first":47,"last":47,"page":47,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-71ef9e139ab9eee8":{"review":{"title":"公立医院编制动态调整","type":"制度与规则","definition":"公立医院编制动态调整是根据医院的功能定位和医疗服务需求等情况，适时调整人员编制配置的机制。","explanation":"2024年《中共中央关于进一步全面深化改革、推进中国式现代化的决定》第（45）项将完善薪酬制度、建立编制动态调整机制一并列入以公益性为导向的公立医院改革。编制调整的方向取决于实际配置需求。","basis":"据关联原题和解析编释。","references":[],"domain":"公共管理","examFocus":{"国考 2025 副省级 行测#16":"区分深化医药卫生体制改革对医疗资源布局、基层服务和公立医院管理的要求，逐项核对改革措施。"}},"aspects":[{"title":"公立医院改革中的编制管理","uses":[{"unit":"Q1","role":"直接考查","use":"题干要求选出深化医药卫生体制改革中不恰当的举措。C项保留了完善薪酬制度的要求，却把编制动态调整写成严格限制、缩减编制数量。","evidence":"完善公立医院薪酬制度，严格限制、缩减编制数量","qids":["国考 2025 副省级 行测#16","国考 2025 地市级 行测#16"]}]}]},"k-14691d1264aa5973":{"review":{"definition":"2024年党的二十届三中全会《决定》把完善市场经济基础制度列为构建高水平社会主义市场经济体制的一项部署，涉及产权、市场信息披露和市场准入等制度。","explanation":"《决定》第（7）项提出依法平等长久保护各种所有制经济产权，完善市场信息披露制度，并优化新业态新领域市场准入环境。B、C、D均属该项部署。A项的财政转移支付体系归入深化财税体制改革，本题问“不属于”，因此选A。","references":[],"evidence":"完善市场信息披露制度，构建商业秘密保护制度","disposition":"独立词条","basis":"据原题和解析编释。","title":"市场经济基础制度","related":[],"examFocus":{"国考 2025 副省级 行测#17":"对照党的二十届三中全会《决定》，辨析题中各项制度是否属于完善市场经济基础制度的部署。"}},"readings":[{"origin":"k-14691d1264aa5973","title":"市场经济基础制度","qs":["国考 2025 副省级 行测#17"],"definition":"2024年党的二十届三中全会《决定》把完善市场经济基础制度列为构建高水平社会主义市场经济体制的一项部署，涉及产权、市场信息披露和市场准入等制度。","explanation":"《决定》第（7）项提出依法平等长久保护各种所有制经济产权，完善市场信息披露制度，并优化新业态新领域市场准入环境。B、C、D均属该项部署。A项的财政转移支付体系归入深化财税体制改革，本题问“不属于”，因此选A。","evidence":"完善市场信息披露制度，构建商业秘密保护制度","doubt":"","references":[]},{"origin":"k-ef63e739408911dd","title":"市场经济基础制度","qs":["国考 2025 行政执法 行测#17"],"definition":"2024年《中共中央关于进一步全面深化改革 推进中国式现代化的决定》第（7）项把完善产权、市场信息披露、市场准入等制度列为完善市场经济基础制度的内容。","explanation":"产权制度涉及依法平等长久保护各种所有制经济产权，信息披露制度和市场准入制度也由第（7）项直接列明，分别对应D、B、C。A项“完善财政转移支付体系”属于深化财税体制改革，因此是本题选非项。","evidence":"完善市场准入制度，优化新业态新领域市场准入环境","doubt":"","references":[]}]},"k-7c21a486552ce461":{"review":{"title":"财政转移支付","type":"制度与规则","definition":"财政转移支付是政府之间按照预算和有关制度安排划拨财政资金，用于调节地区间财力、促进基本公共服务均等化或支持特定政策任务。","explanation":"资金可以由中央财政安排给地方，也可以由地方上级政府安排给下级政府。2024年《中共中央关于进一步全面深化改革、推进中国式现代化的决定》将完善财政转移支付体系列入深化财税体制改革。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"深化财税体制改革"}],"domain":"经济","examFocus":{"国考 2025 副省级 行测#17":"对照党的二十届三中全会《决定》的改革任务划分，核对各项措施所涉及的制度及其用途。"}},"aspects":[{"title":"财政转移支付体系的改革归属","uses":[{"unit":"Q1","role":"直接考查","use":"题干要求选出不属于完善市场经济基础制度的事项。A项属深化财税体制改革，其余三项均见于《决定》关于完善市场经济基础制度的部署。","evidence":"“完善财政转移支付体系”属于“深化财税体制改革”","qids":["国考 2025 副省级 行测#17","国考 2025 地市级 行测#17","国考 2025 行政执法 行测#17"]}]}]},"k-af13498b6f12d3f0":{"review":{"title":"违规操办婚丧喜庆事宜","type":"制度与规则","definition":"根据《中国共产党纪律处分条例》第一百条，党员利用职权或者职务上的影响操办婚丧喜庆事宜，造成不良影响的，属于违反廉洁纪律。","explanation":"造成不良影响的，给予警告或者严重警告处分。情节严重的，给予撤销党内职务处分。借机敛财或者有其他侵犯国家、集体和人民利益行为的，从重或者加重处分，直至开除党籍。","basis":"据关联原题及所列出处编释。","references":[{"source":"discipline","location":"第一百条"}],"examFocus":{"国考 2025 副省级 行测#18":"按《中国共产党纪律处分条例》，结合违纪行为的性质、职权使用和后果区分纪律类别。"}},"aspects":[{"title":"廉洁纪律的适用情形","uses":[{"unit":"Q1","role":"直接考查","use":"本题 均选 D。D 项以借助职权或职务影响操办婚丧喜庆事宜并造成不良影响的情形考查纪律归类。选项用词为“滥用”，条例原文用词为“利用”。","evidence":"滥用职权或者职务上的影响操办婚丧喜庆事宜，造成不良影响的","qids":["国考 2025 副省级 行测#18","国考 2025 地市级 行测#18"]}]}]},"k-c89e5b9cbd29084a":{"review":{"definition":"2024年《政府工作报告》提出，合理扩大地方政府专项债券投向领域和用作资本金范围，并将额度分配向项目准备充分、投资效率较高的地区倾斜。","explanation":"报告将这项措施列在扩大国内需求的“积极扩大有效投资”部署下。扩大投向领域可以让更多符合条件的项目获得融资支持，因此③对应扩大内需的投资措施，与消费端的④一同入选。","references":[],"evidence":"合理扩大地方政府专项债券投向领域和用作资本金范围","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9d70ef2e9465e4d1":{"review":{"definition":"2024年《政府工作报告》提出实施数字消费、绿色消费、健康消费促进政策，以培育壮大新型消费。","explanation":"报告将这三类消费促进政策纳入扩大国内需求的部署，并提出培育智能家居、文娱旅游、体育赛事等消费增长点。因此④对应扩大内需的消费措施。题中①对应粮食安全，②对应稳外贸，正确组合为③④，选D。","references":[],"evidence":"培育壮大新型消费，实施数字消费、绿色消费、健康消费促进政策","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-65facf6513958582":{"review":{"title":"行政强制措施的法律保留","type":"制度与规则","definition":"根据《中华人民共和国行政强制法》第九条、第十条，限制公民人身自由和冻结存款、汇款这两类行政强制措施只能由法律设定。","explanation":"尚未制定法律且属于国务院行政管理职权的事项，行政法规可以设定法律保留范围以外的行政强制措施。尚未制定法律、行政法规且属于地方性事务的，地方性法规可以设定查封场所、设施或者财物以及扣押财物的措施。","basis":"据关联原题及所列出处编释。","references":[{"source":"strong","location":"第九条第一项、第四项及第十条"}],"examFocus":{"国考 2025 副省级 行测#22":"区分行政强制措施的设定、立法授权、法律解释和行政法规制定，核对各自的权限主体或规范层级。"}},"aspects":[{"title":"限制人身自由与冻结存款的设定权限","uses":[{"unit":"Q1","role":"直接考查","use":"本题 均选 A。强制隔离戒毒属于限制公民人身自由的行政强制措施，冻结存款属于冻结存款、汇款一类，两项均须由法律设定。","evidence":"强制隔离戒毒、冻结存款的行政强制措施只能由法律予以设定","qids":["国考 2025 副省级 行测#22","国考 2025 行政执法 行测#21"]}]}]},"k-4f30cd36134bbd26":{"review":{"definition":"行政机关对行政机关工作人员作出的奖惩、任免等人事决定，依法不属于行政复议范围。","explanation":"C项中，公务员丙因不能胜任工作被所属行政机关降职，这属于对工作人员作出的人事决定。A项吊销许可证属于行政处罚，B项拒绝施工许可申请属于行政许可事项，D项不予受理工伤认定申请也属于法定复议范围。题干要求选出不在复议范围内的情形，因此选C。","references":[],"evidence":"行政机关对行政机关工作人员的奖惩、任免等决定","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b003516d27f18ed3":{"review":{"definition":"食品生产企业可以自行检验所生产的食品，也可以委托符合《中华人民共和国食品安全法》规定的食品检验机构检验。","explanation":"法律允许企业选择自行检验或委托检验。A项的企业已自行检验产品，无须就该项检验再委托专业机构，因此符合题干要求。","references":[],"evidence":"某食品生产企业自行检验产品后，不再委托专业机构进行检验","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-69ac055ecd185103":{"review":{"definition":"跳水竞赛为规定的跳水动作设定难度系数。确定系数时考虑动作姿势、翻腾周数和转体周数等因素。","explanation":"难度系数反映规定动作本身的难度，裁判的执行评分反映运动员完成该动作的质量。A项列举的是确定动作难度时考虑的因素，因此说法正确。","references":[],"evidence":"具体因素包括动作的转体次数、翻腾次数和姿势难度等","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-91fe0d5029480d60":{"review":{"definition":"篮球罚球时，罚球队员应在罚球线后方的半圆内站位，可以双脚离地投篮。在球进入球篮或触及篮圈前，罚球队员不得触及罚球线或进入限制区。","explanation":"双脚离地本身符合罚球规则，跳投时仍须遵守罚球线和限制区的要求。B项只说罚球时可以双脚离地，因此说法正确。","references":[],"evidence":"罚球时并未规定球员双脚是否可以离地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b1846880a25bcf5f":{"review":{"definition":"标准十一人制足球比赛的常规规定时长为90分钟，上下半场各45分钟。","explanation":"90分钟是两个半场规定时长的总和。每半场可补足损失的时间，须决出胜负的赛事也可按竞赛规程另行安排加时赛。C项所说的90分钟指常规规定时长，因此说法正确。","references":[],"evidence":"足球比赛的常规时间长度为90分钟，分为上下两个半场","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7647a394f1f47a37":{"review":{"definition":"举重比赛中，三名临场裁判各自对试举作出判定，白灯表示成功，红灯表示失败。按临场裁判的多数判定，两盏或三盏白灯即判试举成功。","explanation":"两白一红时，判成功的裁判已占多数。D项把三盏白灯说成试举成功的必要条件，因此是本题要求选出的错误说法。","references":[],"evidence":"如2白1红或2红1白，那就要少数服从多数","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0ec89fa8df4c3037":{"review":{"definition":"按题干定义，回应型预算要求政府在与公众开展民主协商的基础上作出预算决策，相关责任部门应当及时反应并积极答复公众的质疑和诉求。","explanation":"丁区对涉及公共服务和社会民生的重大支出项目举行预算听证，并书面答复意见和建议，同时体现了预算协商与诉求答复，故选D。甲国安排救灾经费体现的是应急保障，乙省在官网发布说明体现的是预算公开。丙市虽邀请公众提意见，但意见针对上一年度已执行的预算，题中未体现这些意见进入预算决策过程或得到答复。","references":[],"evidence":"对与公共服务和社会民生相关的重大支出项目开展听证，并就意见和建议进行书面答复","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b9e07c46a5b6539e":{"review":{"definition":"《联合国宪章》是创设联合国的国际条约，规定了联合国的宗旨、原则和主要机构等基本事项。","explanation":"第105题按条约属性将《联合国宪章》归入“国际公约”。D项右侧从具体公约指向上位类别，与左侧从“稀树草原”指向“植被类型”的种属方向一致。","references":[],"evidence":"联合国宪章是联合国的基本大法，是国际公约","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-60c8c703ece7f41c":{"review":{"definition":"2022年9月，中共中央办公厅、国务院办公厅印发《关于新时代进一步加强科学技术普及工作的意见》，提出坚持把科学普及放在与科技创新同等重要的位置。","explanation":"材料中丁指出，科学家做科普时仍可能被贴上“不务正业”的标签。提案在案由中引用这一政策要求，为纠正重科研轻科普的倾向、提高对科普工作的重视程度提供依据。","references":[],"evidence":"坚持把科学普及放在与科技创新同等重要的位置","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-016afa40aa881bae":{"review":{"definition":"2023年中央金融工作会议提出，要优化资金供给结构，把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业。","explanation":"A项保留了科技创新和绿色发展，却把先进制造换成传统制造、把中小微企业换成国有企业，偏离了这项资金投向部署。题干要求选出表述不准确的一项，因此选A。","references":[],"evidence":"把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9d9271537a7a63d7":{"review":{"definition":"2023年中央金融工作会议提出，要着力营造良好的货币金融环境，切实加强对重大战略、重点领域和薄弱环节的优质金融服务。","explanation":"B项同时保留了营造良好的货币金融环境这一要求，以及重大战略、重点领域和薄弱环节三类服务重点，符合会议部署。本题为选非题，因此排除B。","references":[],"evidence":"切实加强对重大战略、重点领域和薄弱环节的优质金融服务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-265101863520c2c1":{"review":{"definition":"2023年中央金融工作会议提出，要始终保持货币政策的稳健性，更加注重做好跨周期和逆周期调节，充实货币政策工具箱。","explanation":"稳健性是政策基调，跨周期和逆周期调节是调节要求，工具箱则为实施调节提供政策手段。C项完整保留了这三层表述，符合会议部署，因此在本题中排除。","references":[],"evidence":"更加注重做好跨周期和逆周期调节，充实货币政策工具箱","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-68911927a32560ef":{"review":{"definition":"2023年中央金融工作会议提出，要完善机构定位，支持国有大型金融机构做优做强，使其当好服务实体经济的主力军和维护金融稳定的压舱石。","explanation":"D项的主体是国有大型金融机构，对应的是机构定位和两项作用，符合会议部署，因此在选非题中排除。A项讨论的是优化资金供给结构时的重点投向，其中把中小微企业换成了国有企业。","references":[],"evidence":"当好服务实体经济的主力军和维护金融稳定的压舱石","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b52208ee259a41b2":{"review":{"definition":"粮食安全实行党政同责，党委和政府都要落实粮食安全责任。粮食生产要稳定播种面积、提高单位面积产量，推动粮食均衡增产。","explanation":"2023年12月习近平总书记在广西考察时同时提出了责任和生产两方面的要求。题中①的“党政同责”明确由谁落实，“稳面积、增单产”明确通过哪两方面发力，因此①正确。","references":[],"evidence":"全面落实粮食安全党政同责，坚持稳面积、增单产两手发力","disposition":"独立词条","basis":"据原题和解析编释。","title":"粮食安全党政同责与稳面积、增单产","related":[],"examFocus":{"国考 2025 副省级 行测#6":"核对粮食安全部署时，留意责任如何落实，以及粮食生产提出了哪些具体要求。"}},"readings":[{"origin":"k-b52208ee259a41b2","title":"粮食安全党政同责与稳面积、增单产","qs":["国考 2025 地市级 行测#6"],"definition":"粮食安全实行党政同责，党委和政府都要落实粮食安全责任。粮食生产要稳定播种面积、提高单位面积产量，推动粮食均衡增产。","explanation":"2023年12月习近平总书记在广西考察时同时提出了责任和生产两方面的要求。题中①的“党政同责”明确由谁落实，“稳面积、增单产”明确通过哪两方面发力，因此①正确。","evidence":"全面落实粮食安全党政同责，坚持稳面积、增单产两手发力","doubt":"","references":[]},{"origin":"k-df01cc4389d71a2c","title":"粮食安全党政同责与稳面积、增单产","qs":["国考 2025 行政执法 行测#6"],"definition":"粮食安全党政同责要求党委和政府共同承担保障粮食安全的责任。粮食生产要同时稳定播种面积、提高单位面积产量，实现粮食均衡增产。","explanation":"稳面积是为了稳住粮食生产规模，增单产是为了让同等面积产出更多粮食。第6题①同时列出党政同责和粮食增产的两个着力点，符合2023年12月习近平总书记在广西考察时提出的要求，计入四项正确举措。","evidence":"全面落实粮食安全党政同责，坚持稳面积、增单产两手发力","doubt":"","references":[]},{"origin":"k-ebb34657b20cdddb","title":"粮食安全党政同责与稳面积、增单产","qs":["国考 2025 副省级 行测#6"],"definition":"保障粮食安全要落实党政同责，由党委和政府共同承担责任。粮食增产要同时稳定粮食播种面积和提高单位面积产量。","explanation":"①同时列出了责任要求和生产举措，与解析所引广西考察要求一致。在总产量取决于播种面积和单产的关系中，稳面积夯实生产基础，增单产提高单位面积的产出。①应计入正确项，与②③⑤合计4项，对应C。","evidence":"要全面落实粮食安全党政同责，坚持稳面积、增单产两手发力，实现粮食均衡增产。","doubt":"","references":[]}]},"k-2c4328a87ea1b2ff":{"review":{"definition":"习近平总书记在《促进高质量充分就业》中提出，要坚持创业带动就业，通过创业创造更多就业岗位和机会。","explanation":"文章把“坚持创业带动就业”列为新时代就业工作的经验。题中③写成“坚持就业带动创业”，颠倒了政策表述中的带动方向，因此③错误。","references":[],"evidence":"坚持创业带动就业","disposition":"独立词条","basis":"据原题和解析编释。","title":"创业带动就业","related":[],"examFocus":{"国考 2025 地市级 行测#7":"核对高质量充分就业政策中创业与就业之间的带动方向。"}},"readings":[{"origin":"k-2c4328a87ea1b2ff","title":"创业带动就业","qs":["国考 2025 地市级 行测#7"],"definition":"习近平总书记在《促进高质量充分就业》中提出，要坚持创业带动就业，通过创业创造更多就业岗位和机会。","explanation":"文章把“坚持创业带动就业”列为新时代就业工作的经验。题中③写成“坚持就业带动创业”，颠倒了政策表述中的带动方向，因此③错误。","evidence":"坚持创业带动就业","doubt":"","references":[]},{"origin":"k-63f69e26503e7af2","title":"创业带动就业","qs":["国考 2025 行政执法 行测#7"],"definition":"创业带动就业是指通过创业创造新的工作岗位和就业机会。《促进高质量充分就业》将坚持创业带动就业列为新时代就业工作的经验。","explanation":"政策表述以创业为带动因素、以就业为促进目标。第7题③写成“坚持就业带动创业”，颠倒了文章所述的带动方向，因此错误。","evidence":"坚持创业带动就业","doubt":"","references":[]}]},"k-33019888376c71a6":{"review":{"definition":"2024年党的二十届三中全会《决定》允许科研类事业单位实行比一般事业单位更灵活的管理制度，并提出探索实行企业化管理。","explanation":"B项准确写出适用主体和政策性质，即允许科研类事业单位采用更灵活的管理制度。企业化管理在该条部署中属于探索事项。","references":[],"evidence":"允许科研类事业单位实行比一般事业单位更灵活的管理制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bab481d884488a98":{"review":{"definition":"2023年新时代推动东北全面振兴座谈会提出，东北要主动对接国家战略需求，整合和优化科教创新资源，加大研发投入，掌握更多关键核心技术。","explanation":"国家战略需求为科教创新资源配置和研发提供方向。题中①符合讲话的这项部署，⑤所说的“逐步弱化央地合作”则与讲话提出的创新央地合作模式、促进央地融合发展相冲突。","references":[],"evidence":"主动对接国家战略需求，整合和优化科教创新资源","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8f8bdc0df14e77f0":{"review":{"definition":"2023年新时代推动东北全面振兴座谈会提出，要积极培育产业园区、加强对口合作，加快科研成果落地转化，以科技创新推动产业创新。","explanation":"讲话把产业园区和对口合作放在科研成果落地转化的部署中，题中②准确写出了这两项举措及其目标。③所列新能源、新材料等则对应同一讲话中培育战略性新兴产业的部署。","references":[],"evidence":"积极培育产业园区，加强对口合作，加快科研成果落地转化。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-440f6bbced89d97b":{"review":{"title":"大统战工作格局","type":"制度与规则","definition":"大统战工作格局是党委统一领导、统战部门牵头协调、有关方面各负其责的统一战线工作格局。","explanation":"2024年7月18日，党的二十届三中全会通过的《中共中央关于进一步全面深化改革、推进中国式现代化的决定》在第32项部署完善大统战工作格局，涵盖党外代表人士队伍建设、铸牢中华民族共同体意识和构建亲清政商关系等工作。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"完善大统战工作格局"}],"examFocus":{"国考 2025 地市级 行测#14":"按各项改革措施涉及的对象和制度功能，核对它们在党的二十届三中全会《决定》中是否归入统战工作部署。"}},"aspects":[{"title":"二十届三中全会的统战改革部署","uses":[{"unit":"Q1","role":"直接考查","use":"题干要求选出不属于完善大统战工作格局的措施。A的党外代表人士队伍建设、B的制定民族团结进步促进法及健全相关制度机制、C的亲清政商关系及促进非公有制经济和非公有制经济人士健康发展的相关机制，均列在《决定》第32项。D的议事规则及相关制度列在第29项“加强人民当家作主制度建设”，因此选D。","evidence":"健全人大议事规则和论证、评估、评议、听证制度","qids":["国考 2025 地市级 行测#14","国考 2025 行政执法 行测#14"]}]}]},"k-95dcffde921a07f8":{"review":{"definition":"2024年党的二十届三中全会《决定》将健全人大议事规则和论证、评估、评议、听证制度列入第（29）项“加强人民当家作主制度建设”。","explanation":"题目要求选出不属于完善大统战工作格局的措施。A项党外代表人士队伍建设、B项民族团结进步相关制度、C项亲清政商关系及相关工作机制均列在《决定》第（32）项，D项人大议事及相关制度列在第（29）项，因此选D。","references":[],"evidence":"健全人大议事规则和论证、评估、评议、听证制度","disposition":"独立词条","basis":"据原题和解析编释。","title":"人大议事规则和论证、评估、评议、听证制度","related":[],"examFocus":{"国考 2025 副省级 行测#14":"对照党的二十届三中全会《决定》，辨析各项制度举措的归属，留意大统战工作与人民当家作主制度建设的范围。"}},"readings":[{"origin":"k-95dcffde921a07f8","title":"人大议事规则和论证、评估、评议、听证制度","qs":["国考 2025 地市级 行测#14"],"definition":"2024年党的二十届三中全会《决定》将健全人大议事规则和论证、评估、评议、听证制度列入第（29）项“加强人民当家作主制度建设”。","explanation":"题目要求选出不属于完善大统战工作格局的措施。A项党外代表人士队伍建设、B项民族团结进步相关制度、C项亲清政商关系及相关工作机制均列在《决定》第（32）项，D项人大议事及相关制度列在第（29）项，因此选D。","evidence":"健全人大议事规则和论证、评估、评议、听证制度","doubt":"","references":[]},{"origin":"k-a2009c8b92193e47","title":"人大议事规则和论证、评估、评议、听证制度","qs":["国考 2025 副省级 行测#14"],"definition":"2024年党的二十届三中全会《决定》在第（29）项“加强人民当家作主制度建设”中，部署健全人大议事规则和论证、评估、评议、听证制度。","explanation":"本题按《决定》的条目归属选非。A、B、C分别对应第（32）项“完善大统战工作格局”中的党外代表人士队伍建设、民族团结进步和亲清政商关系等部署。D归入第（29）项，因此应选D。","evidence":"健全人大议事规则和论证、评估、评议、听证制度","doubt":"","references":[]},{"origin":"k-d771fdaf6b69dc36","title":"人大议事规则和论证、评估、评议、听证制度","qs":["国考 2025 行政执法 行测#14"],"definition":"2024年《中共中央关于进一步全面深化改革 推进中国式现代化的决定》第（29）项要求健全人大议事规则和论证、评估、评议、听证制度，并将其列入人民当家作主制度建设。","explanation":"第（29）项和第（32）项都在“健全全过程人民民主制度体系”部分，但部署各有归属。A、B、C分别对应第（32）项的党外代表人士队伍建设、民族团结进步和亲清政商关系。D项属于第（29）项，本题问哪项不属于完善大统战工作格局，因此选D。","evidence":"健全人大议事规则和论证、评估、评议、听证制度","doubt":"","references":[]}]},"k-8c1fa4140851f799":{"review":{"definition":"党的二十届三中全会《决定》提出建立能耗双控向碳排放双控全面转型新机制。转型起点是能源消费总量和强度双控，转型方向是碳排放总量和强度双控。","explanation":"两种双控分别以能源消费和碳排放为管理对象。B项把政策规定的起点和方向对调，写成碳排放双控向能耗双控转型，因此是本题所选的不恰当举措。","references":[],"evidence":"建立能耗双控向\n碳排放双控全面转型新机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-792ffc72bda5a188":{"review":{"definition":"党的二十届三中全会《决定》将完善产权制度、市场信息披露制度和市场准入制度等列入完善市场经济基础制度的部署，具体包括依法平等长久保护各种所有制经济产权、构建商业秘密保护制度和优化新业态新领域市场准入环境。","explanation":"B项的市场信息披露、C项的市场准入和D项的产权都在《决定》第（7）项部署中。A项的完善财政转移支付体系归入深化财税体制改革，因此在本题按文件部署归类时应选A。","references":[],"evidence":"“完善财政转移支付体系”属于“深化财税体制改革”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1adc02dd34141bad":{"review":{"definition":"评价地方党政领导班子和领导干部政绩，应当把贯彻落实党中央决策部署、贯彻新发展理念和推动高质量发展的实际表现与工作实绩作为基本依据。","explanation":"B项要求完善推动高质量发展的政绩考核评价办法，使考核围绕实际成效展开。C项把打基础、利长远落在做强指标和做优数据上，偏离了这一要求。中共中央政治局第十一次集体学习于2024年1月31日下午举行，新华社通稿于2月1日发布，通稿用语为“完善推动高质量发展的考核评价体系”。","references":[{"source":"web-ca0b326636e0ea6a","location":"第一部分","quote":"推动高质量发展的实际表现和工作实绩"},{"source":"web-6d7d94cffb4f04b5","location":"发布日期及正文首段","quote":"完善推动高质量发展的考核评价体系"}],"evidence":"坚持高质量发展，要完善推动高质量发展的政绩考核评价办法","disposition":"独立词条","basis":"据原题与所列资料编释。","title":"推动高质量发展的政绩考核","related":[],"examFocus":{"国考 2025 副省级 行测#19":"辨析正确政绩观对发展导向、干部考核和工作成效的要求。"}},"readings":[{"origin":"k-1adc02dd34141bad","title":"推动高质量发展的政绩考核","qs":["国考 2025 地市级 行测#19"],"definition":"评价地方党政领导班子和领导干部政绩，应当把贯彻落实党中央决策部署、贯彻新发展理念和推动高质量发展的实际表现与工作实绩作为基本依据。","explanation":"B项要求完善推动高质量发展的政绩考核评价办法，使考核围绕实际成效展开。C项把打基础、利长远落在做强指标和做优数据上，偏离了这一要求。中共中央政治局第十一次集体学习于2024年1月31日下午举行，新华社通稿于2月1日发布，通稿用语为“完善推动高质量发展的考核评价体系”。","evidence":"坚持高质量发展，要完善推动高质量发展的政绩考核评价办法","doubt":"","references":[{"source":"web-ca0b326636e0ea6a","location":"第一部分","quote":"推动高质量发展的实际表现和工作实绩"},{"source":"web-6d7d94cffb4f04b5","location":"发布日期及正文首段","quote":"完善推动高质量发展的考核评价体系"}]},{"origin":"k-94ca802922710d66","title":"推动高质量发展的政绩考核","qs":["国考 2025 副省级 行测#19"],"definition":"完善推动高质量发展的政绩考核评价办法，要求把贯彻新发展理念、推动高质量发展的实际表现和工作实绩作为评价领导班子和领导干部政绩的基本依据。","explanation":"B项把高质量发展要求落实到干部政绩考核，符合题干所说的正确工作导向。C项虽提出打基础、利长远，却把工作着力点落在发展指标和数据上。D项虽提出求实效，却把大气派工程当成实现实效的途径。这两项都偏离了以实际工作成效评价政绩的要求。","evidence":"坚持高质量发展，要完善推动高质量发展的政绩考核评价办法","doubt":"","references":[]},{"origin":"k-d780c59a9acc9889","title":"推动高质量发展的政绩考核","qs":["国考 2025 行政执法 行测#19"],"definition":"地方党政领导班子和领导干部的政绩考核，应当以贯彻落实党中央决策部署、贯彻新发展理念和推动高质量发展的实际表现与工作实绩为基本依据。","explanation":"B项完善政绩考核评价办法，体现了以实际成效引导干部工作的要求。D项前半句强调出实招、求实效，后半句却把工程的规模和气派作为着力点，偏离了这一要求。中共中央政治局第十一次集体学习于2024年1月31日下午举行，新华社通稿于2月1日发布，通稿用语为“完善推动高质量发展的考核评价体系”。","evidence":"坚持高质量发展，要完善推动高质量发展的政绩考核评价办法","doubt":"","references":[{"source":"web-ca0b326636e0ea6a","location":"第一部分","quote":"推动高质量发展的实际表现和工作实绩"},{"source":"web-6d7d94cffb4f04b5","location":"发布日期及正文首段","quote":"完善推动高质量发展的考核评价体系"}]}]},"k-2e4d8e52be2a1238":{"review":{"definition":"2024年新时代推动西部大开发座谈会提出，要坚持以大开放促进大开发，提高西部地区对内对外开放水平。","explanation":"讲话把推进西部陆海新通道建设、带动沿线地区开发开放和深度融入共建“一带一路”列为落实要求。B项同时保留了以开放带动开发和提高对内对外开放水平两层意思，符合讲话部署。","references":[],"evidence":"要坚持以大开放促进大开发，提高西部地区对内对外开放水平","disposition":"独立词条","basis":"据原题和解析编释。","title":"西部大开发以大开放促进大开发","related":[],"examFocus":{"国考 2025 地市级 行测#20":"核对新时代西部大开发的部署，重点辨析开放与开发的关系，以及政策涉及的开放范围。"}},"readings":[{"origin":"k-2e4d8e52be2a1238","title":"西部大开发以大开放促进大开发","qs":["国考 2025 地市级 行测#20"],"definition":"2024年新时代推动西部大开发座谈会提出，要坚持以大开放促进大开发，提高西部地区对内对外开放水平。","explanation":"讲话把推进西部陆海新通道建设、带动沿线地区开发开放和深度融入共建“一带一路”列为落实要求。B项同时保留了以开放带动开发和提高对内对外开放水平两层意思，符合讲话部署。","evidence":"要坚持以大开放促进大开发，提高西部地区对内对外开放水平","doubt":"","references":[]},{"origin":"k-d19ff056ad8421d2","title":"西部大开发以大开放促进大开发","qs":["国考 2025 行政执法 行测#20"],"definition":"2024年4月新时代推动西部大开发座谈会提出，坚持以大开放促进大开发，提高西部地区对内对外开放水平。","explanation":"这项部署包括推进西部陆海新通道建设、推动沿线地区开发开放和深度融入共建“一带一路”。B项同时保留了以开放促开发和提高对内对外开放水平两层意思，表述符合部署。","evidence":"要坚持以大开放促进大开发，提高西部地区对内对外开放水平。","doubt":"","references":[]}]},"k-0c637554e885a5b8":{"review":{"definition":"2024年新时代推动西部大开发座谈会提出，西部地区要统筹发展和安全，提升能源资源等重点领域的安全保障能力。","explanation":"讲话把加快建设新型能源体系、做大做强一批国家重要能源基地作为具体举措。C项把统筹发展和安全与能源资源等重点领域的保障能力相联系，符合讲话部署。","references":[],"evidence":"要坚持统筹发展和安全，提升能源资源等重点领域安全保障能力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-67a5775d9a28143d":{"review":{"definition":"2024年新时代推动西部大开发座谈会提出，西部地区要推进新型城镇化和乡村全面振兴有机结合，在发展中保障和改善民生。","explanation":"讲话提出加大对国家乡村振兴重点帮扶县的支持力度，建立低收入人口和欠发达地区常态化帮扶机制，防止发生规模性返贫。D项把城乡发展部署与保障和改善民生相联系，符合讲话要求。","references":[],"evidence":"要坚持推进新型城镇化和乡村全面振兴有机结合，在发展中保障和改善民生","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-df66ec7589c300c4":{"review":{"definition":"依照《中华人民共和国行政复议法》，行政机关对行政机关工作人员作出的奖惩、任免等决定，不属于行政复议范围。","explanation":"C项中，公务员丙因不能胜任工作受到所属机关的降职处理，属于内部人事决定。吊销餐饮服务许可证、拒绝施工许可申请和不予受理工伤认定申请分别属于可申请行政复议的行政处罚、行政许可和工伤认定事项，因此本题选C。","references":[],"evidence":"机关对行政机关工作人员的奖惩、任免等决定。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-858911ce1d33ae7f":{"review":{"definition":"拾得遗失物应当返还权利人。拾得人应当及时通知权利人领取，或者将遗失物送交公安等有关部门。","explanation":"A项中的金项链属于遗失物。甲多方寻找失主未果，可以将项链送交有关部门。寻找未果本身不会使甲取得项链的所有权。","references":[],"evidence":"拾得遗失物，应当返还权利人。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5f862ab0ae36cb2d":{"review":{"definition":"因继承取得物权的，自继承开始时发生效力。继承从被继承人死亡时开始。","explanation":"C项已经给定丙继承了房产。房屋所有权自被继承人死亡时取得，尚未办理变更登记不影响丙在该时点取得所有权。","references":[],"evidence":"因继承取得物权的，自继承开始时发生效力。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b21fb3ecf7bc3ab2":{"review":{"definition":"集体土地的承包方依法享有对承包土地的占有、使用和收益权利。承包后，土地所有权仍归集体。","explanation":"D项中，丁承包村集体的田地，可以依法耕种并取得种植收益。这些权利来自土地承包经营权，因此D项关于丁同时取得田地所有权的说法错误。","references":[],"evidence":"丁从村集体处承包了一块田地用于农作物种植","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e3d1e70dc90271c2":{"review":{"definition":"根据《中华人民共和国公司法》第四十条，公司应当按照规定通过国家企业信用信息公示系统公示有限责任公司股东认缴和实缴的出资额、出资方式和出资日期。","explanation":"B项的实缴出资额和出资方式均在第四十条列明的范围内。题干问的是哪一事项必须通过指定系统公示，因此要看条文是否明确指定渠道。","references":[],"evidence":"有限责任公司股东认缴和实缴的出资额、出资方式和出资日期","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8b41c00e0b50fc03":{"review":{"definition":"依2024年7月1日起施行的《公司法》，公司合并、一般减资和解散清算的债权人公告，可以在报纸或国家企业信用信息公示系统发布。司法破产程序中的法定公告，应由人民法院或管理人依各自职责在全国企业破产重整案件信息网发布。","explanation":"A项合并与C项减资适用可选渠道的规则。D项写的是破产清算，宣告破产由人民法院公告，适用破产程序的发布规则，原解析援引的《公司法》第二百三十五条规定的是解散清算。B项的实缴出资额和出资方式属于第四十条规定的有限责任公司股东信息，必须通过国家企业信用信息公示系统公示。","references":[{"source":"web-10c8ca21f82300d2","location":"第四十条、第二百二十条、第二百二十四条、第二百三十五条、第二百四十二条","quote":"依照有关企业破产的法律实施破产清算"},{"source":"web-7b713ec8e8b090bb","location":"第一百零七条第一款","quote":"通知已知债权人，并予以公告"},{"source":"web-49235732ee4db79a","location":"第一部分第1点","quote":"应当在全国企业破产重整案件信息网发布"}],"evidence":"在报纸上或者国家企业信用信息公示系统公告","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-2d60c095aba8bb2e":{"review":{"definition":"经营者以收取预付款方式提供商品或者服务的，应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方式和违约责任等事项。","explanation":"D项的丁健身馆先收取3000元，再提供为期半年的私教课程，属于预付款消费。其订立书面合同的做法符合《中华人民共和国消费者权益保护法实施条例》第二十二条的形式要求，合同还应明确预付款退还方式和违约责任等事项。","references":[],"evidence":"应当与消费者订立书面合同","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1f8c7e775e5e8d3c":{"review":{"definition":"经营者采取自动续费等方式提供服务的，应当在消费者接受服务前和自动续费日期前，分别以显著方式提请消费者注意。","explanation":"A项的云服务商在订购前显著展示条款，消费者也勾选了自动续费，这些事实只涉及接受服务前的环节。到期扣费前仍负有显著提醒义务，仅凭首次提示和勾选，不能得出可在到期时直接扣费的结论。","references":[],"evidence":"应当在消费者接受服务前和自动展期、自动续费等日期前，以显著方式提请消费者注意。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bfe92274319a826f":{"review":{"definition":"经营者向消费者提供商品或者服务，应当保证其符合保障人身、财产安全的要求。以奖励、赠送、试用等形式免费提供的商品或者服务也适用这一要求。","explanation":"B项中，车身划痕由加油站提供的洗车服务造成，涉及消费者的财产安全。加油站仍负有安全保障义务，免费本身不足以免除相应的赔偿责任。","references":[],"evidence":"包括以奖励、赠送、试用等形式向消费者免费提供商品或者服务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e37f814fbdab8427":{"review":{"definition":"网络购物原则上适用自收到商品之日起七日内无理由退货。除法律直接列明的例外外，经营者主张某商品依其性质不宜退货的，应当显著标注并由消费者在购买时确认，不得擅自扩大例外范围或设置默认同意。","explanation":"C项的直播卖衣服属于网络销售。主播称服装是尾货或瑕疵品，并提醒谨慎购买，既不足以认定这批服装依其性质不宜退货，也没有体现消费者在购买时作出确认，因此不能据此排除七日无理由退货。","references":[],"evidence":"不得将不适用无理由退货作为消费者默认同意的选项。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e12589bf1bcfff1e":{"review":{"definition":"大帆夜市巡查小组从19点起逐一检查商铺和摊位的消防设施器材、防火标志、疏散通道、安全出口、消防车通道及用电安全。按材料中的管理要求，每个摊位至少配备两瓶灭火器，摊主须会使用。","explanation":"材料中，巡查小组发现有摊位只配了一瓶灭火器，随即开展消防安全教育并责令限期改正。指南应把设施是否配齐、通道和出口是否畅通、用电是否安全写成具体巡查内容。","references":[],"evidence":"每个摊位最少配备两瓶灭火器","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ff6e88fe46dcb954":{"review":{"definition":"大帆夜市巡查小组检查食品储存、加工和经手人员情况，查看材料所称的食品卫生许可证是否按要求悬挂、从业人员健康证是否有效。","explanation":"材料中查出了从业人员健康证过期，以及生熟、干湿、鲜活食品未分开储存两类问题。指南应分别写明证件核查和食品储存、加工情况检查。材料还写到可借助库房摄像头查看食品存放、加工和经手人员情况。","references":[],"evidence":"生熟、干湿、鲜活食品未分开储存","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-81c3863e4f1f33fe":{"review":{"definition":"大帆夜市巡查小组发现消防或食品卫生问题后，应及时登记、拍照并上传平台，按具体问题开展教育、要求限期改正。","explanation":"材料写到小葛用手机拍照并上传市场管理平台，健康证过期另作登记并要求尽快更换。对食品未分开储存的问题，由小组中来自市场监管局的工作人员开具限期整改通知书。指南可据此写清记录问题和现场督促整改两项工作。","references":[],"evidence":"对存在问题的地方，小葛用手机拍照，上传到了市场管理平台","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3ed2aa2ea30d417a":{"review":{"definition":"大帆夜市巡查小组遇到纠纷应及时到场，有群众围观时先疏散。小纠纷一般现场调解，较大纠纷转到夜市综合服务办公室调解室处理。","explanation":"两名顾客因抢占座位发生争执并引来大量群众围观。巡查小组先疏散围观群众、现场问询，随后将当事人带到调解室，由民警、调解员和律师共同调解。指南应写明现场稳控和按纠纷大小安排调解地点的做法。","references":[],"evidence":"对于较大的纠纷，则将当事人带到调解室专门解决","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a1cd076ec5ca8eb5":{"review":{"definition":"大帆夜市巡查小组发现走散人员时，应及时联系家属，并将走散人员送到夜市综合服务办公室临时安置。","explanation":"材料中，20时50分发现一名与家长走散的儿童，巡查小组及时联系家长，社区民警随后将孩子送到办公室。参考答案先列安置、再列联络，指南写清两项工作即可。","references":[],"evidence":"社区民警老皮将孩子送到了夜市综合服务办公室","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-aede726fc5de53a1":{"review":{"definition":"大帆夜市每晚例行巡查结束后，巡查小组应根据当天工作情况完成巡查记录，并做好工作交接。","explanation":"材料写到夏季夜市通常到凌晨1点才降温，周末和节假日可能更晚。指南应按每晚例行巡查结束这个节点安排记录和交接，并将两项工作列入打烊后的收尾事项。","references":[],"evidence":"完成当天的巡查记录，做好工作交接","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7d3e3551e4625a5e":{"review":{"definition":"按西瑞药业材料所述的贮存做法，库管人员应将不同种类的危险废物分类打包、贴签并分区存放。仓库设置警示标志、标识牌和防漏设施。","explanation":"申论第4题中，仓库外有警示标志和标识牌，库内设围堰、收集沟并采取独立防漏措施，可写为贮存管理成效。现场发现两袋危废未贴标签，周围还有散落的废包装物，具体暴露出临时收存环节的贴签和分类包装漏洞，对应入库时落实分类打包、贴签的建议。","references":[],"evidence":"有两袋危险废物没有贴标签，周围还零星散落了一些废包装物。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-9ef25c94314f0b3a":{"review":{"definition":"按2024年考试时适用的规定，产生危险废物的单位应制定危险废物管理计划，报所在地生态环境主管部门备案。产生、收集、贮存、运输、利用、处置危险废物的单位还应制定意外事故防范措施和应急预案，向所在地生态环境主管部门及其他负有固体废物污染环境防治监督管理职责的部门备案。","explanation":"管理计划涵盖减量减害和贮存、利用、处置安排，环境应急预案用于突发环境事件应对。企业环境应急预案一般在签署发布后20个工作日内向所在地县级生态环境主管部门备案。材料4报告西瑞药业已制定计划和预案并备案，还定期演练、组织员工培训，可分别写入谈话提纲的危废管理和应急准备成效。","references":[{"source":"web-500595e3e43719b7","location":"第七十八条、第八十五条","quote":"制定意外事故的防范措施和应急预案"},{"source":"web-f626b5f10086d03b","location":"第三条、第十四条","quote":"向企业所在地县级环境保护主管部门备案"},{"source":"web-9e6f394b54583111","location":"第十五条、第十九条","quote":"定期开展应急演练"}],"evidence":"危险废物管理计划及应急预案制度并备案","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-77cb917c003f45bb":{"review":{"definition":"参考提纲建议西瑞药业按危险废物种类单独建册，完整填写流向、利用处置方式等信息，并及时同步纸质和电子台账。","explanation":"申论第4题中，指导组发现台账未按种类分册，部分流向、利用处置方式漏填，电子版因集中补录而滞后且与纸质版有出入。参考提纲中的分类建册、完整填写、电子版实时更新和定期核查，分别针对这些现场问题，属于本题对该企业的整改建议。","references":[],"evidence":"指导组还发现电子版没有同步更新，与纸质版台账信息也不完全相符。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-674d0d2d425c06f1":{"review":{"definition":"按2024年考试时适用的规定，产生工业固体废物的单位委托他人运输、利用或处置工业固体废物，应核实受托方的主体资格和技术能力，依法签订书面合同并约定污染防治要求。委托经营性收集、贮存、利用或处置危险废物时，受托方须持有相应的危险废物经营许可证，并按许可范围开展活动。","explanation":"西瑞药业核实专业处置单位资质、签订书面合同并约定污染防治要求，可作为谈话提纲中的委托处置成效。材料所报100%安全处理率的统计口径是工业固体废物，提纲应沿用这一口径。","references":[{"source":"web-500595e3e43719b7","location":"第三十七条第一款、第八十条","quote":"对受托方的主体资格和技术能力进行核实"}],"evidence":"对方的资质，依法签订书面合同，约定污染防治要求","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-2a1d4e74a17924ae":{"review":{"definition":"2023年中央金融工作会议提出优化资金供给结构，把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业。","explanation":"第5题A项保留了科技创新、绿色发展，却把先进制造改成传统制造，把中小微企业改成国有企业。题干要求选出表述不准确的一项，因此选A。","references":[],"evidence":"把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d61fdd0dab524e93":{"review":{"definition":"2023年中央金融工作会议提出，要着力营造良好的货币金融环境，切实加强对重大战略、重点领域和薄弱环节的优质金融服务。","explanation":"第5题B项同时写出了营造良好货币金融环境的要求和优质金融服务的三类重点对象，符合会议表述。题干问哪项不准确，因此排除B。","references":[],"evidence":"切实加强对重大战略、重点领域和薄弱环节的优质金融服务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8acbf6b6303159f1":{"review":{"definition":"《促进高质量充分就业》提出，要全面贯彻劳动者自主就业、市场调节就业、政府促进就业和鼓励创业的方针。","explanation":"第7题①保留了劳动者自主就业，却把市场的作用写成“促进”、政府的作用写成“主导”，还漏掉了鼓励创业。方针的原表述是市场调节就业、政府促进就业，因此①错误。","references":[],"evidence":"劳动者自主就业、市场调节就业、政府促进就业和","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-acab1b425de0dd66":{"review":{"definition":"2024年党的二十届三中全会《决定》提出，完善竞争性支持和稳定支持相结合的基础研究投入机制。","explanation":"两类支持在同一投入机制中并行。第9题A项用“取代”改写了两者“相结合”的关系，因此错误。","references":[],"evidence":"完善竞争性支持和稳定支持相结合的基础研究投入机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-38d6947ada30dcd0":{"review":{"definition":"2024年党的二十届三中全会《决定》提出，支持基础研究选题多样化，鼓励开展高风险、高价值基础研究。","explanation":"第9题C项有两处改动，将“鼓励”改成“限制”，将“高价值”改成“高投入”。原文强调的是研究价值，选项写的是投入规模，因此错误。","references":[],"evidence":"支持基础研究选题多样化，鼓励开展高风险、高价值基础研究。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-244bf0f68b87e4f8":{"review":{"definition":"2024年党的二十届三中全会《决定》提出，允许科技人员在科技成果转化收益分配上有更大自主权。","explanation":"政策针对的是科技成果转化收益的分配，第9题D项把扩大科技人员自主权写成了降低自主权，因此错误。","references":[],"evidence":"科技成果转化收益分配上有更大自主权","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-95d21d44769d7d1d":{"review":{"definition":"2024年党的二十届三中全会《决定》提出，提高劳动报酬在初次分配中的比重，完善劳动者工资决定、合理增长和支付保障机制，健全按要素分配政策制度。","explanation":"第10题A项对应劳动报酬的比重要求，B项对应工资机制和按要素分配政策，两项均符合《决定》。本题要求选出不准确的一项，D项把税收、社会保障、转移支付等再分配调节机制误归入第三次分配，因此当选。","references":[],"evidence":"完善劳动者工资决定、合理增长、支付保障机制，健全按要素分配政策制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c040cc3e3167558f":{"review":{"definition":"2024年党的二十届三中全会《决定》将规范财富积累机制、多渠道增加城乡居民财产性收入列为完善收入分配制度的举措。","explanation":"第10题C项同时保留了财富积累机制要“规范”、居民财产性收入要“多渠道增加”两项要求，适用对象为城乡居民。C项表述准确，在选非题中排除。","references":[],"evidence":"规范财富积累机制，多渠道增加城乡居民财产性收入","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-98c070e85dbc4782":{"review":{"definition":"2024年《中共中央关于进一步全面深化改革 推进中国式现代化的决定》第（45）项要求深化以公益性为导向的公立医院改革，完善薪酬制度，建立编制动态调整机制。","explanation":"编制动态调整强调根据实际情况调整编制。C项前半句“完善公立医院薪酬制度”符合部署，后半句“严格限制、缩减编制数量”把动态调整改成了统一的缩减要求，因此是题目所问的不恰当举措。","references":[],"evidence":"完善薪酬制度，建立编制动态调整\n机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7d33e47e15b2fbbf":{"review":{"definition":"依照本题引用的《中国共产党纪律处分条例》第一百条，党员利用职权或者职务上的影响操办婚丧喜庆事宜，造成不良影响的，违反廉洁纪律。借机敛财或者有其他侵犯国家、集体和人民利益行为的，从重或者加重处分。","explanation":"D项用“滥用”描述职权或职务影响的使用，条文原词为“利用”。D项同时写明了操办婚丧喜庆事宜和造成不良影响，符合题引条文的情形。A、B、C分别涉及政治纪律、组织纪律和群众纪律。","references":[],"evidence":"利用职权或者职务上的影响操办婚丧喜庆\n事宜，造成不良影响的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3c04393c3295bdcb":{"review":{"definition":"2024年4月新时代推动西部大开发座谈会提出，西部地区要把发展特色优势产业作为主攻方向，因地制宜发展新兴产业，加快产业转型升级。","explanation":"“主攻方向”对应特色优势产业，“因地制宜”限定了发展新兴产业的方式。A项把两层部署合成“把全面发展新兴产业作为主攻方向”，既换了主攻对象，也删去了因地制宜的要求，因此是本题选非项。","references":[],"evidence":"要坚持把发展特色优势产业作为主攻方向，因地制宜发展新兴产业","disposition":"独立词条","basis":"据原题和解析编释。","title":"新时代西部大开发的产业主攻方向","related":[],"examFocus":{"国考 2025 副省级 行测#20":"核对西部大开发部署中产业转型的主攻方向和新兴产业的发展要求。"}},"readings":[{"origin":"k-3c04393c3295bdcb","title":"新时代西部大开发的产业主攻方向","qs":["国考 2025 行政执法 行测#20"],"definition":"2024年4月新时代推动西部大开发座谈会提出，西部地区要把发展特色优势产业作为主攻方向，因地制宜发展新兴产业，加快产业转型升级。","explanation":"“主攻方向”对应特色优势产业，“因地制宜”限定了发展新兴产业的方式。A项把两层部署合成“把全面发展新兴产业作为主攻方向”，既换了主攻对象，也删去了因地制宜的要求，因此是本题选非项。","evidence":"要坚持把发展特色优势产业作为主攻方向，因地制宜发展新兴产业","doubt":"","references":[]},{"origin":"k-abd16a0c792d3701","title":"新时代西部大开发的产业主攻方向","qs":["国考 2025 地市级 行测#20"],"definition":"2024年新时代推动西部大开发座谈会提出，西部地区要把发展特色优势产业作为主攻方向，因地制宜发展新兴产业，加快产业转型升级。","explanation":"部署把主攻方向落在特色优势产业上，对发展新兴产业提出因地制宜的要求。A项改成把全面发展新兴产业作为主攻方向，同时改动了产业重点和发展条件，因此是本题所选的不正确表述。","evidence":"要坚持把发展特色优势产业作为主攻方向，因地制宜发展新兴产业","doubt":"","references":[]},{"origin":"k-f1ee6653bc2d9ca5","title":"新时代西部大开发的产业主攻方向","qs":["国考 2025 副省级 行测#20"],"definition":"2024年新时代推动西部大开发座谈会提出，西部地区要以发展特色优势产业为主攻方向，因地制宜发展新兴产业，加快产业转型升级。","explanation":"讲话分别明确了产业转型升级的主攻方向和发展新兴产业的条件。A项把主攻方向改成了“全面发展新兴产业”，也丢掉了“因地制宜”的要求。本题问“不正确”，因此选A。","evidence":"要坚持把发展特色优势产业作为主攻方向，因地制宜发展新兴产业","doubt":"","references":[]}]},"k-ced308223a1e18fa":{"review":{"definition":"2024年4月新时代推动西部大开发座谈会提出，西部地区要推进新型城镇化和乡村全面振兴有机结合，在发展中保障和改善民生。","explanation":"这项部署具体包括加大对国家乡村振兴重点帮扶县的支持力度，以及建立低收入人口和欠发达地区常态化帮扶机制。D项同时写出了城镇化与乡村振兴的结合要求和发展中的民生目标，符合座谈会部署。","references":[],"evidence":"要坚持推进新型城镇化和乡村全面振兴有机结合，在发展中保障和改善民生。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0e6617f97f239324":{"review":{"definition":"《中华人民共和国食品安全法》第八十九条第一款规定，食品生产企业可以自行检验所生产的食品，也可以委托符合该法规定的食品检验机构检验。","explanation":"条文给出了企业检验本企业所生产食品的两种方式。A项中的企业已经自行检验，依法可以不再委托机构重复检验。C项所说的监管部门收取检验费涉及监督抽样检验，适用另外的费用规则。","references":[],"evidence":"食品生产企业可以自行对所生产的食品进\n行检验，也可以委托符合本法规定的食品检验机构进行检验。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f3b466eb71f4306f":{"review":{"definition":"《中华人民共和国行政复议法》第五条规定，行政复议机关办理行政复议案件，可以进行调解。调解属于复议机关依法可以采用的处理方式。","explanation":"甲对交警当场作出的处罚决定不服，应当先申请行政复议。进入复议程序后，该案可适用调解，因此D项成立。C项涉及简易程序，适用该程序还需复议机关判断事实是否清楚、权利义务关系是否明确、争议是否较小，单凭处罚系当场作出无法确定。","references":[],"evidence":"行政复议机关办理行政复议案件，可以进行调\n解。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5c9d537cf9679800":{"review":{"definition":"以捏造的事实提起民事诉讼，妨害司法秩序或者严重侵害他人合法权益的，构成虚假诉讼罪。","explanation":"C项中，甲确实欠乙2万元，乙补写欠条并模仿甲的签名，伪造的是证明债务的证据。按题设，乙起诉主张的2万元债务真实存在，欠条造假本身不足以认定乙以捏造的事实提起民事诉讼。因此，断言乙构成虚假诉讼罪的C项是本题选出的错误说法。","references":[],"evidence":"甲欠乙2万元，因欠条遗失，乙补写欠条并模仿甲的签名后向法院起诉","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7b359c13fe41cdea":{"review":{"definition":"无处分权人转让动产或不动产时，除法律另有规定外，受让人在受让时为善意、以合理价格受让，并依法完成登记或交付的，可以取得该财产的所有权。依法应当登记的须完成登记，无须登记的须完成交付。","explanation":"B项中，自行车是卖家借来的，卖家无权处分。乙以市价购买，对应合理价格条件。善意以受让时为判断时点，后来发现车辆是借来的，不影响已经成立的善意取得。如果乙受让时为善意且自行车已经交付，就可取得所有权，这与B项所说的“仍可获得”一致。","references":[],"evidence":"乙以市价购买了一辆自行车，后发现该车是卖家借来的","disposition":"独立词条","basis":"据原题和解析编释。","title":"所有权的善意取得","related":[],"examFocus":{"国考 2025 地市级 行测#23":"判断借来的自行车被转卖时能否善意取得所有权，要结合受让时是否善意、成交价格是否合理以及车辆是否交付。"}},"readings":[{"origin":"k-7b359c13fe41cdea","title":"所有权的善意取得","qs":["国考 2025 行政执法 行测#25"],"definition":"无处分权人转让动产或不动产时，除法律另有规定外，受让人在受让时为善意、以合理价格受让，并依法完成登记或交付的，可以取得该财产的所有权。依法应当登记的须完成登记，无须登记的须完成交付。","explanation":"B项中，自行车是卖家借来的，卖家无权处分。乙以市价购买，对应合理价格条件。善意以受让时为判断时点，后来发现车辆是借来的，不影响已经成立的善意取得。如果乙受让时为善意且自行车已经交付，就可取得所有权，这与B项所说的“仍可获得”一致。","evidence":"乙以市价购买了一辆自行车，后发现该车是卖家借来的","doubt":"","references":[]},{"origin":"k-96af23235485e6c6","title":"所有权的善意取得","qs":["国考 2025 地市级 行测#23"],"definition":"除法律另有规定外，无处分权人转让财产时，受让人受让时为善意、转让价格合理，并依法完成登记或者交付的，可以取得所有权。依法应当登记的须已登记，无须登记的须已交付。","explanation":"B项中，卖家借来的自行车属于无权处分的标的物，市价对应合理价格，买后才发现车辆是借来的对应题目对受让时善意的设定。解析按普通自行车买卖已经完成交付来理解。善意取得仍以交付为条件。","evidence":"乙以市价购买了一辆自行车，后发现该车是卖家借来的","doubt":"","references":[]}]},"k-952cbd5333fa6f4b":{"review":{"definition":"经营者以收取预付款的方式提供商品或者服务，应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方式及违约责任等事项。","explanation":"D项中，健身馆预收3000元，用于购买随后半年的私教服务，适用预付款消费的书面合同要求。题干列出了书面合同约定的服务和费用，D项的做法符合题目考查的要求。若要判断合同条款是否齐备，还需看是否约定预付款退还方式和违约责任等事项。","references":[],"evidence":"丁健身馆与消费者签订书面合同，约定提供为期半年的健身私教课程服务并收取3000元预付款","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1c99905a58c61b41":{"review":{"definition":"采取现场拍卖等公开竞价方式订立合同时，当事人请求确认合同自拍卖师落槌时成立的，人民法院应予支持。合同成立后，当事人拒签成交确认书的，法院应依据拍卖公告、竞买人的报价等确定合同内容。","explanation":"A项中，甲在现场拍卖中竞得艺术品，拍卖师落槌时合同即告成立。甲主张以落槌时作为合同成立时点，人民法院应予支持。","references":[],"evidence":"甲竞买人在现场拍卖中拍得一件艺术品，甲主张合同自拍卖师落槌时成立","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-670231d7685365c0":{"review":{"definition":"举重试举由三名临场裁判按多数意见判定。至少两名裁判亮白灯即判试举成功，至少两名裁判亮红灯即判试举失败。","explanation":"两白一红已经满足成功判定条件。D项把三盏白灯说成试举成功的必要条件，所以是本题所选的错误说法。","references":[],"evidence":"如2白1红或2红1白，那就要少数服从多数","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-243780be74415e1a":{"review":{"definition":"公历平年的二月有28天，闰年的二月有29天。","explanation":"连续28天正好是4周，小张每周跑4次，合计16次。二月跑了17次，说明当年是闰年，且2月29日也跑了。三月后28天跑16次，所以3月1日至3日每天都跑。2月29日至3月3日连跑4天，只能对应周一至周四。3月31日距3月3日正好4周，也是周四，因此4月1日为周五。四月的前28天跑16次，余下两天是周五和周六，合计16次，选A。","references":[],"evidence":"故该年2月应为29天，最后1天（2月29日）再夜跑1次","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-20e96d249dc0741a":{"review":{"definition":"犯罪事实或者犯罪嫌疑人未被司法机关发觉，或虽已被发觉，但嫌疑人就该案尚未受到讯问、未被采取强制措施时，主动、直接向公安机关、人民检察院或者人民法院投案，属于自动投案。司法解释还规定了视为自动投案的情形。","explanation":"按题给定义，乙已被确认为伤害案嫌疑人，经该案讯问才交代，因此选B。酒驾行政拘留期间主动交代尚未被掌握的犯罪，依法仍可能视为自动投案。A项仅因形迹可疑被一般盘问后主动交代，若罪行尚未被发觉，且盘查中未发现与犯罪有关的物品，可以视为自动投案。D项在司法认定中适用服刑人员供述余罪的规则，若丁如实供述司法机关尚未掌握的本人走私罪行，并与原判盗窃罪属不同种罪行，则依法以自首论。题解将D项归入题给定义的做法，适用范围限于本题。","references":[{"source":"web-e0bdd7ce68b42002","location":"第一部分、第三部分","quote":"主动向执行机关交代尚未被掌握的犯罪行为"},{"source":"web-6922d99a0cff2a52","location":"第六十七条第二款","quote":"如实供述司法机关还未掌握的本人其他罪行"}],"evidence":"主动、直接向公安机关、人民检察院或者人民法院投案","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-088422e0d4693192":{"review":{"definition":"中共中央办公厅、国务院办公厅印发的《关于深化职称制度改革的意见》（中办发〔2016〕77号）提出，探索在新兴职业领域增设职称系列。新设系列由中央和国家机关有关部门提出，经人力资源社会保障部审核后报国务院批准，各地区各部门未经批准不得自行设置。","explanation":"材料5将《意见》归于人社部，正式印发主体为两办，人社部承担审核职责。材料中的B市科学传播专业职称让科普从业者的业绩有了相应的评价渠道，体现了题干所说的政府适当引导。文件同时允许在职称系列内按专业领域设置专业类别，材料中的专业职称是说明评价渠道如何拓宽的例子。","references":[{"source":"web-045835301a955279","location":"二、健全职称制度体系，（四）完善职称系列","quote":"探索在新兴职业领域增设职称系列。"}],"evidence":"探索在新兴职业领域增设职称系列","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-4fbb444d8345fc0c":{"review":{"definition":"材料5介绍的职称评价做法是，各地各部门按不同从业群体设置标准，降低学历、资历的权重，突出专业业绩、成果和行业认可度。","explanation":"L省评审专家到合作社现场查看种植、养殖业绩，说明“干什么，评什么”可以落实到对实际工作成果的核验。答题时可用这一案例说明，政府既可拓宽职称申报渠道，也可按从业特点调整评价标准和方式。","references":[],"evidence":"弱化学历、资历等要求，突出人才在专业领域取得的业绩、成果和行业认可度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a538f2c34315f1a4":{"review":{"definition":"材料6中，W市新业态从业人员可以下载并注册“暖心工惠 APP”，在线提交入会申请。成为会员后，可以参加工会定期组织的活动。","explanation":"宣传单需要让网约车司机、快递员、网约送餐员等读者知道去哪里申请、怎样申请。应写明应用名称和“下载、注册、在线申请”的顺序，并把参加会员活动写在成为会员之后。","references":[],"evidence":"您下载并注册‘暖心工惠 APP’，就可以在线申请网上入会","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ba003af392389fee":{"review":{"definition":"材料五所述职称改革提出探索在新兴职业领域增设职称系列。各地各部门可结合不同职业群体的工作特点制定评价标准，突出专业业绩、成果和行业认可度。","explanation":"增设评审类别回应的是申报渠道问题，分类制定标准回应的是如何评价实际贡献的问题。材料五中，B市推出科学传播专业职称，为科普从业者提供了申报渠道。L省评审专家到合作社现场核验业绩，体现了按实际工作表现评价的做法。两例分别支撑参考文章提出的拓宽申报渠道和改进评价标准。","references":[],"evidence":"突出人才在专业领域取得的业绩、成果和行业认可度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1602beb56b6f992a":{"review":{"definition":"河长制是由各级党政负责人担任河长，负责组织领导相应河湖管理保护工作的责任制度。","explanation":"材料从古代地方官员承担治水职责写到现代河长负责河湖管护。梅林村由村支书担任村级河长，日常巡查墩子河。当地通过清淤、连通水系和治理污水，使河道恢复畅流，水质由劣Ⅴ类改善到Ⅲ类，河边也成了村民休闲的场所。本题可概括为落实河长制，畅通河道、改善水质、美化环境。","references":[],"evidence":"清淤泥、连水系、治污水，一套组合拳下来，河畅流、水碧清。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-545922862610262f":{"review":{"definition":"司法机关裁判案件时，应以事实和法律为依据，对处于相同法律地位的当事人平等适用法律，不因私人关系或社会身份而偏袒。","explanation":"B项的“不别亲疏，不殊贵贱”排除了关系和身份上的偏袒，“一断于法”明确了裁断依据，因而最契合现代司法公正理念。A项着眼于重罚的威慑，C项劝人少争讼，D项谈亲属相隐。","references":[],"evidence":"不别亲疏，不殊贵贱，一断于法","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fd640613689ed121":{"review":{"definition":"劳动争议仲裁委员会履行劳动争议仲裁职能时作出的不予受理决定不属于行政行为。当事人仅因不服该决定提起行政诉讼的，不属于行政诉讼受案范围。","explanation":"判断时要看被诉决定的性质。甲所争议的是县劳动争议仲裁委员会对劳动仲裁申请作出的不予受理决定，属于仲裁程序中的处理，因此本题选A。","references":[],"evidence":"其所作出的不予受理的决定也不属于行政行为","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-396e9ba2d849fbb9":{"review":{"definition":"职工未请假提前下班，本身不属于法定的工伤认定排除情形。回家途中发生交通事故的，仍须按上下班途中事故的条件认定。","explanation":"方某因家中有急事，未请假提前半小时离岗。C项应理解为这项违纪事实本身不排除工伤认定。提前半小时离岗后乘公交回家的行程是否处于合理时间、是否走合理路线，以及方某是否负事故主要责任，仍须结合事实判断。","references":[],"evidence":"方某未请假提前下班，不影响其工伤认定","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3674de125424ca25":{"review":{"definition":"市场监管部门可以通过发布提醒告诫书，督促经营者依法明码标价，清楚标示商品价格。","explanation":"投诉反映的是水果未标价或标价不清，消费者直到结账才发现价格较高。D项的提醒告诫直接针对标价行为。是否依法处罚，应根据查明的违法事实和适用规定判断。","references":[],"evidence":"发布高价水果的明码标价提醒告诫书","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1c58a5f09133b187":{"review":{"definition":"市场调节价由经营者依法自主制定。适用市场调节价的经营者仍应履行明码标价义务。","explanation":"题中普通零售水果实行市场调节价。商家未标价或标价不清，市场监管部门可以督促其规范标价。题干没有给出依法对这类水果实行限价的条件，因而C项所提最高售价缺乏依据。","references":[],"evidence":"实行市场调节价，由经营者依照本法自主制定","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-73a34e999c17a3ef":{"review":{"definition":"异地代收代办由异地服务机构代为收件或协助办理，多地联办由相关地区共同完成办理所需的环节。国务院办公厅2022年印发的《关于扩大政务服务“跨省通办”范围进一步提升服务效能的意见》将优化两类服务列入提升协同效率的部署。","explanation":"《意见》把完善全国一体化政务服务平台的办件流转功能与优化两类服务放在同一项部署中。B项直接对应不同地区怎样衔接办理，A项的数据和电子证照互认共享属于服务支撑，C项的范围和领域回答哪些事项可以跨省办理。本题的“最关键”按这一政策部署与选项的对应关系理解。","references":[],"evidence":"推动优化‘跨省通办’事项异地代收代办、多地联办服务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c6ff5c958efa9b30":{"review":{"definition":"《现代汉语词典》（第7版）的同音字按笔画数从少到多排列。笔画数相同时，从第一笔起逐笔比较，首次不同的笔形按横、竖、撇、点、折的顺序排列。","explanation":"解析列明，①腌、②阿、③锕、④呵在本题中均读ā。阿有7画，呵有8画，依次排在前两位。锕和腌均为12画，首笔都是撇，第二笔分别为横和折，横排在折前，所以次序为②④③①，对应B项。","references":[],"evidence":"起笔相同的按第二笔笔形的次序排列，以下类推。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8afb79af6cae9a69":{"review":{"definition":"业主为自用车辆依法在专有车位安装充电桩，属于对车位的合理使用。物业服务人应当提供必要协助，包括按报装要求出具施工同意证明，并配合现场勘查和施工。","explanation":"张某的地下车位归其专有，供电部门已勘查认为可以安装，物业公司应配合提供报装所需证明，D项正确。法院在类似案件中将这类协助纳入物业服务合同的履行范围。施工仍须符合用电、消防等要求，物业盖章是报装环节，题中也没有须另行办理行政审批的事实依据。","references":[{"source":"web-13f6e2b627138384","location":"裁判理由第二点","quote":"仅是安装充电桩的一个环节"},{"source":"web-59da6c70dc332f9b","location":"“物业公司应该配合协助业主”","quote":"亦为物业服务应有之义"}],"evidence":"但告知他需提供物业公司同意施工的证明材料","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-3fbd27075fb44452":{"review":{"definition":"没收违法所得是《行政处罚法》列举的处罚种类。行政机关可以依法没收当事人因违法行为取得的款项或其他收益。","explanation":"D项中，市场监管部门查处直播推销劣质面膜的行为，并没收主播的违法所得，符合这一处罚类型。A项的措施是因迟延缴税征收滞纳金，C项的措施是撤销以虚假投标取得的特许经营权，处理对象分别是迟延履行纳税义务和以不正当手段取得的资格。","references":[],"evidence":"没收某主播在网络直播间推销劣质面膜的违法所得","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c99f0694b104fc82":{"review":{"definition":"用人单位认定劳动者不能胜任工作，应结合适用的岗位要求、劳动合同约定的任务和劳动者的实际完成情况。绩效排名末位本身不足以认定不能胜任工作。","explanation":"末位反映的是相对排名。即使同岗位人员都完成了要求的工作量，仍可能有人排在末位。题干仅给出王某连续两年末位的结果，未给出他未完成岗位任务的事实，因此D项的认定依据不足。","references":[],"evidence":"王某连续两个年度考核为末位","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3d850dbdd60c78aa":{"review":{"definition":"劳动者拒绝调岗这一事实本身不足以成为用人单位单方解除劳动合同的依据。用人单位单方解除劳动合同应满足相应的法定条件。","explanation":"公司先以王某考核末位认定其不能胜任，再因王某拒绝调整岗位而通知解除合同。题干既未提供王某未达到岗位要求的事实，也未说明绩效管理办法的制定和公示情况，因此不足以认定公司有权据此调岗或解除合同。C项直接肯定调岗权，超出了题干能够支持的结论。","references":[],"evidence":"由于王某不接受工作岗位的调整，公司便通知他解除劳动合同","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f69764c84da266b9":{"review":{"definition":"用人单位违法解除或者终止劳动合同，劳动者要求继续履行且合同仍能履行的，用人单位应当继续履行。劳动者不要求继续履行或者合同已经不能继续履行的，用人单位应当按法定经济补偿标准的二倍支付赔偿金。","explanation":"连续两年考核末位只表明王某的相对排名，公司仍须证明其不能胜任工作。题中仅凭末位和拒绝调岗解除合同，缺乏法定依据。所查公开题本网络版的B项同样写作“经济补偿金”，参考答案也列B。B项关于违法解除的判断成立，但金钱救济写错了，依法应为赔偿金。","references":[{"source":"web-322a25ea8bce7f43","location":"第四十八条、第八十七条","quote":"经济补偿标准的二倍"},{"source":"web-8a55d7f2bba5768f","location":"选项B及参考答案栏","quote":"王某有权请求支付经济补偿金"}],"evidence":"公司解除劳动合同违法，王某有权请求支付经济补偿金","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-5b74ce11d21caa7f":{"review":{"definition":"构成阻碍人民警察依法执行职务的治安违法行为，公安机关应当从重处罚。考试时适用的《治安管理处罚法》第五十条第二款规定了这一规则，2026年1月1日起施行的修订法在第六十一条第二款保留了该规则。","explanation":"题中的王某正在处理报警并通知张某返回接受调查，张某随后六次以电话、短信辱骂王某。与题情吻合的山东高院再审案例将反复联系、辱骂正在执行职务的民警认定为阻碍执行职务，并结合行为性质、情节和社会影响认定情节严重，支持行政拘留五日。这是B项从重处罚的依据，单凭拒绝返回现场或辱骂次数不足以完成同样的认定。","references":[{"source":"web-46365f6fcdfaa90b","location":"第五十条第二款","quote":"阻碍人民警察依法执行职务的，从重处罚"},{"source":"web-91703126181ab3ca","location":"第六十一条第二款、第一百四十四条","quote":"本法自2026年1月1日起施行"},{"source":"web-dbb850fc3671a1c5","location":"刘某案“二、审理结果”","quote":"反复拨打正在执行职务民警的手机"}],"evidence":"先后6次打电话和短信辱骂","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-ceb3cf767d4ff48e":{"review":{"definition":"侵害他人人身权益并造成财产损失的，赔偿数额按照被侵权人因此受到的损失或者侵权人因此获得的利益确定。损失和获利均难以确定、当事人协商不成并起诉的，由人民法院根据实际情况确定赔偿数额。","explanation":"刘某盗用谢某的身份信息虚列工资，导致谢某被认定收入超标并停发特困经济补助。题中可以明确识别的财产损失是被停发的补助，因此A项由刘某赔偿成立。刘某少缴的税款涉及税务追缴，虚列的工资也没有实际用工关系作为支付依据。","references":[],"evidence":"应赔偿谢某被停发的特困经济补助","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-59d038c9f0e9a332":{"review":{"definition":"以弹出等形式发布互联网广告，广告主、广告发布者应当显著标明关闭标志，确保用户可以一键关闭。2023年5月1日起施行的《互联网广告管理办法》明确将启动互联网应用程序时展示、发布的开屏广告纳入这一规则。","explanation":"江苏2023年度行测笔试于2022年12月17日举行，当时有效的《互联网广告管理暂行办法》第八条已有互联网弹出广告一键关闭要求。乐视案中，法院认定经互联网下载更新、开机自动播放的广告应在开始播放时即可一键关闭，以保障消费者拒绝观看的选择权。题中15秒广告无关闭功能，类似事实可支持周某的请求有法律依据，因此选非题选C。题干只交代电视开机播放广告，具体适用互联网广告规则仍要看广告的发布方式。","references":[{"source":"web-7efd0ef154b85e16","location":"公布说明、第十条第二款","quote":"开屏广告适用前款规定"},{"source":"web-763fad391eace462","location":"第八条第一款","quote":"在互联网页面以弹出等形式发布的广告"},{"source":"web-2e8cf6526505edbd","location":"智能电视开机广告案，裁判结果","quote":"在开机广告播放的同时提供一键关闭功能"},{"source":"web-cac1ae6cc31d46f4","location":"2022年12月18日报道，正文首段","quote":"12月17日，江苏省2023年度考试录用公务员公共科目笔试举行"}],"evidence":"且未提供开机广告一键关闭功能","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-7d9f316361146e82":{"review":{"definition":"消费者有权自主选择经营者、商品品种或服务方式，也有权决定是否购买商品或接受服务。","explanation":"电视每次开机都会自动播放15秒广告，公司又未提供一键关闭功能，消费者使用电视时难以自主决定是否接受这段广告。因此，A项关于消费者选择权受到不当限制的说法，按本题解析成立，不属于本题要求选出的错误说法。","references":[],"evidence":"在一定程度上限缩了消费者自主选择服务的权利。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e77baa686aac3625":{"review":{"definition":"消费者购买商品或接受服务时，有权获得质量有保障、价格合理、计量正确等公平交易条件，并有权拒绝经营者的强制交易行为。","explanation":"公司销售电视时未显著告知开机必播15秒广告，消费者在作出购买决定前缺少一项会影响日常使用的信息。本题解析以这一销售行为违反诚信原则为由，认定B项关于公平交易权受侵害的说法成立。A项关注的是使用电视时能否自主选择接受广告。","references":[],"evidence":"未在销售时以显著的方式提示或告知消费者","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-43348f1370d6f13c":{"review":{"definition":"依《消费者权益保护法》第四十七条，对侵害众多消费者合法权益的行为，中国消费者协会和在省、自治区、直辖市设立的消费者协会可以向人民法院提起消费民事公益诉讼。","explanation":"题中的开机广告设置随电视销售影响众多消费者，周某的个体诉讼与省级消费者组织代表公共消费利益提起的诉讼可以分别成立。类似案件中，江苏省消费者权益保护委员会依法承接原省消费者协会的公益性职责，已作为原告提起同类诉讼。D项属于正确说法，本题要求选不正确的一项。","references":[{"source":"web-92b6031946f2d189","location":"第四十七条","quote":"对侵害众多消费者合法权益的行为"},{"source":"web-2e8cf6526505edbd","location":"智能电视开机广告案，基本案情","quote":"代替原“江苏省消费者协会”履行"}],"evidence":"J省消费者保护委员会也准备提起消费民事公益诉讼","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-7d17ec664d9eac22":{"review":{"definition":"职工在合理时间、沿合理路线通勤时，受到非本人主要责任的交通事故伤害，且无法定排除情形的，应当认定为工伤。","explanation":"方某乘公交车回家途中受伤，下班途中发生事故并不当然排除工伤认定，所以A项错误。实际认定还需判断提前半小时回家是否属于合理通勤，并查明事故责任。题干未交代责任划分，选出C项并不等于已经认定方某构成工伤。","references":[],"evidence":"在上下班途中，受到非本人主要责任的交通事故","disposition":"独立词条","basis":"据原题和解析编释。","title":"上下班途中交通事故的工伤认定","related":[],"examFocus":{"江苏 2023 A类 行测#11":"判断提前下班回家途中发生的交通事故能否认定为工伤，要看通勤时间和路线是否合理，并核对事故责任。"}},"readings":[{"origin":"k-7d17ec664d9eac22","title":"上下班途中交通事故的工伤认定","qs":["江苏 2023 B类 行测#16"],"definition":"职工在合理时间、沿合理路线通勤时，受到非本人主要责任的交通事故伤害，且无法定排除情形的，应当认定为工伤。","explanation":"方某乘公交车回家途中受伤，下班途中发生事故并不当然排除工伤认定，所以A项错误。实际认定还需判断提前半小时回家是否属于合理通勤，并查明事故责任。题干未交代责任划分，选出C项并不等于已经认定方某构成工伤。","evidence":"在上下班途中，受到非本人主要责任的交通事故","doubt":"","references":[]},{"origin":"k-f38f41e2698f2015","title":"上下班途中交通事故的工伤认定","qs":["江苏 2023 A类 行测#11"],"definition":"职工在合理时间内，沿合理路线往返工作地与住所地、经常居住地或单位宿舍，受到非本人主要责任的交通事故伤害，且无法定排除情形的，应当认定为工伤。","explanation":"方某乘公交回家途中受伤，适用上下班途中交通事故的认定条件，因此A项仅凭事故发生在下班途中便否定工伤，判断有误。题干未交代方某的事故责任，选出C项只能说明未请假提前离岗本身不排除认定。","evidence":"在上下班途中，受到非本人主要责任的交通事故","doubt":"","references":[]}]},"k-38b55c23599b16c1":{"review":{"definition":"未请假提前下班本身不属于法定的工伤认定排除情形。通勤事故仍按合理时间、合理路线和事故责任等条件认定。","explanation":"方某因家中急事提前半小时下班，未履行请假手续。C项所说的“不影响”是指不能仅凭未请假就排除工伤认定。提前离岗的实际时间仍可纳入合理通勤时间的判断，交通事故也须符合非本人主要责任的条件。","references":[],"evidence":"没有请假就提前半小时下班","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a621391c4f93c6c7":{"review":{"definition":"按2019年有效的《行政处罚法》，对情节复杂或者重大违法行为给予较重处罚，由行政机关负责人集体讨论决定。依法举行听证的，负责人应在听证结束后审查听证材料，再集体讨论并作出处罚决定。","explanation":"听证前可以研究拟处罚方案，但听证意见必须进入最终决定程序。与题中5月21日集体讨论、5月30日听证、6月18日作出处罚相吻合的淮安医疗广告案中，终审法院认定，区市场监管局未能证明听证后重新集体讨论即罚款30万元，程序违法，撤销了处罚。题库所列B项与该判决冲突，现有选项没有合乎题意的正确项。","references":[{"source":"web-e8eecec5f03b8474","location":"第三十八条第二款、第四十三条","quote":"听证结束后，行政机关依照本法第三十八条的规定，作出决定"},{"source":"web-db0ff5d5b8fb6520","location":"第五十四条","quote":"当事人陈述和申辩意见或者听证报告"},{"source":"web-cde30711fb270fec","location":"转载判决书，二审法院认为及判决主文","quote":"其听证程序后未经集体讨论决定作出处罚"}],"evidence":"对该公司的违法行为进行集体讨论，决定罚款30万元并举行听证","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-609bd9e660959bb2":{"review":{"definition":"行政机关拟作出较大数额罚款，应当在决定前告知当事人有要求听证的权利。当事人在法定期限内提出要求的，行政机关应当组织听证。","explanation":"2019年4月1日起施行的市场监管听证规则，以对法人或其他组织罚款十万元以上作为告知听证权的一般标准，并允许适用地方的具体规定。拟罚整形公司30万元，市监局应当先告知听证权。按当时规则，当事人可在告知书送达回证上签署意见，也可在收到告知书后三个工作日内提出，逾期未要求视为放弃。A项所设的依职权主动启动缺乏该程序依据，原案中的整形公司实际提出了听证申请。","references":[{"source":"web-e8eecec5f03b8474","location":"第四十二条","quote":"当事人要求听证的，行政机关应当组织听证"},{"source":"web-6a0c07ac6db00b4d","location":"第五条第三项、第七条","quote":"未要求举行听证的，视为放弃此权利"},{"source":"web-cde30711fb270fec","location":"转载判决书，二审法院认为","quote":"收到听证告知书后申请要求听证"}],"evidence":"区市场监管局在整形公司未申请的情况下可以主动组织听证","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-0a1f7ec14373790e":{"review":{"definition":"行政处罚听证由行政机关指定的非本案调查人员主持。当事人认为主持人与本案有直接利害关系的，有权申请回避。","explanation":"范某参与了对整形公司的调查，因而不具备主持本案听证的资格。市场监管局以他熟悉案情为由指定他担任主持人，不符合主持人与调查人员分离的要求，D项错误。","references":[],"evidence":"由行政机关指定的非本案调查人员主持","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-01a2baa634a5f22c":{"review":{"definition":"原题引文：孙某再次违法的情形不适用从重处罚","explanation":"题中2019年3月的查处与2020年4月后再次无证加工相隔超过一年，且“依法查处”没有交代既往行政处罚次数，题干不足以认定触发一年内多次受罚的条款。死亡后果还须结合被处罚的具体安全生产违法行为、情节和因果关系判断。解析援引的《行政处罚法》第四十九条自2021年7月15日起施行，针对违反突发事件应对措施的行为，无法据此排除2020年案发时的其他从重依据。","references":[{"source":"web-0f83148a566a7429","location":"第五十五条第二项、第三项","quote":"一年内因同一违法行为受到两次以上行政处罚的"},{"source":"web-dcca42e9a4dd94f4","location":"第十五条第七项","quote":"违法行为情节恶劣，造成人身死亡"},{"source":"web-68468f9a128751eb","location":"第四十九条、第八十六条","quote":"本法自2021年7月15日起施行"}],"evidence":"孙某再次违法的情形不适用从重处罚","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-3efa32ed689d9abc":{"review":{"definition":"在城镇房屋租赁纠纷中，出租未取得建设工程规划许可证或未按许可证规定建设的房屋，租赁合同无效。一审法庭辩论终结前取得该许可证或经主管部门批准建设的，法院应认定合同有效。","explanation":"第18题解析将题称的违建厂房按规划许可有欠缺的房屋处理，题干也未交代补证或获批。双方约定有人举报就退房退租，只安排了举报后的处理，因此A项关于协议合法有效的说法不能成立。","references":[],"evidence":"题中，厂房是违建，该租赁协议无效。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-500c1a1127469d33":{"review":{"definition":"原题引文：沈某将违建厂房出租给孙某","explanation":"沈某有偿出租违建厂房供孙某加工，并约定被举报时退房退租，应结合这些实际经营事实判断其主体身份。《人民法院报》对类似案情的评析主张，明知厂房用于生产经营而有偿出租的自然人可纳入安全生产法上的生产经营单位。该评析使B项的排除性判断缺乏依据，也提示当时《安全生产法》第一百条的连带责任可能适用，仍须查明出租行为与事故损害的法律因果关系。","references":[{"source":"web-0f83148a566a7429","location":"公布说明、第二条、第六十八条","quote":"本办法所称的生产经营单位"},{"source":"web-ca82f6983865dad4","location":"评析第二点","quote":"安全生产法的适用对象“生产经营单位”应包含自然人"},{"source":"web-09971d56c6984e1f","location":"第一百条第一款","quote":"与承包方、承租方承担连带赔偿责任"}],"evidence":"沈某将违建厂房出租给孙某","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-c9d576001babc4b6":{"review":{"definition":"原题引文：区自然资源和规划局无权作出限期拆除的决定","explanation":"第19题为选非题，给定答案选B，意在考查规划主管部门依法可以作出限期拆除决定。重庆原案的公开案情记载，涉案对象是未经规划许可的一层砖混结构房及砖混结构平台，未交代其是否属于临时建设。第六十六条有明确的适用范围，本题解析援引该条的事实依据仍待核。原案发生时的重庆市规章将规划城镇建设用地范围内的违建交由城乡规划主管部门组织查处，并对综合执法另有规定。","references":[{"source":"web-804c3171bbc45bdd","location":"第六十四条、第六十六条","quote":"无法采取改正措施消除影响的，限期拆除"},{"source":"web-ca9b9099e1bc5860","location":"第四条、第十二条第二项","quote":"负有查处职责的行政主管部门依法作出限期拆除或者回填决定"},{"source":"web-8f9d20696d66dd54","location":"案情，2019年9月公告","quote":"砖混结构平台未经规划许可"}],"evidence":"区自然资源和规划局无权作出限期拆除的决定","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-fd7c22a85765faa6":{"review":{"definition":"原题引文：区政府作出批复，同意对上述违法建筑实施强制拆除","explanation":"第19题的C项对应区政府依法作出强拆决定、责成街道办牵头实施的权限。题干和原案公开案情均载明规资局认定违建以及区政府随后批复强拆。认定违建的公告只交代了建筑性质，适用第六十八条还须核实是否已有法定前置决定及当事人是否未履行。原案裁定处理的是陈某诉请街道办履行批复能否受理。","references":[{"source":"web-804c3171bbc45bdd","location":"第六十八条","quote":"当事人不停止建设或者逾期不拆除的"},{"source":"web-8f9d20696d66dd54","location":"案情，2019年10月批复","quote":"同意对上述违法建、构筑物实施强制拆除"}],"evidence":"区政府作出批复，同意对上述违法建筑实施强制拆除","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-9b47841113e622e6":{"review":{"definition":"行政行为的相对人，以及其他与被诉行政行为有利害关系的公民、法人或其他组织，有权提起行政诉讼。被诉行为涉及其相邻权，或者其为维护自身合法权益投诉而有处理职责的机关作出或未作出处理，均可构成利害关系。","explanation":"第19题中，陈某起诉所针对的是街道办未执行区政府的强拆批复。原案法院以该诉请不属于行政诉讼受案范围、陈某不具有原告资格为由裁定驳回。法院供稿的案例评析指出，街道办按批复履行上级命令的行为缺少独立的法律效果，陈某作为小区居民多次反映违建的事实，不能据此取得这项诉请的原告资格。若另行针对涉及自身相邻权的行政行为，或针对有处理职责机关对权益投诉的处理起诉，须就相应被诉行为判断利害关系。","references":[{"source":"web-e498a67eed717441","location":"第二十五条第一款","quote":"行政行为的相对人以及其他与行政行为有利害关系的公民"},{"source":"web-47f9e3dd8cd81c8c","location":"第十二条第一项、第五项","quote":"被诉的行政行为涉及其相邻权或者公平竞争权的"},{"source":"web-8f9d20696d66dd54","location":"裁判、评析第三部分","quote":"且陈某强不具有原告资格"}],"evidence":"陈某认为，街道办未执行区政府的批复，遂提起诉讼。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-497528c798c6df08":{"review":{"definition":"冒用他人身份致使结婚登记对象错误，构成重大且明显违法的，人民法院依法判决确认登记行为无效。错误登记信息持续损害被冒名人权益的，法院可以同时判令登记机关采取删除错误信息等补救措施。","explanation":"第20题中，实际到场登记的是梁某，陈某的身份却被记入登记系统，导致陈某本人无法办理结婚登记。先前的离婚判决并未撤销原结婚登记，法院仍可在行政诉讼中审查该登记行为。南通开发区法院尚某案也有先前的离婚判决。该案主文确认登记无效，并依《行政诉讼法》第七十六条责令如东县民政局在判决生效后六十日内删除错误登记信息。D项中的删除应理解为法院判令登记机关实施的个案补救。","references":[{"source":"web-6e4b58470db61c7f","location":"裁判理由第二、四部分及判决主文第二、三项","quote":"对原告尚某的错误婚姻登记信息采取删除的补救措施"},{"source":"web-e498a67eed717441","location":"第七十五条、第七十六条","quote":"可以同时判决责令被告采取补救措施"},{"source":"web-47f9e3dd8cd81c8c","location":"第九十九条第三项","quote":"行政行为的内容客观上不可能实施"}],"evidence":"法院应判决确认M县民政局的登记无效并删除错误登记信息","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-30eca166ea9db212":{"review":{"definition":"按第20题援引的《婚姻登记条例》第七条，婚姻登记机关应当审查结婚登记当事人出具的证件、证明材料，并询问相关情况。符合结婚条件的，应当当场予以登记并发给结婚证。","explanation":"梁某持拾得的陈某身份证到场，登记却记在陈某名下。本题解析据此认定M县民政局对当事人和材料审核把关不严，排除A项。证件记载的身份与到场申请人能否对应，是本案审查的具体问题。","references":[],"evidence":"婚姻登记机关应当对结婚登记当事人出具的证件、证明材料进行审查","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8b347cf869091e8f":{"review":{"definition":"离婚判决处理婚姻关系的解除。婚姻登记因冒名而存在身份错误时，登记行政行为的效力及记录纠正仍须依法处理。","explanation":"第20题中，M县法院曾判决林某与登记所载的“陈某”离婚，但N县民政局随后仍根据错误记录拒绝为陈某办理结婚登记。先前判决没有撤销冒名形成的登记，因而B项所称的撤销效力不能成立。","references":[],"evidence":"法院判决“陈某”与林某离婚，并不会产生撤销婚姻登记的效力。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-02cb88bbfd3b2402":{"review":{"definition":"《民法典》第一千零五十一条规定，重婚、有禁止结婚的亲属关系、未到法定婚龄的，婚姻无效。以这三种情形之外的理由请求确认婚姻无效的，人民法院应判决驳回该诉讼请求。","explanation":"第20题给出的瑕疵是梁某冒用陈某身份办理登记，题干未给出上述三种情形中的任何一种。C项以所谓虚假结婚请求确认婚姻关系无效，缺少该条所要求的法定事由。本题争议落在M县民政局登记行政行为的效力上。","references":[],"evidence":"（一）重婚；（二）有禁止结婚的亲属关系；（三）未到法定婚龄。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-218399a48e56694e":{"review":{"definition":"中央科技委员会是党中央决策议事协调机构，负责研究审议国家科技发展的重大战略、规划和政策，统筹推进国家创新体系建设和科技体制改革。","explanation":"《党和国家机构改革方案》明确将中央科技委员会定位为党中央决策议事协调机构。研究审议科技重大战略、统筹解决科技领域全局性重大问题是其职责，因此第3题D项的机构性质对应正确。","references":[],"evidence":"中央科技委员会——党中央决策议事协调机构","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b6f5fd5883f17c56":{"review":{"definition":"中央金融工作委员会是党中央派出机关，统一领导金融系统党的工作，并与中央金融委员会办公室合署办公。","explanation":"合署办公是办公安排，中央金融工作委员会的机构性质由《党和国家机构改革方案》明确为党中央派出机关。第3题A项将其配为党中央办事机构，配对错误。","references":[],"evidence":"故中央金融工作委员会为党中央派出机关。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c61b94b64f6312e0":{"review":{"definition":"中央社会工作部是党中央职能部门，承担统筹指导人民信访工作、统筹推进党建引领基层治理和基层政权建设等职责。","explanation":"《党和国家机构改革方案》在列明信访、基层治理和有关领域党建等职责后，明确将中央社会工作部定位为党中央职能部门。第3题B项将其配为党中央派出机关，配对错误。","references":[],"evidence":"作为党中央职能部门。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7261384104d026cb":{"review":{"definition":"中央港澳工作办公室是党中央办事机构，在国务院港澳事务办公室基础上组建，保留国务院港澳事务办公室牌子。","explanation":"该办公室承担贯彻“一国两制”方针等方面的调查研究、统筹协调和督促落实职责。《党和国家机构改革方案》明确其为党中央办事机构，因此第3题C项所列的党中央职能部门配对错误。","references":[],"evidence":"故中央港澳工作办公室为党中央办事机构。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f02cd63c32b2f64f":{"review":{"definition":"2023年中央金融工作会议提出，加快建设金融强国要全面加强金融监管、完善金融体制、优化金融服务、防范化解风险。","explanation":"会议将加强监管与完善金融体制、防范化解风险一并部署。第4题③的“需要更完善的金融监管体系”是对这一部署的概括，因此③应选。","references":[],"evidence":"全面加强\n金融监管，完善金融体制，优化金融服务，防范化解风险","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a75e13cbb8fce7c3":{"review":{"definition":"国际贸易单一窗口是贸易经营者通过统一入口提交办理进出口业务所需的信息和单证、相关部门按职责处理并反馈结果的机制。","explanation":"统一入口可减少向不同部门重复申报。2023年自贸试验区建设十周年新闻发布会将率先建立以国际贸易单一窗口为核心的贸易便利化模式列为创新成果，第5题C项符合这一总结，在选非题中应排除。","references":[],"evidence":"建立以国际贸易“单一窗口”为核心的贸易便利化模式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-82e86c5a22e9f730":{"review":{"definition":"《公务员法》第五十九条第十六项禁止公务员违反有关规定从事或者参与营利性活动，并将公务员在企业或者其他营利性组织中兼任职务列入禁止行为。","explanation":"原条文把“违反有关规定”放在“从事或者参与营利性活动”之前，题干省略了这一限定。D项中熊某主动出资设立以营利为目的的有限责任公司，小股东身份不改变其参与设立的性质。A项的工商联属于人民团体和商会组织，B项的个人证券交易须按相关投资规定判断，C项涉及处置依法继承的股权，三者均有别于D项所述行为。","references":[{"source":"web-b861e36828705722","location":"第五十九条第十六项","quote":"违反有关规定从事或者参与营利性活动，在企业或者其他营利性组织中兼任职务"}],"evidence":"税务人员熊某作为小股东出资设立有限责任公司","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-dd4d19ee3e0e4c2d":{"review":{"definition":"按题解所引规定，党政机关工作人员个人可以按规定买卖股票和证券投资基金，具体交易仍受适用的投资限制约束。","explanation":"B项只写法官赵某开设证券账户并买卖公司股票。标准解析按普通个人证券投资处理，题干未交代触发交易限制的事实，因此未选B项。","references":[],"evidence":"党政机关工作人员个人可以买卖股票和证券投资基金","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8b8c975a7be40751":{"review":{"definition":"依法继承取得股权的人可以依法处分该股权，转让时应遵守适用的股权转让规则。","explanation":"C项的张某转让的是继承取得的既有股权，解析按一次财产处分处理。D项的熊某以出资人身份参与设立公司，属于本题认定的参与营利性活动。C项的判断限于题述这次转让。","references":[],"evidence":"警察张某转让继承取得的某有限责任公司股权","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-032e611a75e3d09a":{"review":{"definition":"因保护他人民事权益而受损的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任时，受损者请求补偿的，受益人应当给予适当补偿。","explanation":"王某失控翻车，李某赶去救助时自行摔伤。题干未交代有人侵害李某的权益，参考答案按无侵权人的情形选A。A项省略了李某提出补偿请求这一条件，完整结论是李某提出请求后，受益人王某应当适当补偿。李某施救时造成王某面部受伤属于另一问题，适用自愿紧急救助的免责规则。","references":[{"source":"web-bd7415d8b4007136","location":"第一百八十三条、第一百八十四条","quote":"受害人请求补偿的，受益人应当给予适当补偿"}],"evidence":"请求补偿的，受益人应当给予适当补偿。","disposition":"独立词条","basis":"据原题与所列资料编释。","title":"保护他人民事权益受损时的受益人补偿","related":[],"examFocus":{"江苏 2024 A类 行测#8":"区分救助途中施救人受伤、施救时受助人受伤和在值班期间参与救助三种情况，分别判断适用的法律规则。"}},"readings":[{"origin":"k-032e611a75e3d09a","title":"保护他人民事权益受损时的受益人补偿","qs":["江苏 2024 A类 行测#8"],"definition":"因保护他人民事权益而受损的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任时，受损者请求补偿的，受益人应当给予适当补偿。","explanation":"王某失控翻车，李某赶去救助时自行摔伤。题干未交代有人侵害李某的权益，参考答案按无侵权人的情形选A。A项省略了李某提出补偿请求这一条件，完整结论是李某提出请求后，受益人王某应当适当补偿。李某施救时造成王某面部受伤属于另一问题，适用自愿紧急救助的免责规则。","evidence":"请求补偿的，受益人应当给予适当补偿。","doubt":"","references":[{"source":"web-bd7415d8b4007136","location":"第一百八十三条、第一百八十四条","quote":"受害人请求补偿的，受益人应当给予适当补偿"}]},{"origin":"k-349991e34929c682","title":"保护他人民事权益受损时的受益人补偿","qs":["江苏 2024 B类 行测#12"],"definition":"因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任时，受害人请求补偿的，受益人应当给予适当补偿。","explanation":"李某赶去救助翻车的王某时自行摔伤，题干未交代有侵权人。按本题情形，李某提出补偿请求后，受益人王某应给予适当补偿，因此A项成立。施救时另行造成王某面部受伤，并不使李某因救助受伤而享有的补偿请求权消失。","evidence":"受益人应当给予适当补偿","doubt":"","references":[]}]},"k-76aabecfae4a7acb":{"review":{"definition":"自愿实施紧急救助，因该救助行为造成受助人损害的，救助人不承担民事责任。","explanation":"李某看到王某翻车后立即前往救助，王某的面部伤害发生在紧急施救中。按题解所引《民法典》第一百八十四条，题中的施救方法不当并不使李某承担B项所称的损害赔偿责任。李某自己摔伤后的补偿适用另一条规则。","references":[],"evidence":"因自愿实施紧急救助行为造成受助人损害的","disposition":"独立词条","basis":"据原题和解析编释。","title":"自愿紧急救助的民事免责","related":[],"examFocus":{"江苏 2024 A类 行测#8":"区分紧急救助中施救者自身受伤与受助者受伤涉及的民事规则，并核对视同工伤的条件。"}},"readings":[{"origin":"k-76aabecfae4a7acb","title":"自愿紧急救助的民事免责","qs":["江苏 2024 A类 行测#8"],"definition":"自愿实施紧急救助，因该救助行为造成受助人损害的，救助人不承担民事责任。","explanation":"李某看到王某翻车后立即前往救助，王某的面部伤害发生在紧急施救中。按题解所引《民法典》第一百八十四条，题中的施救方法不当并不使李某承担B项所称的损害赔偿责任。李某自己摔伤后的补偿适用另一条规则。","evidence":"因自愿实施紧急救助行为造成受助人损害的","doubt":"","references":[]},{"origin":"k-89dae5e66ebdefa6","title":"自愿紧急救助的民事免责","qs":["江苏 2024 B类 行测#12"],"definition":"自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任。","explanation":"王某失控翻车后，李某主动施救，王某的面部损伤发生在这次紧急救助中。B项以李某施救方法不当为由主张损害赔偿，与本题适用的紧急救助免责规则不符。","evidence":"因自愿实施紧急救助行为造成受助人损害的","doubt":"","references":[]}]},"k-67007d1bb4a28f68":{"review":{"definition":"原题引文：李某的救助属于维护公共利益，其受伤应视同工伤","explanation":"最高人民法院指导案例94号确认，职工为制止违法犯罪行为受伤可以适用该条。南阳市中级人民法院也曾认定，下班后舍身救助一名溺水同事的职工应视同工伤，可见救助对象只有一人也可能符合条件。本题D项直接把李某值班时赶去救助翻车的王某定性为维护公共利益，参考答案排除D。能否适用该条仍须结合施救活动的性质及有关认定判断。","references":[{"source":"web-c6bb16c71c2c403b","location":"裁判要点","quote":"为制止违法犯罪行为而受到伤害的"},{"source":"web-78cfa73a3e610d5b","location":"正文首段，南阳市中级人民法院网站转载","quote":"认定李东应视同工伤"}],"evidence":"李某的救助属于维护公共利益，其受伤应视同工伤","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-15740b31266d40d6":{"review":{"definition":"2023年7月，国家网信办等七部门联合公布《生成式人工智能服务管理暂行办法》，规范利用生成式人工智能技术提供文本、图片、音频、视频等内容生成的服务。办法鼓励创新应用，并兼顾个人合法权益、公共利益和国家安全。","explanation":"B项对应题干所说的“内容生成能力”，即办法将具备这类能力的模型及相关技术的服务应用纳入专门治理。材料同时提出鼓励各行业、各领域创新和探索优化应用场景，因此不能推出A项所说的对应用场景实施统一管理。C项涉及利用个人信息进行自动化决策时的不合理差别待遇，解析将其对应到《个人信息保护法》。D项所说的应用处于起步阶段，也无法由文件名称中的“暂行”推出。","references":[],"evidence":"具有文本图片、音频、视频等内容生成能力的模型及相关技术的服务应用加以规范","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e85b8e4f09210b45":{"review":{"definition":"根据2023年《中华老字号示范创建管理办法》，商务部会同相关部门原则上每3年复核一次。品牌经复核已不符合条件的，由商务部商相关部门作出移出名录、收回标识使用权及牌匾的决定。","explanation":"移出名录直接影响品牌的中华老字号资格、标识使用权和牌匾。企业具备相应经营条件时仍可依法经营，因此本题参考答案将A项的“将退出市场”判错。C项可理解为通过复核本身不会扩大经营范围。第二十一条未设复核后不得扩大经营范围的特别限制，企业依法变更经营范围适用一般登记和许可规则。","references":[{"source":"web-1c0bb2999fb1767b","location":"第二十一条","quote":"移出中华老字号名录、收回中华老字号标识使用权及牌匾"},{"source":"web-d5f68264658c3746","location":"《国务院公报》2021年第25号，第十四条","quote":"市场主体的经营范围包括一般经营项目和许可经营项目"}],"evidence":"其仍然可以继续经营，只是不能再使用中华老字号标识。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-241096d44c94b16b":{"review":{"definition":"公共场所设置控烟标识时，应结合人员的行为习惯和平均视高，将标识设在易于看见的显著位置。控烟标识包括禁烟标识、室外吸烟点标识及引导标识。","explanation":"人员进入场所后能否顺着通常的行走路线和视线及时看到标识，决定了标识能否起到提示或引导作用，C项符合这一要求。禁烟场所设置禁烟标识，允许设置室外吸烟点的区域可用引导标识，具体标识随场所功能而定。","references":[],"evidence":"设置控烟标识要符合人们的行为习惯和平均视高","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a100248ad008d20a":{"review":{"definition":"帝王讳名制是古代避讳制度的一种。在规则适用的场合，用字者须避用帝王的名讳，可通过改用其他字来避讳。","explanation":"学者以帛书《道德经》保留刘恒名中的“恒”字，而传世本写作“常”为线索，推测帛书早于刘恒在位时期。D项以秦代避讳已扩至社会、汉朝继承秦制为依据，增强了避讳可能适用于当时文本的判断。两句同义只说明换字后文义可以相同，保留“恒”也只能为断代提供间接支持。","references":[],"evidence":"帝王讳名制在秦朝从宗族内部扩展到社会整体，汉朝继承了秦朝的许多制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-discretion":{"review":{"definition":"行政处罚裁量权是行政机关在法定职权范围内，根据案件具体情节和适用规则，在法定处罚幅度内选择适当处罚的权力。","explanation":"本题的“如意棒”比喻依法选择处罚尺度的空间。老韩无证载客案中，经办人因私人芥蒂有意加重处罚，执法部门复查后将罚款从3.2万元改为1万元。这个事例说明，处罚轻重应由案情和适用规则支撑。","references":[],"evidence":"基于法理或事理做出行政处罚，可在法定处罚幅度内进行选择","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-41bfad2f653bf196":{"review":{"definition":"行政裁量权基准制度通过细化、量化有裁量空间的执法规定，明确可适用的执法尺度和标准。材料中的G省交通运输部门将具体标准向社会公布，接受监督和评议。","explanation":"材料5指出，处罚幅度过宽、严重情节缺少判断指引，会使不同执法人员掌握的尺度不一。具体基准为执法人员判断情节和选择处罚幅度提供共同依据，公开标准让公众可以对照实际处罚进行评议。这是题中“紧箍咒”的具体体现。","references":[],"evidence":"颁行了具体执法尺度和标准，已向社会公布","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-eee37a50a884d0c9":{"review":{"definition":"直播带货经营者不得销售假冒他人注册商标的商品。","explanation":"材料6案例1中，B服装有限公司以远低于正品的价格销售假冒品牌服装，执法人员现场查获侵权服装59件。超低价是案例情节，所售服装系假冒商品才是倡议提出禁售要求的依据。材料对该案的刑事表述是涉嫌犯罪。","references":[],"evidence":"当事人已涉嫌构成“销售假冒注册商标的商品”罪。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-333aae4942c75eba":{"review":{"definition":"直播带货经营者应当如实介绍商品功效，不得通过口播、画面或文字宣称商品具有实际不具备的功效。","explanation":"材料6案例2中，C护肤品有限公司在直播间背景标示“专研抗老”，但涉案化妆品均无抗老功能。倡议可据此要求从业者如实宣传商品功效，并将直播背景中的文字纳入自查。","references":[],"evidence":"上述化妆品均无抗老功能，当事人存在虚假宣传的违法行为。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-edfc70a269219bb1":{"review":{"definition":"经营者不得以虚假折价或虚假的价格比较诱骗消费者交易。","explanation":"材料6案例3中，两家公司事先商定在不同平台为同款商品设置相差悬殊的标价，再由主播把另一平台的展示价用作比较价格，让消费者误以为直播间优惠幅度很大。材料据此认定两家公司共同实施价格欺诈，倡议可明确要求从业者抵制串通制造虚假价差的行为。","references":[],"evidence":"两公司商定在不同平台上架同一商品，并标示相差悬殊的价格，供直播带货比价使用。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e5ac925f40d05e01":{"review":{"definition":"直播带货经营者不得以虚假的库存、赠品余量或让利信息诱导消费者下单。","explanation":"材料6案例4中，主播以“大礼包还剩最后几单现货”等说法虚报赠品余量，制造即将送完的紧迫感，同时传递亏本让利的虚假信息。倡议可以点明这两类做法，要求从业者如实说明赠品供应和优惠情况。","references":[],"evidence":"在直播间内传递赠品“大礼包”所剩不多的不实信息，诱导消费者下单购买。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bf5526af1106c324":{"review":{"definition":"D市市场监管局倡议直播从业者加强自律，防止未成年人和医疗机构工作人员违规参与网络直播带货。","explanation":"材料6的监管通报点明了这两类人员违规参与的问题，参考答案将其写入“加强从业自律”。本题可沿用通报中的“违规参与”表述，具体违规情形和适用条件由相应规则确定，材料未展开。","references":[],"evidence":"未成年人和医疗机构工作人员违规参与网络直播带货","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2ddc78d6a2af0525":{"review":{"definition":"直播带货从业者不得在商品或服务宣传中附加虚假的明星信息。","explanation":"商品或服务附有虚假的明星信息，可能使消费者误以为两者存在真实关联。材料6将这一做法列入监管通报，参考答案据此把它写入“加强从业自律”，使倡议具体对应D市发现的问题。","references":[],"evidence":"直播带货时对商品或服务附加虚假的\n明星信息","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b8e6638c761bd284":{"review":{"definition":"D市市场监管部门表示，将加强直播营销相关法规政策宣传，对屡次出现问题的经营主体督促整改，对明显违法违规或损害消费者权益的行为依法严厉处罚。","explanation":"材料6中，曹局长将法规宣传用于引导经营规范和从业自律，将约谈、责令改正等措施用于督促屡次出现问题的经营主体整改，并说明了依法严厉处罚的情形。这些措施用于倡议书结尾，体现发文机关将承担的监管工作。","references":[],"evidence":"通过约谈、责令改正等方式督促其整改落实","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-474c2a24e94c18b1":{"review":{"definition":"公众发现网络直播营销中的违法线索，可以向市场监管部门反映，也可以拨打12315举报。","explanation":"材料6中，D市市场监管局曹局长明确欢迎网民和社会各界提供违法线索，并列出市各级市场监管部门和12315两个渠道。倡议书结尾可以写明这两个渠道，使鼓励社会监督的呼吁具体可行。","references":[],"evidence":"可以向市各级市场监管部门反映或拨打12315进行举\n报。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b4fe49dfe6abf923":{"review":{"definition":"原题引文：在持续评估和有效管控风险的基础上","explanation":"本题参考答案将①“促进金融保险业的全面开放”列为正确项。同期文件明确支持将保险业纳入开放范围，也强调稳妥推进和健全安全保障机制。题解所举的有序放宽证券业股比限制、稳妥推进银行业开放，可以说明分领域扩大开放，对①中“全面”所指的范围仍需核对。","references":[{"source":"web-5683460e7c2a818a","location":"第四十章第一节","quote":"稳妥推进银行、证券、保险、基金、期货等金融领域开放"},{"source":"web-12f5279a55922f7e","location":"建设更高水平开放型经济新体制相关段落","quote":"着力提升开放监管能力和水平"}],"evidence":"在持续评估和有效管控风险的基础上","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-c41f0c9842014509":{"review":{"definition":"《“十四五”对外贸易高质量发展规划》提出，我国应积极参与国际经贸规则制定，支持多边贸易体制，维护世界贸易组织基本原则，并参与相关议题的谈判和讨论。","explanation":"解析列举渔业补贴、电子商务和服务贸易国内规制等议题，说明我国通过参与国际谈判和讨论推动规则制定。②所说的积极参与国际贸易规则制定，对应规划中的这项任务。","references":[],"evidence":"积极参与国际经贸规则制定","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-92052a1e0611bc45":{"review":{"definition":"政府应当坚持市场化、法治化、国际化原则优化营商环境，完善法治保障和政务服务，便利市场主体投资兴业。","explanation":"二十届中央深改委第二次会议把全面优化营商环境、完善服务保障体系列为建设开放型经济新体制的举措，支持本题③的方向。国务院条例把市场化、法治化、国际化列为原则，把跨境贸易便利化落实到简化通关等措施。海南自贸港建设的地方行动计划则直接把法治化、国际化、便利化同时用于描述营商环境，③可按这一有政策实例的举措理解。","references":[{"source":"web-12f5279a55922f7e","location":"建设更高水平开放型经济新体制相关段落","quote":"全面优化营商环境，完善服务保障体系"},{"source":"web-8c0843154f49006b","location":"第四条、第四十五条","quote":"促进跨境贸易便利化"},{"source":"web-3b9e64a0cdbc3943","location":"行动计划导语","quote":"法治化、国际化、便利化营商环境"}],"evidence":"营造国际化法治化便利化营商环境","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-1913a5c2d7b7d1a9":{"review":{"definition":"2023年中央金融工作会议强调，做好金融工作必须坚持和加强党的全面领导，深刻把握金融工作的政治性、人民性。","explanation":"党的全面领导体现了会议对金融工作政治方向的要求。人民性体现为金融工作要服务经济社会发展和人民需要。题中①用“突出”概括这两项属性，会议在解析所引表述中使用的是“深刻把握”，因此①入选。","references":[],"evidence":"要突出政治性、人民性","disposition":"独立词条","basis":"据原题和解析编释。","title":"金融工作的政治性、人民性","related":[],"examFocus":{"江苏 2024 A类 行测#4":"对照中央金融工作会议的部署，辨析金融工作的基本属性、对外开放要求以及监管和市场体系的建设要求。"}},"readings":[{"origin":"k-1913a5c2d7b7d1a9","title":"金融工作的政治性、人民性","qs":["江苏 2024 B类 行测#4"],"definition":"2023年中央金融工作会议强调，做好金融工作必须坚持和加强党的全面领导，深刻把握金融工作的政治性、人民性。","explanation":"党的全面领导体现了会议对金融工作政治方向的要求。人民性体现为金融工作要服务经济社会发展和人民需要。题中①用“突出”概括这两项属性，会议在解析所引表述中使用的是“深刻把握”，因此①入选。","evidence":"要突出政治性、人民性","doubt":"","references":[]},{"origin":"k-809b126f7131150e","title":"金融工作的政治性、人民性","qs":["江苏 2024 A类 行测#4"],"definition":"2023年中央金融工作会议要求，做好金融工作必须坚持和加强党的全面领导，深刻把握金融工作的政治性、人民性。","explanation":"会议把深刻把握政治性、人民性作为做好当前和今后一个时期金融工作的要求，第4题①用“要突出政治性、人民性”概括了这一要求，因此①应选。","evidence":"要突出政治性、人民性","doubt":"","references":[]}]},"k-f98256692c6a157f":{"review":{"definition":"2023年中央金融工作会议提出，要全面加强金融监管、完善金融体制，同时优化金融服务、防范化解风险。","explanation":"加强监管是会议为防范化解金融风险提出的要求之一。题中③以“需要更完善的金融监管体系”概括这一要求，因此入选。②提出的“加快国际金融一体化进程”未列入题解所引的会议要求。","references":[],"evidence":"全面加强\n金融监管，完善金融体制，优化金融服务，防范化解风险","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3fc2092b18c8a8af":{"review":{"definition":"2023年中央金融工作会议提出，要着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道。","explanation":"会议将金融机构和市场体系建设与金融服务实体经济相联系。题中④直接对应这一建设要求，与①的工作属性、③的监管要求一同构成正确组合。","references":[],"evidence":"要着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道","disposition":"独立词条","basis":"据原题和解析编释。","title":"现代金融机构和市场体系建设","related":[],"examFocus":{"江苏 2024 A类 行测#4":"对照中央金融工作会议的部署，逐条核对金融工作的属性、开放取向、监管和机构市场体系建设要求。"}},"readings":[{"origin":"k-3fc2092b18c8a8af","title":"现代金融机构和市场体系建设","qs":["江苏 2024 B类 行测#4"],"definition":"2023年中央金融工作会议提出，要着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道。","explanation":"会议将金融机构和市场体系建设与金融服务实体经济相联系。题中④直接对应这一建设要求，与①的工作属性、③的监管要求一同构成正确组合。","evidence":"要着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道","doubt":"","references":[]},{"origin":"k-87c744345cd96ff6","title":"现代金融机构和市场体系建设","qs":["江苏 2024 A类 行测#4"],"definition":"2023年中央金融工作会议提出，要着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道。","explanation":"会议将机构和市场体系建设与金融服务实体经济相联系。第4题④直接对应这项部署，因此④应选。题目②所说的加快国际金融一体化进程未列入此次会议的相关部署。","evidence":"要着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道。","doubt":"","references":[]}]},"k-9738a804f4964fab":{"review":{"definition":"对外商投资，在投资准入阶段实行国民待遇和负面清单管理。清单列明外资准入的特别管理措施，清单之外在准入阶段给予外商投资者及其投资不低于境内投资者及其投资的待遇。","explanation":"“准入前”限定了待遇适用的阶段，负面清单则划定特别准入措施的范围。2023年自贸试验区建设十周年发布会将率先实施这一模式列为投资管理创新，故B属于题干所说的成果，在选非题中应排除。","references":[],"evidence":"实施外商投资准入前国民待遇加负面清单管理模式","disposition":"独立词条","basis":"据原题和解析编释。","title":"外商投资准入前国民待遇加负面清单管理","related":[],"examFocus":{"江苏 2024 A类 行测#5":"以自贸试验区建设十周年总结为依据，核对金融、投资准入、贸易便利化和跨境服务贸易方面的措施是否属于突破性创新成果。"}},"readings":[{"origin":"k-9738a804f4964fab","title":"外商投资准入前国民待遇加负面清单管理","qs":["江苏 2024 B类 行测#5"],"definition":"对外商投资，在投资准入阶段实行国民待遇和负面清单管理。清单列明外资准入的特别管理措施，清单之外在准入阶段给予外商投资者及其投资不低于境内投资者及其投资的待遇。","explanation":"“准入前”限定了待遇适用的阶段，负面清单则划定特别准入措施的范围。2023年自贸试验区建设十周年发布会将率先实施这一模式列为投资管理创新，故B属于题干所说的成果，在选非题中应排除。","evidence":"实施外商投资准入前国民待遇加负面清单管理模式","doubt":"","references":[]},{"origin":"k-d451bebac2efb476","title":"外商投资准入前国民待遇加负面清单管理","qs":["江苏 2024 A类 行测#5"],"definition":"外商投资准入前国民待遇加负面清单管理，是指在投资准入阶段，负面清单列明适用于外商投资的特别管理措施，清单之外给予外国投资者及其投资不低于境内投资者及其投资的待遇。","explanation":"自贸试验区率先实施这一模式，2023年自贸试验区建设十周年新闻发布会将其列入“五个率先”。第5题B项对应这项投资管理创新，题干要求选出不属于突破性创新成果的一项，因此排除B项。","evidence":"实施外商投资准入前国民待遇加负面清单管理模式","doubt":"","references":[]}]},"k-5660a0bb5faff060":{"review":{"definition":"国际贸易“单一窗口”允许企业通过统一入口提交办理进出口业务所需的信息和单证，由相关部门共享信息并反馈办理结果。","explanation":"统一入口和部门间的信息共享可以减少企业向多个部门重复申报。2023年自贸试验区建设十周年发布会列出的成果是率先建立以“单一窗口”为核心的贸易便利化模式，因此选项C属于成果，在选非题中应排除。","references":[],"evidence":"以国际贸易“单一窗口”为核心的贸易便利化模式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-46365a675a4ee2ee":{"review":{"definition":"跨境服务贸易负面清单列明对境外服务提供者跨境提供服务采取的特别管理措施，并按清单管理所列事项。","explanation":"这项措施管理的是跨境提供服务，B项的负面清单管理的是外商投资准入。2023年自贸试验区建设十周年发布会把跨境服务贸易负面清单管理列为推进服务业综合开放的代表性做法，因此D属于成果，在选非题中应排除。","references":[],"evidence":"实施跨境服务贸易负面清单管理，推进服务业综合开放","disposition":"独立词条","basis":"据原题和解析编释。","title":"跨境服务贸易负面清单管理","related":[],"examFocus":{"江苏 2024 A类 行测#5":"区分跨境服务贸易和外商投资准入两类负面清单的管理对象，再核对各项措施是否列入自贸试验区十周年总结。"}},"readings":[{"origin":"k-46365a675a4ee2ee","title":"跨境服务贸易负面清单管理","qs":["江苏 2024 B类 行测#5"],"definition":"跨境服务贸易负面清单列明对境外服务提供者跨境提供服务采取的特别管理措施，并按清单管理所列事项。","explanation":"这项措施管理的是跨境提供服务，B项的负面清单管理的是外商投资准入。2023年自贸试验区建设十周年发布会把跨境服务贸易负面清单管理列为推进服务业综合开放的代表性做法，因此D属于成果，在选非题中应排除。","evidence":"实施跨境服务贸易负面清单管理，推进服务业综合开放","doubt":"","references":[]},{"origin":"k-fe8b23c980acab01","title":"跨境服务贸易负面清单管理","qs":["江苏 2024 A类 行测#5"],"definition":"跨境服务贸易负面清单管理，是指以清单列明对境外服务提供者跨境提供服务适用的特别管理措施，清单之外按境内外服务提供者待遇一致的原则管理。","explanation":"这项制度面向跨境提供服务，第5题B项的负面清单则用于外商投资准入。2023年自贸试验区建设十周年新闻发布会将以跨境服务贸易负面清单管理推进服务业综合开放列为创新成果，因此选非时排除D项。","evidence":"实施跨境服务贸易负面清单管理，推进服务业综合开放","doubt":"","references":[]}]},"k-4e53e28a86df1a9c":{"review":{"definition":"依照《中华人民共和国行政处罚法》第三十三条第一款，初次违法且危害后果轻微并及时改正的，行政机关可以不予行政处罚。","explanation":"C项只给出“初次违法”，便得出“应免于处罚”，既遗漏了危害后果轻微和及时改正两个条件，也把“可以”改成了“应当”。同一款还规定，违法行为轻微并及时改正、没有造成危害后果的，不予行政处罚。","references":[],"evidence":"初次违法且危害后果轻微并及时改正的，可以不予行政处罚。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a6e5899721ce1933":{"review":{"definition":"公务员不得违反有关规定从事或者参与营利性活动。以股东身份出资设立有限责任公司，属于本题所指的参与营利性活动。","explanation":"有限责任公司属于营利法人，熊某作为小股东出资参与设立，持股比例小也改变不了行为性质，因此选D。C项中的张某因继承取得股权，随后转让该股权，题中将其认定为处分依法继承的财产。","references":[],"evidence":"熊某作为小股东出资设立有限责任公司属于从事营利性活动。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-125bcf652021e1a9":{"review":{"definition":"原题引文：物业公司因监控设施故障无法告知相关情况","explanation":"本题选C，按物业未尽监控管理义务处理。类似停车场纠纷曾把监控缺失导致无法查明侵权人纳入物业过错分析，但该案业主停在约定车位，最终双方和解。万某停在禁停地点，仍需判断物业对该区域的监控维护义务、设备正常时能否帮助查明肇事者，以及违停对损害发生或扩大的影响。题干没有交代足以确定具体责任范围的事实。","references":[{"source":"web-bc3f8ab1e5a22ac1","location":"第九百四十二条、第一千一百七十三条、第一千一百九十八条","quote":"承担相应的补充责任"},{"source":"web-bccbefcdf8ceec2d","location":"案例说明及法官心语","quote":"双方当事人达成和解"}],"evidence":"物业公司因监控设施故障无法告知相关情况","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-c8d4afa8a1a2cf46":{"review":{"definition":"被侵权人对同一损害的发生或者扩大有过错的，可以减轻侵权人的责任。","explanation":"本题解析将万某在禁停地点停车视为其自身过错。适用减责规则还要看违停对车辆剐蹭的发生或者损失扩大的影响。B项仅凭违停就让万某承担全部损失，D项仅凭双方有过错就认定各担一半，均缺少相应的判断依据。","references":[],"evidence":"可以减轻侵权人的责任","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d8021c15125f1324":{"review":{"definition":"行政机关对同一当事人的同一个违法行为不得给予两次以上罚款。一个行为违反多个法律规范且均应罚款的，按罚款数额高的规定处罚。","explanation":"许某因无证牌驾驶被罚款300元，因醉驾被吊销驾驶证。吊销属于另一处罚种类，这组处理没有重复给予行政罚款，B成立。行政罚款能否折抵刑事罚金另看刑事裁判是否把受罚事实作为同一事实处理。与题情高度相近的卢某检察指导性案例中，无证驾驶无号牌摩托车的300元罚款已折抵危险驾驶罪的罚金，因此A所称“不能折抵”过于绝对。","references":[{"source":"web-eb26c0179fff99a1","location":"第二十九条、第三十五条","quote":"应当折抵相应罚金"},{"source":"web-114c4f41d02daa49","location":"基本案情，刑事判决结果","quote":"300元罚款已折抵"}],"evidence":"交警部门对许某的不同行为作出不同的处罚","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-cba0c06d927e4525":{"review":{"definition":"行政机关实施扣押时，应制作并当场交付扣押决定书和清单。扣押决定书应载明被扣押财物的名称、数量等事项。","explanation":"林某写明了财物名称和15日的扣押期限，但“10多箱”无法确定实际扣押数量，因此D项认定记载不当。扣押决定书在次日才开具，也未满足当场制作并交付的要求。","references":[],"evidence":"“扣押花生油10多箱”“扣押期限15日”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f301c6e3904348a3":{"review":{"definition":"物权受到妨害时，权利人可以请求排除妨害，以恢复对其物权的正常行使。存在可能妨害物权的危险时，权利人可以请求消除危险。","explanation":"高某作为相邻业主，在民事诉讼中请求刘某排除扩建造成的妨害，行使的是保护自身物权的救济，因此A项正确。高某另行提起行政诉讼要求城管履职，针对的是行政机关的法定职责。","references":[],"evidence":"请求判处刘某排除妨害","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-abd6937053b9eaf1":{"review":{"definition":"人民检察院履职中发现食品药品安全领域侵害众多消费者合法权益等损害社会公共利益的行为，在没有法定机关和有关组织起诉资格主体或者这些主体不提起诉讼的情况下，可以提起民事公益诉讼。有关机关或者组织已经提起诉讼的，检察院可以支持起诉。","explanation":"公司无证生产并以原装进口饮用水名义销售，销售额达千万元，解析据此将案件认定为涉及众多消费者的食品安全公益案件。何某举报提供了案件线索，检察院能否自行起诉仍取决于法定起诉顺位。本规则解释了A项涉及的公益诉讼主体资格，惩罚性赔偿请求及其计赔基数另需依据。","references":[],"evidence":"食品药品安全领域侵害众多消费者合法权益等损害社会公共利益的行为","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-57553598a9256d6d":{"review":{"definition":"原题引文：检察机关有权以销售额为基数，请求判令该公司支付惩罚性赔偿金","explanation":"本题选A。考前已有检察公益诉讼典型案例以不符合食品安全标准的食品销售价款计赔。题中千万元销售额表明涉案饮用水销售规模，本身无法证明食品安全问题或公益损害。无证生产和冒充进口应结合产品安全标准、潜在风险及受影响的消费者范围判断。题解援引的消费者个人欺诈三倍赔偿，与公益诉讼采用何种计赔基数是两个问题。","references":[{"source":"web-ab539ec6d5a4da7a","location":"沙坡头区生产、销售不符合安全标准食品案，一审判决结果","quote":"食品价款十倍的惩罚性赔偿金"}],"evidence":"检察机关有权以销售额为基数，请求判令该公司支付惩罚性赔偿金","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-1b242ff768360f03":{"review":{"definition":"原题引文：苏某为获取博弈利益，无权要求返还购买卡片的款项","explanation":"本题选C。解析把卡片主要用作兑奖凭证、苏某为中大奖反复购卡和经营方未经许可合在一起，认定交易具有彩票式博弈性质。购卡款如何处理还要审查具体请求和适用依据。《民法典》第一百五十七条对民事法律行为无效后的财产返还已有一般规则，因此将债务认定为不受保护后，仍需查明该案拒绝返还的具体理由。","references":[{"source":"web-b8302bf465d32129","location":"第二条、第三条","quote":"未经国务院特许，禁止发行其他彩票"},{"source":"web-bc3f8ab1e5a22ac1","location":"第一百五十七条","quote":"行为人因该行为取得的财产，应当予以返还"}],"evidence":"苏某为获取博弈利益，无权要求返还购买卡片的款项","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-f3fc27aeb7966f06":{"review":{"definition":"商业广告和宣传通常属于要约邀请。其内容具体确定，并表明发布方在对方作出承诺后即受该表示约束的，可以构成要约。","explanation":"商场明确公布特等奖为某品牌新能源汽车的一年使用权，宣传中也未附加其他条件。题目据此将这项具体兑奖承诺认定为有约束力的要约，排除声称抽奖宣传没有法律约束力的A项。","references":[],"evidence":"商业广告和宣传的内容符合要约条件的，构成要约。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e4729357bacc3953":{"review":{"definition":"抽奖主办方应按具有约束力的已公布条件兑现奖项。主办方在中奖后新增的兑奖负担，对中奖者无约束力。","explanation":"商场公布的特等奖是一年汽车使用权，宣传中未要求中奖者交押金或保险费。商场与厂商约定的付款要求由商场自行处理。因此，韩某有权取得一年使用权，兑付所需的10万元押金和保险费由商场支付，C项正确。","references":[],"evidence":"并未附加其他条件","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d4cb61d31f99b606":{"review":{"definition":"国家对种质资源享有主权。单位或个人向境外提供种质资源，或者与境外机构、个人合作研究利用种质资源，应当报国务院有关主管部门批准，并同时提交国家共享惠益的方案。","explanation":"题目要求选出不正确的说法。种植者和育种者可以参与种质资源的利用，但利用者身份不改变国家主权的归属。D项把主权归给种植者和育种者，因此应选D。","references":[],"evidence":"国家对种质资源享有主权。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-009af4ef428751c9":{"review":{"definition":"成年子女对父母负有赡养、扶助和保护的法定义务。成年子女放弃分割家庭共有财产，不能据此免除赡养义务。","explanation":"老大即使自愿不分财产，老二、老三即使同意分担赡养，也不能通过协议免除老大的法定义务。C项只判定免除老大赡养义务的约定无效。解析末句将结论扩大到整份协议，超出了C项所判断的范围。","references":[],"evidence":"成年子女对父母负有赡养、扶助和保护的义务。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-50c7fc725f90e378":{"review":{"definition":"《中华人民共和国民法典》第一千二百四十五条规定，饲养的动物致害，原则上由动物饲养人或者管理人承担侵权责任。第一千二百四十九条规定，动物在遗弃、逃逸期间致害，由动物原饲养人或者管理人承担侵权责任。","explanation":"题中耕牛在交由沈某照管后走失。按题意，若果园损害发生在耕牛脱离沈某控制、尚未被农场实际接管期间，沈某作为逃逸前的管理人依法承担侵权责任，支持A项。已支付的2万元是沈某与刘某就耕牛走失约定的赔偿，不能据此确定农场的果园损失。原解析引用的第七百四十九条位于融资租赁合同章，本题给出的是普通租赁关系。","references":[{"source":"web-340d5d1801bcd9a2","location":"合同编第十五章第七百四十九条","quote":"承租人占有租赁物期间"},{"source":"web-340d5d1801bcd9a2","location":"侵权责任编第九章第一千二百四十五条、第一千二百四十九条","quote":"由动物原饲养人或者管理人承担侵权责任"}],"evidence":"因沈某照管不周，耕牛走失","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-e9e601f924dcf2f9":{"review":{"definition":"《完整居住社区建设指南》将完整居住社区作为城市结构的基本单元，通过建设规模适宜、功能完善的社区，优化调整城市结构并完善城市功能。","explanation":"指南指出，传统规划将居住区、工业区等划分为功能单一、相互分离的区域，带来了不紧凑、不宜居等问题。建设功能完善的居住社区是为了解决这类问题，因此把保持现有城市空间结构列为要求的A项应当选出。","references":[],"evidence":"优化调整城市结构、完善城市功能、激发城市活力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-27447db0059cbdf8":{"review":{"definition":"各地应结合儿童、老年人等居民的步行能力、基本服务设施的服务能力及社区综合管理能力，合理确定完整居住社区规模。","explanation":"居民步行能力影响社区服务的可达范围，设施和管理能力影响社区可以服务的人口规模。B项提出要合理确定社区人口规模，符合指南要求，在本题选非时应排除。","references":[],"evidence":"基本服务设施的服务能力以及社区综合管理能力等","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fd9b884b08d97df0":{"review":{"definition":"完整居住社区应在居民适宜步行范围内配备完善的基本公共服务设施、健全的便民商业服务设施、完备的市政配套基础设施和充足的公共活动空间，并有全覆盖的物业管理、健全的社区管理机制以及较强的居民归属感和认同感。","explanation":"C项的较强认同感对应指南对居民归属感、认同感的要求。D项的公共设施对应基本公共服务、市政配套等设施要求，具体配置以居民适宜步行范围内的服务需求为依据。两项均符合指南，在本题选非时应排除。","references":[],"evidence":"且居民归属感、认同感较强的居住社区","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5493a5042119afbd":{"review":{"definition":"《农业农村部关于拓展农业多种功能 促进乡村产业高质量发展的指导意见》提出，以乡村休闲旅游业为重点拓展农业多种功能。","explanation":"该重点列在“绿色引领、功能拓展”原则下。指导意见同时要求保护与开发并重，推动乡村农文旅一体化发展。第13题C项对应文件明确列出的重点，因此在选非题中应排除。","references":[],"evidence":"以乡村休闲旅游业为重点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-095c3644ade196df":{"review":{"definition":"《农业农村部关于拓展农业多种功能 促进乡村产业高质量发展的指导意见》要求坚持“立足特色、市场导向”，立足乡村特色资源，面向市场需求发展产业，由政府发挥政策配套和公共服务作用。","explanation":"第13题D项保留了“立足特色”，却把文件中的“市场导向”改为“政府主导”。文件对政府作用的表述是政策配套和公共服务，因此D项是本题应选的错误表述。","references":[],"evidence":"立足特色、市场导向。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-854c4692925e9ec4":{"review":{"definition":"《全国现代设施农业建设规划（2023—2030年）》要求因地制宜推广先进性与实用性相结合的设施农业类型。重点任务包括改造提升传统优势产区设施、引导潜力区开发非耕地设施农业、加强大中城市都市设施农业建设等。","explanation":"第14题的A、C、D分别对应传统优势产区、潜力区和大中城市的设施农业建设任务。B项“全面布局全产业链发展现代设施农业”未列入解析援引的重点任务，因此是本题所选项。","references":[],"evidence":"加快传统优势产区设施改造提升、引导潜力区实施非耕地设施农业开发","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2e39b8c7060a8c37":{"review":{"definition":"各类城镇建设所需用地，应纳入全省（区、市）规划城镇建设用地规模和城镇开发边界扩展倍数统筹核算。两项指标均不得擅自突破。","explanation":"第15题A项只提到城镇开发边界扩展倍数，准确复述了通知对这一指标的约束。通知同时要求控制城镇建设用地规模。","references":[],"evidence":"突破城镇建设用地规模和城镇开发边界扩展倍数","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3d4f3c0b9cdabc1e":{"review":{"definition":"城镇开发边界外不得进行城镇集中建设，不得规划建设各类开发区和产业园区，也不得规划城镇居住用地。落实耕地保护、节约用地和生态环境保护制度后，可因合理需要规划布局有特定选址要求的零星城镇建设用地，并按国土空间规划及用途管制要求实施监督。","explanation":"第15题B项的数字产业园属于边界外禁止规划建设的产业园区。C项只说为扩大城镇用地而缩减风景名胜区范围，所述条件不足以说明符合相关保护和规划要求。材料允许的情形是符合条件、具有特定选址要求的零星用地。","references":[],"evidence":"可规划布局有特定\n选址要求的零星城镇建设用地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-12c9175d5368fd5d":{"review":{"definition":"原题引文：各地要结合市县国土空间规划编制审批实施","explanation":"A项关于不得擅自突破扩展倍数的表述直接对应通知第一部分。公开试题转载的D项也写作“大力推动城镇地上地下空间复合利用”，但未交代是否依照市县国土空间规划、是否在边界内实施。通知第二部分的规定使合规性取决于这些条件，仅凭D项无法确认合规，也不能认定复合利用本身违背要求。","references":[{"source":"web-9e0c31f3324d0982","location":"第二部分，推动城镇开发边界划定成果精准落地实施","quote":"统筹存量用地和增量用地、地上空间和地下空间"},{"source":"web-fbab594a288ef143","location":"第十九条","quote":"同时废止"},{"source":"web-6d273408178d2c9b","location":"第4页，第15题D项","quote":"某县大力推动城镇地上地下空间复合利用"}],"evidence":"各地要结合市县国土空间规划编制审批实施","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-a130efe365bba368":{"review":{"title":"全面从严治党抓住“关键少数”","type":"制度与规则","definition":"全面从严治党把领导干部作为“关键少数”，要求他们带头遵守党纪国法、履行管党治党责任，发挥以上率下的示范作用。","explanation":"全面从严治党的要求覆盖全党。领导干部既要以身作则，也要在职责范围内推动党员、干部落实相关要求。","basis":"据关联原题及所列出处编释。","references":[{"source":"web-d2f182ac2286236f","location":"正文首段，文末注标明讲话日期","quote":"我们把制度建设贯穿党的各项建设"}],"examFocus":{"江苏 2025 A类 行测#2":"核对新时代全面从严治党成就的表述，区分各项举措的着力对象与所起作用。"}},"aspects":[{"title":"领导干部以上率下","uses":[{"unit":"Q1","role":"直接考查","use":"①把从领导干部抓起、以上率下列为新时代全面从严治党的做法，该项成立。两个所给卷本均标 C，C 同时包含④。所给题干④写作“把制度建设贯穿党的政治各方面”，而解析所引的2023年1月9日讲话表述为“我们把制度建设贯穿党的各项建设”。现有题据支持对①的判断，④及整题答案仍待原卷核实。","evidence":"牢牢抓住“关键少数”，坚持从领导干部抓起，以上率下","qids":["江苏 2025 A类 行测#2","江苏 2025 B类 行测#2"]}]}]},"k-066270830d9bbfc2":{"review":{"title":"党的制度建设","type":"制度与规则","definition":"党的制度建设是中国共产党制定、完善和执行党内制度，以规范党的领导和党的建设的工作。2022年修改的《中国共产党章程》总纲要求把制度建设贯穿党的各项建设。","explanation":"制度规范贯穿党的政治建设、思想建设、组织建设、作风建设和纪律建设等。2023年1月9日，习近平在二十届中央纪委二次全会上回顾新时代十年全面从严治党的成果，指出党把制度建设贯穿党的各项建设，与时俱进完善党章，推进制度创新，形成比较完善的党内法规体系。","basis":"据关联原题及所列出处编释。","references":[{"source":"charter","location":"总纲·党的建设"},{"source":"web-98350e005102fa64","location":"《求是》全文转载，新时代十年构建全面从严治党体系成果段","quote":"我们把制度建设贯穿党的各项建设"}],"related":["k-9a9a9867c701a684","k-7094c74d45ee3380"],"examFocus":{"江苏 2025 A类 行测#2":"对照全面从严治党有关论述，核对各项建设的作用及范围。"}},"aspects":[{"title":"制度建设的贯穿范围","uses":[{"unit":"Q1","role":"直接考查","use":"本题的所给答案均为C，包含判断④。所给题干将贯穿范围写作“党的政治各方面”，解析判④正确时援引的讲话原文写作“党的各项建设”。讲话可确认制度建设的贯穿范围，正式卷面措辞和官方答案仍待核实。","evidence":"④把制度建设贯穿党的政治各方面，形成比较完善的党内法规体系","qids":["江苏 2025 A类 行测#2","江苏 2025 C类 行测#2"]}]}]},"k-b7f605f81f11c010":{"review":{"definition":"2023年7月，习近平总书记在江苏考察时提出，江苏要打造全国重要的产业科技创新高地，使高质量发展更多依靠创新驱动的内涵型增长。","explanation":"这项部署要求强化企业科技创新主体地位，推动创新要素向企业集聚，提高科技成果转化和产业化水平，并深化科技体制改革和人才发展体制机制改革。题中①把高地建设、企业主体地位和体制机制改革结合起来，对应“四个新”中的“在科技创新上取得新突破”。","references":[],"evidence":"强化企业科技创新主体地位，深化科技体制改革和人才发展体制机制改革","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5a9b21d915b02f76":{"review":{"title":"中国特色社会主义法治道路的核心要义","type":"制度与规则","definition":"中国特色社会主义法治道路的核心要义是坚持中国共产党的领导、坚持中国特色社会主义制度、贯彻中国特色社会主义法治理论。","explanation":"党的领导是中国特色社会主义最本质的特征，也是社会主义法治最根本的保证。中国特色社会主义制度是中国特色社会主义法治体系的根本制度基础，也是全面推进依法治国的根本制度保障。中国特色社会主义法治理论为法治体系提供理论指导和学理支撑，是全面推进依法治国的行动指南。","basis":"据关联原题及所列出处编释。","references":[{"source":"rul","location":"法治道路的核心要义"}],"domain":"法律","examFocus":{"江苏 2025 A类 行测#5":"逐项核对各项表述所涉及的制度定位和实践要求。"}},"aspects":[{"title":"党的领导、制度与理论各自的作用","uses":[{"unit":"Q1","role":"直接考查","use":"本题均选A。题目分别从根本制度基础、最根本的保证、理论指导和行动指南三个方面表述核心要义，对应①②③。","evidence":"①中国特色社会主义制度是中国特色社会主义法治体系的根本制度基础②党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证③中国特色社会主义法治理论是法治体系的理论指导，是全面推进依法治国的行动指南","qids":["江苏 2025 A类 行测#5","江苏 2025 B类 行测#5"]}]}]},"k-469f06bedb2b5a5f":{"review":{"title":"法治中国建设的首要任务","type":"制度与规则","definition":"《法治中国建设规划（2020—2025年）》将全面贯彻实施宪法作为法治中国建设的首要任务。","explanation":"该规划要求坚持依宪治国、依宪执政，健全保证宪法全面实施的体制机制，加强宪法实施和监督。","basis":"据关联原题及所列出处编释。","references":[{"source":"lawgov","location":"全面贯彻实施宪法"}],"related":["k-c2383a4ccfc99a5b","k-e69dd9ac0a8d9123"],"domain":"法律","examFocus":{"江苏 2025 A类 行测#5":"核对法治建设中各项表述的依据，辨清具体任务的先后次序。"}},"aspects":[{"title":"规划规定的任务顺序","uses":[{"unit":"Q1","role":"解题依据","use":"本题均选A。④把弘扬社会主义法治精神、传承中华优秀传统法律文化列为首要任务，与该规划规定的任务顺序不符。","evidence":"把全面贯彻实\n施宪法作为首要任务","qids":["江苏 2025 A类 行测#5","江苏 2025 B类 行测#5"]}]}]},"k-005f9458f0d71549":{"review":{"definition":"党的二十届三中全会审议通过的《中共中央关于进一步全面深化改革、推进中国式现代化的决定》提出，依法平等长久保护各种所有制经济产权，并建立高效的知识产权综合管理体制。","explanation":"前一项明确产权保护适用于各种所有制经济，后一项要求健全知识产权综合管理体制。题中④的两项举措均列入《决定》第二部分第（7）项“完善市场经济基础制度”，因此属于构建高水平社会主义市场经济体制的举措。","references":[],"evidence":"依法平等长久保护各种所有制经济产权，建立高效的知识产权综合管理体制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-46669862994b07d9":{"review":{"definition":"党的二十届三中全会审议通过的《中共中央关于进一步全面深化改革、推进中国式现代化的决定》将培育壮大先进制造业集群、推动制造业高端化、智能化、绿色化列入健全推动经济高质量发展体制机制的部署。","explanation":"这项部署位于《决定》第三部分第（9）项“健全促进实体经济和数字经济深度融合制度”。题中①所述举措本身正确，题目限定选取第二部分“构建高水平社会主义市场经济体制”中的举措，因此排除①。","references":[],"evidence":"培育壮大先进制造业集群，推动制造业高端化、智能化、绿色化发展","disposition":"独立词条","basis":"据原题和解析编释。","title":"制造业高端化、智能化、绿色化","related":[],"examFocus":{"政治理论必刷100题#28":"辨析制造业政策表述时，分别核对产业发展基础、产业链供应链建设、转型方向和制造业比重要求。","江苏 2025 A类 行测#6":"按全会《决定》的章节归属，辨析先进制造业集群等举措是否纳入构建高水平社会主义市场经济体制的部署。"}},"readings":[{"origin":"k-46669862994b07d9","title":"制造业高端化、智能化、绿色化","qs":["江苏 2025 A类 行测#6"],"definition":"党的二十届三中全会审议通过的《中共中央关于进一步全面深化改革、推进中国式现代化的决定》将培育壮大先进制造业集群、推动制造业高端化、智能化、绿色化列入健全推动经济高质量发展体制机制的部署。","explanation":"这项部署位于《决定》第三部分第（9）项“健全促进实体经济和数字经济深度融合制度”。题中①所述举措本身正确，题目限定选取第二部分“构建高水平社会主义市场经济体制”中的举措，因此排除①。","evidence":"培育壮大先进制造业集群，推动制造业高端化、智能化、绿色化发展","doubt":"","references":[]},{"origin":"k-c1fb622df43c2bf2","title":"制造业高端化、智能化、绿色化","qs":["政治理论必刷100题#28"],"definition":"制造业要坚持高端化、智能化、绿色化方向，不断提高产品科技含量和附加值。","explanation":"习近平总书记2025年赴辽宁看望慰问基层干部群众时提出这三项转型方向，并要求鞍钢这样的国有大企业为中国式现代化多作贡献。第28题③同时保留了三项方向以及提高产品科技含量和附加值的要求，符合讲话表述。","evidence":"制造业要坚持高端化、智能化、绿色化方向，不断提高产品科技含量和附加值","doubt":"","references":[]}]},"k-9ff08b275eb6eb7b":{"review":{"title":"进一步全面深化改革中的以人民为中心","type":"制度与规则","definition":"党的二十届三中全会通过的2024年《中共中央关于进一步全面深化改革、推进中国式现代化的决定》将坚持以人民为中心列为进一步全面深化改革的原则，要求做到改革为了人民、改革依靠人民、改革成果由人民共享。","explanation":"这一原则要求尊重人民主体地位和首创精神，使群众能够参与改革、提出需求和建议，并使改革回应群众关切，让群众共享改革带来的实际改善。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"进一步全面深化改革的原则"}],"examFocus":{"江苏 2025 A类 行测#7":"从服务对象、参与渠道和实施效果判断各项市政措施与群众的关系。"}},"aspects":[{"title":"民生受益与群众参与","uses":[{"unit":"Q1","role":"直接考查","use":"本题均选B。①减免摊位费，减轻相关群体的经营负担，②通过百姓会客厅问计问需于民，④通过积分落户促进有稳定就业的外来人口有序实现市民化。③仅写明提高资源配置效率和减轻财政负担，题干未交代这些成效如何回应群众需求或惠及群众。","evidence":"改革为了人民、改革依靠人民、改革成果由人民共享","qids":["江苏 2025 A类 行测#7","江苏 2025 B类 行测#7"]}]}]},"k-50a4884a76bbda15":{"review":{"definition":"国务院对《江苏省国土空间规划（2021—2035年）》的批复要求，除国家重大项目外，全面禁止围填海。","explanation":"①把苏北海岸带的管控表述为“一律不得新增围海和填海”，遗漏了国家重大项目这一例外，因此错误。","references":[],"evidence":"除国家重大项目外，全面禁止围填海","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8c8704b949b16ddc":{"review":{"definition":"江苏将统筹推进长江和大运河国家文化公园建设列入全面推进美丽江苏建设的实施意见。","explanation":"实施意见在塑造“水韵江苏”品牌的条目中提出“以水为脉”，把推动江河湖海各展所长和统筹推进两座国家文化公园建设列在一起，③的两部分均有对应依据。","references":[],"evidence":"推动江河湖海各展所长，统筹推进长江和大运河国家文化公园建设","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7a159c8c250f843a":{"review":{"definition":"江苏要求增强全省森林、湿地、土壤、海洋等生态系统的固碳作用，并支持里下河地区提升生态系统碳汇能力。","explanation":"两项举措都列在实施意见关于推进碳达峰碳中和的条目中。④准确区分了面向全省的固碳要求和面向里下河地区的碳汇支持。","references":[],"evidence":"增强省域森林、湿地、土壤、海洋等生态系统固碳作用，支持里下河地区提升生态系统碳汇能力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2fa46ca21030e313":{"review":{"definition":"一方故意告知虚假情况或者隐瞒真实情况，使对方陷入错误认识，并据此作出违背其真实意思的意思表示，可以认定为民事欺诈。","explanation":"第17题中，M公司把“生成临时密码”宣传为所售门锁已有的功能，韩某购买安装后才得知须另付费升级。按题意，M公司隐瞒了影响购买决定的付费条件，使韩某误以为购买该款门锁即可获得这项功能，因此A项成立。","references":[],"evidence":"需要额外付费升级系统后才能安装该功能","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-22af9293a94f8460":{"review":{"definition":"一方以欺诈手段使对方在违背真实意思的情况下实施民事法律行为的，受欺诈方有权请求人民法院或者仲裁机构撤销该行为。","explanation":"第17题中，韩某因误信门锁已具备临时密码功能而订立买卖合同，可以依法请求撤销。欺诈在本题中的法律后果是合同可撤销，B项将其直接认定为无效，因此是选非题的答案。","references":[],"evidence":"受欺诈方有权请求人民法院或者仲裁机构予以撤销","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c133b1ea9487e877":{"review":{"definition":"经营者提供商品或者服务有欺诈行为的，消费者有权要求增加赔偿。增加赔偿额为商品价款或者服务费用的三倍，不足五百元的按五百元计算，法律另有规定的依其规定。","explanation":"第17题中，M公司以门锁具备“生成临时密码”功能招徕购买，却在韩某购买安装后才告知该功能需付费升级。按题意，这一行为构成消费欺诈，韩某可以要求增加赔偿，故C项成立。本题未给出门锁价款，判断的是赔偿请求权。","references":[],"evidence":"增加赔偿的金额不足五百元的，为五百元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3315d546b2462173":{"review":{"definition":"一方不履行合同义务或者履行合同义务不符合约定的，对方可以依法请求其承担违约责任。","explanation":"第17题将“生成临时密码”作为所售门锁的约定功能。M公司交付的门锁须另付费升级才能获得该功能，交付内容与约定不符，韩某据此可以请求M公司承担违约责任，故D项成立。","references":[],"evidence":"履行合同义务不符合约定条件的行为","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c2852d8b366cea44":{"review":{"definition":"通知适用于发布、传达要求下级机关执行和有关单位周知或者执行的事项，以及批转、转发公文。上级机关用通知向下级机关传达执行事项时，属于下行文。","explanation":"第19题引文是皇帝对江苏巡抚张伯行奏疏的批复，发文方向由上至下，与A项通知向下级机关传达执行要求的方向一致。请示和报告由下级机关发往上级机关，题中议案由人民政府向同级人大或其常委会提出。","references":[],"evidence":"为清圣祖皇帝回复江苏巡抚张伯行奏疏的内容","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-163f28e0349bf441":{"review":{"definition":"红灯是表示禁止通行的交通信号。红灯亮时，受该信号控制的交通参与者应按信号要求停止通行。","explanation":"D项的“红灯—禁行”是交通信号及其所表达的通行要求之间的对应，与题干前半组“生肖—地支”同属明确的对应关系。A项中的路口是可能实施禁行的地点，关系不同。","references":[],"evidence":"红灯亮时表示禁止通行","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0ffcdc843366b6ad":{"review":{"definition":"原题引文：把制度建设贯穿党的政治各方面，形成比较完善的党内法规体系","explanation":"习近平2023年1月9日在二十届中央纪委二次全会上的讲话明确使用“党的各项建设”。所给④却写成“党的政治各方面”，与讲话所指范围有出入。题给答案C主要依照解析引用的正确表述把④计入。按现有题面剔除②与④，仅剩①③⑤，四个选项均不匹配。","references":[{"source":"web-d2f182ac2286236f","location":"正文首段，文末注标明讲话日期","quote":"我们把制度建设贯穿党的各项建设"}],"evidence":"把制度建设贯穿党的政治各方面，形成比较完善的党内法规体系","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-9694604e8b726ca0":{"review":{"definition":"2023年7月，习近平在江苏考察时提出，江苏要在建设中华民族现代文明上探索新经验，推进优秀传统文化保护传承和创新发展，加强科教事业和公共文化服务建设。","explanation":"第3题③列出的举措涵盖传统文化保护传承、通过发展现代科技和教育提升群众科学文化素质，以及推进城乡公共文化服务标准化、均等化，均对应建设中华民族现代文明的任务。","references":[],"evidence":"持续推进城乡公共文化服务标准化、均等化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-41e9e1640a30b1e6":{"review":{"definition":"2023年7月，习近平在江苏考察时提出，江苏要在保障和改善民生、推进社会治理现代化上走在前列，健全社会保障和就业服务体系，推进社会治理数字化及应急管理体系和能力现代化。","explanation":"第3题④把社会保障、就业促进和就业公共服务列为民生举措，把社会治理数字化和应急管理体系及能力建设列为提升治理能力的举措。这些安排共同对应在推进社会治理现代化上实现新提升的任务。","references":[],"evidence":"完善社会治理体系，推进社会治理数字化，推进应急管理体系和能力现代化","disposition":"独立词条","basis":"据原题和解析编释。","title":"江苏推进社会治理现代化","related":[],"examFocus":{"江苏 2025 A类 行测#3":"对照江苏考察提出的“四个新”，辨析题中所列举措与社会治理现代化任务的对应关系。"}},"readings":[{"origin":"k-41e9e1640a30b1e6","title":"江苏推进社会治理现代化","qs":["江苏 2025 B类 行测#3"],"definition":"2023年7月，习近平在江苏考察时提出，江苏要在保障和改善民生、推进社会治理现代化上走在前列，健全社会保障和就业服务体系，推进社会治理数字化及应急管理体系和能力现代化。","explanation":"第3题④把社会保障、就业促进和就业公共服务列为民生举措，把社会治理数字化和应急管理体系及能力建设列为提升治理能力的举措。这些安排共同对应在推进社会治理现代化上实现新提升的任务。","evidence":"完善社会治理体系，推进社会治理数字化，推进应急管理体系和能力现代化","doubt":"","references":[]},{"origin":"k-65bffec4446e59e1","title":"江苏推进社会治理现代化","qs":["江苏 2025 C类 行测#3"],"definition":"2023年7月，习近平在江苏考察时要求江苏在保障和改善民生、推进社会治理现代化上走在前列，部署涉及社会保障、就业服务、社会治理和应急管理。","explanation":"④中的健全社会保障体系和就业公共服务体系对应保障和改善民生，完善社会治理体系、推进社会治理数字化对应治理方式改进，推进应急管理体系和能力现代化对应应急能力建设。这些做法共同落实江苏“四个新”中的“在推进社会治理现代化上实现新提升”。","evidence":"完善社会治理体系，推进社会治理数字化，推进应急管理体系和能力现代化","doubt":"","references":[]},{"origin":"k-676d212ed8f38dae","title":"江苏推进社会治理现代化","qs":["江苏 2025 A类 行测#3"],"definition":"2023年7月，习近平总书记在江苏考察时要求，江苏在保障和改善民生、推进社会治理现代化上走在前列。相关部署包括健全社会保障和就业公共服务体系、完善社会治理体系、推进应急管理体系和能力现代化。","explanation":"题中④的社会保障和就业服务举措落实民生要求，治理体系建设和治理数字化落实社会治理要求，应急管理体系和能力建设落实应急管理要求，共同对应“四个新”中的“在推进社会治理现代化上实现新提升”。","evidence":"完善社会治理体系，推进社会治理数字化，推进应急管理体系和能力现代化","doubt":"","references":[]}]},"k-f1dd9f89c7572816":{"review":{"definition":"党的二十届三中全会《决定》把完善产权制度列为完善市场经济基础制度的要求，提出依法平等长久保护各种所有制经济产权，建立高效的知识产权综合管理体制。","explanation":"第6题④对应《决定》第二部分第（7）项“完善市场经济基础制度”，属于构建高水平社会主义市场经济体制的举措。①所述先进制造业集群和制造业转型措施列在第三部分“健全推动经济高质量发展体制机制”。","references":[],"evidence":"依法平等长久保护各种所有制经济产权，建立高效的知识产权综合管理体制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-22104d2cf9010e96":{"review":{"definition":"国务院对《江苏省国土空间规划（2021—2035年）》的批复规定，除国家重大项目外，江苏全面禁止围填海。","explanation":"批复把国家重大项目排除在这项全面禁令的适用范围之外。①对苏北海岸带使用“一律不得新增围海和填海”，遗漏了这一例外，因此应排除①。","references":[],"evidence":"除国家重大项目外，全面禁止围填海","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9400b9d6a9b5d7ef":{"review":{"definition":"江苏推进美丽江苏建设时，将建设黄河故道千里生态富民廊道、构建江淮生态经济区湖群绿心列为塑造“水韵江苏”品牌的举措。","explanation":"《关于全面推进美丽江苏建设的实施意见》将两项任务列在同一节。黄河故道对应生态富民廊道，江淮生态经济区对应湖群绿心，②的两项部署及其地域对应均与文件一致。","references":[],"evidence":"建设黄河故道千里生态富民廊道，构建江淮生态经济区湖群绿心","disposition":"独立词条","basis":"据原题和解析编释。","title":"黄河故道千里生态富民廊道与江淮生态经济区湖群绿心","related":[],"examFocus":{"江苏 2025 A类 行测#9":"依据美丽江苏建设实施意见，辨析生态富民廊道、湖群绿心等建设任务与相关区域的对应关系。"}},"readings":[{"origin":"k-9400b9d6a9b5d7ef","title":"黄河故道千里生态富民廊道与江淮生态经济区湖群绿心","qs":["江苏 2025 B类 行测#9"],"definition":"江苏推进美丽江苏建设时，将建设黄河故道千里生态富民廊道、构建江淮生态经济区湖群绿心列为塑造“水韵江苏”品牌的举措。","explanation":"《关于全面推进美丽江苏建设的实施意见》将两项任务列在同一节。黄河故道对应生态富民廊道，江淮生态经济区对应湖群绿心，②的两项部署及其地域对应均与文件一致。","evidence":"建设黄河故道千里生态富民廊道，构建江淮生态经济区湖群绿心","doubt":"","references":[]},{"origin":"k-d1001a988a639943","title":"黄河故道千里生态富民廊道与江淮生态经济区湖群绿心","qs":["江苏 2025 A类 行测#9"],"definition":"江苏在全面推进美丽江苏建设中，将建设黄河故道千里生态富民廊道、构建江淮生态经济区湖群绿心列为塑造“水韵江苏”品牌的任务。","explanation":"实施意见分别使用“建设”和“构建”对应两项任务。②将黄河故道与生态富民廊道、江淮生态经济区与湖群绿心一一对应，符合文件表述。","evidence":"建设黄河故道千里生态富民廊道，构建江淮生态经济区湖群绿心","doubt":"","references":[]}]},"k-6bb5fedac8e29d61":{"review":{"definition":"江苏在塑造“水韵江苏”品牌时，部署以水为脉，发挥江河湖海各自的特色，统筹推进长江和大运河国家文化公园建设。","explanation":"《关于全面推进美丽江苏建设的实施意见》将“推动江河湖海各展所长”和统筹两项国家文化公园建设写在同一段。③同时准确复述了水系特色和文化公园建设两项要求。","references":[],"evidence":"推动江河湖海各展所长，统筹推进长江和大运河国家文化公园建设","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7e35ea5e9d49a027":{"review":{"definition":"江苏推进碳达峰碳中和的部署包括增强全省森林、湿地、土壤、海洋等生态系统的固碳作用，并支持里下河地区提升生态系统碳汇能力。","explanation":"④前半句对应覆盖全省多类生态系统的固碳任务，后半句对应面向里下河地区的碳汇能力支持。两项要求均见于《 关于全面推进美丽江苏建设的实施意见》的“积极稳妥推进碳达峰碳中和”部分。","references":[],"evidence":"增强省域森林、湿地、土壤、海洋等生态系统固碳作用，支持里下河地区提升生态系统碳汇能力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-87f5d1970cc6d8e6":{"review":{"definition":"行政裁量权基准是行政机关细化行政执法裁量尺度的标准。设定基准须符合有关法律、法规、规章对执法事项、条件、程序、种类和幅度的规定。","explanation":"D项通过统一裁量尺度规范行政处罚等执法行为，属于深化行政执法体制改革。A项处理重大行政决策的合法性审查，B项处理行政机构及其职能的法定化，C项处理中央和地方的管理职责关系。","references":[],"evidence":"裁量权基准的设定要符合法律、法规、规章有关行政执法事项、条件、程序、种类、幅度的规定","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8ac930de774ed325":{"review":{"definition":"国资国企改革要求国有企业增强核心功能，发挥科技创新、产业控制、安全支撑作用。国有经济布局还要聚焦战略安全、产业引领、国计民生和公共服务等功能。","explanation":"A项“维护国家安全”和B项“引领科技创新”分别对应安全支撑、科技创新。C项“服务国计民生”概括了规划纲要明确列出的国有经济功能，属于比题引会议的“三个作用”更宽的政策表述。D项“促进城乡融合”是综合性发展目标，在这组选项中应选D。","references":[{"source":"web-e904a6a29a99ca8e","location":"第十九章第一节“加快国有经济布局优化和结构调整”","quote":"战略安全、产业引领、国计民生、公共服务等功能"},{"source":"web-e39134348035f68b","location":"“多措并举优布局、调结构，增强核心功能、提升核心竞争力”段","quote":"关系国计民生、提供公共服务等国家重大战略领域"}],"evidence":"更好发挥科技创新、产业控制、安\n全支撑作用","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-317769a158fdaf4f":{"review":{"definition":"题中2024年“最美公务员”事迹体现的职业道德是信仰坚定、担当作为、竭诚为民、无私奉献。这些要求分别落在政治信仰、履职担当和为民服务上。","explanation":"坚定拥护“两个确立”、坚持做到“两个维护”体现信仰坚定。承担急难险重任务、在日常工作中恪尽职守体现担当作为。一线履职和践行人民公仆宗旨体现竭诚为民、无私奉献，因此应选A。B、C、D依次对应企业家精神、科学家精神和工匠精神的相关内容。","references":[],"evidence":"信仰坚定，担当作为，竭诚为民，无私奉献","disposition":"独立词条","basis":"据原题和解析编释。","title":"公务员职业道德","related":[],"examFocus":{"江苏 2025 A类 行测#13":"从材料中的政治表现、重大任务和日常履职入手，辨析这些事迹体现了公务员职业道德的哪些方面。"}},"readings":[{"origin":"k-317769a158fdaf4f","title":"公务员职业道德","qs":["江苏 2025 B类 行测#13"],"definition":"题中2024年“最美公务员”事迹体现的职业道德是信仰坚定、担当作为、竭诚为民、无私奉献。这些要求分别落在政治信仰、履职担当和为民服务上。","explanation":"坚定拥护“两个确立”、坚持做到“两个维护”体现信仰坚定。承担急难险重任务、在日常工作中恪尽职守体现担当作为。一线履职和践行人民公仆宗旨体现竭诚为民、无私奉献，因此应选A。B、C、D依次对应企业家精神、科学家精神和工匠精神的相关内容。","evidence":"信仰坚定，担当作为，竭诚为民，无私奉献","doubt":"","references":[]},{"origin":"k-36c53bf802946f1d","title":"公务员职业道德","qs":["江苏 2025 A类 行测#13"],"definition":"公务员应坚定政治信仰，认真履职、勇于担当，坚持全心全意为人民服务并甘于奉献。本题以“信仰坚定，担当作为，竭诚为民，无私奉献”概括这些要求。","explanation":"坚定拥护“两个确立”、坚持做到“两个维护”体现政治信仰，在重大任务中担苦担难担重担险、在日常工作中恪尽职守体现担当作为，把服务人民落实到一线工作体现竭诚为民和无私奉献，合起来对应A项。","evidence":"信仰坚定，担当作为，竭诚为民，无私奉献","doubt":"","references":[]}]},"k-600b61e65082d8de":{"review":{"definition":"我国对列入两用物项出口管制清单的特定石墨及其制品实行出口许可管理，包括天然鳞片石墨及其制品、符合清单条件的特定人造石墨材料及其制品。","explanation":"2023年第39号公告自2023年12月1日起实施，取消了原2006年公告中部分物项的临时管制。自2024年12月1日起，第39号公告废止，笔试时相关管制已纳入统一清单的1C108项。C项把特定物项须经许可才可出口扩大成了所有石墨产品均禁止出口，因此应排除C，题给正确项为D。","references":[{"source":"web-938d1fd7e5beae2b","location":"第一、二、九项","quote":"未经许可，不得出口"},{"source":"web-1543e82ac29d3d3e","location":"公告正文及附件2","quote":"自2024年12月1日起实施"},{"source":"web-80c1d6815eb10736","location":"2024年第51号公告附件2第八项","quote":"商务部、海关总署公告2023年第39号"},{"source":"web-b81c57716c6a65cb","location":"1C108“石墨及其制品”","quote":"天然鳞片石墨及其制品"}],"evidence":"依法对特定石墨物项实施出口管制","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-f522176b278654a3":{"review":{"definition":"人民法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉。","explanation":"第16题A项把禁止特定主体干涉审判扩大成“不受任何机关或组织的制约”。依法独立审判与依法接受监督可以并存，A项超出了原规则的范围。","references":[],"evidence":"法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cd75d494b9976679":{"review":{"definition":"人民法院审理民事案件，应当以证据能够证明的案件事实为根据依法作出裁判。待证事实无法认定时，依法适用举证责任规则确定相应后果。","explanation":"第16题B项认为事实无法查清时法院就不应作出终局裁判。以民事诉讼为例，法院可以根据已经证明的事实及举证责任规则作出裁判，因此B项把事实认定上的困难写成了终局裁判的障碍。","references":[],"evidence":"人民法院应当以证据能够证明的案件事实为根据依法作出裁判。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cda66bb8a91bd549":{"review":{"definition":"人民法院审理案件原则上应当公开。法律规定应当不公开审理的，法院应适用相应例外。法律允许依申请不公开审理的，法院可以在当事人提出申请后依法决定。","explanation":"第16题D项的“一律公开”忽略了法定例外。以民事案件为例，涉及国家秘密、个人隐私的案件不公开审理，离婚案件或涉及商业秘密的案件经当事人申请可以不公开审理。","references":[],"evidence":"离婚案件，涉及商业秘密的案件，当事人申请不公开审理的，可以不公开审理。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-88de38cb4794dd3d":{"review":{"definition":"一方以欺诈手段使对方在违背真实意思的情况下订立合同，受欺诈方有权请求人民法院或者仲裁机构撤销合同。","explanation":"M公司以门锁具备临时密码功能的宣传促成交易，韩某购买后才得知须另行付费升级。按《民法典》第一百四十八条，韩某可以请求撤销合同。B项把因欺诈订立的合同直接认定为无效，是本题要求选出的错误说法。","references":[],"evidence":"受欺诈方有权请求人民法院或者仲裁机构予以撤销。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-646e7ba008d875ad":{"review":{"definition":"一方故意告知虚假情况或者隐瞒真实情况，使对方产生错误认识，并因此作出意思表示，可以认定为民事欺诈。","explanation":"M公司在销售时宣称门锁具有生成临时密码的功能，韩某购买安装后才被告知须付费升级。本题将这一宣传认定为足以使韩某误以为所购门锁已具备该功能并据此订约，故A项成立。","references":[],"evidence":"需要额外付费升级系统后才能安装该功能","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-33f9bebbc50a0920":{"review":{"definition":"经营者提供商品或者服务有欺诈行为的，应按消费者要求增加赔偿。增加赔偿额为商品价款或服务费用的三倍，不足五百元的按五百元计算，法律另有规定的依其规定。","explanation":"题设将M公司对临时密码功能的不实宣传认定为经营者欺诈，韩某可以依《消费者权益保护法》第五十五条第一款主张增加赔偿，因此C项成立。题干未给出购买价款，C项只判断韩某是否有权主张赔偿。","references":[],"evidence":"应当按照消费者的要求增加赔偿其受到的损失","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-91af0376506dec50":{"review":{"definition":"卖方交付的商品不具备买卖合同约定的功能，属于履行不符合约定，买方可以请求卖方承担违约责任。","explanation":"本题将生成临时密码作为销售时承诺的门锁功能。M公司交付的门锁缺少该功能，并要求韩某另付费升级，故其交付不符合约定，D项成立。D项的判断依据是所交付的门锁与约定功能之间的差异。","references":[],"evidence":"M公司的行为构成违约，因此，韩某有权请求M公司承担违约责任。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ff65da82f447cf0d":{"review":{"definition":"当事人有证据足以证明自己没有主观过错的，行政机关不予行政处罚。法律、行政法规另有规定的，从其规定。","explanation":"秦某右转行驶30米后才遇到禁行标志，可以围绕转弯前是否有提示、何时能够看到禁行标志举证，故D项正确。他能否免罚取决于证据是否足以证明没有主观过错，以及有无法定例外。","references":[],"evidence":"不予行政处罚。法律、行政法规另有规定的，从其规定。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-322e3f4dbb6f7773":{"review":{"definition":"行政比例原则中的适当性要求行政机关采取的手段能够促进其管理目的的实现。","explanation":"禁行标志应让驾驶人在仍可选择通行路线时获知禁行要求。按本题解析，丁字路口缺少提前提示，秦某右转行驶30米后才遇到禁行标志、标线，设置方式难以有效预防误入，因此A项对适当性的判断错误。","references":[],"evidence":"没有在起点位置之前的适当位置设置相应的提示标志","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-878c31ac4627015e":{"review":{"definition":"行政机关将内部批复直接付诸实施并对外部相对人的权利义务产生实际影响时，相关对外行政行为可以成为行政诉讼的审查对象。","explanation":"县政府起初向县自然资源和规划局作出同意回收的批复。该局随后将回收事项交由土地储备中心实施，直接影响韩某合法房屋所在宗地的使用权益。C项所说的可诉行为是该局将批复付诸实施的行为。","references":[],"evidence":"当内部行政行为对外部相对人的权利义务产生实际影响并被付诸实施","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d14505b87d3715af":{"review":{"definition":"原题引文：县自然资源和规划局并未制作回收决定书，也未通知该地块的使用权人","explanation":"题中未另作收回决定书，确定被告须先识别韩某所诉的是县自然资源和规划局交付实施的行为，还是已因实际执行而对外产生效力的县政府批复。题给答案D采用前一种理解，将实施行为归于县自然资源和规划局。指导案例22号中，原告起诉的是县政府批复，法院认定批复实际执行后可诉，并指令继续审理。题中仅凭未制作收回决定书，尚不能确定应列哪个机关。","references":[{"source":"web-1eba6cf79110ba1f","location":"第二十六条第一款","quote":"作出行政行为的行政机关是被告"},{"source":"web-6af22ba7c0bedacd","location":"第十九条","quote":"以在对外发生法律效力的文书上署名的机关为被告"},{"source":"web-cbb6009c824299b2","location":"裁判理由","quote":"对该批复不服提起行政诉讼的，人民法院应当依法受理"}],"evidence":"县自然资源和规划局并未制作回收决定书，也未通知该地块的使用权人","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-63827e9a4c679452":{"review":{"definition":"行政机关审查行政许可申请时，发现许可事项直接关系他人重大利益的，应当告知利害关系人，并听取申请人和利害关系人的意见。申请人和利害关系人均有权陈述、申辩。","explanation":"即使炒货店的经营条件与原发证条件相比没有本质变化，延续经营仍可能因噪声、用电安全等问题直接影响相邻居民。本题据此选择D，将相邻关系纳入延续审查。是否准予延续仍须根据审查结果作出判断。","references":[],"evidence":"发现行政许可事项直接关系他人重大利益的，应当告知该利害关系人。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b44633d3253023ad":{"review":{"definition":"交通信号灯的红灯亮起时，受该信号控制的车辆或行人须遵守相应的禁行指示。","explanation":"D项的“红灯—禁行”是信号与指令的对应，与前半组“生肖—地支”的固定配对同属对应关系。C项的“通行—禁行”表达的是相反的通行要求。","references":[],"evidence":"红灯亮时表示禁止通行","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7d219802f2b7b6a9":{"review":{"definition":"“宅基议事会”是中关村自2018年起探索的民主议事制度，组织村民协商河道治理、道路拓宽、消防安全等与自身利益相关的村务。","explanation":"材料中的公共充电桩议题先经过调查和协商，再由村支书主持议事，村民就选址、服务商等提出意见。材料记载该制度六年来解决了五十多项问题。请示正文可用议题范围、参与方式和办理成效说明中关村经验的推广价值。","references":[],"evidence":"“宅基议事会”是中关村从2018年开始推行探索的一项民主议事制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-04a2dc7901adeaba":{"review":{"definition":"原题引文：牢牢抓住“关键少数”，坚持从领导干部抓起，以上率下","explanation":"中央八项规定从中央政治局做起、从领导干部抓起，是以上率下的具体做法，支持本题①。给定答案C还包括④，但公开回忆版④保留了“党的政治各方面”，而讲话所说制度建设贯穿的是“党的各项建设”。按讲话原文修正④后，C才与给定解析的组合一致。","references":[{"source":"web-cd62e019ba2bb06a","location":"中央八项规定与领导干部示范段","quote":"从领导干部抓起，以上率下改进工作作风"},{"source":"web-98350e005102fa64","location":"《求是》全文转载，新时代十年构建全面从严治党体系成果段","quote":"我们把制度建设贯穿党的各项建设"},{"source":"web-c724397a3a8ab268","location":"第2题，陈述④","quote":"把制度建设贯穿党的政治各方面"}],"evidence":"牢牢抓住“关键少数”，坚持从领导干部抓起，以上率下","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-132e8b6eb2183c71":{"review":{"definition":"2023年7月，习近平在江苏考察时提出，江苏要打造全国重要的产业科技创新高地，使高质量发展更多依靠创新驱动的内涵型增长。","explanation":"强化企业科技创新主体地位，有助于创新要素向企业集聚，提高科技成果转化和产业化水平。①将这一要求与深化科技体制改革、人才发展体制机制改革并列，对应江苏“四个新”中的“在科技创新上取得新突破”。","references":[],"evidence":"打造全国重要的产业科技创新高地，使高质量发展更多依靠创新驱动的内涵型增长","disposition":"独立词条","basis":"据原题和解析编释。","title":"江苏建设产业科技创新高地","related":[],"examFocus":{"江苏 2025 B类 行测#3":"对照江苏“四个新”的任务范围，辨析企业创新和体制机制改革等举措分别指向哪项任务。"}},"readings":[{"origin":"k-132e8b6eb2183c71","title":"江苏建设产业科技创新高地","qs":["江苏 2025 C类 行测#3"],"definition":"2023年7月，习近平在江苏考察时提出，江苏要打造全国重要的产业科技创新高地，使高质量发展更多依靠创新驱动的内涵型增长。","explanation":"强化企业科技创新主体地位，有助于创新要素向企业集聚，提高科技成果转化和产业化水平。①将这一要求与深化科技体制改革、人才发展体制机制改革并列，对应江苏“四个新”中的“在科技创新上取得新突破”。","evidence":"打造全国重要的产业科技创新高地，使高质量发展更多依靠创新驱动的内涵型增长","doubt":"","references":[]},{"origin":"k-fa67aacf551b7f8e","title":"江苏建设产业科技创新高地","qs":["江苏 2025 B类 行测#3"],"definition":"2023年7月，习近平在江苏考察时提出，江苏要打造全国重要的产业科技创新高地，强化企业科技创新主体地位，深化科技体制改革和人才发展体制机制改革。","explanation":"第3题①把创新驱动的内涵型增长落实到企业和体制改革上。促进创新要素向企业集聚，有助于提高科技成果转化和产业化水平，这组举措对应江苏在科技创新上取得新突破的任务。","evidence":"强化企业科技创新主体地位，深化科技体制改革和人才发展体制机制改革","doubt":"","references":[]}]},"k-4282b34a03e51d9b":{"review":{"definition":"党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证。坚持中国特色社会主义法治道路，最根本的是坚持党的领导。","explanation":"按题中《习近平新时代中国特色社会主义思想学习纲要》的表述，②回答社会主义法治最根本的保证是什么，①对应法治体系的制度基础，③对应法治体系的理论指导。三项分别对应中国特色社会主义法治道路核心要义中的三个方面。","references":[],"evidence":"党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-925d6cce669136e5":{"review":{"definition":"中国特色社会主义制度是中国特色社会主义法治体系的根本制度基础，也是全面推进依法治国的根本制度保障。","explanation":"①对应法治道路核心要义中的“坚持中国特色社会主义制度”。法治体系以什么制度为基础、依法治国以什么制度为保障，题中《习近平新时代中国特色社会主义思想学习纲要》给出的都是中国特色社会主义制度。③对应的是理论指导。","references":[],"evidence":"中国特色社会主义制度是中国特色社会主义法治体系的根本制度基础","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-861b7d08b6f6fa71":{"review":{"definition":"中国特色社会主义法治理论是中国特色社会主义法治体系的理论指导和学理支撑，是全面推进依法治国的行动指南。","explanation":"③对应法治道路核心要义中的“贯彻中国特色社会主义法治理论”，其中“理论指导”对应法治体系，“行动指南”对应全面推进依法治国。④涉及建设法治中国的首要任务，题中所引《法治中国建设规划（2020－2025年）》将这一任务表述为全面贯彻实施宪法。","references":[],"evidence":"中国特色社会主义法治理论是法治体系的理论指导，是全面推进依法治国的行动指南","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d75947c26647cc7d":{"review":{"definition":"2024年党的二十届三中全会通过的改革《决定》提出，依法平等长久保护各种所有制经济产权，建立高效的知识产权综合管理体制。","explanation":"④的两项要求都出自《决定》“构建高水平社会主义市场经济体制”部分第（7）项“完善市场经济基础制度”。①所说的培育壮大先进制造业集群也有文件依据，文件将它列在“健全推动经济高质量发展体制机制”部分。本题按举措在文件中的归属作答。","references":[],"evidence":"依法平等长久保护各种所有制经济产权，建立高效的知识产权综合管理体制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-77a926aca4c623f6":{"review":{"definition":"党的二十届三中全会要求，进一步全面深化改革必须坚持以人民为中心，尊重人民主体地位和首创精神，做到改革为了人民、改革依靠人民、改革成果由人民共享。","explanation":"①减免摊位费直接减轻相关就业群体的经营负担，②通过“百姓会客厅”了解群众需求、听取群众意见，④通过完善积分落户制促进有稳定就业的外来人口有序实现市民化。③只写了提高资源配置效率和减轻财政负担，题面没有说明如何回应群众需求或让群众受益，因此本题选①②④。","references":[],"evidence":"改革为了人民、改革依靠人民、改革成果由人民共享","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4e4932002c6b79c2":{"review":{"definition":"促进高质量充分就业要循序渐进、尽力而为、量力而行，充分调动人民群众的积极性、主动性和创造性，引导大家依靠努力奋斗创造幸福生活。","explanation":"《促进高质量充分就业》把高质量充分就业视为一项要求很高、需要逐步推进的任务。③前半句写推进节奏和条件，后半句写调动群众积极性、主动性和创造性，两部分都符合文章表述。","references":[],"evidence":"循序渐进的过程，必须尽力而为、量力而行","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d94cb9ff2fda57ad":{"review":{"definition":"国务院关于《江苏省国土空间规划（2021—2035年）》的批复要求全面禁止围填海，国家重大项目除外。","explanation":"①把苏北海岸带的管控要求写成“一律不得新增围海和填海”，省略了批复明确保留的国家重大项目例外，因此①错误。","references":[],"evidence":"除国家重大项目外，全面禁止围填海","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c130e5cd47df478b":{"review":{"definition":"江苏省全面推进美丽江苏建设的实施意见提出建设黄河故道千里生态富民廊道，构建江淮生态经济区湖群绿心。两项任务都属于塑造“水韵江苏”品牌的部署。","explanation":"②把千里生态富民廊道对应到黄河故道，把湖群绿心对应到江淮生态经济区，两处区域与建设任务的搭配均与实施意见一致，因此②正确。","references":[],"evidence":"建设黄河故道千里生态富民廊道，构建江淮生态经济区湖群绿心","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ceb5ebf28bb6514f":{"review":{"definition":"江苏省全面推进美丽江苏建设的实施意见在塑造“水韵江苏”品牌的部署中，要求推动江河湖海各展所长，统筹推进长江和大运河国家文化公园建设。","explanation":"③前半句写发挥不同水域的特色，后半句写统筹推进长江和大运河两项国家文化公园建设，两项要求均见于实施意见的“水韵江苏”品牌部署，因此③正确。","references":[],"evidence":"推动江河湖海各展所长，统筹推进长江和大运河国家文化公园建设","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-497d018cdf5106d9":{"review":{"definition":"江苏省全面推进美丽江苏建设的实施意见要求增强省域森林、湿地、土壤、海洋等生态系统固碳作用，并支持里下河地区提升生态系统碳汇能力。","explanation":"④前半句列出全省需要增强固碳作用的生态系统，后半句明确支持提升碳汇能力的地区是里下河。两层要求均出自实施意见关于积极稳妥推进碳达峰碳中和的部署，因此④正确。","references":[],"evidence":"增强省域森林、湿地、土壤、海洋等生态系统固碳作用，支持里下河地区提升生态系统碳汇能力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ea731fd2ac32d02e":{"review":{"definition":"城乡基层治理坚持党组织领导，发挥政府、社会组织和居民等各方作用，共同建设、共同治理、共享治理成果。","explanation":"本题④讲的是谁来领导、哪些主体参与。材料指出社区事务多而繁杂，需要发挥社会各方面作用。党的十九大提出打造共建共治共享的社会治理格局，党的二十大进一步部署建设人人有责、人人尽责、人人享有的社会治理共同体。","references":[],"evidence":"构建党组织领导的共建共治共享的城乡基层治理格局","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-439df46f3fea6e71":{"review":{"definition":"基层治理应当在党组织领导下，将群众自治、依法治理和道德教化结合起来，增强治理活力和效能。","explanation":"自治、法治、德治相结合，是本题⑤所说的构建富有活力和效率的新型基层社会治理体系的一项要求。材料还以资源下沉、网格化管理和信息化支撑为例，说明怎样提高社区治理的精细化水平和服务的精准性。","references":[],"evidence":"健全党组织领导的自治、法治、德治相结合的基层治理体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3d38256bfd1864c5":{"review":{"definition":"巩固和完善农村基本经营制度，应坚持农村土地农民集体所有、坚持家庭经营的基础性地位、坚持稳定土地承包关系。","explanation":"本题①讲承包关系应当稳定，②讲家庭经营的基础性地位，④讲农村土地的所有权归属。三项分别对应《​​关于完善农村土地所有权承包权经营权分置办法的意见》列明的政策底线。","references":[],"evidence":"坚持农村土地集体所有，坚持家庭经营基础性地位","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d23abaf8ac4d7955":{"review":{"definition":"《农村土地经营权流转管理办法》规定，土地经营权流转应当因地制宜、循序渐进，把握好流转、集中和规模经营的程度。","explanation":"流转规模应与城镇化进程、农村劳动力转移规模、农业科技和生产手段进步程度、农业社会化服务水平相适应。本题③把集中连片流转写成普遍应当坚持的要求，忽略了规则对地方条件和适度规模的要求。","references":[],"evidence":"土地经营权流转应当因地制宜、循序","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ac67a052412bb19d":{"review":{"definition":"依照《农村集体经济组织法》第十五条，非成员长期在农村集体经济组织工作并对集体作出贡献，经成员大会全体成员四分之三以上同意，可以参与分配集体收益、享受组织提供的服务和福利，并享有法律法规和组织章程规定的其他权利。","explanation":"四分之三以上的同意门槛以成员大会全体成员为基数。第十五条援引第十三条第七项、第九项和第十项，涵盖题中的①和③。②所涉宅基地使用权对应第六项，④所涉土地补偿费分配对应第八项，两项均在本条授权范围之外，因此选B。","references":[],"evidence":"经农村集体经济组织成员大会全体成员四分之三以上同意，可以享有本法第十三条","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d8dea5ce4709eb7a":{"review":{"definition":"原题引文：并在小区公告栏、电梯间等处张贴判决书","explanation":"给定答案C以张某在公告栏、电梯间张贴的判决书披露了可归属于李某的私密信息为前提。判断时要结合公开的具体内容、脱敏情况和邻居能否识别李某。B主张侵害名誉权，还需有侵害社会评价的事实，题面所述的群内讨债本身不足以推出这一点。","references":[{"source":"web-57a51e8c731c9535","location":"人格权编第六章，第一千零三十二条至第一千零三十四条","quote":"个人信息中的私密信息，适用有关隐私权的规定"}],"evidence":"并在小区公告栏、电梯间等处张贴判决书","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-ac18264ee796d7ca":{"review":{"definition":"民事诉讼受案范围包括因人身关系或财产关系提起的诉讼。微信群进出争议是否属于该范围，取决于它是否涉及具体的人身或财产权益。","explanation":"徐某在群内与他人发生争执后被移出群，申请重新入群又遭拒并被拉黑。题干中的人格贬损是徐某的主张，所述行为只涉及群成员和联系人管理，未交代具体贬损行为或财产权益纠纷。标准答案C适用于题中这一单纯的群成员进出争议。","references":[],"evidence":"因财产关系和人身关系提起的民事诉讼","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7df003fe837dda7c":{"sources":[{"id":"5507b615e6d18124","label":"市场准入负面清单","topic":"发展与治理","category":"非时政","text":"2.市场准入负面清单\n市场准入负面清单分为禁止和许可两类事项。对禁止准入事项，经营主体不得进入，政\n府依法不予审批、核准，不予办理有关手续；对许可准入事项，地方各级政府要公开法律法\n规依据、技术标准、许可要求、办理流程、办理时限，制定市场准入服务规程，由经营主体\n按照规定的条件和方式合规进入；对市场准入负面清单以外的行业、领域、业务等，各类经\n营主体皆可依法平等进入。对未实施市场禁入或许可准入但按照备案管理的事项，不得以备\n案名义变相设立许可。\n——《市场准入负面清单（2025 年版）》","source":{"doc":"6cbfb01fe723bba64b75","first":8,"last":8,"page":8,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ff4f281aa7a31b1c":{"sources":[{"id":"fb268ae88da0ea94","label":"渐进式延迟法定退休年龄","topic":"年度政府工作","category":"时政","text":"2.渐进式延迟法定退休年龄\n综合考虑我国人均预期寿命、健康水平、人口结构、国民受教育程度、劳动力供给等因\n素，按照小步调整、弹性实施、分类推进、统筹兼顾的原则，实施渐进式延迟法定退休年龄。\n从 2025 年 1 月 1 日起，男职工和原法定退休年龄为五十五周岁的女职工，法定退休年\n龄每四个月延迟一个月，分别逐步延迟至六十三周岁和五十八周岁；原法定退休年龄为五十\n周岁的女职工，法定退休年龄每二个月延迟一个月，逐步延迟至五十五周岁。国家另有规定\n的，从其规定。\n从 2030 年 1 月 1 日起，将职工按月领取基本养老金最低缴费年限由十五年逐步提高至\n二十年，每年提高六个月。\n职工达到最低缴费年限，可以自愿选择弹性提前退休，提前时间最长不超过三年，且\n退休年龄不得低于女职工五十周岁、五十五周岁及男职工六十周岁的原法定退休年龄。职工\n达到法定退休年龄，所在单位与职工协商一致的，可以弹性延迟退休，延迟时间最长不超过\n三年。\n——《国务院关于渐进式延迟法定退休年龄的办法》","source":{"doc":"6cbfb01fe723bba64b75","first":10,"last":11,"page":10,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-8a560d9db0559d67":{"sources":[{"id":"d6c31e0b2d2626ab","label":"个人养老金制度","topic":"就业、社保与公共服务","category":"非时政","text":"3.个人养老金制度\n个人养老金是指政府政策支持、个人自愿参加、市场化运营、实现养老保险补充功能\n的制度。个人养老金实行个人账户制，缴费完全由参加人个人承担，自主选择购买符合规\n定的储蓄存款、理财产品、商业养老保险、公募基金等金融产品，实行完全积累，按照国家\n有关规定享受税收优惠政策。\n个人养老金的参加人应当是在中国境内参加城镇职工基本养老保险或者城乡居民基本\n养老保险的劳动者。\n参加人每年缴纳个人养老金额度上限为 12000 元，参加人每年缴费不得超过该缴费额度\n上限。\n——《个人养老金实施办法》","source":{"doc":"6cbfb01fe723bba64b75","first":11,"last":11,"page":11,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-9dcbb0434a0f2f9a":{"sources":[{"id":"93ad81128acfcedd","label":"财政政策","topic":"经济指标与宏观调控","category":"非时政","text":"1.财政政策\n财政政策是指政府运用国家预算和税收等财政手段，通过对国民收入的分配和再分配，\n来实现社会总供给和社会总需求平衡的一种经济政策。","source":{"doc":"6cbfb01fe723bba64b75","first":23,"last":23,"page":23,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-72f8415a87009f9f":{"sources":[{"id":"d1d03e4f5f7e9094","label":"一般公共预算支出","topic":"经济指标与宏观调控","category":"非时政","text":"3.一般公共预算支出\n一般公共预算支出指国家财政将筹集起来的资金进行分配使用，以满足经济建设和各项\n事业的需要。主要包括：一般公共服务、外交、国防、公共安全、教育、科学技术、文化体\n育与传媒、社会保障和就业、医疗卫生与计划生育、节能环保、城乡社区、农林水、交通运\n输、资源勘探信息等、商业服务业等、金融、援助其他地区、国土海洋气象等、住房保障、\n粮油物资储备、债务付息、债务发行费用等方面的支出。财政支出根据政府在经济和社会活\n动中的不同职权，划分为中央财政支出和地方财政支出。","source":{"doc":"6cbfb01fe723bba64b75","first":23,"last":23,"page":23,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-85e833398dfbf081":{"sources":[{"id":"3cf134cec16fa339","label":"超长期特别国债","topic":"经济指标与宏观调控","category":"非时政","text":"4.超长期特别国债\n超长期特别国债，包含三个关键词，超长期、特别、国债。\n超长期，指的是期限。在债券市场上，一般认为发行期限在 10 年以上的利率债为“超\n长期债券”。和普通国债相比，超长期债券能够缓解中短期偿债压力，以时间换空间。\n特别，说的是资金用途。它是为特定目标发行的、具有明确用途的国债，资金需要专款\n专用。\n国债，是国家为了筹集财政资金而发行的一种政府债券，具有最高的信用度，被公认为\n是最安全的投资工具。","source":{"doc":"6cbfb01fe723bba64b75","first":23,"last":24,"page":23,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a7067b4c64c4938e":{"sources":[{"id":"05ec04047198eda6","label":"“两新”","topic":"发展与治理","category":"非时政","text":"5.“两新”\n指大规模设备更新和消费品以旧换新。","source":{"doc":"6cbfb01fe723bba64b75","first":24,"last":24,"page":24,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-b57fda2086bf86ee":{"sources":[{"id":"17600fc85ffadfaa","label":"基层“三保”","topic":"经济指标与宏观调控","category":"非时政","text":"6.基层“三保”\n基层“三保”，即保基本民生、保工资、保运转，是推动政府履职和各项政策实施的基\n础条件，直接关系经济运行秩序、社会大局稳定以及人民群众切身利益。","source":{"doc":"6cbfb01fe723bba64b75","first":24,"last":24,"page":24,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-81f82c633eb30d79":{"sources":[{"id":"c8060276eb2d793b","label":"高水平社会主义市场经济体制","topic":"发展与治理","category":"非时政","text":"1.高水平社会主义市场经济体制\n党的二十届三中全会鲜明提出进一步全面深化改革要“以经济体制改革为牵引”、“高\n水平社会主义市场经济体制是中国式现代化的重要保障”等重大论断，明确“到二〇三五\n年，全面建成高水平社会主义市场经济体制”。高水平社会主义市场经济体制，是我们党对\n市场经济理论的发展与深化，是推进中国式现代化的重要保障。以保障中国式现代化为重要\n目标构建高水平社会主义市场经济体制，必须坚持系统集成方法，处理好经济和社会、政府\n和市场、效率和公平、活力和秩序、发展和安全等重大关系，更好推动经济建设、政治建\n设、文化建设、社会建设、生态文明建设取得更大成效。","source":{"doc":"6cbfb01fe723bba64b75","first":28,"last":28,"page":28,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-5d77ddd66e72fa84":{"sources":[{"id":"8f207ee51f5e40d8","label":"零基预算","topic":"经济指标与宏观调控","category":"非时政","text":"2.零基预算\n零基预算是不考虑过去的预算项目和收支水平，以零为基点编制的预算，具体指不受以\n往预算安排情况的影响，一切从实际需要出发，逐项审议预算年度内各项费用的内容及其开\n支标准，结合财力状况，在综合平衡的基础上编制预算的一种科学的现代预算编制方法。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-d88080b318933b55":{"sources":[{"id":"58be95d753eb210f","label":"国家服务业扩大开放综合示范区","topic":"产业、科技与对外开放","category":"非时政","text":"2.国家服务业扩大开放综合示范区\n国家服务业扩大开放综合示范区（简称“综合示范区”），是党中央、国务院着眼于构\n建以国内大循环为主体、国内国际双循环相互促进的新发展格局，着眼于建设迈向中华民\n族伟大复兴的社会主义大国首都，作出的重大战略决策，充分体现了以习近平同志为核心的\n党中央对北京工作的高度重视和亲切关怀，为本市进一步深化改革、扩大开放，推动服务业\n高质量发展提供了根本遵循。","source":{"doc":"6cbfb01fe723bba64b75","first":31,"last":31,"page":31,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-22877e06cad33bb0":{"sources":[{"id":"b82351c495067b45","label":"《数字经济伙伴关系协定》","topic":"产业、科技与对外开放","category":"非时政","text":"3.《数字经济伙伴关系协定》\n《数字经济伙伴关系协定》由新加坡、智利、新西兰三国于 2020 年 6 月 12 日线上签署，\n是旨在加强三国间数字贸易合作并建立相关规范的数字贸易协定。","source":{"doc":"6cbfb01fe723bba64b75","first":31,"last":31,"page":31,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ad63c456766661ac":{"sources":[{"id":"b59026e7637ea40b","label":"《全面与进步跨太平洋伙伴关系协定》","topic":"产业、科技与对外开放","category":"非时政","text":"4.《全面与进步跨太平洋伙伴关系协定》\n《全面与进步跨太平洋伙伴关系协定》（CPTPP），是在 TPP 基础上构建的一个自由化\n水平高、涵盖领域广、纪律要求严的自贸协定。该协定致力于维护开放市场，增加世界贸易，\n为不同收入水平和经济背景的人民创造新的经济机会；促进缔约方之间进一步区域经济一体\n化与合作；为加快区域贸易自由化和投资增加机会；2021 年 9 月 16 日，中国正式提出申请\n加入《全面与进步跨太平洋伙伴关系协定》。","source":{"doc":"6cbfb01fe723bba64b75","first":31,"last":31,"page":31,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-b8815c2eecb50c79":{"sources":[{"id":"52998774d3311fa2","label":"社会救助","topic":"就业、社保与公共服务","category":"非时政","text":"3.社会救助\n社会救助与社会保险、社会福利、社会优抚等其他社会保障形式，共同构成我国的社会\n保障体系。其中，社会救助是最先形成的、历史最悠久的社会保障形式，是保障社会成员生\n活安全和生存权利的“最后一道防线”。","source":{"doc":"6cbfb01fe723bba64b75","first":35,"last":35,"page":35,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-e50aa174141c7843":{"sources":[{"id":"39b3c738fc3895eb","label":"第二轮土地承包到期后再延长三十年整省试点","topic":"年度政府工作","category":"时政","text":"1.第二轮土地承包到期后再延长三十年整省试点\n我国农村土地承包经营制度始于上世纪 80 年代，先后经历过两轮承包，第一轮承包期\n为 1983-1997 年，为期 15 年。到期后国家提出延长承包期，第二轮承包期为 30 年，即\n1997-2027 年。2017 年，党的十九大报告明确提出，“保持土地承包关系稳定并长久不变，\n第二轮土地承包到期后再延长三十年。”坚持“大稳定、小调整”，有序推进第二轮土地\n承包到期后再延长三十年试点，扩大整省试点范围，妥善化解延包中的矛盾纠纷，确保绝大\n多数农户承包地总体顺延、保持稳定。","source":{"doc":"6cbfb01fe723bba64b75","first":35,"last":36,"page":35,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a47269f086bf52c1":{"sources":[{"id":"80b0764101d67b48","label":"健全现代农业经营体系和社会化服务体系","topic":"农业与城乡治理","category":"非时政","text":"2.健全现代农业经营体系和社会化服务体系\n党的二十届三中全会提出“完善农业经营体系”“健全便捷高效的农业社会化服务体系”。","source":{"doc":"6cbfb01fe723bba64b75","first":36,"last":36,"page":36,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-aa5e0a05a122e2fc":{"sources":[{"id":"06eb2511c8386498","label":"“人地钱”挂钩","topic":"农业与城乡治理","category":"非时政","text":"2.“人地钱”挂钩\n“人地钱”挂钩是通过建立人口流动、土地指标、财政资金的联动机制，将城镇建设用\n地指标分配、财政转移支付与城市吸纳农业转移人口的数量挂钩，实现“人多就多给地、多\n给钱”的激励导向。","source":{"doc":"6cbfb01fe723bba64b75","first":38,"last":38,"page":38,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-08105443615f5fb0":{"sources":[{"id":"f3ab02f32165e5e8","label":"加强就业歧视治理","topic":"就业、社保与公共服务","category":"非时政","text":"5.加强就业歧视治理\n坚决破除影响劳动力、人才流动的体制机制障碍，同步推进户籍、用人、档案等服务改\n革，消除地域、身份、性别、年龄等影响平等就业的不合理限制和就业歧视，畅通社会流动\n渠道。健全就业歧视救济机制，依法纳入劳动保障监察范围，完善民事支持起诉机制，稳妥\n开展公益诉讼检察工作。\n——《中共中央 国务院关于实施就业优先战略 促进高质量充分就业的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":40,"last":41,"page":40,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a64c8c0e24af07c4":{"sources":[{"id":"afa845e668ca6349","label":"行政监督体系","topic":"发展与治理","category":"非时政","text":"2.行政监督体系\n（1）行政内部监督系统\n行政内部监督系统，是指行政机关在国家行政系统内部实施的各种监督所组成的行政监\n督系统，分为一般监督和审计监督。\n（2）行政外部监督系统\n行政外部监督系统，是指除行政机关以外的监督主体所构成的对行政机关及其工作人员\n行政行为的遵纪守法情况进行督查、督导的监督体系。外部监督主要包括立法监督、监察监\n督、司法监督、政党监督、社会监督。","source":{"doc":"6cbfb01fe723bba64b75","first":52,"last":52,"page":52,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-9fedd684f4bd94ae":{"sources":[{"id":"96057c4cf6f4aa3c","label":"党对人民军队的绝对领导","topic":"发展与治理","category":"非时政","text":"2.党对人民军队的绝对领导\n党对军队绝对领导的根本原则和制度，发端于南昌起义，奠基于三湾改编，定型于古田\n会议，是人民军队完全区别于一切旧军队的政治特质和根本优势。\n——《在庆祝中国人民解放军建军 90 周年大会上的讲话》","source":{"doc":"6cbfb01fe723bba64b75","first":54,"last":54,"page":54,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ea9b753c174f8c7c":{"sources":[{"id":"1f810b9249ae6b9c","label":"中央委员会是什么？","topic":"党政制度与理论","category":"非时政","text":"（1）中央委员会是什么？\n党的最高领导机关，是党的全国代表大会和它所产生的中央委员会。在全国代表\n大会闭会期间，中央委员会执行全国代表大会的决议，领导党的全部工作，对外代表\n中国共产党。中央委员会由党的全国代表大会选举产生，由委员和候补委员组成，每\n届任期五年。","source":{"doc":"41195a191a57c1c36332","first":2,"last":2,"page":2,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-11b53e93615f6309":{"sources":[{"id":"3772253675514584","label":"民主集中制是党的根本组织原则和领导制度，贯彻执行民主集中制是全面从严治","topic":"二十届五中全会","category":"时政","text":"（二）民主集中制是党的根本组织原则和领导制度，贯彻执行民主集中制是全面从严治\n党的内在要求\n必须完善和落实民主集中制①各项制度，充分发扬党内民主，有效实行正确的集中，更\n好发挥民主集中制的政治优势、组织优势、制度优势、工作优势。要坚持和加强党中央集中\n统一领导，提高党内民主质量，严格执行领导班子决策议事规则，规范“一把手”履职用权。","source":{"doc":"41195a191a57c1c36332","first":14,"last":14,"page":14,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-646d833c5a188554":{"sources":[{"id":"3cd0eab6f95914e6","label":"民主集中制","topic":"党政制度与理论","category":"非时政","text":"1.民主集中制\n民主集中制就是民主基础上的集中和集中指导下的民主相结合的制度。民主集中制\n包括民主和集中两个方面，两者互为条件、相辅相成、缺一不可。我们党实行的民主集中\n制，是又有集中又有民主、又有纪律又有自由、又有统一意志又有个人心情舒畅生动活泼\n的制度。\n民主集中制是马克思主义建党学说的重要内容。中国共产党从一开始就是按照民主\n集中制原则组织起来的。党的二大首次确认民主集中制的建党原则，党的六大通过的党章\n第一次明确规定党的组织原则是民主集中制。习近平总书记曾指出：民主集中制是我们党\n的根本组织制度和领导制度，是科学的合理的有效率的制度，是我们党最大的制度优势。\n民主集中制的基本原则：第一，坚持“四个服从”（即党员个人服从党的组织，少数\n服从多数，下级组织服从上级组织，全党各个组织和全体党员服从党的全国代表大会和中\n央委员会）；第二，坚持选举产生党的领导机关；第三，坚持集体领导；第四，善于发挥\n下级党组织的积极性；第五，注意尊重少数人意见；第六，禁止个人崇拜。","source":{"doc":"41195a191a57c1c36332","first":14,"last":15,"page":14,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-83e53ed14ea92058":{"sources":[{"id":"c054b0f36623248e","label":"严格贯彻执行民主集中制","topic":"党政制度与理论","category":"非时政","text":"2.严格贯彻执行民主集中制\n《决定》从 4 个方面作出了具体部署。一是坚持和加强党中央集中统一领导。完善党\n中央集中统一领导的体制机制，完善党中央重大决策部署落实机制，严格执行向党中央请\n示报告制度，推进政治监督具体化、精准化、常态化。二是提高党内民主质量。坚持和完\n善党内民主制度，健全党内情况通报制度、情况反映制度，坚持党内民主平等的同志关系。\n三是严格执行领导班子决策议事规则。完善党委（党组）议事规则和决策程序，加强重大\n决策合规合法性审查，健全重大决策、重要人事任免、重大项目安排、大额资金使用事项\n监督机制，也就是常说的“三重一大”监督机制。四是规范“一把手”履职用权。落实加\n强对“一把手”和领导班子监督的制度规定，健全领导班子权力运行制约机制，完善同级\n监督制度机制。","source":{"doc":"41195a191a57c1c36332","first":15,"last":15,"page":15,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-9c4efafe28cdc4a0":{"sources":[{"id":"56574b4813fad321","label":"全面从严治党关键在从严治吏①","topic":"二十届五中全会","category":"时政","text":"（三）全面从严治党关键在从严治吏①\n必须贯彻新时代党的组织路线②，严格干部教育培养、选拔任用、管理监督，建设\n一支政治过硬、本领高强、作风优良、纪律严明的高素质干部队伍③。①要坚持正确用\n人导向，②精准科学选人用人，③推动干部树立和践行正确政绩观，④增强干部干事\n创业本领，⑤提高培养选拔优秀年轻干部质量，⑥加强干部管理监督，全方位培养、\n引进、用好人才。","source":{"doc":"41195a191a57c1c36332","first":15,"last":15,"page":15,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-7d207bce59663cac":{"sources":[{"id":"bbe80a7e2a294b5e","label":"全面从严治党关键在从严治吏","topic":"党政制度与理论","category":"非时政","text":"1.全面从严治党关键在从严治吏\n2013 年 6 月，习近平总书记在全国组织工作会议上首次强调“党要管党，首先是管\n好干部；从严治党，关键是从严治吏”。 其核心逻辑在于：干部是党的事业的骨干，中\n央战略部署要靠各级领导干部层层落实，因此治党之要，重在治吏。","source":{"doc":"41195a191a57c1c36332","first":15,"last":15,"page":15,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-4cf174b0eeda8583":{"sources":[{"id":"274da3266b72e0b0","label":"新时代党的组织路线","topic":"党政制度与理论","category":"非时政","text":"2.新时代党的组织路线\n组织路线是政党进行组织工作的根本原则和根本方针。新时代党的组织路线是全面\n贯彻习近平新时代中国特色社会主义思想，以组织体系建设为重点，着力培养忠诚干净担\n当的高素质干部，着力集聚爱国奉献的各方面优秀人才，坚持德才兼备、以德为先、任人\n唯贤，为坚持和加强党的全面领导、坚持和发展中国特色社会主义提供坚强组织保证。","source":{"doc":"41195a191a57c1c36332","first":15,"last":16,"page":15,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-a16e4b76620ee985":{"sources":[{"id":"db639c4f78ade198","label":"党的各级组织是全面从严治党的主体","topic":"二十届五中全会","category":"时政","text":"（四）党的各级组织是全面从严治党的主体。\n必须体系化推进各层级各领域党组织建设①，强化党组织政治功能和组织功能，确\n保贯彻落实党的路线方针政策和党中央决策部署上下协同、精准高效。①要发挥中央\n和国家机关党组织表率作用，②强化地方党委功能，③统筹推进各领域基层党组织建\n设，④突出抓好新兴领域党的建设，⑤加强党员队伍建设，⑥完善党的各级组织贯通\n机制。","source":{"doc":"41195a191a57c1c36332","first":16,"last":16,"page":16,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-8ca2340187b3de17":{"sources":[{"id":"99694140e5b6e631","label":"党的“六大纪律”","topic":"党政制度与理论","category":"非时政","text":"2.党的“六大纪律”\n党的纪律主要包括“六大纪律”，即：政治纪律、组织纪律、廉洁纪律、群众\n纪律、工作纪律、生活纪律。严明党的纪律，首要的就是严明政治纪律。政治纪律\n是最重要、最根本、最关键的纪律，遵守党的政治纪律是遵守党的全部纪律的重要\n基础。","source":{"doc":"41195a191a57c1c36332","first":17,"last":18,"page":17,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-6c1fd408fe2fe5f0":{"sources":[{"id":"af79157c33f634e4","label":"加强党内法规制度建设是全面从严治党的长远之策、根本之策①","topic":"二十届五中全会","category":"时政","text":"（七）加强党内法规制度建设是全面从严治党的长远之策、根本之策①。\n必须坚持把党章作为全党的根本行为规范②，深化党的建设制度改革，推动依法治\n国和依规治党有机统一③，为持之以恒推进全面从严治党提供有力制度保障。要完善党\n内法规制度体系，增强制度执行力，大力破除潜规则。","source":{"doc":"41195a191a57c1c36332","first":19,"last":19,"page":19,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-d6097bcce284f493":{"sources":[{"id":"6af25dbdd03d5a34","label":"党内法规制度建设是全面从严治党的长远之策、根本之策","topic":"党政制度与理论","category":"非时政","text":"1.党内法规制度建设是全面从严治党的长远之策、根本之策\n党内法规制度承载党的意志，制度治党具有刚性约束功能，制度的约束力不仅\n体现为对违规行为的惩戒，也体现为明确行为尺度，使党员干部能够预知行为后果，\n自觉规范权力行使。因此，具有固本长效功能，是巩固党的长期执政根基的重要支\n撑。","source":{"doc":"41195a191a57c1c36332","first":19,"last":19,"page":19,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-fd3d32c9cbc2ce95":{"sources":[{"id":"97ecf430b27275eb","label":"把党章作为全党的根本行为规范","topic":"党政制度与理论","category":"非时政","text":"2.把党章作为全党的根本行为规范\n以党章为根本构建党内法规体系，是制度治党的根本依托。党章是党的根本大\n法，是制定其他党内法规的基础和依据。以党章为根本，意味着各项制度必须遵循\n共同的基本原则，任何党内法规都不得同党章相抵触。","source":{"doc":"41195a191a57c1c36332","first":19,"last":19,"page":19,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-ad2bc978efdde6b9":{"sources":[{"id":"6e5b52c2a070c063","label":"依法治国和依规治党有机统一","topic":"党政制度与理论","category":"非时政","text":"3.依法治国和依规治党有机统一\n坚持依法治国和依规治党有机统一是全面依法治国的本质要求和重要保障。依规治\n党是依法治国的引领和保障，依法治国是依规治党的基础和依托。","source":{"doc":"41195a191a57c1c36332","first":19,"last":19,"page":19,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-2e5e66bf667e7d7b":{"sources":[{"id":"6a6ad082ab611eba","label":"持之以恒推进全面从严治党，必须进一步完善党和国家监督体系①","topic":"二十届五中全会","category":"时政","text":"（八）持之以恒推进全面从严治党，必须进一步完善党和国家监督体系①。\n要做实党委（党组）全面监督②，完善纪检监察工作双重领导体制③，推动党内监\n督同各方面监督深度融合、高效联动，发挥巡视综合监督利剑作用。","source":{"doc":"41195a191a57c1c36332","first":19,"last":19,"page":19,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-fbdcaa4ff8744146":{"sources":[{"id":"f678a920d963368a","label":"党和国家监督体系","topic":"党政制度与理论","category":"非时政","text":"1.党和国家监督体系\n党的二十大报告鲜明提出要健全“党统一领导、全面覆盖、权威高效”的监督\n体系。具体包括：党内监督、人大监督、民主监督、行政监督、司法监督、审计监\n督、财会监督、统计监督、群众监督、舆论监督等监督。其中，党内监督在党和国\n家监督体系中是最基本的、第一位的，是各类监督发挥作用的方向引领和根本支撑，\n要以党内监督为主导，不断完善权力监督制度和执纪执法体系，推动各类监督贯通\n协调，形成常态长效的监督合力。","source":{"doc":"41195a191a57c1c36332","first":19,"last":20,"page":19,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-b27ace94ee24b63f":{"sources":[{"id":"d56b2b6974f5eb31","label":"党内监督体系","topic":"党政制度与理论","category":"非时政","text":"2.党内监督体系\n《中国共产党党内监督条例》规定：“建立健全党中央统一领导，党委（党组）\n全面监督，纪律检查机关专责监督，党的工作部门职能监督，党的基层组织日常监\n督，党员民主监督的党内监督体系。\n党中央集中统一领导：党内监督工作由党中央集中统一领导，各级党组织都要服从\n党中央领导。\n党委（党组）全面监督：党委（党组）在党内监督中负主体责任，由书记第一\n负责，统一领导本地区本部门本单位的党内监督工作。\n纪律检查机关专责监督：各级纪委是党内监督的专责机关，履行监督执纪问责\n职责。\n党的工作部门职能监督：党的工作部门是党委（党组）主体责任在不同领域的\n载体和抓手，党委办公厅、组织部、宣传部、统战部、政法委等工作部门，在职责\n范围内承担相应的监督职责。\n党的基层组织日常监督：基层党组织要通过组织生活等，对党员进行日常监督。\n党员民主监督：党员要行使监督权利，对领导干部和党的工作进行监督。","source":{"doc":"41195a191a57c1c36332","first":20,"last":20,"page":20,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-dd1ca9734df1d917":{"sources":[{"id":"a478e95546ddcea5","label":"纪检监察工作双重领导体制","topic":"党政制度与理论","category":"非时政","text":"3.纪检监察工作双重领导体制\n纪检监察工作双重领导体制是指党的纪律检查机关和国家监察机关在同级党委\n（政府）和上级纪委监委的双重领导下开展工作的制度安排。这一体制是中国特色\n社会主义监督体系的重要组成部分，旨在强化党对反腐败工作的集中统一领导，同\n时保证纪检监察机关行使职权的相对独立性和权威性。","source":{"doc":"41195a191a57c1c36332","first":20,"last":20,"page":20,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-c352b3325de0ff0e":{"sources":[{"id":"5f43ac4a1cb0e794","label":"全面从严治党是全党的共同政治责任","topic":"党政制度与理论","category":"非时政","text":"1.全面从严治党是全党的共同政治责任\n习近平总书记强调，管党治党的主体责任、监督责任、第一责任人责任、“一\n岗双责”等构成完整的责任链条，每一种责任都要严格落实。\n主体责任：党委（党组）负主体责任，是管党治党的“牛鼻子”。\n监督责任：纪委是党内监督的专责机关，是管党治党的重要力量，在全面从严治党\n中负监督责任。\n第一责任人责任：全面从严治党第一责任人是各级党委（党组）书记，要做到重要\n工作亲自部署、重大问题亲自过问、重要环节亲自协调、重要案件亲自督办。\n“一岗双责”：领导班子其他成员履行“一岗双责”，即既要抓好分管业务工作，\n也要抓好分管领域的党风廉政建设工作，两个责任一起扛、一起落实。","source":{"doc":"41195a191a57c1c36332","first":21,"last":21,"page":21,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-1d82eeba2f5e93af":{"sources":[{"id":"de9ea4a9f64d045c","label":"持之以恒推进全面从严治党是全党的共同政治责任①","topic":"二十届五中全会","category":"时政","text":"全会指出，深入学习贯彻全会精神是当前和今后一个时期全党的重大政治任务。要深入\n学习领会全会精神，加强组织领导，持续在解决突出问题上下功夫，推动《决定》各项部署\n落到实处。\n全会强调，要做好岁末年初各项工作。坚持稳中求进工作总基调①，完整准确全面贯彻\n新发展理念，加快构建新发展格局，用好用足宏观政策，深入挖掘内需潜力，进一步深化改\n革开放，推动经济持续向新向优向好发展，确保完成今年经济社会发展主要目标任务，实现\n“十五五”良好开局。统筹发展和安全②，加强普惠性、基础性、兜底性民生建设③，做好安\n全生产、防灾减灾救灾、食品药品安全和社会稳定工作。巩固拓展树立和践行正确政绩观学\n习教育成果，结合换届抓好新任职领导班子成员特别是“一把手”的政绩观培训，教育引导\n他们自觉坚持立党为公、为民造福、科学决策、真抓实干，努力为人民出政绩、以实干出政\n绩。","source":{"doc":"41195a191a57c1c36332","first":21,"last":21,"page":21,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"},{"id":"65686e70c35f2e40","label":"持之以恒推进全面从严治党是全党的共同政治责任①","topic":"二十届五中全会","category":"时政","text":"（九）持之以恒推进全面从严治党是全党的共同政治责任①。\n必须扭住管党治党责任制“牛鼻子”，健全各负其责、统一协调的责任体系，优\n化责任落实考评机制，对管党治党不力、出现严重问题的严肃追责问责。","source":{"doc":"41195a191a57c1c36332","first":20,"last":20,"page":20,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"},{"id":"d8b26b3c6d2061ca","label":"持之以恒推进全面从严治党是全党的共同政治责任①","topic":"二十届五中全会","category":"时政","text":"全会决定，中国共产党第二十一次全国代表大会于 2027 年下半年在北京召开。全会认\n为，党的二十一大是我们党在基本实现社会主义现代化①的关键时期、向第二个百年奋斗目\n标进军新征程上召开的一次十分重要的代表大会，是党和国家政治生活中的一件大事。全党\n要团结带领全国各族人民万众一心、勠力进取，为基本实现社会主义现代化而共同奋斗，不\n断开创以中国式现代化全面推进强国建设、民族复兴伟业新局面，以实际行动迎接党的二十\n一大胜利召开。\n全会号召，全党更加紧密地团结在以习近平同志为核心的党中央周围，全面贯彻习近平\n新时代中国特色社会主义思想，励精图治、奋发图强，持之以恒推进全面从严治党，不断开\n创新时代管党治党、兴党强党新局面，团结带领全国各族人民为全面建成社会主义现代化强\n国、以中国式现代化全面推进中华民族伟大复兴②而不懈奋斗。","source":{"doc":"41195a191a57c1c36332","first":22,"last":23,"page":22,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-84a1934394881b8b":{"review":{"title":"授权国务院先制定行政法规","type":"制度与规则","domain":"法律","definition":"《立法法》第十一条所列事项尚未制定法律时，全国人大及其常委会可以授权国务院就其中部分事项先制定行政法规。","explanation":"国务院须依授权决定行使权限。犯罪和刑罚、剥夺公民政治权利、限制人身自由的强制措施和处罚、司法制度等事项不得依此授权。辨认选项时既要看受权机关，也要看它获准制定哪一种规范。","basis":"据原题解析及《中华人民共和国立法法》编释。","references":[{"source":"legislation2023","location":"第十一条至第十五条"}],"questionEvidence":{"国考 2025 副省级 行测#22":"对其中的部分事项先制定行政法规","国考 2025 行政执法 行测#21":"对其中的部分事项先制定行政法规"},"related":["k-24a0f49999363e27"]}},"k-24a0f49999363e27":{"review":{"title":"法律解释权与司法解释","type":"制度与规则","domain":"法律","definition":"全国人大常委会行使法律解释权。最高人民法院、最高人民检察院可以对审判、检察工作中具体应用法律的问题作出解释。","explanation":"法律规定的具体含义需要进一步明确，或者法律制定后出现新情况需要明确适用依据时，由全国人大常委会解释。两高的司法解释应主要针对具体条文，符合立法目的、原则和原意。","basis":"据原题解析及《中华人民共和国立法法》编释。","references":[{"source":"legislation2023","location":"第四十八条、第一百一十九条"}],"questionEvidence":{"国考 2025 副省级 行测#22":"法律解释权属于全国人民代表大会常务委员会","国考 2025 行政执法 行测#21":"法律解释权属于全国人民代表大会常务委员会"},"related":["k-84a1934394881b8b"]}}}};
